(window.SB_FULLC=window.SB_FULLC||{})["nono"]={c:"[{\"w\":\"nonpareil\",\"d\":\"model of excellence or perfection of a kind; one having no equal\",\"s\":\"Among all the chess players in the regional tournament, twelve-year-old Maya stood as a true nonpareil, defeating every opponent with strategies that even seasoned adults could not anticipate.\",\"p\":\"non-puh-REL\",\"o\":\"French\",\"y\":6,\"bp\":70,\"m\":\"nonparell\",\"nt\":\"Advanced\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonprofit\",\"d\":\"an organization chartered for other than profit-making activities\",\"s\":\"The local nonprofit raised enough money to build a new shelter for homeless families.\",\"p\":\"nah-NPRAH-fuht\",\"o\":\"Latin\",\"y\":2,\"bp\":33,\"m\":\"non-profit\",\"sy\":\"naa.npraa.fah.t\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonpublic\",\"d\":\"not invested with or related to prominent position or status etc.\",\"s\":\"The meeting was held in a nonpublic location to ensure the privacy of those involved.\",\"p\":\"nah-NPUH-blihk\",\"o\":\"Latin\",\"y\":5,\"bp\":33,\"m\":\"nonpublick\",\"sy\":\"naa.npah.blih.k\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonracial\",\"d\":\"not racial; having nothing to do with race or races\",\"s\":\"His remarks were intended to be completely nonracial.\",\"p\":\"nah-NRAY-shuhl\",\"o\":\"French\",\"y\":7,\"bp\":33,\"m\":\"nonraciel\",\"sy\":\"naa.nrey.shah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"sports\",\"ofrench\"]},{\"w\":\"nonsense\",\"d\":\"a message that seems to convey no meaning\",\"s\":\"The teacher dismissed the rumor about a school holiday on Friday as complete nonsense, reminding students that there were still two full weeks before any break was scheduled.\",\"p\":\"NAH-nsehns\",\"o\":\"Latin\",\"y\":3,\"bp\":30,\"m\":\"nonsence\",\"sy\":\"naa.nseh.ns\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsmoker\",\"d\":\"a person who does not smoke tobacco\",\"s\":\"As a nonsmoker, Marcus always requested a seat far from the smoking section at restaurants.\",\"p\":\"nah-NSMOH-ker\",\"o\":\"Old English\",\"y\":6,\"bp\":29,\"m\":\"nonsmokker\",\"sy\":\"naa.nsmow.ker\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ooldeng\"]},{\"w\":\"nonstick\",\"d\":\"(of surfaces especially of cooking utensils) permitting easy removal of adherent food particles\",\"s\":\"A frying pan with a nonstick surface.\",\"p\":\"nah-NSTIHK\",\"o\":\"Old English\",\"y\":5,\"bp\":26,\"m\":\"non-stick\",\"sy\":\"naa.nstih.k\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"physics\",\"culinary\",\"household\",\"ooldeng\"]},{\"w\":\"nonstop\",\"d\":\"a flight made without intermediate stops between source and destination\",\"s\":\"How many nonstops are there to Dallas?\",\"p\":\"nah-NSTAHP\",\"o\":\"Latin\",\"y\":3,\"bp\":30,\"m\":\"non-stop\",\"sy\":\"naa.nstaa.p\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpayment\",\"d\":\"act of failing to meet a financial obligation\",\"p\":\"nah-NPAY-muhnt\",\"o\":\"Latin\",\"y\":6,\"bp\":34,\"m\":\"nonpaiment\",\"sy\":\"naa.npey.mah.nt\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonplussed\",\"d\":\"be a mystery or bewildering to\",\"s\":\"The experienced teacher was completely nonplussed when a parrot flew through the classroom window, calmly asking a student to open the door so the bird could find its way out.\",\"p\":\"nah-NPLUHST\",\"o\":\"Latin\",\"y\":6,\"bp\":32,\"m\":\"nonplused\",\"sy\":\"naa.nplah.st\",\"nt\":\"Open\",\"ps\":\"verb\",\"t\":[\"olatin\"]},{\"w\":\"nonrenewable\",\"d\":\"that can not be renewed\",\"p\":\"nah-nree-NOO-uh-buhl\",\"o\":\"French\",\"y\":8,\"bp\":38,\"m\":\"nonrenewible\",\"sy\":\"naa.nriy.nuw.ah.bah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"nonresident\",\"d\":\"someone who does not live in a particular place\",\"s\":\"Described by an admiring nonresident as a green and pleasant land.\",\"p\":\"nah-NREH-zuh-duhnt\",\"o\":\"Latin\",\"y\":6,\"bp\":36,\"m\":\"nonresidant\",\"sy\":\"naa.nreh.zah.dah.nt\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonresidents\",\"d\":\"someone who does not live in a particular place\",\"p\":\"nah-NREH-zuh-duhnts\",\"o\":\"Latin\",\"y\":7,\"bp\":37,\"m\":\"nonresidants\",\"sy\":\"naa.nreh.zah.dah.nts\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsectarian\",\"d\":\"not tied to any one religion, church, or group\",\"s\":\"Religious training in a nonsectarian atmosphere.\",\"p\":\"nah-nseh-KTEH-ree-uhn\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"m\":\"nonsecterian\",\"sy\":\"naa.nseh.kteh.riy.ah.n\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsensical\",\"d\":\"incongruous;inviting ridicule\",\"p\":\"nah-NSEH-nsih-kuhl\",\"o\":\"Latin\",\"y\":5,\"bp\":36,\"m\":\"nonsensicle\",\"sy\":\"naa.nseh.nsih.kah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspecific\",\"d\":\"not caused by a specific agent; used also of staining in making microscope slides\",\"p\":\"nah-nspuh-SIH-fihk\",\"o\":\"Latin\",\"y\":6,\"bp\":36,\"m\":\"nonspeciffic\",\"sy\":\"naa.nspah.sih.fih.k\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonstandard\",\"d\":\"not following the usual or accepted rules of a language\",\"s\":\"Saying \\\"ain't\\\" is considered nonstandard in a formal essay, even though people say it every day.\",\"p\":\"nah-NSTA-nderd\",\"o\":\"Latin\",\"y\":6,\"bp\":34,\"m\":\"nonstanded\",\"sy\":\"naa.nstae.nder.d\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsurgical\",\"d\":\"not surgical\",\"p\":\"nah-NSUR-jih-kuhl\",\"o\":\"Latin\",\"y\":6,\"bp\":36,\"m\":\"nonsurgicle\",\"sy\":\"naa.nser.jhih.kah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonprescription\",\"d\":\"purchasable without a doctor's prescription\",\"p\":\"nah-npruh-SKRIH-pshuhn\",\"o\":\"Latin\",\"y\":7,\"bp\":39,\"m\":\"nonprescripion\",\"sy\":\"naa.nprah.skrih.pshah.n\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"olatin\"]},{\"w\":\"nonproductive\",\"d\":\"not directly productive\",\"s\":\"The committee decided that spending three hours debating a topic already settled was nonproductive, and they redirected their energy toward planning the upcoming community fundraiser instead.\",\"p\":\"nah-npruh-DUH-ktihv\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"m\":\"nonproductve\",\"sy\":\"naa.nprah.dah.ktih.v\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprofessional\",\"d\":\"not professional; not engaged in a profession or engaging in as a profession or for gain\",\"s\":\"The town team was made up of nonprofessional players who all had other jobs during the week.\",\"p\":\"nah-npruh-FEH-shuh-nuhl\",\"o\":\"Latin\",\"y\":8,\"bp\":41,\"m\":\"nonprofesional\",\"sy\":\"naa.nprah.feh.shah.nah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"jobs\",\"olatin\"]},{\"w\":\"nonproliferation\",\"d\":\"the prevention of something increasing or spreading (especially the prevention of an increase in the number of countries possessing nuclear weapons)\",\"s\":\"They protested that the nonproliferation treaty was just a plot to maintain the hegemony of those who already had nuclear weapons.\",\"p\":\"nah-npruh-lih-fer-AY-shuhn\",\"o\":\"Latin\",\"y\":7,\"bp\":43,\"sy\":\"naa.nprah.lih.fer.ey.shah.n\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"war\",\"numbers\",\"olatin\"]},{\"w\":\"nonresidential\",\"d\":\"not residential\",\"s\":\"The commercial or nonresidential areas of a town.\",\"p\":\"nah-nreh-zuh-DEH-nshuhl\",\"o\":\"Latin\",\"y\":7,\"bp\":40,\"m\":\"nonresidencial\",\"sy\":\"naa.nreh.zah.deh.nshah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperson\",\"d\":\"a person regarded as nonexistent and having no rights; a person whose existence is systematically ignored (especially for ideological or political reasons)\",\"s\":\"The former senator is treated as a nonperson by this administration.\",\"p\":\"NON-per-sun\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"m\":\"nonpersen\",\"sy\":\"non.per.son\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonplus\",\"d\":\"be a mystery or bewildering to\",\"s\":\"The magician's final trick managed to nonplus even the most skeptical members of the audience.\",\"p\":\"non-PLUS\",\"o\":\"Latin\",\"y\":8,\"bp\":71,\"m\":\"nonpluss\",\"sy\":\"non.plus\",\"nt\":\"Open | North South Finals\",\"ps\":\"verb\",\"t\":[\"olatin\"]},{\"w\":\"nonplused\",\"d\":\"be a mystery or bewildering to\",\"s\":\"She was completely nonplused by the surprise ending of the novel and had to reread the final chapter twice.\",\"p\":\"non-PLUZD\",\"o\":\"Latin\",\"y\":7,\"bp\":31,\"m\":\"nonplussed\",\"sy\":\"non.plused\",\"nt\":\"Open\",\"ps\":\"verb\",\"t\":[\"olatin\"]},{\"w\":\"nonpluses\",\"d\":\"be a mystery or bewildering to\",\"s\":\"The magician's impossible trick nonpluses even the most skeptical members of the audience.\",\"p\":\"non-PLOO-sez\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"m\":\"nonplusses\",\"sy\":\"non.plus.es\",\"nt\":\"Open\",\"ps\":\"verb\",\"t\":[\"olatin\"]},{\"w\":\"nonpolar\",\"d\":\"Describing a molecule or chemical bond that has no separation of electrical charge, meaning neither end carries a positive or negative charge; not ionic in nature.\",\"s\":\"Water is polar, but oil is nonpolar, which is why the two liquids refuse to mix.\",\"p\":\"non-POH-ler\",\"o\":\"Latin\",\"y\":6,\"bp\":32,\"m\":\"nonpollar\",\"sy\":\"non.po.lar\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonporous\",\"d\":\"not porous; especially not having vessels that appear as pores\",\"s\":\"The nonporous granite countertop resisted stains far better than the softer stone.\",\"p\":\"non-POR-us\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"nonporrous\",\"sy\":\"non.po.rous\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"materials\",\"ogreek\"]},{\"w\":\"nonrandom\",\"d\":\"Not based on chance or randomness; following a definite pattern, plan, or rule rather than occurring unpredictably.\",\"s\":\"The scientist confirmed that the clustering of stars was nonrandom and followed a distinct pattern.\",\"p\":\"non-RAN-dum\",\"o\":\"Latin\",\"y\":7,\"bp\":33,\"m\":\"nonrandome\",\"sy\":\"non.ran.dom\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreader\",\"d\":\"a person who cannot read, or who chooses not to read\",\"s\":\"The teacher used picture books and audio recordings to help every nonreader in her class catch up.\",\"p\":\"non-REE-der\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"m\":\"nonreeder\",\"sy\":\"non.read.er\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrigid\",\"d\":\"not stiff; able to bend, flex, or change shape\",\"s\":\"The nonrigid blimp kept its shape only because of the pressurized helium inside its envelope.\",\"p\":\"non-RIJ-id\",\"o\":\"Latin\",\"y\":8,\"bp\":32,\"sy\":\"non.rig.id\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsenses\",\"d\":\"a message that seems to convey no meaning\",\"s\":\"The toddler babbled cheerful nonsenses that made everyone in the room burst out laughing.\",\"p\":\"NON-sen-sez\",\"o\":\"Latin\",\"y\":7,\"bp\":33,\"m\":\"nonsences\",\"sy\":\"non.sens.es\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsexual\",\"d\":\"not having or involving sex\",\"s\":\"The friendship between the two characters was purely nonsexual, built entirely on mutual respect.\",\"p\":\"non-SEK-shoo-ul\",\"o\":\"Latin\",\"y\":6,\"bp\":34,\"m\":\"nonsexuel\",\"sy\":\"non.sex.u.al\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonskid\",\"d\":\"designed to reduce or prevent skidding\",\"s\":\"The coach insisted that all players wear nonskid shoes on the freshly waxed gym floor.\",\"p\":\"non-SKID\",\"o\":\"Norse\",\"y\":7,\"bp\":26,\"m\":\"nonskidd\",\"sy\":\"non.skid\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"onordic\"]},{\"w\":\"nonslip\",\"d\":\"designed to reduce or prevent slipping\",\"s\":\"The elderly woman placed a nonslip mat in her bathtub to avoid dangerous falls.\",\"p\":\"non-SLIP\",\"o\":\"Old English\",\"y\":6,\"bp\":26,\"m\":\"non-slip\",\"sy\":\"non.slip\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ooldeng\"]},{\"w\":\"nonsocial\",\"d\":\"of plants and animals; not growing or living in groups or colonies\",\"s\":\"Certain spider species are nonsocial and aggressively defend their territory from others of their kind.\",\"p\":\"non-SOH-shul\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"m\":\"nonsociel\",\"sy\":\"non.so.cial\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"animals\",\"botany\",\"olatin\"]},{\"w\":\"nonsuch\",\"d\":\"model of excellence or perfection of a kind; one having no equal\",\"s\":\"The legendary chess player was considered a nonsuch, a genius without rival in the entire world.\",\"p\":\"NON-such\",\"o\":\"Old English\",\"y\":7,\"bp\":26,\"m\":\"nonesuch\",\"sy\":\"non.such\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ooldeng\"]},{\"w\":\"nonsuches\",\"d\":\"model of excellence or perfection of a kind; one having no equal\",\"s\":\"History remembers both artists as nonsuches whose brilliance set a standard no one has since matched.\",\"p\":\"NON-such-ez\",\"o\":\"Old English\",\"y\":9,\"bp\":29,\"m\":\"nonesuches\",\"sy\":\"non.such.es\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ooldeng\"]},{\"w\":\"nonpartisan\",\"d\":\"not favoring any political party or side\",\"s\":\"The judge tried to make a nonpartisan decision that did not favor either political party.\",\"p\":\"nah-NPAH-rtuh-zuhn\",\"o\":\"French\",\"y\":5,\"bp\":36,\"m\":\"nonpartisian\",\"sy\":\"naa.npaa.rtah.zah.n\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"character\",\"politics\",\"ofrench\"]},{\"w\":\"nonpoisonous\",\"d\":\"not producing poison\",\"s\":\"The ranger assured us that the small green snake we found was nonpoisonous and harmless.\",\"p\":\"nah-NPOY-zuh-nuhs\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"m\":\"nonpoisonus\",\"sy\":\"naa.npoy.zah.nah.s\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpolitical\",\"d\":\"not political\",\"s\":\"The charity insisted its food drive was a nonpolitical event open to everyone regardless of beliefs.\",\"p\":\"nah-npuh-LIH-tih-kuhl\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"m\":\"nonpoliticle\",\"sy\":\"naa.npah.lih.tih.kah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonsmokers\",\"d\":\"a person who does not smoke tobacco\",\"s\":\"The restaurant reserved a separate section for nonsmokers who wanted to enjoy their meal without cigarette fumes.\",\"p\":\"nah-NSMOH-kerz\",\"o\":\"Old English\",\"y\":6,\"bp\":30,\"m\":\"nonsmokkers\",\"sy\":\"naa.nsmow.ker.z\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ooldeng\"]},{\"w\":\"nonstarter\",\"d\":\"something that has no chance of working or being accepted\",\"s\":\"The coach said that any plan without proper funding was a nonstarter from the very beginning.\",\"p\":\"nah-NSTAH-rter\",\"o\":\"Old English\",\"y\":6,\"bp\":30,\"m\":\"nonstater\",\"sy\":\"naa.nstaa.rter\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ooldeng\"]},{\"w\":\"nonsensicality\",\"d\":\"a message that seems to convey no meaning\",\"s\":\"The comedian's act was full of pure nonsensicality, leaving the audience laughing at total absurdity.\",\"p\":\"non-sen-sih-KAL-ih-tee\",\"o\":\"French\",\"y\":9,\"bp\":30,\"sy\":\"non.sen.si.cal.i.ty\",\"ps\":\"noun\",\"t\":[\"ofrench\"]},{\"w\":\"nonobedience\",\"d\":\"The refusal or failure to comply with rules, commands, or authority; the state of not being obedient or submissive to established guidelines.\",\"s\":\"The students' nonobedience to the fire drill rules frustrated the principal.\",\"p\":\"non-oh-BEE-dee-uns\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonobe.di.ence\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonobese\",\"d\":\"Not having excess body fat that qualifies as obesity; describing a person whose body mass index falls below the threshold for obesity.\",\"s\":\"The study compared health outcomes in nonobese and obese participants.\",\"p\":\"non-oh-BEES\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobesity\",\"d\":\"The state or condition of not being obese; the absence of excessive body weight that poses health risks.\",\"s\":\"Researchers linked nonobesity to better cardiovascular health in the long-term study.\",\"p\":\"non-oh-BEE-sih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonobe.si.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonobject\",\"d\":\"Something that is not a physical object or that lacks the properties of a tangible, concrete thing.\",\"s\":\"In abstract art, the painting depicted a nonobject that existed only as color and form.\",\"p\":\"non-OB-jekt\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonob.ject\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonobjectifiable\",\"d\":\"Not capable of being treated as or reduced to a mere object; unable to be objectified.\",\"s\":\"The artist's emotion was nonobjectifiable and could not be reduced to a simple image.\",\"p\":\"non-ob-JEK-tih-fy-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonob.jec.ti.fi.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobjectified\",\"d\":\"Not having been treated as an object; describing a person or thing whose full humanity or complexity has been respected and not reduced to a simple object.\",\"s\":\"The campaign aimed to show women as nonobjectified, fully realized human beings.\",\"p\":\"non-ob-JEK-tih-fyd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonob.jec.ti.fied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobjecting\",\"d\":\"Not raising an objection or protest; accepting without opposition or complaint.\",\"s\":\"The nonobjecting committee members allowed the proposal to pass without debate.\",\"p\":\"non-ob-JEK-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonob.ject.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobjectivism\",\"d\":\"A philosophy or artistic approach that rejects objective reality as the basis for art or thought, favoring abstract or subjective expression instead.\",\"s\":\"The art movement embraced nonobjectivism, rejecting realistic depictions entirely.\",\"p\":\"non-ob-JEK-tih-viz-um\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonob.jec.tivism\",\"ps\":\"noun\",\"t\":[\"painting\",\"logic\",\"olatin\"]},{\"w\":\"nonobjectivist\",\"d\":\"A person who holds or practices nonobjectivism, rejecting the idea that art or knowledge must be grounded in objective reality.\",\"s\":\"As a nonobjectivist, she believed truth was always shaped by personal experience.\",\"p\":\"non-ob-JEK-tih-vist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonob.jec.tivist\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonobjectivity\",\"d\":\"The quality or state of lacking objectivity; the absence of impartiality or freedom from personal bias.\",\"s\":\"The judge was criticized for nonobjectivity when ruling on his friend's case.\",\"p\":\"non-ob-jek-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonob.jec.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonoblate\",\"d\":\"Not having a flattened or oblate shape; describing a sphere or body that is not compressed at the poles.\",\"s\":\"The planet's shape was described as nonoblate, meaning it wasn't flattened at the poles.\",\"p\":\"non-OB-layt\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobligate\",\"d\":\"Not required or compelled by obligation; describing an organism or action that is not restricted to one particular condition or behavior.\",\"s\":\"The bacteria were nonobligate anaerobes, able to survive with or without oxygen.\",\"p\":\"non-OB-lih-gayt\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonob.li.gate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobligated\",\"d\":\"Not bound by a legal, moral, or contractual obligation; free from any duty or requirement to act.\",\"s\":\"Volunteers are nonobligated participants who choose to help freely.\",\"p\":\"non-OB-lih-gay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"nonob.li.gat.ed\",\"ps\":\"adjective\",\"t\":[\"law\",\"logic\",\"olatin\"]},{\"w\":\"nonobservable\",\"d\":\"Not able to be seen, detected, or measured through direct observation; beyond the reach of the senses or instruments.\",\"s\":\"Some subatomic particles are nonobservable with current technology.\",\"p\":\"non-ob-ZUR-vuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonob.serv.able\",\"ps\":\"adjective\",\"t\":[\"music\",\"numbers\",\"olatin\"]},{\"w\":\"nonobservational\",\"d\":\"Not based on or involving direct observation; describing a method or approach that does not rely on watching or measuring phenomena firsthand.\",\"s\":\"The theoretical study was nonobservational, relying on math rather than experiments.\",\"p\":\"non-ob-zur-VAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonob.ser.va.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobsessive\",\"d\":\"Not characterized by obsession; describing a person or attitude that is relaxed and not fixated on any particular idea or activity.\",\"s\":\"She described herself as nonobsessive about cleanliness, happy with 'good enough.'.\",\"p\":\"non-ob-SES-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonob.ses.sive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonobsolescence\",\"d\":\"The quality or state of not becoming outdated or obsolete; the ability to remain relevant and useful over time.\",\"s\":\"The manufacturer boasted of the product's nonobsolescence, claiming it would never go out of date.\",\"p\":\"non-ob-suh-LES-unts\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonob.so.les.cence\",\"ps\":\"noun\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonobsolescent\",\"d\":\"Not in the process of becoming obsolete or outdated; remaining current and in use.\",\"s\":\"Good design creates nonobsolescent products that remain useful for decades.\",\"p\":\"non-ob-suh-LES-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonob.so.les.cent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobsolete\",\"d\":\"Not obsolete or out of date; still in current use, relevant, or functioning as intended.\",\"s\":\"The classic technique proved nonobsolete when engineers returned to using it.\",\"p\":\"non-ob-suh-LEET\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonob.so.lete\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobstetric\",\"d\":\"Not relating to obstetrics or the branch of medicine dealing with pregnancy and childbirth.\",\"s\":\"The patient was referred to a nonobstetric specialist since her issue wasn't pregnancy-related.\",\"p\":\"non-ob-STET-rik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonob.stet.ric\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonobstructed\",\"d\":\"Not blocked, hindered, or impeded; having a clear and unimpeded path or passage.\",\"s\":\"Emergency crews confirmed the road was nonobstructed and safe to travel.\",\"p\":\"non-ob-STRUK-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonob.struct.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobstructing\",\"d\":\"Not blocking or getting in the way; describing something that allows free passage or movement.\",\"s\":\"The slim design of the post was nonobstructing, allowing a clear view of the stage.\",\"p\":\"non-ob-STRUK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonob.struct.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobstructive\",\"d\":\"Not causing obstruction or blockage; allowing things to flow or move freely without interference.\",\"s\":\"The new speed bump design was nonobstructive for emergency vehicles.\",\"p\":\"non-ob-STRUK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonob.struc.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobtainable\",\"d\":\"Not able to be obtained, acquired, or achieved; impossible to get or secure.\",\"s\":\"The rare gem was nonobtainable through regular market channels.\",\"p\":\"non-ob-TAY-nuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonob.tain.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonobvious\",\"d\":\"Not immediately clear or easy to understand; requiring thought or investigation to recognize or discover.\",\"s\":\"The solution to the puzzle was nonobvious, requiring creative thinking to discover.\",\"p\":\"non-OB-vee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonob.vi.ous\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonobviousness\",\"d\":\"The quality of not being obvious or immediately apparent; in patent law, the requirement that an invention must not be evident to someone skilled in the relevant field.\",\"s\":\"Patent law requires nonobviousness, meaning the invention can't be something anyone would think of.\",\"p\":\"non-OB-vee-us-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonob.vi.ous.ness\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonoccidental\",\"d\":\"Not of or relating to the Western world or its cultures, traditions, and peoples.\",\"s\":\"The museum featured nonoccidental art from Asia, Africa, and the Middle East.\",\"p\":\"non-ok-sih-DEN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonoc.ci.den.tal\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"nonoccipital\",\"d\":\"Not relating to or located in the occipital region, which is the back and lower part of the skull.\",\"s\":\"The neurologist noted that the patient's headache was nonoccipital, originating at the front of the skull.\",\"p\":\"non-ok-SIP-ih-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"nonoc.cip.i.tal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonoccupant\",\"d\":\"A person who does not occupy or reside in a particular place, vehicle, or property.\",\"s\":\"The landlord noted that the apartment had been a nonoccupant unit for three months before the new family moved in.\",\"p\":\"non-OK-yoo-punt\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonoc.cu.pant\",\"ps\":\"noun\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonocean\",\"d\":\"Not relating to or consisting of ocean; describing a body of water or geographic region that is not an ocean.\",\"s\":\"The geography report divided Earth's water into nonocean sources, such as rivers, lakes, and glaciers.\",\"p\":\"non-OH-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"nono.cean\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"nonoceanic\",\"d\":\"Not of, relating to, or located in the ocean; describing environments or regions that are not associated with the sea.\",\"s\":\"Scientists studied nonoceanic climates to understand how landlocked regions experience different weather patterns.\",\"p\":\"non-oh-shee-AN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nono.cean.ic\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"waterways\",\"olatin\"]},{\"w\":\"nonoceanographic\",\"d\":\"Not relating to oceanography, the scientific study of the ocean and its physical, chemical, and biological properties.\",\"s\":\"The research team pursued nonoceanographic studies, focusing on freshwater ecosystems instead of the sea.\",\"p\":\"non-oh-shee-uh-noh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nono.ceano.graph.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"waterways\",\"olatin\"]},{\"w\":\"nonocular\",\"d\":\"Not relating to or involving the eyes or the sense of sight.\",\"s\":\"The doctor explained that the patient's headaches had a nonocular cause unrelated to vision problems.\",\"p\":\"non-OK-yoo-lur\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nonoc.u.lar\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonodd\",\"d\":\"Not odd; describing a number or thing that is even or does not possess the quality of being odd.\",\"s\":\"In math class, we listed nonodd numbers, which included all the even integers on the chart.\",\"p\":\"non-OD\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.odd\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonodontogenic\",\"d\":\"Not originating from or caused by tooth-forming tissues; describing a cyst, tumor, or lesion that does not arise from dental structures.\",\"s\":\"The oral surgeon determined that the jaw cyst was nonodontogenic, meaning it did not originate from tooth tissue.\",\"p\":\"non-oh-don-toh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.odon.to.genic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonoestrogenic\",\"d\":\"Not producing or relating to estrogenic effects; describing a substance that does not mimic or stimulate the action of the hormone estrogen.\",\"s\":\"Researchers developed a nonoestrogenic compound that could treat certain conditions without affecting hormone levels.\",\"p\":\"non-es-troh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonoe.stro.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoffender\",\"d\":\"A person who has not committed an offense or crime; someone with no history of wrongdoing or illegal behavior.\",\"s\":\"The program distinguished between repeat criminals and the nonoffender who had accidentally broken a minor rule.\",\"p\":\"non-uh-FEN-dur\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonof.fend.er\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonoffending\",\"d\":\"Not committing an offense or causing harm; describing a person or behavior that does not violate rules, laws, or standards of conduct.\",\"s\":\"The judge praised the nonoffending parent for protecting the child throughout the difficult legal case.\",\"p\":\"non-uh-FEN-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonof.fend.ing\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonoffensive\",\"d\":\"Not causing offense or harm; inoffensive, harmless, and unlikely to upset or antagonize others.\",\"s\":\"The coach designed a nonoffensive game strategy that focused entirely on strong defense and careful positioning.\",\"p\":\"non-uh-FEN-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonof.fen.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoffice\",\"d\":\"A space or environment that does not function as a traditional office, often lacking the formal structures and features associated with typical workplace settings.\",\"s\":\"The startup converted the warehouse into a nonoffice creative space with no cubicles or traditional desks.\",\"p\":\"non-OF-is\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonof.fice\",\"ps\":\"noun\",\"t\":[\"ecology\",\"festivals\",\"olatin\"]},{\"w\":\"nonofficer\",\"d\":\"A person who does not hold an officer rank or position, especially in a military, police, or organizational context.\",\"s\":\"As a nonofficer volunteer, Marcus helped organize the event without holding any formal leadership title.\",\"p\":\"non-OF-ih-sur\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonof.fi.cer\",\"ps\":\"noun\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonofficiating\",\"d\":\"Not serving in an official capacity or performing the duties of an official, referee, or presiding authority at an event or ceremony.\",\"s\":\"The nonofficiating referee sat in the stands and observed the game without making any calls.\",\"p\":\"nahn-uh-FISH-ee-ay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonof.fi.ci.at.ing\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"religion\",\"sports\",\"olatin\"]},{\"w\":\"nonohmic\",\"d\":\"Not following Ohm's Law, meaning the relationship between voltage and current is not constant or proportional in the material or device.\",\"s\":\"The diode is a nonohmic device because its resistance changes depending on the voltage applied to it.\",\"p\":\"nahn-OHM-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"law\",\"tools\",\"olatin\"]},{\"w\":\"nonoil\",\"d\":\"Not involving, derived from, or related to oil; describing products, industries, or substances that are free from oil content.\",\"s\":\"The chef recommended nonoil cooking sprays for people trying to reduce fat in their daily meals.\",\"p\":\"nahn-OYL\",\"o\":\"Latin\",\"y\":8,\"bp\":16,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoiled\",\"d\":\"Not treated, coated, or lubricated with oil; describing a surface or mechanism that has not had oil applied to it.\",\"s\":\"The nonoiled machine parts squeaked loudly, alerting the mechanic that maintenance was urgently needed.\",\"p\":\"nahn-OYLD\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonoily\",\"d\":\"Not having the characteristics or texture of oil; lacking a greasy, slick, or fatty quality.\",\"s\":\"She preferred nonoily sunscreen because it kept her skin feeling fresh and smooth all day long.\",\"p\":\"nahn-OY-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":17,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonold\",\"d\":\"Not old; describing something that is new, recent, or youthful rather than aged or long-established.\",\"s\":\"The museum exhibit celebrated nonold inventions created within the last decade by young innovators.\",\"p\":\"nahn-OHLD\",\"o\":\"Latin\",\"y\":8,\"bp\":16,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoleaginous\",\"d\":\"Not oily, greasy, or fatty in nature; lacking the smooth, slippery qualities associated with oils and lipids.\",\"s\":\"The scientist searched for a nonoleaginous binder that would hold the mixture together without any oily residue.\",\"p\":\"nahn-oh-lee-AJ-uh-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonoleagi.nous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonolfactory\",\"d\":\"Not related to or involving the sense of smell; describing stimuli, nerves, or responses that have nothing to do with detecting odors.\",\"s\":\"The neurologist tested nonolfactory senses first, checking vision and hearing before assessing the patient's sense of smell.\",\"p\":\"nahn-ol-FAK-tuh-ree\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"nonol.fac.to.ry\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonomnipotence\",\"d\":\"The state or condition of lacking unlimited power; the absence of the ability to do all things or control every outcome.\",\"p\":\"nahn-om-NIP-uh-tence\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonom.nipo.tence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonomnipotent\",\"d\":\"Not all-powerful; describing a being or force that does not possess unlimited power or the ability to accomplish anything.\",\"s\":\"Even the most powerful leaders are nonomnipotent, unable to control every outcome no matter how hard they try.\",\"p\":\"nahn-om-NIP-uh-tent\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonom.nipo.tent\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonomniscience\",\"d\":\"The lack of complete or unlimited knowledge; the state of not knowing everything that exists or has occurred.\",\"s\":\"The student's essay explored the idea that nonomniscience means every human must accept the limits of their own knowledge.\",\"p\":\"nahn-om-NISH-ence\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonom.ni.science\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonomniscient\",\"d\":\"Not all-knowing; describing a being or mind that does not possess complete knowledge of all things past, present, or future.\",\"s\":\"Detective Rivera admitted she was nonomniscient and relied on clues rather than any magical knowledge of the truth.\",\"p\":\"nahn-om-NISH-ent\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonom.ni.scient\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonontological\",\"d\":\"Not relating to ontology, the philosophical study of the nature of being and existence; not concerned with questions about what fundamentally exists.\",\"s\":\"The professor dismissed the argument as nonontological because it ignored the fundamental question of what actually exists.\",\"p\":\"nahn-on-tuh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonon.to.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonoolitic\",\"d\":\"Not composed of or characterized by oolites, which are small spherical grains formed by layers of minerals; describing rock or sediment lacking this rounded grain structure.\",\"s\":\"The geologist classified the smooth limestone as nonoolitic since it lacked the tiny spherical grains typical of oolite rock.\",\"p\":\"nahn-oh-oh-LIT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"minerals\",\"character\",\"olatin\"]},{\"w\":\"nonopacity\",\"d\":\"The quality or condition of being transparent or translucent; the absence of opacity, meaning light can pass through freely.\",\"s\":\"The glass designer aimed for maximum nonopacity so that light would pass through the panel completely unobstructed.\",\"p\":\"nahn-oh-PAS-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonopac.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonopalescent\",\"d\":\"Not displaying the milky, rainbow-like shimmer characteristic of an opal; lacking iridescent or multicolored reflected light.\",\"s\":\"Unlike the shimmering gemstone next to it, the plain white pebble was completely nonopalescent under the lamp.\",\"p\":\"nahn-oh-puh-LES-ent\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonopales.cent\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"colors\",\"olatin\"]},{\"w\":\"nonopaque\",\"d\":\"Not blocking the passage of light; allowing light to pass through so that objects on the other side can be seen.\",\"s\":\"The scientist chose a nonopaque container so she could observe the chemical reaction without opening the lid.\",\"p\":\"nahn-oh-PAYK\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonopera\",\"d\":\"A musical or theatrical performance that deliberately lacks the defining features of traditional opera, such as full orchestration or sung dialogue throughout.\",\"s\":\"The music festival featured a nonopera vocal performance that blended jazz and folk singing instead of classical arias.\",\"p\":\"nahn-OP-er-uh\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.opera\",\"ps\":\"noun\",\"t\":[\"music\",\"festivals\",\"olatin\"]},{\"w\":\"nonoperatic\",\"d\":\"Not characteristic of or related to opera; lacking the dramatic singing, large orchestras, or stylistic conventions typical of operatic performance.\",\"s\":\"The drama teacher praised Maya's calm, nonoperatic delivery, which felt natural and believable on stage.\",\"p\":\"nahn-op-er-AT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.op.er.at.ic\",\"ps\":\"adjective\",\"t\":[\"music\",\"stage\",\"olatin\"]},{\"w\":\"nonoperating\",\"d\":\"Not currently functioning, running, or performing its intended role; describing a machine, system, or business unit that is inactive or not in use.\",\"s\":\"The factory listed its nonoperating machinery as assets even though the equipment had not been used in years.\",\"p\":\"NAH-NAW-per-ay-tih-ng\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"naa.nao.per.ey.tih.ng\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonoperator\",\"d\":\"A person or entity that provides financial investment or ownership in a project but does not actively manage or run its day-to-day operations.\",\"s\":\"As a nonoperator investor, she funded the oil well project but was not involved in the day-to-day drilling decisions.\",\"p\":\"nahn-OP-er-ay-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.op.er.a.tor\",\"ps\":\"noun\",\"t\":[\"economy\",\"time\",\"olatin\"]},{\"w\":\"nonoperculate\",\"d\":\"Not having an operculum, which is a lid-like covering or flap; describing organisms or structures that lack this protective cap.\",\"s\":\"The botanist identified the moss as nonoperculate because its spore capsule lacked the small lid-like covering.\",\"p\":\"nahn-oh-PER-kyoo-lit\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonop.er.cu.late\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoperculated\",\"d\":\"Lacking an operculum or lid-like covering; used to describe biological structures or shells that have no protective flap attached.\",\"s\":\"The aquatic snail specimen was classified as nonoperculated since researchers found no protective plate over its opening.\",\"p\":\"nahn-oh-PER-kyoo-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonop.er.cu.lat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonophthalmic\",\"d\":\"Not relating to or involving the eye; describing conditions, treatments, or fields of study that have nothing to do with vision or eye health.\",\"s\":\"The specialist confirmed the vision loss had a nonophthalmic source, tracing it back to a neurological condition.\",\"p\":\"nahn-off-THAL-mik\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonoph.thalmic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonopinionated\",\"d\":\"Not holding or expressing strong personal opinions; describing a person or statement that remains neutral, open-minded, and free from bias.\",\"s\":\"The mediator remained completely nonopinionated, listening to both sides without ever expressing a personal preference.\",\"p\":\"nahn-uh-PIN-yun-ay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonopin.ion.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonopportunistic\",\"d\":\"Not taking selfish advantage of situations or other people's weaknesses for personal gain; acting with consistent principles rather than exploiting circumstances.\",\"s\":\"The volunteer's nonopportunistic motives were clear because she continued helping even when no one was watching.\",\"p\":\"nahn-op-er-too-NIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonop.por.tunis.tic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonopposable\",\"d\":\"Not capable of being placed opposite another digit, especially describing a thumb or toe that cannot press against other fingers to grip objects.\",\"s\":\"Unlike a human thumb, a fish fin is nonopposable and cannot grip objects.\",\"p\":\"nahn-uh-POH-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonop.pos.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonopposed\",\"d\":\"Not facing opposition, resistance, or a competing candidate or argument; running or standing without anyone working against it.\",\"s\":\"The student council president ran nonopposed, so no election was needed.\",\"p\":\"nahn-uh-POHZD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonop.posed\",\"ps\":\"adjective\",\"t\":[\"politics\",\"logic\",\"olatin\"]},{\"w\":\"nonopposing\",\"d\":\"Not acting in opposition or resistance to something; describing a force, group, or argument that does not work against another.\",\"s\":\"The two teams took nonopposing routes through the forest during the scavenger hunt.\",\"p\":\"nahn-uh-POH-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonop.pos.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"olatin\"]},{\"w\":\"nonopposition\",\"d\":\"The absence of resistance, disagreement, or competing forces; a state in which no one or nothing actively works against a proposal or action.\",\"s\":\"The committee approved the plan with complete nonopposition from all members.\",\"p\":\"nahn-op-uh-ZIH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonop.po.si.tion\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonoppositional\",\"d\":\"Not characterized by conflict, resistance, or taking a stance against something; describing a cooperative or neutral approach that avoids confrontation.\",\"s\":\"The student's nonoppositional attitude made group projects much easier for everyone.\",\"p\":\"nahn-op-uh-ZIH-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonop.po.si.tion.al\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonoppressed\",\"d\":\"Not subjected to unjust authority, hardship, or cruel treatment; describing individuals or groups who are free from systematic persecution or burden.\",\"s\":\"Citizens in that country considered themselves nonoppressed because they enjoyed full freedoms.\",\"p\":\"nahn-uh-PREST\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonop.pressed\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonoppression\",\"d\":\"The absence of unjust or cruel exercise of power over others; a condition in which people are not subjected to harsh authority or systematic mistreatment.\",\"s\":\"The new constitution was celebrated as a symbol of nonoppression for all people.\",\"p\":\"nahn-uh-PRESH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonop.pres.sion\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonoppressive\",\"d\":\"Not characterized by the unjust or harsh use of power or authority; describing systems, policies, or people that do not burden or mistreat others.\",\"s\":\"The teacher's nonoppressive classroom rules encouraged students to speak freely.\",\"p\":\"nahn-uh-PRES-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonop.pres.sive\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"politics\",\"character\",\"olatin\"]},{\"w\":\"nonopsonic\",\"d\":\"Not relating to or having the properties of opsonins, which are substances that coat bacteria to make them easier for immune cells to destroy.\",\"s\":\"The researchers noted that the antibody was nonopsonic and could not help white blood cells engulf bacteria.\",\"p\":\"nahn-op-SON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonop.son.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"fabrics\",\"olatin\"]},{\"w\":\"nonoptimal\",\"d\":\"Not at the best or most effective level; describing a solution, condition, or performance that falls short of the ideal or most efficient outcome.\",\"s\":\"Running in heavy boots is a nonoptimal strategy for winning a race.\",\"p\":\"nahn-OP-tih-mul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonop.ti.mal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoptimizable\",\"d\":\"Not capable of being improved to reach the best possible state; describing a system or process that cannot be adjusted for maximum efficiency or performance.\",\"s\":\"The old computer program had nonoptimizable code that could never run faster.\",\"p\":\"nahn-OP-tih-my-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonop.ti.miz.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoptimized\",\"d\":\"Not adjusted or refined to achieve the best possible performance or efficiency; describing a system, process, or design that has not been fine-tuned.\",\"s\":\"The nonoptimized website loaded slowly because the images were too large.\",\"p\":\"nahn-OP-tih-myzd\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonop.ti.mized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoptional\",\"d\":\"Not left to personal choice; mandatory or required, meaning it must be done or included with no possibility of skipping or refusing.\",\"s\":\"Wearing a seatbelt is nonoptional by law in most states.\",\"p\":\"nahn-OP-shun-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonop.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoral\",\"d\":\"Not involving or done through the mouth; relating to communication or administration that does not use spoken or oral means.\",\"s\":\"Sign language is a nonoral form of communication that uses hand movements instead of speech.\",\"p\":\"non-OR-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"nono.ral\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonorally\",\"d\":\"In a manner that does not involve the mouth; by means other than speaking or swallowing, such as through injection or a feeding tube.\",\"s\":\"The medicine was administered nonorally through an IV drip in the patient's arm.\",\"p\":\"non-OR-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nono.ral.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonorange\",\"d\":\"Not orange in color; describing any hue, shade, or tint that is distinctly different from the color orange.\",\"s\":\"The artist painted the sunset in nonorange tones, using purples and pinks instead.\",\"p\":\"non-OR-inj\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nono.r.ange\",\"ps\":\"adjective\",\"t\":[\"spices\",\"colors\",\"olatin\"]},{\"w\":\"nonorbital\",\"d\":\"Not related to or following an orbit; describing motion or a path that does not circle around a central body such as a planet or star.\",\"s\":\"The satellite's nonorbital path meant it would fall back to Earth quickly.\",\"p\":\"non-OR-bit-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nonor.bital\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"numbers\",\"olatin\"]},{\"w\":\"nonorchestral\",\"d\":\"Not involving or performed by an orchestra; referring to music or sound that does not use a full ensemble of orchestral instruments.\",\"s\":\"The film's soundtrack had a nonorchestral feel, relying mostly on electronic beats.\",\"p\":\"non-or-KES-trul\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonorches.tral\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonordained\",\"d\":\"Not officially appointed or consecrated to a religious ministry or office; describing a person who has not gone through formal ordination.\",\"s\":\"The nonordained speaker led the ceremony warmly even though he wasn't an official minister.\",\"p\":\"non-or-DAYND\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonor.dained\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonorderable\",\"d\":\"Not capable of being ordered, purchased, or arranged in sequence; describing something that cannot be requested or systematically arranged.\",\"s\":\"Some specialty items were listed as nonorderable because the company no longer made them.\",\"p\":\"non-OR-dur-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonorder.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonordered\",\"d\":\"Not arranged in any particular sequence or structure; lacking a defined order or organizational pattern.\",\"s\":\"The pile of books was completely nonordered, stacked randomly on the shelf.\",\"p\":\"non-OR-durd\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonorderly\",\"d\":\"Not arranged in an organized or systematic way; lacking neatness, structure, or proper sequence.\",\"s\":\"The nonorderly crowd rushed through the doors the moment the store opened.\",\"p\":\"non-OR-dur-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nonorder.ly\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonordinal\",\"d\":\"Not relating to a position in a ranked or sequential order; describing numbers or categories that do not indicate ranking or position.\",\"s\":\"The list used nonordinal labels like colors instead of numbered positions.\",\"p\":\"non-OR-din-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonor.di.nal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonorganic\",\"d\":\"Not derived from living organisms; referring to substances, compounds, or materials that are not produced by or related to living things.\",\"s\":\"The plastic chair is a nonorganic material that was created in a factory.\",\"p\":\"non-or-GAN-ik\",\"o\":\"Latin\",\"y\":7,\"bp\":29,\"sy\":\"nonor.gan.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonorganism\",\"d\":\"Something that is not a living organism; an entity that lacks the biological characteristics of life such as growth, reproduction, or metabolism.\",\"s\":\"A rock is a nonorganism because it has no life processes like growth or reproduction.\",\"p\":\"non-OR-guh-niz-um\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonor.gan.ism\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonorganizational\",\"d\":\"Not relating to or characteristic of a formal organization; describing activities, behaviors, or structures that exist outside institutional frameworks.\",\"s\":\"Her nonorganizational approach to studying meant her notes were scattered everywhere.\",\"p\":\"non-or-gan-ih-ZAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nonor.ga.ni.za.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonorganized\",\"d\":\"Not arranged into an orderly structure; lacking systematic planning, coordination, or formal group membership.\",\"s\":\"The nonorganized volunteers showed up without any clear plan for the cleanup.\",\"p\":\"non-OR-guh-nyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonor.ga.nized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonorganometallic\",\"d\":\"Not involving a chemical bond between a carbon atom of an organic group and a metal atom; describing compounds that lack organo-metallic structure.\",\"s\":\"The compound was classified as nonorganometallic because it contained no carbon-metal bonds.\",\"p\":\"non-or-gan-oh-meh-TAL-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonorganometal.lic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonoriginal\",\"d\":\"Not first in existence or unique; describing something that is copied, derived, or lacks novelty and creative distinction.\",\"s\":\"The painting was considered nonoriginal because it was a copy of a famous masterpiece.\",\"p\":\"non-uh-RIJ-ih-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"nono.rig.i.nal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoriginalist\",\"d\":\"A person who does not interpret laws or constitutions strictly according to their original historical meaning, instead allowing for evolving interpretations.\",\"s\":\"The nonoriginalist judge believed the Constitution should be interpreted for modern times.\",\"p\":\"non-uh-RIJ-ih-nul-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nono.rig.i.nal.ist\",\"ps\":\"noun\",\"t\":[\"law\",\"politics\",\"olatin\"]},{\"w\":\"nonornamental\",\"d\":\"Not serving a decorative purpose; describing something that is purely functional rather than intended to add beauty or visual appeal.\",\"s\":\"The nonornamental fence around the yard was plain and purely functional.\",\"p\":\"non-or-nuh-MEN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonor.na.men.tal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonorphan\",\"d\":\"A person who is not an orphan; a child or individual who still has at least one living parent or legal guardian.\",\"s\":\"Unlike his friend in the story, Jake was a nonorphan who lived happily with both parents.\",\"p\":\"non-OR-fun\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonor.phan\",\"ps\":\"noun\",\"t\":[\"law\",\"character\",\"kinship\",\"olatin\"]},{\"w\":\"nonorphaned\",\"d\":\"Not having lost both parents; describing a person who still has living parents or guardians and has not been left without family care.\",\"s\":\"The social worker confirmed the children were nonorphaned and reunited them with their family.\",\"p\":\"non-OR-fund\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonor.phaned\",\"ps\":\"adjective\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonorthodox\",\"d\":\"Not conforming to established or traditional beliefs, practices, or doctrines; describing views or methods that differ from accepted norms.\",\"s\":\"Her nonorthodox teaching style involved letting students sit on the floor and learn through games.\",\"p\":\"non-OR-thuh-doks\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonortho.dox\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"logic\",\"olatin\"]},{\"w\":\"nonorthogonal\",\"d\":\"Not at right angles to each other; describing lines, vectors, or axes that are not perpendicular and therefore share directional components.\",\"s\":\"The nonorthogonal lines in the drawing crossed at odd angles instead of perfect right angles.\",\"p\":\"non-or-THOG-uh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonorthog.o.nal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonorthogonality\",\"d\":\"The state or condition of not being orthogonal; the quality of vectors, axes, or lines that are not perpendicular to one another.\",\"s\":\"The nonorthogonality of the building's walls made the architect's calculations much harder.\",\"p\":\"non-or-thog-uh-NAL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonorthog.o.nal.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonorthographic\",\"d\":\"Not conforming to standard spelling or conventional written representation; describing a writing system or transcription that departs from official orthographic rules.\",\"s\":\"The ancient symbol system was nonorthographic because it used pictures instead of letters.\",\"p\":\"non-or-thuh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonortho.graph.ic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonorthologous\",\"d\":\"Not derived from the same ancestral gene or sequence; describing genes in different species that arose independently rather than from a common evolutionary origin.\",\"s\":\"Scientists found that the two genes were nonorthologous, meaning they evolved separately in different species.\",\"p\":\"non-or-THOL-uh-gus\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonorthol.o.gous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonorthorhombic\",\"d\":\"Not having the crystal structure of the orthorhombic system; describing a crystalline substance whose unit cell does not have three mutually perpendicular axes of unequal length.\",\"s\":\"The crystal structure was nonorthorhombic, so its angles didn't follow the standard geometric pattern.\",\"p\":\"non-or-thoh-ROM-bik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonorthorhom.bic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"nonoscillating\",\"d\":\"Not moving back and forth in a regular, repeating pattern; describing a system or signal that does not produce oscillating or wave-like motion.\",\"s\":\"The nonoscillating signal moved in a straight line without any wave-like pattern.\",\"p\":\"non-OS-ih-lay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonoscil.lat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoscillatory\",\"d\":\"not having periodic vibrations\",\"s\":\"The engineer designed a nonoscillatory circuit so the signal would remain perfectly steady without any unwanted vibrations.\",\"p\":\"non-os-IL-uh-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonoscil.la.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonosmium\",\"d\":\"Not composed of or containing osmium; describing a material or compound that lacks the dense, bluish-white metallic element osmium.\",\"s\":\"The chemist confirmed the sample was nonosmium, meaning it contained none of the rare metallic element.\",\"p\":\"non-OZ-mee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nonos.mi.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonosmotic\",\"d\":\"Not related to or operating by osmosis; describing a process or membrane that does not involve the movement of water or solvent across a semipermeable barrier.\",\"s\":\"The lab report classified the membrane transport as nonosmotic since water movement was driven by pressure rather than osmosis.\",\"p\":\"non-oz-MOT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonos.mot.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonossifying\",\"d\":\"Not converting or hardening into bone; describing tissue or a growth that does not undergo the process of ossification.\",\"s\":\"The doctor noted a nonossifying fibroma in the bone scan, meaning the fibrous tissue was not turning into bone.\",\"p\":\"non-OS-ih-fy-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"nonos.si.fy.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonostentatious\",\"d\":\"Not showy or designed to impress others; describing behavior or style that is modest and unpretentious rather than flashy or boastful.\",\"s\":\"Her nonostentatious style meant she wore simple clothes and avoided flashy jewelry even at fancy events.\",\"p\":\"non-os-ten-TAY-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonos.ten.ta.tious\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonosteogenic\",\"d\":\"Not producing or forming bone tissue; describing cells, substances, or conditions that do not stimulate or contribute to bone generation.\",\"s\":\"The biopsy revealed nonosteogenic tissue, which meant the cells were not capable of forming bone.\",\"p\":\"non-os-tee-oh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonos.teogenic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonosteoporotic\",\"d\":\"Not affected by or related to osteoporosis; describing bones or individuals that do not show the reduced density and increased brittleness associated with osteoporosis.\",\"s\":\"The elderly patient's scan was surprisingly nonosteoporotic, showing her bones were still dense and strong.\",\"p\":\"non-os-tee-oh-puh-ROT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonos.teo.porot.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonoutlet\",\"d\":\"Not serving as an outlet or point of exit; describing a wall, surface, or channel that has no opening, socket, or means of discharge.\",\"s\":\"The wall section was a nonoutlet zone, so the electrician had to run wiring to a different panel location.\",\"p\":\"non-OWT-let\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonout.let\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoutlier\",\"d\":\"A data point or value that falls within the expected range of a data set and is not statistically extreme or anomalous.\",\"s\":\"Most of the test scores were nonoutliers, clustering neatly around the class average of 82 percent.\",\"p\":\"non-OWT-ly-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonout.li.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonoutlying\",\"d\":\"Not situated far from the center or main body; describing data points, locations, or elements that remain within the typical or expected range.\",\"s\":\"The researcher focused on nonoutlying data points that represented the typical behavior of the population.\",\"p\":\"non-OWT-ly-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonout.ly.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoutput\",\"d\":\"The absence of any produced result, signal, or product; describing a system or process that generates no measurable output or outcome.\",\"s\":\"The broken printer produced nonoutput — it hummed and whirred but never delivered a single printed page.\",\"p\":\"non-OWT-poot\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonout.put\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonoval\",\"d\":\"Not shaped like an oval or egg; describing a form or figure whose outline is not rounded and elongated in the characteristic oval manner.\",\"s\":\"The scientist noted that the cell's shape was nonoval, appearing more rectangular under the microscope.\",\"p\":\"non-OH-vul\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"nono.val\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonovarian\",\"d\":\"Not relating to or originating from the ovary; describing tissue, cysts, or conditions that do not involve the female reproductive glands that produce eggs.\",\"s\":\"The doctor determined the cyst was nonovarian in origin, meaning it had developed from tissue unrelated to the ovaries.\",\"p\":\"non-oh-VAIR-ee-un\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"nono.var.i.an\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonovergrown\",\"d\":\"Not overgrown; describing an area where plants or vegetation have not spread excessively or covered surfaces beyond their natural boundaries.\",\"s\":\"The gardener was pleased to find the pathway was nonovergrown after the dry summer kept the weeds in check.\",\"p\":\"non-oh-ver-GROHN\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonover.grown\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonoverhanging\",\"d\":\"Not hanging or extending outward over an edge or surface; describing a structure or object that does not protrude beyond its base.\",\"s\":\"The architect specified a nonoverhanging roofline so the building would have clean, straight vertical walls.\",\"p\":\"non-oh-ver-HANG-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonover.hang.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoverlapped\",\"d\":\"Not placed so as to cover part of another object; describing items that do not share or cover any common area with each other.\",\"s\":\"The tiles were carefully arranged in a nonoverlapped pattern so each one sat flat without covering another.\",\"p\":\"non-oh-ver-LAPT\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"nonover.lapped\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoverlapping\",\"d\":\"Not covering or sharing any common area with another object or set; describing things that remain entirely separate without any shared portion.\",\"s\":\"The teacher divided students into nonoverlapping groups so that no student belonged to more than one team.\",\"p\":\"non-oh-ver-LAP-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonover.lap.ping\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonoverloaded\",\"d\":\"Not carrying or containing more than the normal or safe capacity; describing a system, circuit, or vessel that has not been burdened beyond its limit.\",\"s\":\"The technician confirmed the circuit was nonoverloaded, safely running well below its maximum power capacity.\",\"p\":\"non-oh-ver-LOH-ded\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonover.load.ed\",\"ps\":\"adjective\",\"t\":[\"seafaring\",\"olatin\"]},{\"w\":\"nonovernight\",\"d\":\"Not lasting through the night or requiring an overnight stay; describing a trip, process, or event that is completed within a single day.\",\"s\":\"She booked a nonovernight flight that departed at noon and arrived the same evening before sunset.\",\"p\":\"non-OH-ver-nyt\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonoverridable\",\"d\":\"Not able to be overridden, canceled, or set aside by a higher authority; describing a rule, setting, or command that must be followed without exception.\",\"s\":\"The safety protocol was nonoverridable, meaning no manager could bypass the automatic shutdown command.\",\"p\":\"non-oh-ver-RY-duh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonover.rid.able\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonoverridden\",\"d\":\"Not having been overridden or superseded; describing a decision, command, or rule that remains in full effect because no higher authority has canceled it.\",\"s\":\"The original decision stood nonoverridden because no higher authority chose to challenge or reverse it.\",\"p\":\"non-oh-ver-RID-en\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonover.rid.den\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonovert\",\"d\":\"Not open, visible, or obvious; describing an action, feeling, or behavior that is hidden, subtle, or not openly displayed.\",\"s\":\"The spy's nonovert behavior allowed her to gather information without anyone suspecting she was watching them.\",\"p\":\"non-oh-VERT\",\"o\":\"Latin\",\"y\":8,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonovoid\",\"d\":\"Not having an oval or egg-like shape; describing an object whose form is distinctly different from an egg or ellipse.\",\"s\":\"The engineer described the container's cross-section as nonovoid since it formed a perfect circle, not an oval.\",\"p\":\"non-OH-voyd\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonovulating\",\"d\":\"Not currently releasing an egg from the ovary; describing a person or animal that is not in the phase of the reproductive cycle in which ovulation occurs.\",\"s\":\"The veterinarian explained that the nonovulating hen would not produce fertilized eggs during that season.\",\"p\":\"non-OV-yuh-lay-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonovu.lat.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonovulation\",\"d\":\"The absence or lack of ovulation; a condition in which an egg is not released from the ovary during a reproductive cycle.\",\"s\":\"The doctor diagnosed nonovulation as the reason the patient was having difficulty conceiving.\",\"p\":\"non-ov-yuh-LAY-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonovu.la.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonovulational\",\"d\":\"Relating to or characterized by the absence of ovulation; describing processes, cycles, or conditions in which no egg is released from the ovary.\",\"s\":\"The hormone levels indicated a nonovulational cycle, meaning the body went through the motions without releasing an egg.\",\"p\":\"non-ov-yuh-LAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonovu.la.tion.al\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonowner\",\"d\":\"A person who does not own a particular piece of property, asset, or item; someone who has no legal claim of ownership.\",\"s\":\"As a nonowner of the property, she needed special written permission before making any changes to the building.\",\"p\":\"non-OH-ner\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"nonown.er\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonownership\",\"d\":\"The state or condition of not owning something; the lack of any legal right or title to a property or asset.\",\"s\":\"His nonownership of the vehicle meant he could not legally sell it or make decisions about its repair.\",\"p\":\"non-OH-ner-ship\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonown.er.ship\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonoxalic\",\"d\":\"Not containing or related to oxalic acid; describing a substance or compound that is free from oxalic acid or its derivatives.\",\"s\":\"The chemist selected a nonoxalic solvent for the experiment to avoid the toxic effects of oxalic acid.\",\"p\":\"non-ok-SAL-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nonox.al.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonoxidative\",\"d\":\"Not involving or producing oxidation; describing a chemical process or pathway that proceeds without the transfer of electrons to oxygen.\",\"s\":\"The nonoxidative pathway in the cell provides energy without using oxygen to break down glucose.\",\"p\":\"non-OK-si-day-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonox.ida.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonoxidized\",\"d\":\"Not having undergone oxidation; describing a material or substance that has not reacted with oxygen and therefore shows no signs of rust or chemical change.\",\"s\":\"The surface of the freshly cut metal was nonoxidized and shiny before it was exposed to the open air.\",\"p\":\"non-OK-si-dyzd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonox.i.dized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonoxidizing\",\"d\":\"Not causing or undergoing oxidation; describing an agent or environment that does not promote the chemical reaction with oxygen.\",\"s\":\"The storage chamber used a nonoxidizing nitrogen atmosphere to keep the sensitive materials from rusting.\",\"p\":\"non-OK-si-dy-zing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"nonox.i.diz.ing\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ecology\",\"olatin\"]},{\"w\":\"nonoxygen\",\"d\":\"Not consisting of or relating to oxygen; describing a gas, atmosphere, or environment that contains no oxygen.\",\"s\":\"The planet's atmosphere was a nonoxygen environment, composed mostly of nitrogen and carbon dioxide.\",\"p\":\"non-OK-si-jen\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonoxy.gen\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ecology\",\"olatin\"]},{\"w\":\"nonoxygenated\",\"d\":\"Not enriched or supplied with oxygen; describing blood, water, or another substance that has not had oxygen added to it.\",\"s\":\"The nonoxygenated blood returning to the heart appeared darker red compared to the oxygen-rich blood leaving it.\",\"p\":\"non-ok-SIJ-uh-nay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonoxy.genat.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"nonoxygenic\",\"d\":\"Not producing or generating oxygen; describing organisms or chemical processes that do not release oxygen as a byproduct.\",\"s\":\"Some ancient bacteria used nonoxygenic photosynthesis, producing energy from sunlight without releasing oxygen as a byproduct.\",\"p\":\"non-ok-si-JEN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonoxy.genic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonoxygenous\",\"d\":\"Not containing or composed of oxygen; describing a compound or environment in which oxygen is absent or plays no role.\",\"s\":\"The compound was classified as nonoxygenous because its molecular structure contained no oxygen atoms whatsoever.\",\"p\":\"non-ok-SIJ-uh-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonoxyge.nous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ecology\",\"olatin\"]},{\"w\":\"nonozone\",\"d\":\"Not consisting of or relating to ozone; describing an area, layer, or substance that is free from ozone molecules.\",\"s\":\"Scientists were alarmed to find a nonozone region in the upper atmosphere where the protective layer had completely vanished.\",\"p\":\"non-OH-zohn\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nono.zone\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpacific\",\"d\":\"Not peaceful or calm; describing a person, group, or situation that is aggressive, hostile, or unwilling to avoid conflict.\",\"s\":\"The senator's nonpacific response to the proposal surprised everyone who expected a calm and peaceful reply.\",\"p\":\"non-puh-SIF-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.pa.cif.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpackaged\",\"d\":\"Not enclosed in a package or container; describing goods or items that are sold or distributed loose without any wrapping or box.\",\"s\":\"The farmer sold nonpackaged produce directly from bins so customers could select the exact amount they needed.\",\"p\":\"non-PAK-ijd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pack.aged\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpackaging\",\"d\":\"Not related to or involving the process of wrapping or boxing items; describing materials, methods, or industries that do not use packaging.\",\"s\":\"The eco-friendly store adopted a nonpackaging policy, encouraging shoppers to bring their own reusable containers.\",\"p\":\"non-PAK-ij-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pack.ag.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonpacked\",\"d\":\"Not tightly filled or compressed into a space; describing a container, bag, or area that has not been stuffed or loaded with contents.\",\"s\":\"The nonpacked suitcase left plenty of room for souvenirs from the trip.\",\"p\":\"non-PAKT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.packed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpadded\",\"d\":\"Not having any cushioning, padding, or soft material added for protection or comfort; describing a surface or garment that is bare and firm.\",\"s\":\"The nonpadded chair looked sleek but was uncomfortable after an hour.\",\"p\":\"non-PAD-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.padded\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"household\",\"olatin\"]},{\"w\":\"nonpagan\",\"d\":\"Not belonging to or associated with paganism; describing a person, belief, or practice that does not follow polytheistic or nature-based ancient religions.\",\"s\":\"The historian noted that the village's traditions were largely nonpagan in origin.\",\"p\":\"non-PAY-gun\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pa.gan\",\"ps\":\"adjective\",\"t\":[\"religion\",\"ancient\",\"logic\",\"olatin\"]},{\"w\":\"nonpaged\",\"d\":\"Not assigned page numbers; describing a document, memory, or text that lacks numbered pages or does not use a paging system.\",\"s\":\"The nonpaged memory section of the document had no numbered sheets at all.\",\"p\":\"non-PAYJD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.paged\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpaginated\",\"d\":\"Not numbered by pages; describing a document or publication in which the pages have not been assigned sequential numbers.\",\"s\":\"The teacher was frustrated that the nonpaginated report made referencing difficult.\",\"p\":\"non-PAJ-uh-nay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.pag.i.nat.ed\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpaging\",\"d\":\"Not using a paging system; describing a computer memory management approach or document format that does not divide content into numbered pages.\",\"s\":\"The nonpaging memory system stored data without swapping it to a disk.\",\"p\":\"non-PAY-jing\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pag.ing\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpaid\",\"d\":\"Not receiving payment; describing a position, service, or worker that does not involve financial compensation.\",\"s\":\"The nonpaid volunteers worked tirelessly to clean up the park after the storm.\",\"p\":\"non-PAYD\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.paid\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpainful\",\"d\":\"Not causing or involving pain; describing a medical procedure, sensation, or condition that does not produce any feeling of hurt or discomfort.\",\"s\":\"The dentist assured me the procedure would be completely nonpainful with anesthesia.\",\"p\":\"non-PAYN-ful\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.painful\",\"ps\":\"adjective\",\"t\":[\"body\",\"emotions\",\"olatin\"]},{\"w\":\"nonpaint\",\"d\":\"Not consisting of or relating to paint; describing a substance, material, or surface treatment that does not involve the use of paint.\",\"s\":\"The artist experimented with nonpaint materials like sand and fabric on her canvas.\",\"p\":\"non-PAYNT\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.paint\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonpainted\",\"d\":\"Not covered or decorated with paint; describing a surface, object, or material that remains in its natural, uncoated state.\",\"s\":\"The nonpainted wooden fence gave the yard a natural, rustic look.\",\"p\":\"non-PAYN-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.paint.ed\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonpainting\",\"d\":\"Not involving the act or art of applying paint; describing an artistic method, technique, or activity that does not use painting as its medium.\",\"s\":\"His nonpainting artwork included sculptures, collages, and digital prints.\",\"p\":\"non-PAYN-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.paint.ing\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonpaired\",\"d\":\"Not matched or grouped with a partner; describing elements, chromosomes, or objects that exist alone without a corresponding counterpart.\",\"s\":\"The nonpaired socks tumbled out of the dryer in a jumbled, unmatched heap.\",\"p\":\"non-PAIRD\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.paired\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpalatable\",\"d\":\"Not pleasant or acceptable to the taste; describing food, drink, or an idea that is disagreeable, unpleasant, or difficult to accept.\",\"s\":\"The experiment produced a nonpalatable compound that no one could stand to taste.\",\"p\":\"non-PAL-uh-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.palat.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpalatal\",\"d\":\"Not relating to or produced at the palate; describing a speech sound or anatomical feature that does not involve the hard or soft palate.\",\"s\":\"The linguist classified the sound as nonpalatal because it was formed at the back of the throat.\",\"p\":\"non-PAL-uh-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.palatal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpalindromic\",\"d\":\"Not reading the same forward and backward; describing a sequence of letters, numbers, or genetic bases that differs depending on the direction it is read.\",\"s\":\"The word 'cat' is nonpalindromic because it reads differently forwards and backwards.\",\"p\":\"non-pal-in-DROM-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.palin.dromic\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpalliative\",\"d\":\"Not merely soothing or relieving symptoms; describing a treatment or approach that aims to cure or eliminate a condition rather than simply ease discomfort.\",\"s\":\"The doctor prescribed a nonpalliative treatment intended to cure rather than just ease symptoms.\",\"p\":\"non-PAL-ee-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pal.lia.tive\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpalmar\",\"d\":\"Not relating to or located on the palm of the hand; describing a surface, region, or structure found on any part of the hand other than its inner surface.\",\"s\":\"The rash appeared on the nonpalmar side of the hand, covering only the knuckles.\",\"p\":\"non-PAL-mar\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pal.mar\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpalmate\",\"d\":\"Not shaped like a hand with spread fingers or webbed lobes; describing leaves, feet, or appendages that lack the divided, hand-like or webbed structure of a palmate form.\",\"s\":\"The bird's nonpalmate feet were adapted for perching rather than swimming.\",\"p\":\"non-PAL-mayt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pal.mate\",\"ps\":\"adjective\",\"t\":[\"botany\",\"numbers\",\"olatin\"]},{\"w\":\"nonpalpable\",\"d\":\"Not able to be felt by touching; describing a lump, organ, or structure that cannot be detected through physical examination with the fingers.\",\"s\":\"The doctor noted that the growth was nonpalpable and too small to feel by hand.\",\"p\":\"non-PAL-puh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.pal.pa.ble\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonpancreatic\",\"d\":\"Not originating from or relating to the pancreas; describing enzymes, hormones, or conditions that come from a source other than the pancreas.\",\"s\":\"The enzyme was classified as nonpancreatic because it originated in the salivary glands.\",\"p\":\"non-pan-kree-AT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pan.cre.at.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpanoramic\",\"d\":\"Not providing a wide, sweeping view of a scene or landscape; describing a perspective, image, or setting that is narrow or limited in scope.\",\"s\":\"The nonpanoramic camera lens captured only a narrow slice of the mountain view.\",\"p\":\"non-pan-uh-RAM-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.panoram.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpapal\",\"d\":\"Not relating to, issued by, or under the authority of the Pope; describing church matters, documents, or decisions that do not involve papal authority.\",\"s\":\"The nonpapal decree came from a regional bishop rather than the Vatican.\",\"p\":\"non-PAY-pul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pa.pal\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"religion\",\"olatin\"]},{\"w\":\"nonpaper\",\"d\":\"Not consisting of or produced on paper; describing a document, communication, or record that exists in a non-physical or digital format rather than on printed sheets.\",\"s\":\"The office pledged to move toward nonpaper communication by using only digital files.\",\"p\":\"non-PAY-per\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pa.per\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpapillary\",\"d\":\"Not having or relating to papillae, which are small nipple-like projections on a surface; describing tissue or structures that lack these characteristic bumps.\",\"s\":\"The pathologist described the tumor as nonpapillary, meaning it lacked the finger-like projections.\",\"p\":\"non-PAP-ih-lair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pap.il.lary\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpapist\",\"d\":\"Not a follower of the Pope or Roman Catholic Church; describing a person or belief system that does not adhere to papal authority or Catholic doctrine.\",\"s\":\"The nonpapist congregation followed Protestant traditions and had no ties to Rome.\",\"p\":\"non-PAY-pist\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pa.pist\",\"ps\":\"noun\",\"t\":[\"poetry\",\"religion\",\"ancient\",\"logic\",\"olatin\"]},{\"w\":\"nonparabolic\",\"d\":\"Not having the shape or properties of a parabola; describing a curve, surface, or mathematical function that does not follow a parabolic path or equation.\",\"s\":\"The graph's nonparabolic curve confused the students who expected a standard U-shape.\",\"p\":\"non-pair-uh-BOL-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.parabol.ic\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonparabolicity\",\"d\":\"The quality or state of not being parabolic; used especially in physics and mathematics to describe the degree to which a curve or energy band deviates from a perfect parabolic shape.\",\"s\":\"The physicist measured the nonparabolicity of the electron's energy band in the semiconductor.\",\"p\":\"non-pair-uh-buh-LIS-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.parabol.ic.i.ty\",\"ps\":\"noun\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonparacompact\",\"d\":\"Not satisfying the mathematical property of paracompactness; describing a topological space in which not every open cover can be refined into a locally finite one.\",\"s\":\"The mathematician proved that the topological space was nonparacompact and could not be easily covered.\",\"p\":\"non-pair-uh-KOM-pakt\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.para.com.pact\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonparadigmatic\",\"d\":\"Not conforming to or serving as a standard model or pattern; describing an example, method, or case that falls outside the accepted paradigm of a field.\",\"s\":\"Her nonparadigmatic approach to science broke all the usual rules of the field.\",\"p\":\"non-pair-uh-dig-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.paradig.mat.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparadox\",\"d\":\"A statement or situation that appears straightforward and contains no self-contradiction; something that seems like it might be paradoxical but is actually perfectly logical and consistent.\",\"s\":\"The statement turned out to be a simple nonparadox — straightforward and easy to understand.\",\"p\":\"non-PAIR-uh-doks\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.para.dox\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonparadoxical\",\"d\":\"Not contradictory or self-opposing; describing a statement, outcome, or situation that is entirely consistent with logic and does not produce conflicting conclusions.\",\"s\":\"The scientist's conclusion was refreshingly nonparadoxical, fitting neatly with existing knowledge.\",\"p\":\"non-pair-uh-DOK-sih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.para.dox.i.cal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonparaffin\",\"d\":\"Not composed of or derived from paraffin wax; describing a substance, fuel, or product that does not contain the waxy hydrocarbon compounds found in paraffin.\",\"s\":\"The chemist searched for a nonparaffin lubricant that would work at very high temperatures.\",\"p\":\"non-PAIR-uh-fin\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.paraf.fin\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparallelism\",\"d\":\"The absence of parallel arrangement or similarity; a condition in which lines, structures, or ideas diverge and do not run side by side in a consistent, matching manner.\",\"s\":\"The architect's bold nonparallelism meant that no two walls in the building ran in the same direction.\",\"p\":\"non-PAIR-uh-lel-iz-um\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.par.al.lelism\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonparallelizable\",\"d\":\"Not capable of being divided into parallel tasks or processes that can run simultaneously; describing a computation or workflow that must be completed in a single sequential order.\",\"s\":\"The algorithm was nonparallelizable, meaning each step had to finish before the next could begin.\",\"p\":\"non-PAIR-uh-lel-ize-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.par.al.leliz.able\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonparallelized\",\"d\":\"Not converted into or processed as simultaneous parallel tasks; describing a computing operation or workflow that runs as a single sequential process rather than being split across multiple processors.\",\"s\":\"The nonparallelized code ran slower because it used only one processor at a time.\",\"p\":\"non-PAIR-uh-lel-ized\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.par.al.lelized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparalytic\",\"d\":\"Not causing or characterized by paralysis; describing a condition, substance, or state in which normal muscle movement and nerve function are preserved.\",\"s\":\"The doctor confirmed the condition was nonparalytic, so the patient's muscles remained fully functional.\",\"p\":\"non-pair-uh-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.par.a.lyt.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"character\",\"olatin\"]},{\"w\":\"nonparalyzed\",\"d\":\"Not affected by paralysis; describing a person, animal, or body part that retains full ability to move and respond normally without loss of muscle function.\",\"s\":\"The nonparalyzed limb regained strength quickly after the patient began physical therapy.\",\"p\":\"non-PAIR-uh-lized\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.par.a.lyzed\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"animals\",\"olatin\"]},{\"w\":\"nonparamagnetic\",\"d\":\"Not exhibiting paramagnetism; describing a material that is not weakly attracted to a magnetic field and does not become temporarily magnetized when exposed to one.\",\"s\":\"The nonparamagnetic material showed no attraction to the powerful magnet in the lab.\",\"p\":\"non-pair-uh-mag-NET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.para.m.ag.net.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"music\",\"olatin\"]},{\"w\":\"nonparameterized\",\"d\":\"Not defined or adjusted by specific parameters or variables; describing a model, function, or system that operates without having particular settings or values assigned to control its behavior.\",\"s\":\"The nonparameterized model was simpler but less flexible than the advanced version.\",\"p\":\"non-puh-RAM-ih-ter-ized\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pa.ram.e.ter.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparametric\",\"d\":\"not involving an estimation of the parameters of a statistic\",\"s\":\"The researcher chose a nonparametric test because the data didn't follow a normal distribution.\",\"p\":\"non-pair-uh-MET-rik\",\"o\":\"Latin\",\"y\":6,\"bp\":26,\"sy\":\"non.para.met.ric\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparametrically\",\"d\":\"In a manner that does not rely on assumptions about the parameters or distribution of a population; describing how a statistical test or analysis is conducted without a fixed mathematical model.\",\"s\":\"The scientists analyzed the skewed data nonparametrically, avoiding assumptions about its distribution.\",\"p\":\"non-pair-uh-MET-rih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.para.met.ri.cal.ly\",\"ps\":\"adverb\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonparaneoplastic\",\"d\":\"Not related to or caused by a paraneoplastic syndrome; describing symptoms or conditions that arise independently of the indirect effects of a tumor on distant tissues.\",\"s\":\"The neurologist confirmed the symptoms were nonparaneoplastic, meaning they were unrelated to any tumor activity.\",\"p\":\"non-pair-uh-nee-oh-PLAS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.para.ne.o.plas.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonparanoid\",\"d\":\"Not exhibiting or characterized by paranoia; describing a person or mental state that is free from irrational suspicion, distrust, or the belief that others are conspiring against them.\",\"s\":\"Her nonparanoid reaction to the criticism surprised her teammates, who expected her to become defensive.\",\"p\":\"non-PAIR-uh-noid\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.para.noid\",\"ps\":\"adjective\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonparanormal\",\"d\":\"Not beyond what is considered normal or explainable by natural laws; describing events or phenomena that have a rational, scientific explanation rather than a supernatural one.\",\"s\":\"The investigator concluded that the strange sounds had a nonparanormal explanation — just pipes in the walls.\",\"p\":\"non-pair-uh-NOR-mul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.para.nor.mal\",\"ps\":\"adjective\",\"t\":[\"law\",\"logic\",\"olatin\"]},{\"w\":\"nonparasite\",\"d\":\"An organism that does not live at the expense of a host; a creature or plant that obtains its nutrients independently without harming or depending on another organism.\",\"s\":\"The clownfish is a nonparasite that lives among anemones in a mutually beneficial relationship.\",\"p\":\"non-PAIR-uh-site\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.par.a.site\",\"ps\":\"noun\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonparasitic\",\"d\":\"not parasitic on another organism\",\"s\":\"Unlike tapeworms, many fungi are nonparasitic and actually help plants absorb nutrients from the soil.\",\"p\":\"non-pair-uh-SIT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.par.a.sitic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparasitized\",\"d\":\"Not invaded or infected by a parasite; describing an organism or host that has not been colonized by another organism living off its resources.\",\"s\":\"The nonparasitized plants in the control group grew twice as tall as those attacked by root worms.\",\"p\":\"non-PAIR-uh-sih-tized\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.par.a.sitized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparasitological\",\"d\":\"Not relating to the scientific study of parasites; describing research, methods, or fields that fall outside the discipline of parasitology.\",\"s\":\"The research took a nonparasitological approach, focusing on bacteria rather than parasites as disease agents.\",\"p\":\"non-pair-uh-sit-uh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.par.a.sito.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparaxial\",\"d\":\"Not parallel to or near the central optical axis; describing light rays, beams, or geometric paths that travel at significant angles away from the main axis of a lens or optical system.\",\"s\":\"The optical engineer studied nonparaxial light rays that bent sharply far from the central lens axis.\",\"p\":\"non-puh-RAK-see-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.parax.i.al\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonparaxiality\",\"d\":\"The property or condition of not being paraxial; the degree to which light rays or geometric paths deviate significantly from the central axis of an optical system.\",\"s\":\"The nonparaxiality of the laser beam caused distortion at the edges of the holographic image.\",\"p\":\"non-puh-rak-see-AL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.parax.i.al.i.ty\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonparenchymal\",\"d\":\"Not relating to the parenchyma, which is the functional tissue of an organ; describing cells, structures, or processes associated with the supporting framework of an organ rather than its main working tissue.\",\"s\":\"Nonparenchymal liver cells, such as Kupffer cells, play a crucial role in immune defense.\",\"p\":\"non-puh-RENG-kih-mul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.parenchy.mal\",\"ps\":\"adjective\",\"t\":[\"body\",\"music\",\"olatin\"]},{\"w\":\"nonparent\",\"d\":\"A person who is not a parent; an individual who has not had or adopted children and does not hold the role of a mother or father.\",\"s\":\"As a nonparent, she still deeply understood children's needs from years of teaching kindergarten.\",\"p\":\"non-PAIR-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.par.ent\",\"ps\":\"noun\",\"t\":[\"character\",\"kinship\",\"olatin\"]},{\"w\":\"nonparental\",\"d\":\"Not relating to or characteristic of a parent; describing care, influence, decisions, or roles that come from someone other than a child's mother or father.\",\"s\":\"The study examined how nonparental caregivers, like grandparents and nannies, influence child development.\",\"p\":\"non-puh-REN-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.parental\",\"ps\":\"adjective\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonparenteral\",\"d\":\"Describing a method of administering medication or nutrients that does not bypass the digestive tract, meaning it is taken through the gut rather than by injection.\",\"s\":\"The doctor chose a nonparenteral treatment, giving the patient medicine by mouth rather than injection.\",\"p\":\"non-puh-REN-ter-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.par.enter.al\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonparenthetical\",\"d\":\"Not of the nature of a parenthetical remark; describing information that is directly part of the main text rather than inserted as an aside or clarification in brackets.\",\"s\":\"His nonparenthetical writing style was direct, with no extra phrases tucked inside brackets or commas.\",\"p\":\"non-pair-en-THET-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.par.en.thet.i.cal\",\"ps\":\"adjective\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonparish\",\"d\":\"Not belonging to or associated with a parish; describing a community, district, or organization that operates outside the structure of an ecclesiastical or civil parish.\",\"s\":\"The nonparish community center served residents of many faiths without any religious affiliation.\",\"p\":\"non-PAIR-ish\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.parish\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparity\",\"d\":\"The absence of equality or equivalence between two or more things, especially in terms of status, value, or treatment.\",\"s\":\"The debate over nonparity in salaries between men and women continued in the boardroom for hours.\",\"p\":\"non-PAIR-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.par.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpark\",\"d\":\"Land or an area that is not designated or maintained as a public park, often used in zoning or land-use contexts.\",\"s\":\"The city council debated how to develop nonpark land near the river without destroying green spaces.\",\"p\":\"non-PARK\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.park\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparkinsonian\",\"d\":\"Not related to, caused by, or characteristic of Parkinson's disease; used to describe symptoms or conditions that resemble but are distinct from Parkinson's disease.\",\"s\":\"The tremors turned out to be nonparkinsonian, caused instead by an essential tremor disorder.\",\"p\":\"non-par-kin-SOH-nee-un\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.parkin.so.ni.an\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonparliamentary\",\"d\":\"Not conforming to or governed by the rules and procedures of a parliament or legislative body; describing conduct or methods that fall outside accepted parliamentary practice.\",\"s\":\"The chairperson warned that the delegate's rude outburst was nonparliamentary and violated meeting rules.\",\"p\":\"non-par-lih-MEN-tuh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.par.lia.men.tary\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonparochial\",\"d\":\"Not limited to or governed by a single parish; describing an organization, school, or outlook that extends beyond local parish boundaries and interests.\",\"s\":\"The nonparochial school welcomed students from across the city regardless of their neighborhood or church.\",\"p\":\"non-puh-ROH-kee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.parochial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparoxysmal\",\"d\":\"Not occurring in sudden, intense episodes or attacks; describing a condition or symptom that develops gradually rather than in abrupt bursts.\",\"s\":\"The patient's steady, nonparoxysmal chest pain was less alarming than the sudden spasms the doctor had feared.\",\"p\":\"non-pair-ok-SIZ-mul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.parox.ys.mal\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonparsed\",\"d\":\"Not broken down or analyzed into grammatical or structural components; describing data, text, or code that has not been processed by a parser.\",\"s\":\"The programmer found that the nonparsed text string caused the app to crash whenever users submitted the form.\",\"p\":\"non-PARST\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.parsed\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonparsing\",\"d\":\"Not involving the process of breaking text or data into its component parts for analysis; describing a method or system that does not perform parsing operations.\",\"s\":\"The nonparsing function simply stored the raw input without trying to interpret or organize its structure.\",\"p\":\"non-PAR-sing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pars.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparthenogenetic\",\"d\":\"Not involving or produced by parthenogenesis, the process by which an organism develops from an unfertilized egg; describing reproduction that requires fertilization by a male gamete.\",\"s\":\"Most mammals reproduce in a nonparthenogenetic way, requiring fertilization by a male to create offspring.\",\"p\":\"non-par-thuh-noh-juh-NET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.partheno.genet.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparticipation\",\"d\":\"withdrawing from the activities of a group\",\"s\":\"Her nonparticipation in the school play puzzled her teacher, since she had always loved performing before.\",\"p\":\"non-par-tis-ih-PAY-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":32,\"sy\":\"non.par.tic.i.pa.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonparticipative\",\"d\":\"Not involving active engagement or contribution; describing a role, approach, or system in which individuals do not take part in decision-making or shared activities.\",\"s\":\"The nonparticipative students sat quietly while their classmates eagerly debated the science experiment results.\",\"p\":\"non-par-TIS-ih-pay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.par.tic.i.pa.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparticipatory\",\"d\":\"Not structured to allow or encourage the involvement of participants; describing processes, governments, or events in which people have no active role or voice.\",\"s\":\"The museum offered a nonparticipatory exhibit where visitors could only observe, not touch, the artifacts.\",\"p\":\"non-par-tis-ih-PAY-tuh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.par.tic.i.pa.to.ry\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonparticipial\",\"d\":\"Not functioning as or relating to a participle; describing a word, phrase, or grammatical form that does not share the characteristics of a participial construction.\",\"s\":\"The grammar teacher explained that 'running' in that sentence was nonparticipial — it was used as a noun, not a verb.\",\"p\":\"non-par-tih-SIP-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.par.ticip.i.al\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonparticularistic\",\"d\":\"Not focused on or favoring specific individuals, groups, or cases over others; describing a universal or impartial approach that does not single out particular instances.\",\"s\":\"Her nonparticularistic approach to teaching treated every student equally without playing favorites.\",\"p\":\"non-par-tik-yuh-lair-IS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.par.tic.u.lar.is.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonparticulate\",\"d\":\"not composed of distinct particles\",\"s\":\"Scientists discovered that the new pollutant was nonparticulate, existing as a dissolved gas rather than tiny solid bits.\",\"p\":\"non-par-TIK-yuh-lut\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.par.tic.u.late\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpartitive\",\"d\":\"Not expressing or relating to a part of a whole; describing a grammatical construction or quantity that refers to something in its entirety rather than a portion of it.\",\"s\":\"In that sentence, 'some water' is used in a nonpartitive sense, referring to water in general rather than a portion of a specific amount.\",\"p\":\"non-PAR-tih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.par.ti.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonparturient\",\"d\":\"Not in the process of giving birth or about to give birth; describing a female animal or person who is not in labor or in the immediate period surrounding childbirth.\",\"s\":\"The veterinarian monitored the nonparturient cows separately from those expected to give birth that week.\",\"p\":\"non-par-TYOOR-ee-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.par.turi.ent\",\"ps\":\"adjective\",\"t\":[\"animals\",\"character\",\"olatin\"]},{\"w\":\"nonparturition\",\"d\":\"The state or condition of not giving birth; the absence of the childbirth process, often referenced in medical or veterinary contexts to distinguish animals or individuals not undergoing delivery.\",\"s\":\"The extended nonparturition of the lioness concerned zookeepers who had hoped for cubs that season.\",\"p\":\"non-par-tyoo-RIH-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.par.tu.ri.tion\",\"ps\":\"noun\",\"t\":[\"body\",\"animals\",\"olatin\"]},{\"w\":\"nonparty\",\"d\":\"Not affiliated with or belonging to a political party or other organized group; describing an individual, candidate, or organization that operates independently of party membership.\",\"s\":\"As a nonparty citizen, she voted based on the candidate's character rather than any political affiliation.\",\"p\":\"non-PAR-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.par.ty\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonpassenger\",\"d\":\"A person who is not traveling as a passenger on a vehicle, aircraft, or vessel; often referring to crew members, staff, or others present who are not fare-paying riders.\",\"s\":\"Security stopped the nonpassenger at the gate, explaining that only ticketed travelers could proceed to the terminal.\",\"p\":\"non-PAS-un-jer\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pas.sen.ger\",\"ps\":\"noun\",\"t\":[\"character\",\"seafaring\",\"vehicles\",\"olatin\"]},{\"w\":\"nonpasserine\",\"d\":\"relating to or characteristic of birds that are not perching birds\",\"s\":\"Owls and penguins are nonpasserine birds, since they do not belong to the perching bird order.\",\"p\":\"non-PAS-uh-ryn\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.passer.ine\",\"ps\":\"adjective\",\"t\":[\"birds\",\"olatin\"]},{\"w\":\"nonpassionate\",\"d\":\"Lacking strong emotion, enthusiasm, or intense feeling; describing a calm, detached, or indifferent attitude toward a subject or activity.\",\"s\":\"His nonpassionate delivery of the speech left the audience unmoved and quietly checking their phones.\",\"p\":\"non-PASH-un-ut\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pas.sion.ate\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonpassive\",\"d\":\"Not passive; describing an active, engaged, or assertive approach in which a person or force takes initiative rather than remaining inactive or submissive.\",\"s\":\"The nonpassive investor actively managed her portfolio every day, refusing to simply leave money in index funds.\",\"p\":\"non-PAS-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pas.sive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpassivity\",\"d\":\"The quality or state of being active, assertive, or engaged rather than passive or submissive; the absence of a passive disposition or behavior.\",\"s\":\"The coach praised the team's nonpassivity, applauding how they challenged every call rather than accepting defeat.\",\"p\":\"non-pa-SIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.pas.siv.i.ty\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonpassivizable\",\"d\":\"Describing a verb or construction in grammar that cannot be transformed into the passive voice; referring to sentences or verb types that do not allow a passive form.\",\"s\":\"The linguist explained that some active verbs are nonpassivizable and cannot be rewritten in passive form.\",\"p\":\"non-PAS-ih-vy-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pas.siviz.able\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpast\",\"d\":\"In linguistics, referring to a tense or time frame that is not the past, typically encompassing present and future forms; describing verb forms that do not indicate completed or previous action.\",\"s\":\"In grammar class, we learned that nonpast tense describes actions happening now or in the future.\",\"p\":\"non-PAST\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.past\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"time\",\"olatin\"]},{\"w\":\"nonpasta\",\"d\":\"Food items or menu choices that do not include pasta; describing meals or dietary options that are free from noodle- or dough-based Italian-style dishes.\",\"s\":\"The Italian restaurant added a nonpasta section to their menu for customers avoiding wheat.\",\"p\":\"non-PAH-stuh\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pas.ta\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"dishes\",\"olatin\"]},{\"w\":\"nonpasteurized\",\"d\":\"Not subjected to the process of pasteurization, in which food or drink is heated to kill harmful bacteria; describing products such as milk or juice that are raw and untreated by heat.\",\"s\":\"The label warned that the nonpasteurized milk had not been heat-treated to kill bacteria.\",\"p\":\"non-PAS-chuh-ryzdtd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pas.teur.ized\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpasture\",\"d\":\"Land that is not used or designated for grazing livestock; describing fields, areas, or terrain that serve purposes other than feeding animals outdoors.\",\"s\":\"The ecologist studied nonpasture land to see how forests recover when animals are kept away.\",\"p\":\"non-PAS-chur\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pas.ture\",\"ps\":\"adjective\",\"t\":[\"animals\",\"landforms\",\"farming\",\"olatin\"]},{\"w\":\"nonpaternity\",\"d\":\"The condition in which a man who is presumed to be the biological father of a child is in fact not; the absence of a biological paternal relationship.\",\"s\":\"The legal case hinged on a nonpaternity finding after the DNA results came back negative.\",\"p\":\"non-puh-TUR-nih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.pa.ter.ni.ty\",\"ps\":\"noun\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonpathetic\",\"d\":\"Not arousing pity, sympathy, or sadness; describing something or someone that does not evoke feelings of sorrow or inspire a sense of inadequacy.\",\"s\":\"The coach gave a nonpathetic, energetic speech that fired up the entire team before the championship.\",\"p\":\"non-puh-THET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pa.thet.ic\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonpathogen\",\"d\":\"A microorganism or agent that does not cause disease in a host; a bacterium, virus, or other organism that lives without producing harmful effects.\",\"s\":\"Scientists confirmed the bacteria found in the sample was a nonpathogen that posed no health risk.\",\"p\":\"non-PATH-uh-jen\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.pathogen\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpathogenic\",\"d\":\"Not capable of causing disease; describing microorganisms that can exist in or on a host without triggering illness or harmful biological responses.\",\"s\":\"The microbiologist noted that most bacteria living in your gut are nonpathogenic and actually help digestion.\",\"p\":\"non-path-uh-JEN-ik\",\"o\":\"Latin\",\"y\":7,\"bp\":23,\"sy\":\"non.pathogenic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpathological\",\"d\":\"Not related to or caused by disease or disorder; describing a condition, behavior, or finding that falls within the range of normal and healthy functioning.\",\"s\":\"The doctor reassured the patient that his unusual habit was nonpathological and not a sign of disease.\",\"p\":\"non-path-uh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.patho.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpathologically\",\"d\":\"In a manner that is not related to disease or disorder; describing how something occurs or is evaluated within the bounds of normal, healthy functioning rather than as a symptom of illness.\",\"s\":\"The scientist concluded that the tissue had changed nonpathologically due to normal aging, not illness.\",\"p\":\"non-path-uh-LOJ-ih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.patho.log.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpathologist\",\"d\":\"A medical professional or scientist who does not specialize in pathology; any doctor or researcher whose primary field of study is not the diagnosis and investigation of disease.\",\"s\":\"As a nonpathologist, the general practitioner referred the unusual tissue sample to a specialist.\",\"p\":\"non-puh-THOL-uh-jist\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pathol.o.gist\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"economy\",\"olatin\"]},{\"w\":\"nonpathology\",\"d\":\"The study or consideration of conditions and processes that are not related to disease; the field or perspective concerned with normal, healthy biological or psychological states.\",\"s\":\"The researcher's work focused on nonpathology, examining healthy tissue rather than diseased samples.\",\"p\":\"non-puh-THOL-uh-jee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pathol.o.gy\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpatient\",\"d\":\"A person who is not currently receiving medical treatment or registered as a patient at a healthcare facility.\",\"s\":\"The hospital volunteer was a nonpatient who came each week simply to read to elderly residents.\",\"p\":\"non-PAY-shent\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pa.tient\",\"ps\":\"noun\",\"t\":[\"body\",\"character\",\"olatin\"]},{\"w\":\"nonpatron\",\"d\":\"A person who does not regularly support, frequent, or financially back a particular business, artist, or institution.\",\"s\":\"A nonpatron of the arts, he rarely attended gallery openings or donated to cultural organizations.\",\"p\":\"non-PAY-trun\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pa.tron\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpatronizing\",\"d\":\"Describing a manner of speaking or behaving that treats others as equals, without condescension or a superior attitude.\",\"s\":\"Her nonpatronizing teaching style made every student feel respected and capable of learning.\",\"p\":\"non-PAY-truh-ny-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pa.tron.iz.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpatterned\",\"d\":\"Lacking any repeated design, motif, or decorative arrangement; plain and without a visible pattern.\",\"s\":\"She chose a nonpatterned, solid-blue fabric for the curtains to keep the room looking calm.\",\"p\":\"non-PAT-ernd\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.pat.terned\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"olatin\"]},{\"w\":\"nonpaved\",\"d\":\"Describing a road, path, or surface that has not been covered with asphalt, concrete, or other hard paving material.\",\"s\":\"The hikers followed a nonpaved trail through the forest, kicking up dust with every step.\",\"p\":\"non-PAYVD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.paved\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpayee\",\"d\":\"A person or entity that is not designated to receive a payment, check, or financial transfer in a given transaction.\",\"s\":\"Since he was listed as a nonpayee on the check, the bank refused to let him cash it.\",\"p\":\"non-pay-EE\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pay.ee\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpayer\",\"d\":\"A person or organization that fails or refuses to make a required or expected payment.\",\"s\":\"The landlord took the nonpayer to court after three months of unpaid rent.\",\"p\":\"non-PAY-er\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pay.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpeaceful\",\"d\":\"Characterized by conflict, unrest, or hostility; not peaceful or tranquil in nature.\",\"s\":\"The protest turned nonpeaceful when a small group began throwing objects at the police.\",\"p\":\"non-PEES-ful\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.peace.ful\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonpeasant\",\"d\":\"A person who does not belong to the peasant class; someone who is not a rural agricultural laborer or subsistence farmer.\",\"s\":\"As a nonpeasant landowner, the nobleman paid no field taxes in medieval society.\",\"p\":\"non-PEZ-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.peas.ant\",\"ps\":\"noun\",\"t\":[\"farming\",\"character\",\"olatin\"]},{\"w\":\"nonpedestrian\",\"d\":\"Not relating to or involving people traveling on foot; also used to describe something that is not ordinary or dull.\",\"s\":\"The city built a nonpedestrian overpass reserved strictly for cyclists and motorists.\",\"p\":\"non-puh-DES-tree-un\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pedes.tri.an\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpedigree\",\"d\":\"Describing an animal, especially a pet, that does not have a documented or registered ancestral lineage.\",\"s\":\"Our lovable nonpedigree mutt won the crowd's hearts at the dog show despite having no papers.\",\"p\":\"non-PED-ih-gree\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.pedi.gree\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonpedunculated\",\"d\":\"In biology, describing a structure that is attached directly to a surface without a stalk or stem-like connection.\",\"s\":\"The surgeon noted the growth was nonpedunculated, meaning it was flat against the tissue with no stalk.\",\"p\":\"non-peh-DUNK-yoo-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonpe.dun.cu.lat.ed\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonpeelable\",\"d\":\"Describing a surface, coating, or material that cannot be peeled away or removed by stripping.\",\"s\":\"The manufacturer designed a nonpeelable coating on the surface so the label would stay permanently.\",\"p\":\"non-PEEL-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.pee.lable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpejorative\",\"d\":\"Describing a word, phrase, or tone that does not carry a negative, insulting, or degrading connotation.\",\"s\":\"The teacher asked students to use nonpejorative language when discussing differences between cultures.\",\"p\":\"non-pih-JOR-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pe.jo.ra.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpelagic\",\"d\":\"Not relating to or living in the open ocean; describing organisms or processes associated with the seafloor or coastal areas rather than open water.\",\"s\":\"The marine biologist focused on nonpelagic organisms that live on the seafloor rather than in open water.\",\"p\":\"non-puh-LAJ-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pelag.ic\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"nonpelvic\",\"d\":\"Not relating to or located in the region of the pelvis or hip girdle of the body.\",\"s\":\"The X-ray revealed a nonpelvic fracture located higher up in the spine.\",\"p\":\"non-PEL-vik\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.pelvic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpenal\",\"d\":\"Not relating to punishment or the penal system; describing rules, institutions, or measures that do not involve criminal penalties.\",\"s\":\"The judge recommended nonpenal community service instead of a prison sentence for the first-time offender.\",\"p\":\"non-PEE-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pe.nal\",\"ps\":\"adjective\",\"t\":[\"law\",\"numbers\",\"olatin\"]},{\"w\":\"nonpenetrated\",\"d\":\"Describing something that has not been pierced, entered, or broken through by an outside force or object.\",\"s\":\"The armor remained nonpenetrated after the test, proving the material could withstand the impact.\",\"p\":\"non-PEN-ih-tray-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pen.e.trat.ed\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpenetrating\",\"d\":\"Describing a force, object, or wound that does not pierce or pass through a surface or bodily tissue.\",\"s\":\"The doctor confirmed the wound was nonpenetrating, meaning it had not broken through to deeper tissue.\",\"p\":\"non-PEN-ih-tray-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pen.e.trat.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"physics\",\"olatin\"]},{\"w\":\"nonpenetration\",\"d\":\"The state or condition of not having been pierced, breached, or entered by an outside force or substance.\",\"s\":\"Security engineers celebrated the nonpenetration of their firewall after hours of simulated cyberattacks.\",\"p\":\"non-pen-ih-TRAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pen.e.tra.tion\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpenetrative\",\"d\":\"Describing an action or activity that does not involve physical piercing or deep entry into a surface or body.\",\"s\":\"Physical therapists often recommend nonpenetrative massage techniques that work on surface muscles only.\",\"p\":\"non-PEN-ih-tray-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pen.e.tra.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpenicillin\",\"d\":\"Describing an antibiotic or drug that does not belong to the penicillin family of medications, used especially for patients with penicillin allergies.\",\"s\":\"Since she was allergic to penicillin, the doctor prescribed a nonpenicillin antibiotic to treat her infection.\",\"p\":\"non-pen-ih-SIL-in\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.peni.cillin\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"pharmacy\",\"kinship\",\"olatin\"]},{\"w\":\"nonpensioner\",\"d\":\"A person who does not receive a pension; someone who has not yet retired or does not qualify for pension benefits.\",\"s\":\"As a nonpensioner still in her forties, she had years of work ahead before retirement benefits would apply.\",\"p\":\"non-PEN-shuh-ner\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pen.sion.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpeptic\",\"d\":\"Not related to or caused by stomach acid or the digestive process; describing ulcers or conditions with a different origin than acid digestion.\",\"s\":\"The gastroenterologist explained that the patient's stomach pain was nonpeptic and unrelated to acid.\",\"p\":\"non-PEP-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pep.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"nonpeptide\",\"d\":\"Describing a chemical compound or drug that is not composed of peptide chains and does not have the structure of a peptide.\",\"s\":\"Researchers developed a nonpeptide drug that mimicked the effect of natural hormones in the body.\",\"p\":\"non-PEP-tyd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pep.tide\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"chemistry\",\"olatin\"]},{\"w\":\"nonpeptidergic\",\"d\":\"In neuroscience, describing nerve cells or pathways that do not use peptides as their primary chemical signaling molecules.\",\"s\":\"The neuroscience study identified nonpeptidergic nerve fibers that transmit pain signals differently from peptide-based pathways.\",\"p\":\"non-pep-tih-DER-jik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pep.tider.gic\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"olatin\"]},{\"w\":\"nonpeptidic\",\"d\":\"Not having the chemical structure or properties of a peptide; describing molecules that lack the amino-acid chain bonds characteristic of peptides.\",\"s\":\"The researchers developed a nonpeptidic drug that could survive digestion without breaking down.\",\"p\":\"non-pep-TID-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pep.tidic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpeptidyl\",\"d\":\"In biochemistry, describing a molecular group or compound that does not carry or contain a peptide chain as part of its structure.\",\"s\":\"The nonpeptidyl compound attached to the enzyme in a completely different way than amino acids do.\",\"p\":\"non-PEP-tih-dil\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.pep.tidyl\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonperceived\",\"d\":\"Not noticed, detected, or recognized by the senses or the mind; remaining below the threshold of conscious awareness.\",\"s\":\"The subtle change in color was nonperceived by most students during the experiment.\",\"p\":\"non-per-SEEVD\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.per.ceived\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperceiving\",\"d\":\"Not capable of or engaged in detecting, sensing, or becoming aware of stimuli or information from the environment.\",\"s\":\"A nonperceiving observer would miss the tiny vibrations that signal an earthquake is coming.\",\"p\":\"non-per-SEEV-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.ceiv.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonperception\",\"d\":\"The absence or lack of conscious awareness, sensory detection, or recognition of a stimulus or event.\",\"s\":\"His nonperception of the warning signs led to a dangerous situation on the hiking trail.\",\"p\":\"non-per-SEP-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.cep.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonperceptive\",\"d\":\"Lacking the ability or tendency to notice, understand, or interpret sensory information or subtle details.\",\"s\":\"A nonperceptive audience failed to notice the actor's subtle clues about the villain's identity.\",\"p\":\"non-per-SEP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.cep.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperceptual\",\"d\":\"Not relating to or based on direct sensory perception; existing or operating outside the realm of what can be directly sensed.\",\"s\":\"Some knowledge is nonperceptual, meaning it comes from logic rather than from our senses.\",\"p\":\"non-per-SEP-choo-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.per.cep.tu.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperching\",\"d\":\"Describing birds or animals that do not rest by gripping a branch or elevated rod with their feet.\",\"s\":\"Ducks are nonperching birds that prefer floating on water to sitting in trees.\",\"p\":\"non-PERCH-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.perch.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"birds\",\"olatin\"]},{\"w\":\"nonpercolative\",\"d\":\"Describing a material or process through which liquid does not slowly filter or seep; not allowing percolation.\",\"s\":\"The nonpercolative material blocked all liquid from seeping through its layers.\",\"p\":\"non-PER-kuh-lay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.per.cola.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpercussive\",\"d\":\"Not involving striking, tapping, or the use of percussion; describing sounds or instruments that do not rely on impact to produce sound.\",\"s\":\"The flute produces a nonpercussive sound, relying on breath rather than striking.\",\"p\":\"non-per-KUS-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.cus.sive\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonperennial\",\"d\":\"Describing a plant or phenomenon that does not last throughout the year or recur every year; temporary or seasonal in nature.\",\"s\":\"Unlike roses, some nonperennial flowers must be replanted every single year.\",\"p\":\"non-puh-REN-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.peren.ni.al\",\"ps\":\"adjective\",\"t\":[\"botany\",\"music\",\"time\",\"olatin\"]},{\"w\":\"nonperforated\",\"d\":\"Describing a surface or material that has no holes, punctures, or perforations made through it.\",\"s\":\"The nonperforated stamp had no holes along its edges, making it very rare for collectors.\",\"p\":\"non-PER-fuh-ray-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.per.fo.rat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperformance\",\"d\":\"The failure to carry out a required duty, task, or contractual obligation; the state of not fulfilling an expected action or role.\",\"s\":\"The contractor faced a fine due to nonperformance of the agreed construction work.\",\"p\":\"non-per-FOR-muns\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.per.for.mance\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonperformative\",\"d\":\"Describing something that does not carry out or enact an action through its utterance or execution; lacking the quality of performing a function.\",\"s\":\"His nonperformative speech was a simple statement of fact, not an action in itself.\",\"p\":\"non-per-FOR-muh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.per.for.ma.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperformer\",\"d\":\"A person or thing that does not perform, achieve, or fulfill expected duties or functions.\",\"s\":\"The manager identified the nonperformer on the team and offered him extra training.\",\"p\":\"non-per-FOR-mer\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.per.former\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonperfumed\",\"d\":\"Not containing or treated with any added fragrance or scent.\",\"s\":\"She chose a nonperfumed lotion to avoid triggering her classmate's allergies.\",\"p\":\"non-per-FYOOMD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.per.fumed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpericyclic\",\"d\":\"Describing a chemical reaction that does not proceed through a cyclic transition state involving a closed loop of electrons.\",\"s\":\"The nonpericyclic reaction followed a stepwise path rather than a concerted ring mechanism.\",\"p\":\"non-pehr-ih-SY-klik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.i.cyclic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonperiod\",\"d\":\"A span of time or a unit that does not qualify as a standard or recognized period; something lacking the characteristics of a defined period.\",\"s\":\"During a nonperiod in the school schedule, students were free to study independently.\",\"p\":\"non-PEER-ee-ud\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pe.ri.od\",\"ps\":\"noun\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonperiodic\",\"d\":\"not recurring at regular intervals\",\"s\":\"The earthquakes in that region are nonperiodic, striking without any predictable pattern.\",\"p\":\"non-peer-ee-OD-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pe.ri.od.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperiodically\",\"d\":\"In a manner that does not recur at regular, predictable intervals; irregularly or randomly over time.\",\"s\":\"The alarm sounded nonperiodically throughout the night, making it impossible to predict.\",\"p\":\"non-peer-ee-OD-ih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.pe.ri.od.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonperiodontal\",\"d\":\"Not relating to or affecting the periodontium, which is the tissue and bone surrounding and supporting the teeth.\",\"s\":\"The dentist noted the pain was nonperiodontal, meaning it had nothing to do with the gums.\",\"p\":\"non-pehr-ee-oh-DON-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pe.ri.odon.tal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonperipheral\",\"d\":\"Not situated at or relating to the outer edge or periphery; central or directly relevant rather than marginal.\",\"s\":\"The scientist argued that the immune system plays a nonperipheral, central role in mental health.\",\"p\":\"non-peh-RIF-er-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pe.riph.er.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperiphrastic\",\"d\":\"Describing a grammatical construction that expresses meaning directly without using additional words or roundabout phrasing.\",\"s\":\"Her nonperiphrastic style meant she said exactly what she meant with no extra words.\",\"p\":\"non-pehr-ih-FRAS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pe.riphrastic\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"wordwords\",\"olatin\"]},{\"w\":\"nonperishable\",\"d\":\"Not subject to quick decay or spoilage; able to be stored for a long time without going bad.\",\"s\":\"The food drive collected only nonperishable items like canned beans and dried pasta.\",\"p\":\"non-PEHR-ish-uh-bul\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.per.ish.able\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonperistaltic\",\"d\":\"Not involving or relating to the wavelike muscular contractions that move food and fluids through the digestive tract.\",\"s\":\"The scientist studied a nonperistaltic pump that moved fluid without wave-like contractions.\",\"p\":\"non-pehr-ih-STAWL-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.peri.staltic\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonperitoneal\",\"d\":\"Not relating to or located within the peritoneum, the membrane that lines the abdominal cavity and covers most abdominal organs.\",\"s\":\"The surgeon confirmed the tumor was nonperitoneal, located outside the abdominal lining.\",\"p\":\"non-pehr-ih-toh-NEE-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.peri.toneal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpermanent\",\"d\":\"Not lasting indefinitely; temporary or subject to change over time.\",\"s\":\"The mural was painted with nonpermanent paint so the school could change it each year.\",\"p\":\"non-PER-muh-nent\",\"o\":\"Latin\",\"y\":7,\"bp\":38,\"sy\":\"non.per.ma.nent\",\"ps\":\"adjective\",\"t\":[\"music\",\"time\",\"olatin\"]},{\"w\":\"nonpermissible\",\"d\":\"Not allowed or permitted; not acceptable under a given set of rules or standards.\",\"s\":\"Talking during a test is nonpermissible and could result in a zero on your paper.\",\"p\":\"non-per-MIS-ih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.per.mis.si.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpermissive\",\"d\":\"Not allowing or granting permission; restrictive in terms of what is tolerated or approved.\",\"s\":\"The nonpermissive coach refused to let players skip practice for any reason.\",\"p\":\"non-per-MIS-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.mis.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpermissiveness\",\"d\":\"The quality or state of being restrictive and unwilling to allow certain behaviors or actions.\",\"s\":\"The school's nonpermissiveness about phone use surprised students used to fewer rules.\",\"p\":\"non-per-MIS-iv-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.per.mis.sive.ness\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpermitted\",\"d\":\"Not authorized or officially allowed; done or existing without proper permission or approval.\",\"s\":\"Building the shed without approval was a nonpermitted construction that violated city codes.\",\"p\":\"non-per-MIT-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.per.mit.ted\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonpermutable\",\"d\":\"Not capable of being rearranged or exchanged in order; unable to be swapped or substituted without changing the outcome.\",\"s\":\"In this equation, the two operations are nonpermutable, so changing their order gives a different answer.\",\"p\":\"non-per-MYOO-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.per.mutable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperpetual\",\"d\":\"Not lasting forever or continuing indefinitely; having a defined end or limited duration.\",\"s\":\"The contract was nonperpetual, set to expire after exactly three years.\",\"p\":\"non-per-PECH-oo-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.per.pet.u.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpersistent\",\"d\":\"Not continuing or enduring over time; tending to break down, disappear, or cease quickly.\",\"s\":\"The nonpersistent pesticide broke down quickly, leaving no harmful residue in the soil.\",\"p\":\"non-per-SIS-tent\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.sis.tent\",\"ps\":\"adjective\",\"t\":[\"character\",\"time\",\"olatin\"]},{\"w\":\"nonpersonal\",\"d\":\"lacking personality\",\"s\":\"The safety manual used nonpersonal language throughout, keeping every instruction objective and detached so that no single employee would feel singled out or blamed for past accidents.\",\"p\":\"non-PER-suh-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.per.son.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpersonality\",\"d\":\"The absence or lack of distinct personal character, individuality, or emotional depth; a state of having no defined personality.\",\"s\":\"The robot's nonpersonality made interactions feel cold and robotic to the customers.\",\"p\":\"non-per-suh-NAL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.per.son.al.i.ty\",\"ps\":\"noun\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonpersonnel\",\"d\":\"Not involving or relating to the staff or human workforce of an organization; referring to equipment, resources, or matters that are not about people.\",\"s\":\"The security badge restricted nonpersonnel from entering the government building.\",\"p\":\"non-per-suh-NEL\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.per.son.nel\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpersuasive\",\"d\":\"Not effective at convincing others; failing to change someone's opinion or move them to action.\",\"s\":\"The student's nonpersuasive essay failed to convince the judges of her argument.\",\"p\":\"non-per-SWAY-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.per.sua.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpertinent\",\"d\":\"Not relevant or applicable to the subject at hand; having no direct bearing on the matter being discussed.\",\"s\":\"The teacher asked students to remove nonpertinent details from their research papers.\",\"p\":\"non-PER-tih-nent\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.per.ti.nent\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonperturbative\",\"d\":\"In physics and mathematics, describing methods or phenomena that cannot be adequately described by adding small disturbances to a known solution; dealing with strong effects that cannot be approximated step by step.\",\"s\":\"The physicist used a nonperturbative method to solve the equation without relying on small approximations.\",\"p\":\"non-per-TER-buh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.per.tur.ba.tive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonpervasive\",\"d\":\"Not spreading widely throughout a system, area, or group; limited in reach and not affecting everything around it.\",\"s\":\"The mild scent of the candle was nonpervasive, staying only in the corner of the room.\",\"p\":\"non-per-VAY-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.per.va.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonperverted\",\"d\":\"Not distorted, corrupted, or turned away from its original or correct meaning and purpose.\",\"s\":\"The judge noted that the defendant's original statement was nonperverted and had not been twisted out of context.\",\"p\":\"non-per-VER-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.per.vert.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpest\",\"d\":\"An organism or creature that is not considered harmful, destructive, or a nuisance to humans, crops, or property.\",\"s\":\"The ladybug is classified as a nonpest insect because it actually helps gardens by eating harmful bugs.\",\"p\":\"NON-pest\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.pest\",\"ps\":\"noun\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonpesticidal\",\"d\":\"Not involving or having the properties of a pesticide; not designed or used to kill or repel pests.\",\"s\":\"The farmer chose a nonpesticidal approach, using natural predators to control insects instead of chemicals.\",\"p\":\"non-pes-tih-SY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pes.ti.ci.dal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpesticide\",\"d\":\"A substance or method used in pest control that does not involve chemical pesticides; any non-chemical approach to managing pests.\",\"s\":\"The organic label confirmed that the spray was a nonpesticide solution safe for children and pets.\",\"p\":\"non-PES-tih-syd\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pes.ti.cide\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpetrified\",\"d\":\"Not turned to stone or fossilized; remaining in an organic or unsolidified state rather than being mineralized over time.\",\"s\":\"The nonpetrified wood in the forest floor was still soft and decomposing naturally.\",\"p\":\"non-PET-rih-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pet.ri.fied\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"time\",\"olatin\"]},{\"w\":\"nonpetrochemical\",\"d\":\"Not derived from petroleum or natural gas; referring to chemicals or processes that do not originate from fossil fuel sources.\",\"s\":\"The company invested in nonpetrochemical plastics made from plants rather than oil.\",\"p\":\"non-pet-roh-KEM-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.petro.chem.i.cal\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"nonphage\",\"d\":\"An entity, particularly a virus or organism, that does not function as a bacteriophage and therefore does not infect or destroy bacterial cells.\",\"s\":\"Scientists identified the bacterium's behavior as nonphage, meaning it was not infected or driven by a virus.\",\"p\":\"NON-fayj\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.phage\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonphagocytic\",\"d\":\"Not capable of or relating to phagocytosis, the process by which certain cells engulf and destroy bacteria, foreign particles, or debris.\",\"s\":\"The researchers discovered that the nonphagocytic cells could not engulf and destroy the invading bacteria.\",\"p\":\"non-fag-oh-SIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.phago.cyt.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"physics\",\"olatin\"]},{\"w\":\"nonpharma\",\"d\":\"Not relating to the pharmaceutical industry; referring to healthcare, treatments, or companies that operate outside of drug manufacturing and sales.\",\"s\":\"The health startup focused on nonpharma solutions like exercise and diet to treat mild depression.\",\"p\":\"non-FAR-muh\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.phar.ma\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"olatin\"]},{\"w\":\"nonpharmacist\",\"d\":\"A person who is not a licensed or trained pharmacist; someone working in a related field without pharmacist credentials.\",\"s\":\"As a nonpharmacist, she was not allowed to dispense prescription medications without supervision.\",\"p\":\"non-FAR-muh-sist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.phar.ma.cist\",\"ps\":\"noun\",\"t\":[\"pharmacy\",\"character\",\"olatin\"]},{\"w\":\"nonpharmacological\",\"d\":\"Not involving the use of drugs or medications; referring to treatments or therapies that address health conditions through non-drug means such as exercise, therapy, or diet.\",\"s\":\"The doctor recommended nonpharmacological treatments like meditation and stretching before prescribing pills.\",\"p\":\"non-far-muh-kuh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"sy\":\"non.phar.ma.co.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonpharmacy\",\"d\":\"Not related to or operating as a pharmacy; describing a business, product, or service that does not involve the dispensing or sale of prescription medications.\",\"s\":\"The wellness store was a nonpharmacy retailer, selling vitamins but not prescription drugs.\",\"p\":\"non-FAR-muh-see\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.phar.ma.cy\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonpharyngeal\",\"d\":\"Not relating to or involving the pharynx, the muscular tube at the back of the throat that connects the nasal passages and mouth to the esophagus.\",\"s\":\"The infection was nonpharyngeal, affecting the lungs rather than the throat.\",\"p\":\"non-fuh-RIN-jee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pha.ryn.geal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonphased\",\"d\":\"not divided into or carried out in separate stages\",\"s\":\"The builders used a nonphased schedule and finished the whole school in one go instead of stage by stage.\",\"p\":\"non-FAYZD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.phased\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonphasic\",\"d\":\"Not occurring in distinct phases or stages; describing a process or signal that does not alternate between separate, identifiable states.\",\"s\":\"The electrical signal was described as nonphasic because it did not occur in distinct repetitive phases.\",\"p\":\"non-FAY-zik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pha.sic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonphatic\",\"d\":\"Not serving merely as a social ritual or conversational filler; describing communication that conveys real, substantive meaning rather than just maintaining social contact.\",\"s\":\"Unlike casual small talk, the speech was nonphatic, loaded with specific and meaningful information.\",\"p\":\"non-FAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.phat.ic\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonphenomenological\",\"d\":\"Not based on or relating to phenomenology, the philosophical study of conscious experience and how things appear to the mind from a first-person perspective.\",\"s\":\"The study took a nonphenomenological approach, relying on data and statistics rather than personal experience.\",\"p\":\"non-feh-nom-uh-nuh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.phe.nomeno.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonphenomenologically\",\"d\":\"In a manner that does not rely on phenomenological methods; approaching a subject without analyzing lived, subjective experience from a first-person perspective.\",\"s\":\"The researcher argued nonphenomenologically, focusing on measurable facts rather than subjective feelings.\",\"p\":\"non-feh-nom-uh-nuh-LOJ-ih-kuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.phe.nomeno.log.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonphilanthropic\",\"d\":\"Not charitable or generous toward others; describing an organization or activity that does not aim to promote the welfare of people through donations or volunteer work.\",\"s\":\"The corporation was criticized for its nonphilanthropic practices, giving almost nothing back to the community.\",\"p\":\"non-fil-un-THROP-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.phi.lan.throp.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonphilatelic\",\"d\":\"Not related to or associated with the hobby of stamp collecting; describing items or events that have nothing to do with postage stamps or their study.\",\"s\":\"He organized his collection into nonphilatelic memorabilia, like coins and old postcards rather than stamps.\",\"p\":\"non-fil-uh-TEL-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.philatel.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonphilosopher\",\"d\":\"A person who is not trained in or professionally engaged with philosophy; someone who does not study or practice systematic reasoning about fundamental questions.\",\"s\":\"As a nonphilosopher, she still enjoyed debating big questions about life and meaning with her friends.\",\"p\":\"non-fih-LOS-uh-fer\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.philoso.pher\",\"ps\":\"noun\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonphilosophical\",\"d\":\"Not involving or based on philosophical reasoning or deep abstract thought; dealing with practical matters rather than fundamental questions about existence, knowledge, or ethics.\",\"s\":\"His answer was practical and nonphilosophical, focused on solving the immediate problem rather than pondering its meaning.\",\"p\":\"non-fil-uh-SOF-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.philo.soph.i.cal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonphilosophically\",\"d\":\"In a manner that does not involve philosophical thinking or analysis; approaching a topic practically without examining underlying principles or abstract reasoning.\",\"s\":\"She responded nonphilosophically to the ethical dilemma, choosing the most practical solution without deeper reflection.\",\"p\":\"non-fil-uh-SOF-ih-kuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.philo.soph.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonphilosophy\",\"d\":\"Thought, belief, or everyday reasoning that does not follow the formal methods or traditions of academic philosophy; practical thinking that avoids systematic inquiry into fundamental questions.\",\"s\":\"The professor argued that common sense was a form of nonphilosophy, useful but lacking rigorous reasoning.\",\"p\":\"non-fih-LOS-uh-fee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.phi.los.o.phy\",\"ps\":\"noun\",\"t\":[\"festivals\",\"logic\",\"olatin\"]},{\"w\":\"nonphobic\",\"d\":\"Not having or showing an irrational, extreme fear of a particular thing or situation; describing a person or response that is free from phobia-related anxiety.\",\"s\":\"Unlike her sister, Maya was completely nonphobic about spiders and could hold them without flinching.\",\"p\":\"non-FOH-bik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pho.bic\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonphonemic\",\"d\":\"Not functioning as a phoneme, meaning the difference between two sounds does not change the meaning of a word in a particular language.\",\"s\":\"The slight variation in the speaker's vowel was nonphonemic, not changing the meaning of any word.\",\"p\":\"non-fuh-NEE-mik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.phone.mic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonphonetic\",\"d\":\"Not representing speech sounds directly or consistently; describing a writing system or spelling where letters do not reliably correspond to the sounds they stand for.\",\"s\":\"English spelling is often nonphonetic, meaning words like 'knight' are not spelled the way they sound.\",\"p\":\"non-fuh-NET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pho.net.ic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonphonetically\",\"d\":\"In a way that does not correspond directly to the sounds of spoken language; spelled or written without following phonetic principles.\",\"s\":\"The word 'colonel' is spelled nonphonetically, looking nothing like it sounds when spoken aloud.\",\"p\":\"non-fuh-NET-ih-kuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.pho.net.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"logic\",\"wordwords\",\"olatin\"]},{\"w\":\"nonphonological\",\"d\":\"Not related to phonology, the study of sound patterns in language; describing a feature or process that involves language but does not concern how sounds are organized or structured.\",\"s\":\"The linguist noted that the speech error was nonphonological, related to word choice rather than sound patterns.\",\"p\":\"non-foh-nuh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.phono.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonphosphate\",\"d\":\"Not containing or derived from phosphate; describing a detergent, fertilizer, or chemical compound that is free of phosphate compounds, which can pollute waterways.\",\"s\":\"The environmentally friendly detergent was nonphosphate, helping to prevent algae blooms in nearby lakes.\",\"p\":\"non-FOS-fayt\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.phos.phate\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"farming\",\"olatin\"]},{\"w\":\"nonphosphatized\",\"d\":\"Not having been treated or coated with a phosphate compound; describing a surface or material that has not undergone a phosphatizing chemical process.\",\"s\":\"The nonphosphatized metal surface required a different coating process to prevent rust.\",\"p\":\"non-FOS-fuh-tyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.phos.pha.tized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonphosphorized\",\"d\":\"Not having been treated or alloyed with phosphorus; describing a metal or material that has not undergone a phosphorizing process to alter its properties.\",\"s\":\"The steel was labeled nonphosphorized, meaning it contained no added phosphorus during production.\",\"p\":\"non-FOS-fuh-ryzd\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.phos.pho.rized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonphosphorous\",\"d\":\"Not containing or relating to the element phosphorus in its lower-valence form; describing a substance that is free of phosphorous compounds.\",\"s\":\"The chemist confirmed the compound was nonphosphorous, ruling out any phosphorus-based reactions.\",\"p\":\"non-FOS-fuh-rus\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.phos.pho.rous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonphosphorus\",\"d\":\"Not containing the chemical element phosphorus; describing a compound, material, or formula that is entirely free of phosphorus.\",\"s\":\"The fertilizer was certified as nonphosphorus to protect the nearby wetland from nutrient pollution.\",\"p\":\"non-FOS-fuh-rus\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.phos.pho.rus\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonphosphorylated\",\"d\":\"Describing a molecule, especially a protein, that has not had a phosphate group chemically attached to it; lacking the phosphorylation modification that often activates or deactivates biological molecules.\",\"s\":\"The nonphosphorylated protein could not activate the cell's signaling pathway, halting the reaction.\",\"p\":\"non-fos-FOR-ih-lay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.phos.pho.ry.lat.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonphotic\",\"d\":\"Not involving or triggered by light; describing environmental cues or biological processes, such as certain circadian rhythm signals, that do not depend on light exposure.\",\"s\":\"Deep-sea creatures rely on nonphotic cues like pressure and chemical signals instead of light to navigate.\",\"p\":\"non-FOH-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.phot.ic\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"music\",\"olatin\"]},{\"w\":\"nonphotobiotic\",\"d\":\"Not dependent on light for survival or biological activity; describing organisms or processes that can live and function without the presence of light.\",\"s\":\"The cave bacteria were nonphotobiotic, thriving completely without any exposure to sunlight.\",\"p\":\"non-foh-toh-by-OT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pho.to.bi.ot.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonphotochromic\",\"d\":\"Not capable of changing color in response to light exposure; describing a lens, material, or substance that remains the same color regardless of light conditions.\",\"s\":\"The nonphotochromic lenses in his glasses did not darken when he stepped outside into the bright sun.\",\"p\":\"non-foh-toh-KROH-mik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pho.tochromic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"colors\",\"olatin\"]},{\"w\":\"nonphotographer\",\"d\":\"A person who does not practice or identify as a photographer; someone who takes pictures casually or rarely rather than as a skill or profession.\",\"s\":\"As a nonphotographer, Marcus still managed to snap a stunning picture with his phone.\",\"p\":\"non-fuh-TOG-ruh-fer\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pho.tog.ra.pher\",\"ps\":\"noun\",\"t\":[\"jobs\",\"olatin\"]},{\"w\":\"nonphotographic\",\"d\":\"Not relating to or produced by photography; describing images, techniques, or artwork that are created without the use of a camera or photographic processes.\",\"s\":\"The artist chose a nonphotographic style, using bold brushstrokes instead of realistic detail.\",\"p\":\"non-foh-tuh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pho.to.graph.ic\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonphotolithographic\",\"d\":\"Not using photolithography, a process that uses light to transfer patterns onto surfaces; describing manufacturing or printing techniques that create patterns without exposing light-sensitive materials.\",\"s\":\"The engineers developed a nonphotolithographic method to print circuits on tiny chips.\",\"p\":\"non-foh-toh-lith-uh-GRAF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pho.tolitho.graph.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonphotonic\",\"d\":\"Not involving or relating to photons, the fundamental particles of light; describing a device, process, or system that operates without using light-based technology.\",\"s\":\"The nonphotonic signal traveled through the wire using electrons rather than light particles.\",\"p\":\"non-foh-TON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pho.ton.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"tools\",\"olatin\"]},{\"w\":\"nonphotoreactive\",\"d\":\"Not capable of undergoing a chemical reaction when exposed to light; describing a substance or material that remains chemically unchanged regardless of light exposure.\",\"s\":\"The nonphotoreactive coating stayed stable even after hours of direct sunlight.\",\"p\":\"non-foh-toh-ree-AK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pho.tore.ac.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonphotorealistic\",\"d\":\"Not attempting to resemble a real photograph or lifelike image; describing an artistic or digital style that uses abstraction, stylization, or cartoon-like qualities instead of realistic detail.\",\"s\":\"The video game had a charming nonphotorealistic look, with cartoon-like colors and thick outlines.\",\"p\":\"non-foh-toh-ree-uh-LIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.pho.to.re.al.is.tic\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonphotorefractive\",\"d\":\"Not causing the refraction or bending of light; describing an optical material or medium through which light passes without being bent or redirected.\",\"s\":\"Scientists searched for a nonphotorefractive crystal that would not bend light when exposed to a laser.\",\"p\":\"non-foh-toh-rih-FRAK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pho.tore.frac.tive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonphotosensitive\",\"d\":\"Not reactive or sensitive to light; describing a material, organism, or chemical that does not change or respond when exposed to light energy.\",\"s\":\"The nonphotosensitive material could be handled under bright lab lights without being damaged.\",\"p\":\"non-foh-toh-SEN-sih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pho.to.sen.si.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonphotovoltaic\",\"d\":\"Not capable of converting light energy into electrical energy; describing a material or device that does not produce voltage or electric current when exposed to sunlight.\",\"s\":\"The roof tiles were decorative and nonphotovoltaic, meaning they couldn't generate electricity from sunlight.\",\"p\":\"non-foh-toh-vol-TAY-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pho.to.volta.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"tools\",\"olatin\"]},{\"w\":\"nonphrasal\",\"d\":\"Not consisting of or functioning as a phrase; describing a grammatical unit, especially a single word, that does not form a multi-word phrase.\",\"s\":\"The grammar lesson focused on nonphrasal verbs, which are single words rather than multi-word expressions.\",\"p\":\"non-FRAY-zul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.phrasal\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonphreatic\",\"d\":\"Not relating to groundwater or the zone of saturation below the water table; describing water, geological features, or processes that are not connected to underground aquifer systems.\",\"s\":\"The geologist noted that the cave's water source was nonphreatic and came from surface rainfall instead.\",\"p\":\"non-free-AT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.phreat.ic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"household\",\"olatin\"]},{\"w\":\"nonphylogenetic\",\"d\":\"Not based on or relating to phylogenetics, the study of evolutionary relationships among organisms; describing a classification or analysis that does not use family-tree or ancestral lineage data.\",\"s\":\"The classification system was nonphylogenetic, grouping animals by color rather than by evolutionary history.\",\"p\":\"non-fy-loh-juh-NET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.phy.lo.ge.net.ic\",\"ps\":\"adjective\",\"t\":[\"flowers\",\"kinship\",\"olatin\"]},{\"w\":\"nonphysician\",\"d\":\"A person who works in a healthcare or medical setting but does not hold a physician's medical degree; such as a nurse, physician assistant, or medical technician.\",\"s\":\"The hospital employed many nonphysician staff members, including nurses, technicians, and counselors.\",\"p\":\"non-fih-ZIH-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.physi.cian\",\"ps\":\"noun\",\"t\":[\"body\",\"jobs\",\"olatin\"]},{\"w\":\"nonphysicist\",\"d\":\"A person who is not a scientist specializing in physics; someone whose work or expertise lies outside the field of physics.\",\"s\":\"Even as a nonphysicist, Elena understood the basic concept of gravity after watching the documentary.\",\"p\":\"non-FIZ-ih-sist\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.physi.cist\",\"ps\":\"noun\",\"t\":[\"physics\",\"character\",\"olatin\"]},{\"w\":\"nonphysics\",\"d\":\"Any subject, field, or area of study that is not physics; relating to disciplines outside the science of physics.\",\"s\":\"Her nonphysics classes, like art and history, were her favorite parts of the school day.\",\"p\":\"non-FIZ-iks\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.physics\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonphysiological\",\"d\":\"Not related to or consistent with the normal functioning of a living organism's body; outside the scope of physiology.\",\"s\":\"The researcher warned that the nonphysiological conditions in the lab might affect the experiment's results.\",\"p\":\"non-fiz-ee-oh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.phys.i.o.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonphytotoxic\",\"d\":\"Not harmful or poisonous to plants; describing a substance that can be used around plants without causing damage to them.\",\"s\":\"Gardeners preferred the nonphytotoxic fertilizer because it fed the soil without harming the plants.\",\"p\":\"non-fy-toh-TOK-sik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.phy.to.tox.ic\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonpianist\",\"d\":\"A person who does not play the piano or has no training or skill as a pianist.\",\"s\":\"As a nonpianist, Jake still enjoyed listening to Beethoven's sonatas for hours.\",\"p\":\"non-pee-AN-ist\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pianist\",\"ps\":\"noun\",\"t\":[\"music\",\"stage\",\"olatin\"]},{\"w\":\"nonpiano\",\"d\":\"Relating to or describing music or musical performance that does not involve or feature a piano.\",\"s\":\"The composer wrote a nonpiano arrangement so the piece could be performed by a string quartet.\",\"p\":\"non-pee-AN-oh\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.piano\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonpictorial\",\"d\":\"Not expressed through or consisting of pictures or images; conveying information through means other than visual illustration.\",\"s\":\"The nonpictorial text consisted entirely of words and numbers with no images or diagrams.\",\"p\":\"non-pik-TOR-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.pic.to.ri.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpierced\",\"d\":\"Not having been pierced; describing something, such as ears or metal, that has no holes made through it.\",\"s\":\"She chose nonpierced earrings that clipped onto the earlobe without any holes.\",\"p\":\"non-PEERST\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pierced\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpiezoelectric\",\"d\":\"Not exhibiting the piezoelectric effect; describing a material that does not generate an electric charge when mechanical pressure is applied to it.\",\"s\":\"The lab tested a nonpiezoelectric crystal that produced no voltage when squeezed.\",\"p\":\"non-pee-AY-zoh-ih-lek-trik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.piezo.elec.tric\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpiezomagnetic\",\"d\":\"Not exhibiting piezomagnetic properties; describing a material that does not become magnetized when subjected to mechanical stress or pressure.\",\"s\":\"The nonpiezomagnetic alloy showed no change in magnetism when mechanical stress was applied.\",\"p\":\"non-pee-AY-zoh-mag-NET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.piezo.mag.net.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpig\",\"d\":\"Any animal or living thing that is not a pig; used to distinguish organisms or categories that exclude swine.\",\"s\":\"The farmer separated the nonpig animals into a different pen from the swine.\",\"p\":\"non-PIG\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.pig\",\"ps\":\"noun\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonpilot\",\"d\":\"A person who is not a pilot; someone who travels in an aircraft or operates in aviation without being the one flying the plane.\",\"s\":\"As a nonpilot passenger, she trusted the crew completely to navigate the stormy skies.\",\"p\":\"non-PY-lut\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.pilot\",\"ps\":\"noun\",\"t\":[\"character\",\"vehicles\",\"olatin\"]},{\"w\":\"nonpiloted\",\"d\":\"Not operated or controlled by a human pilot; describing a vehicle or aircraft that flies or moves without a person at the controls.\",\"s\":\"The nonpiloted drone completed its delivery route using only GPS and automated software.\",\"p\":\"non-PY-lut-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pilot.ed\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonpine\",\"d\":\"Referring to trees or plants that are not members of the pine family; any woody plant that lacks the characteristics of pines, such as needles or cones.\",\"s\":\"The forest contained mostly nonpine trees, such as oak, maple, and birch.\",\"p\":\"non-PYN\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.pine\",\"ps\":\"adjective\",\"t\":[\"botany\",\"flowers\",\"kinship\",\"olatin\"]},{\"w\":\"nonpink\",\"d\":\"Of any color other than pink; used to describe objects, materials, or items that are not pink in hue.\",\"s\":\"She requested a nonpink birthday cake, choosing a deep blue frosting instead.\",\"p\":\"non-PINK\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.pink\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonpionic\",\"d\":\"Not involving or relating to pions, which are subatomic particles found in physics; describing processes or interactions in which pions play no role.\",\"s\":\"The physics team studied nonpionic particle interactions that didn't involve pion exchange.\",\"p\":\"non-py-ON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.pionic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"stage\",\"olatin\"]},{\"w\":\"nonpipelined\",\"d\":\"Not using a pipeline architecture; describing a computer or processor system in which tasks are completed one at a time rather than in overlapping stages.\",\"s\":\"The older, nonpipelined processor handled one instruction at a time, making it slower than modern chips.\",\"p\":\"non-PYP-lynd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pipelined\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"time\",\"olatin\"]},{\"w\":\"nonpirated\",\"d\":\"Legally obtained or produced; describing software, media, or goods that have not been copied or distributed without authorization.\",\"s\":\"She always purchased nonpirated software directly from the company's official website.\",\"p\":\"non-PY-ray-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pirat.ed\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"nonpitcher\",\"d\":\"A baseball player who does not play the position of pitcher; any player whose primary role on the team is something other than pitching.\",\"s\":\"The baseball manager moved the nonpitcher to first base since he wasn't skilled at throwing strikes.\",\"p\":\"non-PICH-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pitch.er\",\"ps\":\"noun\",\"t\":[\"stage\",\"sports\",\"olatin\"]},{\"w\":\"nonpitching\",\"d\":\"Not related to the act of throwing pitches in baseball; describing a player's arm, actions, or roles that do not involve pitching.\",\"s\":\"Her nonpitching arm was stronger, so coaches moved her to the outfield instead.\",\"p\":\"non-PICH-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.pitch.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonpitted\",\"d\":\"Having no pit, cavity, or hollow center; describing a fruit or surface that is smooth and free of indentations or pits.\",\"s\":\"The chef preferred nonpitted olives because they were safer to serve at the party.\",\"p\":\"non-PIT-ed\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pit.ted\",\"ps\":\"adjective\",\"t\":[\"spices\",\"olatin\"]},{\"w\":\"nonpituitary\",\"d\":\"Not originating from or related to the pituitary gland; describing hormones, tumors, or conditions that do not involve the pituitary gland.\",\"s\":\"The doctors discovered that the hormone imbalance had a nonpituitary cause, originating in the thyroid instead.\",\"p\":\"non-pih-TOO-ih-ter-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pi.tu.itary\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonpivotal\",\"d\":\"Not central or critical to an outcome; describing something that does not serve as a turning point or key factor in a situation or process.\",\"s\":\"The coach considered that play a nonpivotal moment in the game since it didn't change the score.\",\"p\":\"non-PIV-uh-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.piv.otal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpivoted\",\"d\":\"Not having turned or rotated on a central point; describing something that remained stationary rather than swinging or rotating around a pivot.\",\"s\":\"The nonpivoted arm of the machine moved only in a straight line rather than rotating.\",\"p\":\"non-PIV-ut-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.piv.ot.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpivoting\",\"d\":\"Not rotating or turning around a fixed central point; describing a mechanism or object that remains fixed in one direction without swiveling.\",\"s\":\"The nonpivoting shelf stayed fixed to the wall and could not be rotated to a different angle.\",\"p\":\"non-PIV-ut-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.piv.ot.ing\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonpixel\",\"d\":\"Not consisting of or relating to pixels; describing an image, graphic, or display technology that does not use individual square dots to form a picture.\",\"s\":\"The artist's nonpixel artwork was hand-painted on canvas and had no digital components at all.\",\"p\":\"non-PIK-sul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pix.el\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpizza\",\"d\":\"Any food item or menu option that is not pizza; used to describe meals or dishes served at a restaurant that fall outside the pizza category.\",\"s\":\"The restaurant offered a nonpizza menu for customers who wanted pasta, salads, and sandwiches instead.\",\"p\":\"non-PEET-suh\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.piz.za\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"nonplace\",\"d\":\"A location that lacks a distinct identity or sense of community, such as an airport, highway, or shopping mall, where people pass through without forming meaningful connections.\",\"s\":\"The airport terminal felt like a nonplace where travelers existed between destinations without truly belonging anywhere.\",\"p\":\"non-PLAYS\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.place\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonplacebo\",\"d\":\"An actual medical treatment or drug that has a real pharmacological effect, as opposed to an inert substance given to a control group in an experiment.\",\"s\":\"Researchers distinguished the active drug from the nonplacebo controls in their clinical trial notes.\",\"p\":\"non-pluh-SEE-boh\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.place.bo\",\"ps\":\"noun\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonplaced\",\"d\":\"Not assigned to a specific position, rank, or location; describing a person or thing that has not been placed in a particular spot or standing.\",\"s\":\"Several nonplaced applicants waited anxiously to hear if any remaining spots in the program would open up.\",\"p\":\"non-PLAYST\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.placed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonplacement\",\"d\":\"The condition of not being placed or assigned to a position; the absence of a formal or official assignment to a role, location, or rank.\",\"s\":\"The agency reported a high rate of nonplacement among foster children who had been in the system for years.\",\"p\":\"non-PLAYS-munt\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.place.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonplacental\",\"d\":\"Not having or relating to a placenta; describing mammals, such as marsupials or monotremes, whose young do not develop through a placenta inside the mother.\",\"s\":\"Monotremes are nonplacental mammals that lay eggs instead of giving birth to fully developed young.\",\"p\":\"non-pluh-SEN-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pla.cen.tal\",\"ps\":\"adjective\",\"t\":[\"animals\",\"kinship\",\"olatin\"]},{\"w\":\"nonplague\",\"d\":\"Not constituting or caused by a plague; describing a disease, infection, or event that does not rise to the level of a widespread epidemic catastrophe.\",\"s\":\"Scientists confirmed the illness was a nonplague bacterial infection that responded well to standard antibiotics.\",\"p\":\"non-PLAYG\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.plague\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonplaintiff\",\"d\":\"A party in a legal case who is not the plaintiff; any person involved in or affected by a lawsuit who did not initiate the legal action.\",\"s\":\"The judge reminded the nonplaintiff parties in the courtroom to remain silent during the opening statements.\",\"p\":\"non-PLAYN-tif\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.plain.tiff\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonplanarity\",\"d\":\"The quality or state of not being flat or lying in a single geometric plane; the property of a shape or molecule that curves or extends into three-dimensional space.\",\"s\":\"The chemist noted the nonplanarity of the molecule made it twist in three dimensions rather than lying flat.\",\"p\":\"non-pluh-NAIR-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pla.nari.ty\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonplane\",\"d\":\"Not flat or two-dimensional; describing a surface, curve, or shape that does not lie entirely within a single geometric plane.\",\"s\":\"The architect designed a nonplane surface that curved elegantly across the entire roof of the building.\",\"p\":\"non-PLAYN\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.plane\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonplanetary\",\"d\":\"Not relating to or characteristic of a planet; describing celestial objects, such as asteroids or comets, that do not qualify as full planets in the solar system.\",\"s\":\"Astronomers studied the nonplanetary debris floating in the asteroid belt between Mars and Jupiter.\",\"p\":\"non-PLAN-ih-ter-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.plan.e.tary\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"nonplankton\",\"d\":\"Aquatic organisms that are not plankton; creatures that actively swim or move through water rather than drifting passively with currents.\",\"s\":\"The marine biologist separated the nonplankton organisms from the tiny drifting creatures in her water sample.\",\"p\":\"non-PLANK-tun\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.plank.ton\",\"ps\":\"noun\",\"t\":[\"marine\",\"olatin\"]},{\"w\":\"nonplanktonic\",\"d\":\"Not characteristic of or relating to plankton; describing aquatic organisms that do not drift passively with water currents but instead move under their own power.\",\"s\":\"The nonplanktonic larvae attached themselves firmly to rocks rather than floating freely in the current.\",\"p\":\"non-plank-TON-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.plank.ton.ic\",\"ps\":\"adjective\",\"t\":[\"marine\",\"olatin\"]},{\"w\":\"nonplanned\",\"d\":\"Not organized, arranged, or decided in advance; occurring without a formal plan or deliberate prior preparation.\",\"s\":\"The nonplanned detour through the small town turned out to be the best part of their road trip.\",\"p\":\"non-PLAND\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.planned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonplanner\",\"d\":\"A person who does not make plans or prepare in advance; someone who acts spontaneously without organizing or scheduling their activities.\",\"s\":\"As a self-described nonplanner, she preferred to make decisions spontaneously rather than scheduling every detail.\",\"p\":\"non-PLAN-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.plan.ner\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonplant\",\"d\":\"An organism or object that is not a plant; something that lacks the characteristics of plant life, such as photosynthesis or rooted growth.\",\"s\":\"Fungi are classified as nonplant organisms because they lack chlorophyll and cannot perform photosynthesis.\",\"p\":\"NON-plant\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.plant\",\"ps\":\"noun\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonplantar\",\"d\":\"Not relating to or located on the sole of the foot; describing a surface, structure, or region that is not on the bottom of the foot.\",\"s\":\"The doctor examined the nonplantar surface of the foot, focusing on the top rather than the sole.\",\"p\":\"non-PLAN-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.plan.tar\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonplantation\",\"d\":\"A piece of land or agricultural operation that is not organized as a plantation; a farming arrangement that lacks the large-scale, single-crop structure of a traditional plantation.\",\"s\":\"The region's nonplantation farms relied on small family operations rather than large-scale crop production.\",\"p\":\"non-plan-TAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.plan.ta.tion\",\"ps\":\"noun\",\"t\":[\"farming\",\"festivals\",\"olatin\"]},{\"w\":\"nonplanted\",\"d\":\"Not deliberately placed in the ground by human effort; describing vegetation or seeds that established themselves naturally rather than through intentional cultivation.\",\"s\":\"Wildflowers filled the nonplanted field, having seeded themselves naturally without any human intervention.\",\"p\":\"non-PLANT-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.plant.ed\",\"ps\":\"adjective\",\"t\":[\"botany\",\"farming\",\"olatin\"]},{\"w\":\"nonplantigrade\",\"d\":\"Not walking with the entire sole of the foot flat on the ground; describing an animal that walks on its toes or hooves rather than the full foot surface.\",\"s\":\"Horses are nonplantigrade animals because they walk on their hooftips rather than the full sole of the foot.\",\"p\":\"non-PLAN-tih-grayd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.planti.grade\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonplaque\",\"d\":\"Not consisting of or relating to plaque; describing a substance, surface, or condition that does not involve the sticky bacterial film found on teeth or in arteries.\",\"s\":\"The dentist confirmed the white spots were nonplaque deposits that required a different cleaning technique.\",\"p\":\"non-PLAK\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.plaque\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonplasmatic\",\"d\":\"Not of or relating to plasma; describing particles, components, or substances that are not found within or derived from the liquid portion of blood or other bodily fluids.\",\"s\":\"The researchers identified the nonplasmatic proteins that existed outside the cell's plasma environment.\",\"p\":\"non-plaz-MAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.plas.mat.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"physics\",\"olatin\"]},{\"w\":\"nonplastic\",\"d\":\"Not made of or resembling plastic; lacking the ability to be molded or shaped, or simply not composed of synthetic polymer material.\",\"s\":\"The eco-friendly store prided itself on selling only nonplastic packaging made from recycled paper.\",\"p\":\"non-PLAS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.plas.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonplasticity\",\"d\":\"The quality or state of being unable to be molded, shaped, or permanently deformed; the absence of the ability to change form under pressure or stress.\",\"s\":\"The ceramic's nonplasticity made it impossible to reshape once it had hardened in the kiln.\",\"p\":\"non-plas-TIS-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.plas.tic.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonplatelet\",\"d\":\"Not consisting of or relating to platelets; describing a blood component or cell type that is not one of the small disc-shaped particles responsible for blood clotting.\",\"s\":\"The hematologist studied the nonplatelet cells in the blood sample to rule out clotting disorders.\",\"p\":\"non-PLAYT-let\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.platelet\",\"ps\":\"adjective\",\"t\":[\"body\",\"physics\",\"olatin\"]},{\"w\":\"nonplatinum\",\"d\":\"Not composed of or relating to the precious metal platinum; describing a catalyst, jewelry, or chemical compound that does not contain or use platinum.\",\"s\":\"The jeweler crafted the ring from a nonplatinum alloy that was more affordable but equally durable.\",\"p\":\"non-PLAT-ih-num\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.plat.inum\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonplatonic\",\"d\":\"Not purely spiritual or intellectual in nature; describing a relationship or feeling that includes physical attraction or romantic interest beyond Plato's concept of ideal, non-physical love.\",\"s\":\"Their friendship quickly became nonplatonic when they realized they had developed deeper romantic feelings.\",\"p\":\"non-pluh-TON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pla.ton.ic\",\"ps\":\"adjective\",\"t\":[\"religion\",\"ancient\",\"olatin\"]},{\"w\":\"nonplay\",\"d\":\"A theatrical or literary work that does not conform to the conventions of a traditional stage play; also used to describe a situation or piece of writing that lacks dramatic or performative qualities.\",\"s\":\"The director categorized the script as a nonplay since it was written as a prose narrative, not a drama.\",\"p\":\"NON-play\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.play\",\"ps\":\"noun\",\"t\":[\"stage\",\"poetry\",\"festivals\",\"olatin\"]},{\"w\":\"nonplayable\",\"d\":\"Not able to be played, performed, or used in a game; describing a character, piece of music, or game element that cannot be directly controlled or performed by a participant.\",\"s\":\"The cracked vinyl record was nonplayable and would scratch the needle if placed on the turntable.\",\"p\":\"non-PLAY-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.playable\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"music\",\"sports\",\"olatin\"]},{\"w\":\"nonplayer\",\"d\":\"A person who does not participate as an active player in a game, sport, or activity; someone who observes, manages, or supports without directly competing.\",\"s\":\"As a nonplayer, she enjoyed watching the chess tournament but never competed herself.\",\"p\":\"non-PLAY-er\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.play.er\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonplaying\",\"d\":\"Not actively participating in a game or performance; describing a coach, manager, or official who is involved in an activity but does not take part as a competitor or performer.\",\"s\":\"The nonplaying coach stood on the sideline, giving advice to the team without entering the game.\",\"p\":\"non-PLAY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.play.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"vehicles\",\"olatin\"]},{\"w\":\"nonplayoff\",\"d\":\"Not relating to or participating in a playoff; describing a game, team, or season that does not qualify for or is not part of the postseason elimination rounds.\",\"s\":\"Several talented teams had a nonplayoff season after losing key players to injury early in the year.\",\"p\":\"non-PLAY-awf\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.play.off\",\"ps\":\"adjective\",\"t\":[\"sports\",\"time\",\"olatin\"]},{\"w\":\"nonpleasurable\",\"d\":\"Not producing or associated with pleasure or enjoyment; describing an experience, activity, or sensation that fails to bring satisfaction or positive feelings.\",\"s\":\"The patient described the physical therapy exercises as nonpleasurable but necessary for recovery.\",\"p\":\"non-PLEZH-er-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.plea.sur.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpleomorphic\",\"d\":\"Not exhibiting pleomorphism; describing an organism, cell, or crystal that maintains a single, consistent shape rather than taking on multiple different forms.\",\"s\":\"The nonpleomorphic bacteria maintained a consistent rod shape under all the laboratory conditions tested.\",\"p\":\"non-plee-oh-MOR-fik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pleo.mor.phic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonpliable\",\"d\":\"Not easily bent, folded, or shaped; rigid and resistant to being manipulated into different forms, whether physically or metaphorically in terms of attitude.\",\"s\":\"The frozen rubber hose became nonpliable in the cold and cracked when the plumber tried to bend it.\",\"p\":\"non-PLY-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pli.able\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonpliant\",\"d\":\"Unwilling or unable to bend, yield, or adapt; stubbornly stiff in either a physical sense or in terms of personality and compliance with others.\",\"s\":\"The nonpliant metal rod refused to bend no matter how much force the worker applied to it.\",\"p\":\"non-PLY-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.pli.ant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonplosive\",\"d\":\"A speech sound that is produced without a sudden burst or explosion of air; a consonant such as a nasal or fricative that does not involve the complete stoppage and release of airflow.\",\"s\":\"In linguistics class, we learned that the letter 'm' is a nonplosive sound because it doesn't release a burst of air.\",\"p\":\"non-PLOH-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.plo.sive\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonplumber\",\"d\":\"A person who is not a licensed or trained plumber; someone without professional qualifications or skills in the installation and repair of water pipes and plumbing systems.\",\"s\":\"As a nonplumber, Marcus struggled to fix the leaky pipe and ended up flooding the bathroom floor.\",\"p\":\"non-PLUM-er\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.plumber\",\"ps\":\"noun\",\"t\":[\"jobs\",\"character\",\"olatin\"]},{\"w\":\"nonplural\",\"d\":\"Not plural in grammatical form; referring to a word, noun, or pronoun that denotes only one person, place, thing, or idea rather than more than one.\",\"s\":\"The grammar teacher explained that 'sheep' in nonplural contexts refers to just one animal.\",\"p\":\"non-PLOOR-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.plu.ral\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonplussedness\",\"d\":\"The state or quality of being thoroughly bewildered, confused, or at a complete loss as to what to think, say, or do in a given situation.\",\"s\":\"Her complete nonplussedness in the face of the surprise party impressed everyone who had worked to plan it.\",\"p\":\"non-PLUST-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.plussed.ness\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonplutonium\",\"d\":\"Not composed of or involving the radioactive element plutonium; describing nuclear fuel, materials, or reactions that do not make use of plutonium as a component.\",\"s\":\"Scientists developed a nonplutonium reactor design that relied on thorium as its primary fuel source.\",\"p\":\"non-ploo-TOH-nee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.plu.to.ni.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonpluvial\",\"d\":\"Not relating to or caused by rain; describing a geological period, climate condition, or region characterized by the absence of significant rainfall.\",\"s\":\"The desert region experienced a nonpluvial period lasting several decades, with almost no rainfall recorded.\",\"p\":\"non-PLOO-vee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.plu.vial\",\"ps\":\"adjective\",\"t\":[\"weather\",\"minerals\",\"character\",\"olatin\"]},{\"w\":\"nonplywood\",\"d\":\"Not made of plywood; describing wood products, panels, or building materials that are solid, engineered in a different manner, or composed of a single layer rather than multiple glued plies.\",\"s\":\"The carpenter chose nonplywood boards made of solid oak for the bookshelf's sturdiest shelves.\",\"p\":\"non-PLY-wood\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ply.wood\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"tools\",\"olatin\"]},{\"w\":\"nonpneumatic\",\"d\":\"Not operated by, filled with, or relying on compressed air; describing a tire, tool, or device that uses solid material or another mechanism instead of air pressure.\",\"s\":\"The nonpneumatic tires on the robot never go flat because they contain no air at all.\",\"p\":\"non-noo-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonpneu.mat.ic\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonpneumococcal\",\"d\":\"Not caused by or relating to the bacterium Streptococcus pneumoniae; describing an infection, pneumonia, or illness that is produced by a different organism or pathogen.\",\"s\":\"The lab confirmed the infection was nonpneumococcal, so doctors searched for a different bacterial cause.\",\"p\":\"non-noo-moh-KOK-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonpneu.mo.coc.cal\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpoaching\",\"d\":\"Not involving the illegal hunting, capturing, or taking of wildlife or other protected resources; describing behavior or agreements that respect legal boundaries around animal and resource protection.\",\"s\":\"The park ranger praised the nonpoaching communities who respected wildlife laws and protected the elephants.\",\"p\":\"non-POCH-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.poach.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"ecology\",\"law\",\"olatin\"]},{\"w\":\"nonpoet\",\"d\":\"A person who is not a poet; someone who does not write or compose poetry and does not identify with the creative practice of poetic expression.\",\"s\":\"As a self-described nonpoet, Marcus preferred writing straightforward essays over rhyming verses.\",\"p\":\"non-POH-et\",\"o\":\"Latin\",\"y\":8,\"bp\":20,\"sy\":\"non.po.et\",\"ps\":\"noun\",\"t\":[\"poetry\",\"character\",\"olatin\"]},{\"w\":\"nonpoetic\",\"d\":\"Not having the qualities of poetry; lacking rhythm, imagery, or the elevated language associated with poetic expression, and tending toward plain or prosaic communication.\",\"s\":\"Her nonpoetic writing style was direct and factual, more like a newspaper article than a literary piece.\",\"p\":\"non-poh-ET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.po.et.ic\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"music\",\"poetry\",\"character\",\"wordwords\",\"olatin\"]},{\"w\":\"nonpoetical\",\"d\":\"Utterly lacking in the beauty, rhythm, or imaginative language characteristic of poetry; describing writing, speech, or thought that is entirely prosaic and devoid of artistic expression.\",\"s\":\"The historian's nonpoetical account of the war left readers with cold facts rather than emotional imagery.\",\"p\":\"non-poh-ET-ih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.po.et.i.cal\",\"ps\":\"adjective\",\"t\":[\"music\",\"painting\",\"poetry\",\"wordwords\",\"olatin\"]},{\"w\":\"nonpoetry\",\"d\":\"Written or spoken language that is not poetry; prose, technical writing, journalism, or any other form of expression that does not employ the structural and artistic devices of verse.\",\"s\":\"The anthology surprisingly included nonpoetry selections like short stories and journal entries alongside the verses.\",\"p\":\"non-POH-ih-tree\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.po.et.ry\",\"ps\":\"noun\",\"t\":[\"painting\",\"poetry\",\"tools\",\"wordwords\",\"olatin\"]},{\"w\":\"nonpoint\",\"d\":\"Not originating from a single, identifiable location; often used to describe a source of pollution, such as agricultural runoff, that comes from many diffuse and spread-out origins rather than one specific pipe or outlet.\",\"s\":\"Runoff from farm fields is a nonpoint source of pollution because it comes from many scattered locations, not one pipe.\",\"p\":\"NON-point\",\"o\":\"Latin\",\"y\":7,\"bp\":25,\"sy\":\"non.point\",\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonpointer\",\"d\":\"A dog or person that does not point toward a target or object; in hunting, a breed of dog that does not freeze and indicate the location of game with its body posture.\",\"s\":\"In the dog show, the judge noted the retriever was a nonpointer breed that tracked by scent rather than stance.\",\"p\":\"non-POINT-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.point.er\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonpointlike\",\"d\":\"Not resembling or behaving like a dimensionless point; describing a physical object or particle that has measurable size, width, or structure rather than existing at a single infinitely small location.\",\"s\":\"Scientists discovered the particle was nonpointlike, meaning it had measurable size rather than being infinitely small.\",\"p\":\"non-POINT-lyk\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.point.like\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpoints\",\"d\":\"Actions, behaviors, or items that do not earn or accumulate points in a scoring system; elements of a game, competition, or program that contribute nothing to the numerical score or tally.\",\"s\":\"The scoring system counted only goals, ignoring all the nonpoints earned from minor achievements in the game.\",\"p\":\"NON-points\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.points\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonpoisoned\",\"d\":\"Not having been exposed to or affected by poison; describing a substance or organism that has not been contaminated with a harmful toxin.\",\"s\":\"The chemist confirmed the water sample was nonpoisoned and completely safe for the community to drink.\",\"p\":\"non-POY-zund\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.poi.soned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpoisoning\",\"d\":\"Not causing or producing poisoning; describing a substance or process that does not introduce harmful toxins into a living organism.\",\"s\":\"The company advertised its nonpoisoning cleaning products as safe for households with small children and pets.\",\"p\":\"non-POY-zun-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.poi.son.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpoker\",\"d\":\"Not relating to or involving the card game of poker; describing a game, activity, or context that has no connection to poker.\",\"s\":\"At the casino's nonpoker tables, guests enjoyed blackjack and roulette instead of card tournaments.\",\"p\":\"non-POH-ker\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pok.er\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonpolemic\",\"d\":\"Not involving controversy, aggressive argument, or strong verbal attack; describing writing or speech that is calm and avoids heated debate.\",\"s\":\"The professor wrote a nonpolemic essay that presented multiple viewpoints without attacking anyone's beliefs.\",\"p\":\"non-puh-LEM-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.polemic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpolice\",\"d\":\"Not belonging to or operated by an official police force; referring to individuals or organizations that perform community or safety roles outside of law enforcement.\",\"s\":\"The school hired nonpolice counselors to resolve student conflicts without involving law enforcement.\",\"p\":\"non-puh-LEES\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.po.lice\",\"ps\":\"adjective\",\"t\":[\"physics\",\"law\",\"olatin\"]},{\"w\":\"nonpoliced\",\"d\":\"Not monitored, regulated, or patrolled by police officers; describing an area or event that lacks official law-enforcement oversight.\",\"s\":\"The nonpoliced festival relied entirely on volunteers to keep crowds safe and orderly throughout the night.\",\"p\":\"non-puh-LEEST\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.po.liced\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonpolicy\",\"d\":\"Not constituting an official rule, plan, or course of action adopted by an organization or government; describing something done without formal policy guidance.\",\"s\":\"Critics argued the committee's vague suggestion was a nonpolicy that offered no real guidelines for action.\",\"p\":\"non-POL-ih-see\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pol.i.cy\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonpolite\",\"d\":\"Lacking politeness or courtesy; describing behavior or language that is rude, blunt, or fails to follow social norms of respect.\",\"s\":\"His nonpolite interruptions during the presentation made several audience members shift uncomfortably in their seats.\",\"p\":\"non-puh-LYT\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.po.lite\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpolitician\",\"d\":\"A person who is not a professional politician and does not hold elected office or engage in formal political activities as a career.\",\"s\":\"The voters were excited to elect a nonpolitician — a local teacher who had never held public office before.\",\"p\":\"non-puh-lit-ih-SHUN\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.politi.cian\",\"ps\":\"noun\",\"t\":[\"politics\",\"character\",\"olatin\"]},{\"w\":\"nonpoliticized\",\"d\":\"Not influenced, shaped, or taken over by political interests or party ideology; remaining neutral and free from partisan involvement.\",\"s\":\"The relief organization remained nonpoliticized, focusing solely on delivering food and medicine regardless of parties involved.\",\"p\":\"non-puh-LIT-ih-syzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.politi.cized\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonpollen\",\"d\":\"Not consisting of or relating to pollen; describing airborne particles or substances that are not the powdery grains produced by flowering plants.\",\"s\":\"Researchers studied nonpollen particles in the air to understand other causes of seasonal allergies in the city.\",\"p\":\"non-POL-un\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pollen\",\"ps\":\"adjective\",\"t\":[\"botany\",\"flowers\",\"physics\",\"olatin\"]},{\"w\":\"nonpollinated\",\"d\":\"Not having received pollen from another flower or plant; describing a flower or plant that has not undergone the process of pollination.\",\"s\":\"The isolated greenhouse flower remained nonpollinated because no bees or insects could reach it through the sealed glass.\",\"p\":\"non-POL-ih-nay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pol.li.nat.ed\",\"ps\":\"adjective\",\"t\":[\"botany\",\"flowers\",\"olatin\"]},{\"w\":\"nonpolling\",\"d\":\"Not participating in or related to the act of polling or voting; describing individuals or groups who did not take part in a survey or election.\",\"s\":\"Many nonpolling citizens skipped the survey, leaving researchers with an incomplete picture of public opinion.\",\"p\":\"non-POH-ling\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.polling\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonpolluted\",\"d\":\"Not contaminated by harmful substances such as chemicals, waste, or toxins; describing an environment or resource that remains clean and pure.\",\"s\":\"The mountain stream was crystal-clear and nonpolluted, making it perfect for drinking without any treatment.\",\"p\":\"non-puh-LOO-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.pol.lut.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ecology\",\"olatin\"]},{\"w\":\"nonpolluter\",\"d\":\"A person, organization, or process that does not release harmful substances into the environment; one that causes no pollution.\",\"s\":\"The electric car company marketed itself as a nonpolluter that released zero emissions from its vehicles.\",\"p\":\"non-puh-LOO-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.pol.luter\",\"ps\":\"noun\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonpolluting\",\"d\":\"Not producing or releasing harmful contaminants into the environment; describing an activity, technology, or substance that causes no pollution.\",\"s\":\"Solar panels are considered nonpolluting energy sources because they generate electricity without burning any fuel.\",\"p\":\"non-puh-LOO-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pol.lut.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonpollution\",\"d\":\"The absence of pollution or the state of being free from environmental contamination; a condition in which no harmful substances are introduced into the environment.\",\"s\":\"The town celebrated its nonpollution status after the factory installed filters that eliminated all harmful emissions.\",\"p\":\"non-puh-LOO-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pol.lu.tion\",\"ps\":\"noun\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonpolycyclic\",\"d\":\"Not having multiple rings in its molecular structure; describing a chemical compound whose structure does not contain several interconnected ring formations.\",\"s\":\"The chemist noted the compound was nonpolycyclic, meaning its structure contained only a single ring rather than many fused rings.\",\"p\":\"non-pol-ee-SY-klik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.poly.cyclic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpolycystic\",\"d\":\"Not characterized by the presence of multiple cysts; describing an organ or tissue that does not have numerous fluid-filled sacs within it.\",\"s\":\"The ultrasound confirmed the patient's kidneys were nonpolycystic and free of the multiple fluid-filled cysts they feared.\",\"p\":\"non-pol-ee-SIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.poly.cys.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"music\",\"character\",\"olatin\"]},{\"w\":\"nonpolyester\",\"d\":\"Not made of or containing polyester; describing a fabric or material that is free from synthetic polyester fibers.\",\"s\":\"The boutique specialized in nonpolyester fabrics like linen and cotton that felt natural against the skin.\",\"p\":\"non-pol-ee-ES-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.polyester\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonpolygonal\",\"d\":\"Not having the shape of a polygon; describing a figure or form that does not consist of straight sides and angles, such as a circle or irregular curve.\",\"s\":\"The artist preferred nonpolygonal curves and circles in her designs rather than sharp-edged geometric shapes.\",\"p\":\"non-puh-LIG-uh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.polyg.o.nal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpolymeric\",\"d\":\"Not consisting of or relating to polymers; describing a substance whose molecules are not formed by the linking together of many repeated smaller units.\",\"s\":\"The scientist classified the small molecule as nonpolymeric because it lacked the long repeating chain structure of polymers.\",\"p\":\"non-pol-ih-MAIR-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.poly.mer.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpolymerized\",\"d\":\"Not having undergone polymerization; describing molecules or substances that have not been chemically joined into long chains of repeating units.\",\"s\":\"The liquid resin remained nonpolymerized until heat was applied, triggering it to harden into a solid plastic.\",\"p\":\"non-puh-LIM-er-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.poly.mer.ized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpolymorphic\",\"d\":\"Not exhibiting multiple forms or structures; describing a substance, organism, or code that exists in only one consistent form rather than several variations.\",\"s\":\"The crystal sample was nonpolymorphic, existing in only one stable form regardless of temperature or pressure changes.\",\"p\":\"non-pol-ee-MOR-fik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.poly.mor.phic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpolynomial\",\"d\":\"Not expressible as a polynomial; describing a mathematical function or expression that cannot be written as a finite sum of terms involving variables raised to whole-number powers.\",\"s\":\"The advanced equation was nonpolynomial, making it far harder to solve than standard algebra problems in class.\",\"p\":\"non-pol-ee-NOH-mee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.poly.no.mi.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpolyphonic\",\"d\":\"Not involving multiple simultaneous independent melodies or voices; describing music or sound that consists of only a single melodic line.\",\"s\":\"The simple folk melody was nonpolyphonic — a single singer carrying one tune with no harmonizing voices beneath it.\",\"p\":\"non-pol-ee-FON-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.poly.phon.ic\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonpolypoid\",\"d\":\"Not resembling or characteristic of a polyp; describing tissue or a growth that does not protrude or have the mushroom-like form of a polyp.\",\"s\":\"The colonoscopy report noted a small nonpolypoid lesion that was flat rather than raised like a typical polyp.\",\"p\":\"non-POL-ih-poyd\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.poly.poid\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpolyposis\",\"d\":\"A medical condition or state in which polyps are not present; describing a diagnosis or situation that is free from the abnormal growth of polyps.\",\"s\":\"The doctor noted the patient had a nonpolyposis condition, meaning no polyps were detected during the colonoscopy.\",\"p\":\"non-pol-ih-POH-sis\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.poly.po.sis\",\"ps\":\"noun\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpolysaccharide\",\"d\":\"Not composed of or relating to polysaccharides; describing a carbohydrate or molecule that is not made up of many linked simple sugar units.\",\"s\":\"The chemist confirmed the compound was a nonpolysaccharide, lacking the long chain sugar structure found in starch.\",\"p\":\"non-pol-ee-SAK-uh-ryd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.polysac.cha.ride\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpolysemous\",\"d\":\"Having only one meaning; describing a word or term that does not carry multiple distinct senses or interpretations.\",\"s\":\"The technical term was nonpolysemous, carrying only one precise meaning with no room for confusion.\",\"p\":\"non-pol-ee-SEE-mus\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pol.y.se.mous\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpolysyllabic\",\"d\":\"Not having many syllables; describing a word that consists of only one or two syllables rather than several.\",\"s\":\"The teacher asked students to use nonpolysyllabic words in their first drafts to keep sentences clear and simple.\",\"p\":\"non-pol-ee-sih-LAB-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.poly.syl.lab.ic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpolytheistic\",\"d\":\"Not believing in or relating to the worship of many gods; describing a religion or belief system that does not embrace multiple deities.\",\"s\":\"A nonpolytheistic religion worships only one god rather than many divine figures.\",\"p\":\"non-pol-ee-thee-IS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.poly.the.is.tic\",\"ps\":\"adjective\",\"t\":[\"myth\",\"religion\",\"logic\",\"olatin\"]},{\"w\":\"nonpolytropic\",\"d\":\"Not following a polytropic process; describing a thermodynamic process in which the relationship between pressure and volume does not conform to the standard polytropic equation.\",\"s\":\"The engineer described the gas process as nonpolytropic because it did not follow the standard variable-pressure curve.\",\"p\":\"non-pol-ee-TROP-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.poly.trop.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonpolyurethane\",\"d\":\"Not made of or containing polyurethane; describing a material or product that is free from the synthetic plastic polymer known as polyurethane.\",\"s\":\"The eco-friendly foam was proudly labeled nonpolyurethane, made entirely from natural plant-based materials.\",\"p\":\"non-pol-ee-YOOR-ih-thayn\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.polyurethane\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpooled\",\"d\":\"Not combined or merged into a shared collection; describing data, resources, or funds that are kept separate rather than gathered together into a common pool.\",\"s\":\"The nonpooled data from each school was analyzed separately rather than combined into one large dataset.\",\"p\":\"non-POOLD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.pooled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpoor\",\"d\":\"Not living in poverty; describing individuals or households whose income and resources meet or exceed the standard threshold for economic sufficiency.\",\"s\":\"The study compared spending habits between poor and nonpoor households across the city.\",\"p\":\"non-POOR\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.poor\",\"ps\":\"adjective\",\"t\":[\"household\",\"economy\",\"olatin\"]},{\"w\":\"nonpopular\",\"d\":\"Not widely liked, accepted, or favored by the general public; describing something that lacks widespread appeal or mainstream support.\",\"s\":\"The documentary covered a nonpopular but important scientific topic that most people had never heard of.\",\"p\":\"non-POP-yuh-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.pop.u.lar\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpopulated\",\"d\":\"Not inhabited or settled by people; describing a region or area in which no human population lives.\",\"s\":\"The hikers crossed a vast nonpopulated stretch of desert where no towns or villages existed for miles.\",\"p\":\"non-POP-yuh-lay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.pop.u.lat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonporcine\",\"d\":\"Not relating to or derived from pigs; describing an animal product, ingredient, or characteristic that has no connection to swine.\",\"s\":\"The menu at the halal restaurant featured only nonporcine meats, with no pork products of any kind.\",\"p\":\"non-POR-syne\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.porcine\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonpork\",\"d\":\"Not consisting of or containing pork; describing food or a diet that excludes meat from pigs.\",\"s\":\"The dietary guidelines for the event specified nonpork options to accommodate all religious preferences.\",\"p\":\"non-PORK\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.pork\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonporosity\",\"d\":\"The quality or state of lacking pores or very small openings; the condition of being impermeable to liquids or gases.\",\"s\":\"The ceramic tile's nonporosity made it ideal for bathroom walls because liquids could not seep through.\",\"p\":\"non-puh-ROS-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.poros.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonporphyritic\",\"d\":\"Describing a rock or mineral texture that lacks the large, distinct crystals embedded in a finer-grained matrix that characterize porphyritic rock.\",\"s\":\"The geologist classified the igneous rock as nonporphyritic because all its crystals were the same small size.\",\"p\":\"non-por-fih-RIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.por.phyrit.ic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonportable\",\"d\":\"Not capable of being easily carried or moved from place to place; too large, heavy, or fixed to be transported conveniently.\",\"s\":\"The heavy industrial generator was nonportable and had to remain permanently installed in the factory.\",\"p\":\"non-POR-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.portable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonportal\",\"d\":\"Not relating to or involving the portal vein, which carries blood from the digestive organs to the liver; describing circulation that bypasses the portal system.\",\"s\":\"The hospital's nonportal veins carried blood through pathways unrelated to the liver's portal system.\",\"p\":\"non-POR-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.por.tal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpositional\",\"d\":\"Not determined by or dependent on position or location; describing a quality or value that remains the same regardless of where something is placed.\",\"s\":\"The nonpositional value of the symbol meant it carried the same meaning regardless of where it appeared in the sequence.\",\"p\":\"non-puh-ZISH-uh-nul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.po.si.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpositive\",\"d\":\"Not positive; describing a number or quantity that is either zero or negative, rather than greater than zero.\",\"s\":\"In math class, we learned that zero is considered nonpositive because it is not greater than zero.\",\"p\":\"non-POZ-ih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.pos.i.tive\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpositively\",\"d\":\"In a manner that is not positive; in a way that is neutral, zero, or negative rather than affirmative or greater than zero.\",\"s\":\"The test result came back nonpositively, indicating no signs of the targeted antibody in the sample.\",\"p\":\"non-POZ-ih-tiv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pos.i.tive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonpositivist\",\"d\":\"A person who does not adhere to positivism, the philosophical view that only scientifically verifiable facts constitute genuine knowledge.\",\"s\":\"The philosopher was a nonpositivist who believed truth could not be reduced purely to observable facts.\",\"p\":\"non-POZ-ih-tiv-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pos.i.tivist\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpositivity\",\"d\":\"The state or quality of not being positive; the absence of a positive value, attitude, or quantity, encompassing zero or negative states.\",\"s\":\"The mathematician proved the nonpositivity of the function across the entire negative domain.\",\"p\":\"non-poz-ih-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pos.i.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpossession\",\"d\":\"The state of not owning or holding something; the lack of legal or physical control over an object or property.\",\"s\":\"The monk's vow of nonpossession meant he owned nothing but the robe on his back.\",\"p\":\"non-puh-ZESH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pos.ses.sion\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonpossessory\",\"d\":\"Not involving or conferring ownership or possession of property; describing a legal right or interest in property that does not include the right to possess it.\",\"s\":\"The tenant had a nonpossessory interest in the land, giving rights of use without actual ownership.\",\"p\":\"non-puh-ZES-uh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pos.ses.so.ry\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonpossibility\",\"d\":\"The state of being impossible or incapable of occurring; the absence of any chance or likelihood that something can happen.\",\"s\":\"The scientist argued that faster-than-light travel was a nonpossibility given our current understanding of physics.\",\"p\":\"non-pos-ih-BIL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pos.si.bil.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpostal\",\"d\":\"Not related to or carried by the postal system; describing communication or delivery methods that do not involve the official mail service.\",\"s\":\"The company sent the contract through a nonpostal courier service to ensure faster and more secure delivery.\",\"p\":\"non-POS-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.postal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonposted\",\"d\":\"Not publicly displayed, announced, or listed; describing information or notices that have not been officially posted or published.\",\"s\":\"The nonposted announcement was shared only verbally in class, never appearing on the bulletin board.\",\"p\":\"non-POHST-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.post.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonposterior\",\"d\":\"Not situated at the back or rear; describing an anatomical position or direction that is not toward the posterior side of the body.\",\"s\":\"The surgical incision was made at a nonposterior location, accessing the organ from the front rather than the back.\",\"p\":\"non-pos-TEER-ee-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.pos.te.ri.or\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpostmodern\",\"d\":\"Not belonging to or characteristic of the postmodern movement; describing ideas, art, or culture that do not reflect the skepticism and irony typical of postmodernism.\",\"s\":\"The art critic argued the painter's style was distinctly nonpostmodern, rooted in classical traditions rather than irony.\",\"p\":\"non-pohst-MOD-urn\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.post.mod.ern\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpostpartum\",\"d\":\"Not occurring or existing after childbirth; describing a condition, treatment, or period of time that is not related to the period following delivery.\",\"s\":\"The depression was classified as nonpostpartum because it began well before the patient gave birth.\",\"p\":\"non-pohst-PAR-tum\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.post.par.tum\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonpostural\",\"d\":\"Not related to or caused by the posture or positioning of the body; describing a condition or factor that is independent of how a person holds themselves.\",\"s\":\"The therapist identified a nonpostural cause for the back pain, tracing it to a nerve rather than body alignment.\",\"p\":\"non-POS-chur-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pos.tu.ral\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpotassium\",\"d\":\"Not containing or involving potassium; describing a substance, diet, or chemical compound that lacks the element potassium.\",\"s\":\"The supplement was labeled nonpotassium for patients who needed to avoid that mineral due to kidney issues.\",\"p\":\"non-puh-TAS-ee-um\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.potas.si.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpotato\",\"d\":\"Not made from or consisting of potatoes; describing a food, dish, or ingredient that does not include potatoes as a component.\",\"s\":\"The low-carb recipe called for nonpotato vegetables like cauliflower and zucchini as substitutes.\",\"p\":\"non-puh-TAY-toh\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pota.to\",\"ps\":\"adjective\",\"t\":[\"spices\",\"olatin\"]},{\"w\":\"nonpotential\",\"d\":\"Not involving stored or latent energy; describing a physical system or force that does not have potential energy available to do work.\",\"s\":\"The force field was described as nonpotential because it could not be derived from any scalar energy function.\",\"p\":\"non-puh-TEN-shul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.po.ten.tial\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpotentiometric\",\"d\":\"Not involving or measured by the difference in electrical potential; describing an analytical method or sensor that does not rely on voltage measurement to detect substances.\",\"s\":\"The lab used a nonpotentiometric method to measure ion concentration, relying on color change instead of voltage.\",\"p\":\"non-puh-ten-shee-oh-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.po.ten.tio.met.ric\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonpottery\",\"d\":\"Not made of or relating to pottery; describing ceramic objects, art forms, or materials that are not produced using traditional clay-firing techniques.\",\"s\":\"The ancient site contained nonpottery artifacts such as bone tools and woven baskets.\",\"p\":\"non-POT-ur-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pot.tery\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"nonpoultry\",\"d\":\"Not consisting of or derived from poultry such as chickens, turkeys, or ducks; describing meat, food, or farming that involves animals other than domesticated birds.\",\"s\":\"The farm specialized in nonpoultry livestock, raising only cattle, sheep, and pigs.\",\"p\":\"non-POHL-tree\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.poul.try\",\"ps\":\"adjective\",\"t\":[\"animals\",\"birds\",\"farming\",\"olatin\"]},{\"w\":\"nonpoverty\",\"d\":\"Not characterized by or existing in a state of poverty; describing a level of income, living standard, or community that meets or exceeds the basic poverty threshold.\",\"s\":\"Researchers studied nonpoverty communities to understand what factors helped families maintain financial stability.\",\"p\":\"non-POV-ur-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pover.ty\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonpowdered\",\"d\":\"Not reduced to or coated with a fine powder; describing a substance or product that remains in its original liquid, solid, or granular form without being pulverized.\",\"s\":\"She chose a nonpowdered latex glove because she was allergic to the coating.\",\"p\":\"non-POW-durd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pow.dered\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpowdery\",\"d\":\"Not having the texture or consistency of powder; describing a material or surface that is not fine, dry, or dusty to the touch.\",\"s\":\"The new sunscreen had a nonpowdery finish that felt smooth on her skin.\",\"p\":\"non-POW-dur-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pow.dery\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpower\",\"d\":\"Not relating to power generation or mechanical force; describing a system, tool, or action that does not involve the use of electrical or mechanical power.\",\"s\":\"The treaty classified the small island nation as a nonpower in global politics.\",\"p\":\"non-POW-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.pow.er\",\"ps\":\"adjective\",\"t\":[\"physics\",\"tools\",\"olatin\"]},{\"w\":\"nonpowered\",\"d\":\"Not operated or driven by mechanical or electrical power; describing a device or vehicle that relies on human or natural force rather than an engine or motor.\",\"s\":\"The hikers used a nonpowered raft to drift lazily down the calm river.\",\"p\":\"non-POW-urd\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pow.ered\",\"ps\":\"adjective\",\"t\":[\"physics\",\"vehicles\",\"tools\",\"olatin\"]},{\"w\":\"nonpowerful\",\"d\":\"Lacking strength, authority, or influence; describing a person, group, or force that does not have significant power or the ability to exert control.\",\"s\":\"The nonpowerful ally had little influence during the peace negotiations.\",\"p\":\"non-POW-ur-ful\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pow.er.ful\",\"ps\":\"adjective\",\"t\":[\"physics\",\"poetry\",\"olatin\"]},{\"w\":\"nonpractical\",\"d\":\"Not useful, realistic, or suited to actual use; describing an idea, plan, or object that cannot be applied effectively in real-world situations.\",\"s\":\"The teacher dismissed the overly theoretical idea as nonpractical for the classroom.\",\"p\":\"non-PRAK-tih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.prac.ti.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpractitioner\",\"d\":\"A person who does not actively practice a particular profession, religion, or skill; someone lacking hands-on experience or formal practice in a given field.\",\"s\":\"As a nonpractitioner, she studied medicine but never treated patients.\",\"p\":\"non-prak-TISH-un-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.prac.ti.tion.er\",\"ps\":\"noun\",\"t\":[\"religion\",\"jobs\",\"olatin\"]},{\"w\":\"nonpragmatic\",\"d\":\"Not concerned with practical results or real-world applications; describing an approach, philosophy, or attitude that prioritizes abstract principles over usefulness.\",\"s\":\"His nonpragmatic approach focused on ideals rather than real-world solutions.\",\"p\":\"non-prag-MAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.prag.mat.ic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpraying\",\"d\":\"Not engaged in or involving the act of prayer; describing a person, group, or situation that does not include religious prayer or supplication.\",\"s\":\"The study compared praying and nonpraying participants to measure stress levels.\",\"p\":\"non-PRAY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pray.ing\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonpreaching\",\"d\":\"Not involving sermons, moral lectures, or religious instruction; describing communication or content that avoids a preachy or moralizing tone.\",\"s\":\"Her nonpreaching teaching style made students feel respected rather than lectured.\",\"p\":\"non-PREE-ching\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.preach.ing\",\"ps\":\"adjective\",\"t\":[\"religion\",\"logic\",\"olatin\"]},{\"w\":\"nonpreachy\",\"d\":\"Not excessively moralistic or self-righteous in tone; describing writing, speech, or a person that conveys ideas without lecturing or moralizing.\",\"s\":\"The book delivered its moral lessons in a nonpreachy, entertaining way.\",\"p\":\"non-PREE-chee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.preachy\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprecedential\",\"d\":\"Not establishing or constituting a legal precedent; describing a court ruling or decision that cannot be cited as binding authority in future cases.\",\"s\":\"The judge noted that the ruling was nonprecedential and could not be cited in future cases.\",\"p\":\"non-pres-ih-DEN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.prece.den.tial\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"nonprecipitable\",\"d\":\"Not capable of being separated out of a solution as a solid through a chemical reaction; describing a substance that remains dissolved and cannot be made to precipitate.\",\"s\":\"The scientist confirmed the compound was nonprecipitable in the given solution.\",\"p\":\"non-prih-SIP-ih-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.precip.itable\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonprecipitating\",\"d\":\"Not causing or undergoing precipitation; describing a substance or process that does not result in the formation of a solid from a solution or moisture falling from clouds.\",\"s\":\"They used a nonprecipitating buffer to keep the proteins dissolved.\",\"p\":\"non-preh-SIP-ih-tay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.precip.i.tat.ing\",\"ps\":\"adjective\",\"t\":[\"weather\",\"olatin\"]},{\"w\":\"nonprecise\",\"d\":\"Not precise; lacking exactness, accuracy, or careful attention to detail in measurement or expression.\",\"s\":\"The nonprecise measurements made it difficult to replicate the experiment.\",\"p\":\"non-preh-SYCE\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.precise\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonpredator\",\"d\":\"An organism or entity that does not hunt, kill, or feed on other animals; one that does not act as a predator in an ecosystem.\",\"s\":\"The deer is a nonpredator that survives entirely on plants.\",\"p\":\"non-PRED-uh-tor\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.preda.tor\",\"ps\":\"noun\",\"t\":[\"animals\",\"ecology\",\"olatin\"]},{\"w\":\"nonpredatory\",\"d\":\"Not predatory; not characterized by hunting or exploiting other organisms or people for one's own gain.\",\"s\":\"Beavers are nonpredatory animals that build dams rather than hunt prey.\",\"p\":\"non-PRED-uh-tor-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.preda.to.ry\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"character\",\"olatin\"]},{\"w\":\"nonpredetermined\",\"d\":\"Not decided, fixed, or arranged in advance; occurring or chosen without any prior planning or predetermination.\",\"s\":\"The outcome of the experiment was nonpredetermined, keeping the results truly random.\",\"p\":\"non-pree-deh-TUR-mind\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pre.de.ter.mined\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpredicate\",\"d\":\"Not functioning as or relating to a predicate; describing a word or phrase that does not serve the grammatical role of stating something about the subject of a sentence.\",\"s\":\"The linguist identified the phrase as a nonpredicate element in the sentence structure.\",\"p\":\"non-PRED-ih-kit\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pred.i.cate\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpredictable\",\"d\":\"Not able to be predicted or foreseen; behaving in a way that cannot be anticipated based on known patterns or information.\",\"s\":\"Weather in the mountains is notoriously nonpredictable and changes within minutes.\",\"p\":\"non-preh-DIK-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pre.dictable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpredictive\",\"d\":\"Not having the quality of predicting or forecasting future events or outcomes; unable to serve as an indicator of what will happen.\",\"s\":\"The test was considered nonpredictive because it didn't correlate with future performance.\",\"p\":\"non-preh-DIK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pre.dic.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpredisposed\",\"d\":\"Not inclined or made susceptible in advance; lacking any prior tendency or vulnerability toward a particular condition, belief, or behavior.\",\"s\":\"She was nonpredisposed to any disease, according to her genetic test results.\",\"p\":\"non-pree-dih-SPOZD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pre.dis.posed\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpreferential\",\"d\":\"Not giving preference or special advantage to any particular person, group, or option; treating all equally without favoritism.\",\"s\":\"The lottery used a nonpreferential system so every applicant had an equal chance.\",\"p\":\"non-pref-er-EN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pref.er.en.tial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprefixed\",\"d\":\"Not having a prefix attached; describing a word or element that exists without any added beginning syllable or morpheme.\",\"s\":\"The word 'run' is nonprefixed, while 'rerun' has a prefix.\",\"p\":\"non-PREE-fikst\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pre.fixed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"wordwords\",\"olatin\"]},{\"w\":\"nonpregnancy\",\"d\":\"The state or condition of not being pregnant; the absence of a pregnancy in a person or organism capable of bearing offspring.\",\"s\":\"The clinic tracked both pregnancy and nonpregnancy outcomes after the treatment.\",\"p\":\"non-PREG-nun-see\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.preg.nan.cy\",\"ps\":\"noun\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonpregnant\",\"d\":\"not pregnant\",\"s\":\"The doctor confirmed she was nonpregnant before prescribing the medication.\",\"p\":\"non-PREG-nunt\",\"o\":\"Latin\",\"y\":7,\"bp\":35,\"sy\":\"non.preg.nant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprehensile\",\"d\":\"not prehensile\",\"s\":\"A dog's paw is nonprehensile and cannot grasp objects the way a monkey's hand can.\",\"p\":\"non-preh-HEN-syl\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pre.hen.sile\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprehistoric\",\"d\":\"Not belonging to or relating to the period before written history; occurring within or pertaining to recorded historical times rather than prehistoric eras.\",\"s\":\"The archaeologist focused on nonprehistoric artifacts from the medieval period.\",\"p\":\"non-pree-hih-STOR-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pre.his.toric\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonprejudiced\",\"d\":\"Free from prejudice or bias; not holding unfair preconceived opinions or judgments about people or groups based on limited information.\",\"s\":\"The nonprejudiced judge evaluated every case based solely on the evidence.\",\"p\":\"non-PREJ-uh-dist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.prej.u.diced\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpremature\",\"d\":\"Not occurring before the proper or expected time; happening at the appropriate stage of development rather than too early.\",\"s\":\"The baby's nonpremature birth meant she could go home from the hospital quickly.\",\"p\":\"non-pree-muh-CHOOR\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pre.ma.ture\",\"ps\":\"adjective\",\"t\":[\"stage\",\"time\",\"olatin\"]},{\"w\":\"nonpremium\",\"d\":\"Not of premium quality or price; referring to a product, service, or category that does not carry extra cost or superior status.\",\"s\":\"She selected a nonpremium subscription that covered only the basic features.\",\"p\":\"non-PREE-mee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.premi.um\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprenylated\",\"d\":\"Not having undergone prenylation; describing a molecule, especially a protein, that has not had a prenyl chemical group attached to it.\",\"s\":\"The nonprenylated protein could not attach properly to the cell membrane.\",\"p\":\"non-PREE-nih-lay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.preny.lat.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpreparation\",\"d\":\"The absence or lack of preparation; a state in which no steps have been taken to get ready for an event, task, or situation.\",\"s\":\"His nonpreparation for the speech was obvious when he stumbled over every sentence.\",\"p\":\"non-prep-uh-RAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.prepa.ra.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprepared\",\"d\":\"Not prepared or made ready; lacking the necessary readiness, supplies, or training needed to handle a task or situation.\",\"s\":\"The nonprepared student panicked when the surprise quiz was handed out.\",\"p\":\"non-preh-PAIRD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pre.pared\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpreparedness\",\"d\":\"The quality or state of being completely unprepared; a total lack of readiness or planning for a specific event or challenge.\",\"s\":\"The team's nonpreparedness led to costly mistakes during the championship game.\",\"p\":\"non-preh-PAIR-id-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pre.pared.ness\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprepositional\",\"d\":\"Not relating to or functioning as a preposition; describing a phrase, word, or grammatical construction that does not use or act as a preposition.\",\"s\":\"The clause was analyzed as nonprepositional because it lacked any preposition.\",\"p\":\"non-prep-uh-ZIH-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.prepo.si.tion.al\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpresence\",\"d\":\"The state of not being present or existing in a particular place or situation; the absence of a person, thing, or quality.\",\"s\":\"The student's nonpresence at the meeting was noted in the official record.\",\"p\":\"non-PREZ-uns\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.pres.ence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpresent\",\"d\":\"Not present; absent from a place, moment, or situation; not existing or occurring at the current time.\",\"s\":\"All nonpresent members were asked to submit their votes by email.\",\"p\":\"non-PREZ-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pre.sent\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonpresentable\",\"d\":\"Not in a condition suitable for being shown or introduced to others; lacking the appearance, quality, or completeness needed for presentation.\",\"s\":\"The rough draft was nonpresentable and needed much more editing before the meeting.\",\"p\":\"non-preh-ZEN-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pre.sentable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpresentation\",\"d\":\"The failure or absence of a presentation; a situation in which information, a proposal, or material is not formally shown or delivered to an audience.\",\"s\":\"The award committee marked the entry as a nonpresentation since the author never showed up.\",\"p\":\"non-prez-un-TAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pre.sen.ta.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpresentational\",\"d\":\"Not representational or realistic in depicting recognizable images; often used in art to describe abstract work that does not attempt to portray real-world subjects.\",\"s\":\"The museum's nonpresentational exhibit confused visitors who expected realistic paintings.\",\"p\":\"non-prez-un-TAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pre.sen.ta.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpreservation\",\"d\":\"The lack or absence of preservation; a failure to maintain, protect, or keep something from decay, loss, or destruction.\",\"s\":\"The historian criticized the city's nonpreservation of the oldest buildings downtown.\",\"p\":\"non-prez-ur-VAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.preser.va.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpreserved\",\"d\":\"Not preserved or protected from decay, damage, or loss; describing food, materials, or historical items that have not been treated or maintained for long-term keeping.\",\"s\":\"The nonpreserved fruit rotted within days of being left on the counter.\",\"p\":\"non-preh-ZURVD\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.pre.served\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpresidential\",\"d\":\"Not relating to, suitable for, or characteristic of a president or presidency; describing something that falls outside the scope of presidential authority or style.\",\"s\":\"The election was a nonpresidential year, so only local seats were on the ballot.\",\"p\":\"non-prez-ih-DEN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pres.i.den.tial\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"politics\",\"olatin\"]},{\"w\":\"nonpress\",\"d\":\"Not belonging to or associated with the press or journalism; describing individuals, events, or materials that are not part of the news media.\",\"s\":\"The celebrity requested a nonpress event so she could attend without cameras.\",\"p\":\"non-PRES\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.press\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpressured\",\"d\":\"Not subjected to pressure, stress, or coercion; describing an environment or situation in which no urgency or force is applied to influence behavior or decisions.\",\"s\":\"The teacher created a nonpressured environment where students felt free to make mistakes.\",\"p\":\"non-PRESH-urd\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.pres.sured\",\"ps\":\"adjective\",\"t\":[\"physics\",\"ecology\",\"olatin\"]},{\"w\":\"nonpressuring\",\"d\":\"Not applying pressure or coercion; describing an approach or interaction that does not attempt to force, rush, or manipulate someone into making a decision.\",\"s\":\"Her nonpressuring sales approach made customers feel comfortable browsing the store.\",\"p\":\"non-PRESH-ur-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pres.sur.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpressurized\",\"d\":\"Not pressurized; describing a container, cabin, or system that has not been sealed and filled with pressurized air or gas to maintain safe conditions.\",\"s\":\"The nonpressurized storage compartment was unsafe for passengers to enter mid-flight.\",\"p\":\"non-PRESH-ur-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pres.sur.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprestige\",\"d\":\"Lacking prestige or high social standing; not associated with admiration, respect, or a distinguished reputation in society.\",\"s\":\"He was happy to take the nonprestige job because it allowed him to work outdoors.\",\"p\":\"non-preh-STEEZH\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.pres.tige\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprestigious\",\"d\":\"Not prestigious; lacking the high status, honor, or admirable reputation that would make something or someone widely respected or admired.\",\"s\":\"Although the award was nonprestigious, winning it still meant a lot to her.\",\"p\":\"non-preh-STIJ-us\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pres.ti.gious\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpretentious\",\"d\":\"Not pretentious; humble and straightforward without attempting to appear more important, sophisticated, or impressive than one truly is.\",\"s\":\"The nonpretentious chef served simple food without any fancy decoration on the plate.\",\"p\":\"non-preh-TEN-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pre.ten.tious\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpreventable\",\"d\":\"Not able to be prevented or stopped; describing an event or condition that cannot be avoided regardless of the precautions taken.\",\"s\":\"The doctor explained that some genetic conditions are nonpreventable with current medicine.\",\"p\":\"non-preh-VEN-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pre.ventable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprevention\",\"d\":\"The absence or failure of prevention; a situation in which no action is taken to stop a harmful event or condition from occurring.\",\"s\":\"Critics blamed the fire department's nonprevention policies for the spread of the wildfire.\",\"p\":\"non-preh-VEN-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pre.ven.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprickly\",\"d\":\"Not having sharp points, spines, or thorns; smooth and safe to the touch without any prickling sensation.\",\"s\":\"The gardener selected a nonprickly cactus variety for the classroom windowsill.\",\"p\":\"non-PRIK-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.prick.ly\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpriestly\",\"d\":\"Not related to, characteristic of, or belonging to the role or duties of a priest or religious clergy.\",\"s\":\"He wore nonpriestly clothes at the community picnic to blend in with the crowd.\",\"p\":\"non-PREEST-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.priest.ly\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonprimary\",\"d\":\"Not primary; not of the first rank, importance, or order; secondary or supplementary in nature.\",\"s\":\"Green is a nonprimary color because it is mixed from blue and yellow.\",\"p\":\"non-PRY-mair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.pri.ma.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprimed\",\"d\":\"Not having been coated with a primer or preparatory base layer before painting or finishing.\",\"s\":\"The nonprimed wall soaked up paint unevenly, leaving blotchy patches everywhere.\",\"p\":\"non-PRYMD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.primed\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonprimitive\",\"d\":\"Not primitive; characterized by complexity, sophistication, or advanced development rather than simplicity or crudeness.\",\"s\":\"Archaeologists discovered nonprimitive tools suggesting the ancient people had advanced skills.\",\"p\":\"non-PRIM-ih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.prim.i.tive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonprimordial\",\"d\":\"Not existing from the very beginning of time; not belonging to the earliest or most ancient stage of existence.\",\"s\":\"The scientist argued that language is nonprimordial, developing long after basic survival instincts.\",\"p\":\"non-pry-MOR-dee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pri.mor.dial\",\"ps\":\"adjective\",\"t\":[\"stage\",\"ancient\",\"time\",\"olatin\"]},{\"w\":\"nonprincipled\",\"d\":\"Lacking clear moral principles or ethical standards to guide one's actions and decisions.\",\"s\":\"The nonprincipled politician changed his stance whenever it was convenient for him.\",\"p\":\"non-PRIN-sih-puld\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.prin.ci.pled\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonprint\",\"d\":\"Not existing in or relating to printed form; referring to media or resources that are not produced on paper through printing.\",\"s\":\"The library expanded its nonprint collection to include videos, podcasts, and digital maps.\",\"p\":\"non-PRINT\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.print\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprinted\",\"d\":\"Not produced by a printing process; not having been set down in ink on paper or another physical surface.\",\"s\":\"The nonprinted instructions were delivered as a voice recording instead of a written sheet.\",\"p\":\"non-PRIN-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.print.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprinting\",\"d\":\"Describing characters or elements in a document that are present in the data but do not produce a visible mark when the document is printed.\",\"s\":\"The nonprinting characters in the document, like spaces and tabs, were invisible on screen.\",\"p\":\"non-PRIN-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.print.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprioritized\",\"d\":\"Not arranged or organized according to importance or urgency; lacking a ranked order of tasks or items.\",\"s\":\"The nonprioritized task list overwhelmed her because everything seemed equally urgent.\",\"p\":\"non-pry-OR-ih-tyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pri.or.i.tized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprison\",\"d\":\"Not involving or relating to a prison; describing a punishment, setting, or program that does not include incarceration.\",\"s\":\"The judge chose a nonprison sentence, ordering community service instead of jail time.\",\"p\":\"non-PRIZ-un\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.prison\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonprisoner\",\"d\":\"A person who is not held captive, incarcerated, or confined as a prisoner in any detention facility.\",\"s\":\"As a nonprisoner volunteer, she helped teach art classes inside the correctional facility.\",\"p\":\"non-PRIZ-un-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pris.on.er\",\"ps\":\"noun\",\"t\":[\"law\",\"character\",\"olatin\"]},{\"w\":\"nonprivate\",\"d\":\"Not private; open, accessible, or available to the general public rather than restricted to specific individuals.\",\"s\":\"The nonprivate conversation was overheard by everyone sitting nearby in the café.\",\"p\":\"non-PRY-vit\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pri.vate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprivileged\",\"d\":\"Not having special advantages, rights, or opportunities that others possess; lacking the benefits of a privileged position.\",\"s\":\"The program was designed to give nonprivileged students access to advanced science labs.\",\"p\":\"non-PRIV-ih-lijd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.priv.i.leged\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprivy\",\"d\":\"Not having private knowledge of or access to particular information; not admitted into a secret or confidential matter.\",\"s\":\"As a nonprivy bystander, she had no idea what secret plans were being discussed.\",\"p\":\"non-PRIV-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.privy\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpro\",\"d\":\"Not a professional; an amateur or someone who does not engage in an activity at a professional level.\",\"s\":\"The league welcomed nonpro players who simply wanted to enjoy the sport on weekends.\",\"p\":\"non-PRO\",\"o\":\"Latin\",\"y\":9,\"bp\":18,\"sy\":\"non.pro\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprobabilistic\",\"d\":\"Not based on or involving probability or chance; describing a system or method that yields definite rather than statistical outcomes.\",\"s\":\"The nonprobabilistic model gave definite yes-or-no answers without any uncertainty scores.\",\"p\":\"non-prob-uh-bih-LIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.prob.a.bilis.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprobable\",\"d\":\"Not likely to happen or be true; having little or no probability of occurring.\",\"s\":\"Scientists considered the meteor hitting Earth a nonprobable event within this century.\",\"p\":\"non-PROB-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.prob.a.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprobative\",\"d\":\"Not serving as proof or evidence; failing to demonstrate or establish a fact, especially in a legal context.\",\"s\":\"The judge dismissed the nonprobative evidence because it did nothing to prove the case.\",\"p\":\"non-PROH-buh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pro.ba.tive\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonproblem\",\"d\":\"Something that appears to be a problem but is actually not an issue; a situation that requires no real solution or concern.\",\"s\":\"After talking it through, the disagreement turned out to be a complete nonproblem.\",\"p\":\"non-PROB-lum\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.prob.lem\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonproblematic\",\"d\":\"Not causing or presenting any problems, difficulties, or complications; straightforward and free of issues.\",\"s\":\"The transition to the new schedule was surprisingly nonproblematic for all the students.\",\"p\":\"non-prob-luh-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.prob.lem.at.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprocedural\",\"d\":\"Not following or based on a set of prescribed steps or procedures; describing an approach that does not rely on sequential instructions.\",\"s\":\"The nonprocedural programming language let coders describe what they wanted, not how to do it.\",\"p\":\"non-pruh-SEE-jur-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pro.ce.du.ral\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprocedurally\",\"d\":\"In a manner that does not follow prescribed steps or formal procedures; without adherence to a structured sequence of operations.\",\"s\":\"The software was designed nonprocedurally, allowing the computer to figure out the steps itself.\",\"p\":\"non-pruh-SEE-jur-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.pro.ce.du.ral.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonprocessable\",\"d\":\"Unable to be processed, handled, or treated by a particular system, machine, or method.\",\"s\":\"The corrupt file was nonprocessable, and the software crashed every time she tried to open it.\",\"p\":\"non-PROS-es-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pro.cess.able\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonprocessed\",\"d\":\"Not having undergone any industrial treatment, refinement, or preparation; in its natural or original state.\",\"s\":\"The nutrition label proudly declared the snack was made from nonprocessed, whole ingredients.\",\"p\":\"non-PROS-est\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.pro.cessed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprocrastinating\",\"d\":\"Not delaying or postponing tasks; acting promptly and without putting off responsibilities to a later time.\",\"s\":\"Her nonprocrastinating study habit meant she always finished assignments days before the deadline.\",\"p\":\"non-proh-KRAS-tih-nay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pro.cras.ti.nat.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonprocreative\",\"d\":\"Not related to or resulting in reproduction; not serving the biological purpose of producing offspring.\",\"s\":\"The scientists studied nonprocreative behaviors in animals to understand social bonding.\",\"p\":\"non-proh-KREE-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pro.cre.ative\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproducer\",\"d\":\"A person, organization, or entity that does not produce goods, crops, creative works, or other outputs.\",\"s\":\"The farmer was labeled a nonproducer after his fields yielded nothing for two seasons.\",\"p\":\"non-pruh-DOO-sur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pro.duc.er\",\"ps\":\"noun\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonproducing\",\"d\":\"Not generating, creating, or yielding any goods, results, or output; failing to produce what is expected.\",\"s\":\"The nonproducing oil well was eventually sealed and abandoned by the company.\",\"p\":\"non-pruh-DOO-sing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pro.duc.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproduction\",\"d\":\"The state or condition of not producing goods, results, or output; a failure or absence of productive activity.\",\"s\":\"The factory's nonproduction days during the holiday caused delays in shipments.\",\"p\":\"non-pruh-DUK-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.duc.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonproductivity\",\"d\":\"The state of being unproductive; the lack of ability or effort to generate useful output, results, or work.\",\"s\":\"The manager worried that the team's nonproductivity would hurt the company's quarterly results.\",\"p\":\"non-proh-duk-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.pro.duc.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprofane\",\"d\":\"Not vulgar, irreverent, or disrespectful; free from offensive or blasphemous language and behavior.\",\"s\":\"The speaker kept his language nonprofane out of respect for the younger audience.\",\"p\":\"non-proh-FAYN\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pro.fane\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonprofessionalism\",\"d\":\"The absence of professional standards, conduct, or ethics in one's work or behavior; a lack of the qualities expected of a trained professional.\",\"s\":\"The coach criticized the team's nonprofessionalism after players showed up late to practice.\",\"p\":\"non-pruh-FESH-un-ul-iz-um\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pro.fes.sion.al.ism\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonprofessor\",\"d\":\"A person who does not hold the academic rank or position of professor at a college or university.\",\"s\":\"As a nonprofessor, the guest lecturer still shared fascinating insights about marine biology.\",\"p\":\"non-pruh-FES-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pro.fes.sor\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprofessorial\",\"d\":\"Not characteristic of or relating to a professor; lacking the qualities, style, or manner associated with academic professorship.\",\"s\":\"Her nonprofessorial style of teaching made the subject feel fun and approachable.\",\"p\":\"non-proh-feh-SOR-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.pro.fes.so.ri.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproficiency\",\"d\":\"The lack of skill, competence, or expertise in a particular area or activity; an inability to perform at a proficient level.\",\"s\":\"His nonproficiency in Spanish made traveling through Mexico more challenging.\",\"p\":\"non-pruh-FISH-un-see\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pro.fi.cien.cy\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonproficient\",\"d\":\"Not skilled or competent in a particular task or area; lacking the ability to perform with expertise or ease.\",\"s\":\"The student was nonproficient in algebra and needed extra tutoring sessions.\",\"p\":\"non-pruh-FISH-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.fi.cient\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprofitable\",\"d\":\"Not capable of generating financial gain or profit; unable to produce a monetary benefit or return.\",\"s\":\"Running the community garden was nonprofitable but brought the neighborhood together.\",\"p\":\"non-PROF-it-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.prof.itable\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonprogram\",\"d\":\"Something that is not an organized program or scheduled broadcast; an activity or item that lacks the structure of a formal program.\",\"s\":\"The station aired a nonprogram segment of static due to the technical failure.\",\"p\":\"non-PROH-gram\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pro.gram\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprogrammable\",\"d\":\"Not capable of being programmed or configured through a set of coded instructions; describing a device or system that cannot be customized by entering commands.\",\"s\":\"The old thermostat was nonprogrammable, so you had to adjust it manually every day.\",\"p\":\"non-PRO-gram-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pro.grammable\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonprogrammatic\",\"d\":\"Not following or representing a descriptive narrative or storyline, especially in music or art; lacking a programmatic structure that tells a story.\",\"s\":\"The composer wrote nonprogrammatic music that conveyed pure emotion without telling a story.\",\"p\":\"non-pro-gruh-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pro.gram.mat.ic\",\"ps\":\"adjective\",\"t\":[\"music\",\"poetry\",\"olatin\"]},{\"w\":\"nonprogrammed\",\"d\":\"Not set up, scheduled, or controlled by a predetermined program or coded set of instructions; operating without a loaded sequence of commands.\",\"s\":\"The robot's nonprogrammed response to the obstacle confused the engineers.\",\"p\":\"non-PRO-gramd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.pro.grammed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprogrammer\",\"d\":\"A person who does not write or develop computer programs; someone whose work or skills do not involve coding or software development.\",\"s\":\"As a nonprogrammer, she relied on apps to help her manage her small business.\",\"p\":\"non-PRO-gram-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.gram.mer\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprogramming\",\"d\":\"Not related to or involving the writing of computer code or software; describing tasks or roles that fall outside the scope of coding and software development.\",\"s\":\"The nonprogramming staff focused on design and marketing rather than writing code.\",\"p\":\"non-PRO-gram-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pro.gram.ming\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprogression\",\"d\":\"The absence or lack of forward movement, advancement, or worsening; often used in medicine to describe a disease that is not getting worse.\",\"s\":\"The doctor noted a nonprogression of the disease, which was a hopeful sign.\",\"p\":\"non-pruh-GRESH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pro.gres.sion\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonprojectile\",\"d\":\"Not designed or capable of being launched or fired through the air as a projectile; describing an object that does not travel in a ballistic trajectory.\",\"s\":\"The safety officer confirmed the object was nonprojectile and posed no flight risk.\",\"p\":\"non-pruh-JEK-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.jec.tile\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprojective\",\"d\":\"Not involving or relating to psychological projection, or not capable of being projected; in psychology, describing a test or method that does not invite the subject to project feelings onto ambiguous stimuli.\",\"s\":\"The therapist used a nonprojective assessment instead of inkblot tests for the evaluation.\",\"p\":\"non-pruh-JEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.jec.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprokaryotic\",\"d\":\"Not belonging to prokaryotes; describing organisms or cells that possess a true membrane-bound nucleus, as found in eukaryotes.\",\"s\":\"Human cells are nonprokaryotic, meaning they have a true nucleus enclosing their DNA.\",\"p\":\"non-pro-kair-ee-OT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.prokary.ot.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproletarian\",\"d\":\"Not belonging to or characteristic of the proletariat or working class; describing a person, idea, or lifestyle associated with a class other than industrial laborers.\",\"s\":\"The author described the protagonist as a nonproletarian who had never experienced factory work.\",\"p\":\"non-pro-luh-TAIR-ee-un\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pro.le.tar.i.an\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproliferating\",\"d\":\"Not rapidly multiplying, spreading, or increasing in number; describing cells, organisms, or weapons that are not undergoing proliferation.\",\"s\":\"The treaty aimed to keep nonproliferating nations from developing nuclear weapons.\",\"p\":\"non-pruh-LIF-ur-ay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pro.lif.er.at.ing\",\"ps\":\"adjective\",\"t\":[\"war\",\"numbers\",\"olatin\"]},{\"w\":\"nonproliferative\",\"d\":\"Not characterized by rapid or excessive cell division or growth; describing a biological state in which cells are not multiplying at an abnormal rate.\",\"s\":\"The biopsy showed nonproliferative cells, indicating the tissue was not growing abnormally.\",\"p\":\"non-pruh-LIF-ur-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pro.lif.er.a.tive\",\"ps\":\"adjective\",\"t\":[\"character\",\"numbers\",\"olatin\"]},{\"w\":\"nonprolific\",\"d\":\"Not producing a large quantity of output, offspring, or creative work; describing someone or something with minimal or limited production.\",\"s\":\"Unlike his famous peers, the painter was nonprolific and completed only a dozen works.\",\"p\":\"non-pruh-LIF-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pro.lif.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpromoted\",\"d\":\"Not having been advanced in rank, position, or status; describing an employee or student who has not received a promotion or been moved to a higher level.\",\"s\":\"The nonpromoted employee felt frustrated after working hard all year without recognition.\",\"p\":\"non-pruh-MOH-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pro.mot.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpromotional\",\"d\":\"Not intended for advertising, marketing, or sales purposes; describing content, material, or communication that does not promote a product, service, or idea.\",\"s\":\"The email was nonpromotional and simply informed customers about a policy change.\",\"p\":\"non-pruh-MO-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pro.mo.tion.al\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonproof\",\"d\":\"Lacking sufficient evidence or demonstration to establish the truth of a claim; describing something for which no valid proof has been provided.\",\"s\":\"The argument remained nonproof without any data or evidence to support the claim.\",\"p\":\"non-PROOF\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.proof\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonproofreading\",\"d\":\"The absence of the process of carefully reviewing a text for errors in spelling, grammar, or punctuation; describing work done without editorial checking.\",\"s\":\"The nonproofreading policy led to several embarrassing typos in the school newspaper.\",\"p\":\"non-PROOF-ree-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.proof.read.ing\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonpropaganda\",\"d\":\"Information or content that is free from biased, misleading, or politically motivated messaging; material presented without the intent to manipulate opinions.\",\"s\":\"The documentary was praised for being nonpropaganda, presenting balanced views on the conflict.\",\"p\":\"non-prop-uh-GAN-duh\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pro.pa.gan.da\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonpropagandistic\",\"d\":\"Not having the characteristics of propaganda; describing communication or content that does not attempt to manipulate beliefs through biased or misleading information.\",\"s\":\"The history textbook was written in a nonpropagandistic style to present facts objectively.\",\"p\":\"non-prop-uh-gan-DIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pro.pa.gan.dis.tic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpropellant\",\"d\":\"Not serving as or relating to a substance that propels an object forward; describing a material that does not generate thrust or drive motion.\",\"s\":\"The engineer replaced the rocket's faulty component with a nonpropellant material.\",\"p\":\"non-pruh-PEL-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.pel.lant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpropelled\",\"d\":\"Not driven forward by an engine, motor, or other propulsion system; describing an object or vehicle that moves without mechanical thrust.\",\"s\":\"The nonpropelled glider floated silently on the warm updrafts over the valley.\",\"p\":\"non-pruh-PELD\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.pro.pelled\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"tools\",\"olatin\"]},{\"w\":\"nonproper\",\"d\":\"Not conforming to accepted standards, rules, or conventions; lacking the qualities considered correct, appropriate, or suitable for a given context.\",\"s\":\"The judge ruled the evidence nonproper and refused to allow it in court.\",\"p\":\"non-PROP-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.prop.er\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproperty\",\"d\":\"Something that does not qualify as property under legal or formal definitions; describing assets, items, or concepts that cannot be owned or legally claimed.\",\"s\":\"The city classified the abandoned lot as nonproperty since it had no registered owner.\",\"p\":\"non-PROP-ur-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.prop.er.ty\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonprophetic\",\"d\":\"Not having the quality of prophecy or prediction; describing statements, writings, or individuals that do not claim or demonstrate the ability to foretell future events.\",\"s\":\"His nonprophetic guess about the weather was completely wrong the next day.\",\"p\":\"non-pruh-FET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.prophet.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprophylactic\",\"d\":\"Not serving to prevent disease or infection; describing a substance, device, or practice that does not provide protection against illness or harmful conditions.\",\"s\":\"The treatment was nonprophylactic, meaning it cured the illness rather than prevented it.\",\"p\":\"non-pro-fuh-LAK-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pro.phy.lac.tic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"tools\",\"olatin\"]},{\"w\":\"nonproportional\",\"d\":\"Not maintaining a consistent ratio or relationship between quantities; describing measurements, representations, or distributions that are not in proper proportion to one another.\",\"s\":\"The map used a nonproportional scale that made some regions appear larger than others.\",\"p\":\"non-pruh-POR-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pro.por.tion.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonproportionate\",\"d\":\"Not corresponding in size, degree, or amount relative to something else; describing a response, reward, or punishment that does not match the scale of the situation.\",\"s\":\"The punishment seemed nonproportionate to the minor mistake the student had made.\",\"p\":\"non-pruh-POR-shun-it\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pro.por.tion.ate\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonproposal\",\"d\":\"A communication or document that does not constitute a formal proposal; something presented that lacks the structure or intent of an official offer or suggestion.\",\"s\":\"The committee issued a nonproposal statement, meaning they declined to suggest any new plans.\",\"p\":\"non-pruh-POH-zul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pro.pos.al\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpropositional\",\"d\":\"Not having the form or function of a proposition; describing content or thought that does not make a truth claim or assert something that can be evaluated as true or false.\",\"s\":\"The artist's abstract painting conveyed a nonpropositional message that couldn't be put into words.\",\"p\":\"non-prop-uh-ZI-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.propo.si.tion.al\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonproprioceptive\",\"d\":\"Not relating to or involving proprioception, the body's internal sense of its own position and movement; describing stimuli or responses that do not originate from the body's own sensory receptors.\",\"s\":\"The researcher noted that certain reflexes were nonproprioceptive, not relying on the body's sense of its own position.\",\"p\":\"non-pro-pree-oh-SEP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.pro.pri.o.cep.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpropulsion\",\"d\":\"The absence of a force or mechanism that drives something forward; describing a state or system lacking any means of generating thrust or forward movement.\",\"s\":\"The glider relied on nonpropulsion to soar, using wind currents instead of an engine.\",\"p\":\"non-pruh-PUL-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.propul.sion\",\"ps\":\"noun\",\"t\":[\"physics\",\"tools\",\"olatin\"]},{\"w\":\"nonprosecutable\",\"d\":\"Not capable of being brought to trial or subject to legal prosecution; describing an offense, person, or case for which formal charges cannot legally be pursued.\",\"s\":\"The lawyer argued the case was nonprosecutable because key evidence had been lost.\",\"p\":\"non-PROS-ih-kyoo-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pros.e.cutable\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"nonprosecuted\",\"d\":\"Not having been subjected to legal prosecution or brought to trial; describing a person or case against which formal criminal or civil charges were not pursued.\",\"s\":\"The nonprosecuted suspect was relieved when the charges were officially dropped.\",\"p\":\"non-PROS-ih-kyoo-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pros.e.cut.ed\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"nonprosecution\",\"d\":\"The decision or condition of not pursuing legal charges against a person or entity; the absence of a formal legal case being brought to trial.\",\"s\":\"The judge signed a nonprosecution agreement, allowing the witness to testify freely.\",\"p\":\"non-pros-ih-KYOO-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pros.e.cu.tion\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonprosecutive\",\"d\":\"not involving the bringing of criminal charges against someone in court\",\"s\":\"The district attorney took a nonprosecutive route and settled the matter without ever filing charges.\",\"p\":\"non-PROS-ek-yoo-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pros.ec.u.tive\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonprosecutorial\",\"d\":\"Not relating to or characteristic of a prosecutor or the act of prosecution; describing a role, approach, or decision that does not involve pursuing legal charges.\",\"s\":\"The panel took a nonprosecutorial approach, focusing on rehabilitation rather than punishment.\",\"p\":\"non-pros-ih-kyoo-TOR-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.pros.e.cu.to.ri.al\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"nonprosodic\",\"d\":\"Not relating to prosody, the study of meter, rhythm, and intonation in language; describing speech or text that lacks or ignores the patterns of stress and sound studied in prosody.\",\"s\":\"The poet chose a nonprosodic style, ignoring traditional rules of meter and rhythm.\",\"p\":\"non-pruh-SOD-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.prosod.ic\",\"ps\":\"adjective\",\"t\":[\"music\",\"wordwords\",\"olatin\"]},{\"w\":\"nonprostatic\",\"d\":\"Not relating to or involving the prostate gland; describing a medical condition, symptom, or structure that has no connection to the prostate.\",\"s\":\"The doctor confirmed the pain was nonprostatic, originating from a different organ entirely.\",\"p\":\"non-pro-STAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pro.stat.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonprosthetic\",\"d\":\"Not involving or requiring a prosthesis or artificial body part; describing a limb, organ, or bodily function that is natural and does not depend on an artificial replacement.\",\"s\":\"The treatment plan was nonprosthetic, relying on physical therapy rather than an artificial limb.\",\"p\":\"non-pros-THET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pros.thet.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"music\",\"olatin\"]},{\"w\":\"nonprotagonist\",\"d\":\"A character in a story or narrative who is not the main character; someone who plays a supporting or secondary role rather than the central role in a plot.\",\"s\":\"The story was surprisingly gripping even though it was told from a nonprotagonist's perspective.\",\"p\":\"non-proh-TAG-oh-nist\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pro.tag.o.nist\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonprotectionist\",\"d\":\"Not favoring policies that shield a country's domestic industries from foreign competition through tariffs or trade barriers; opposed to economic protectionism.\",\"s\":\"The nonprotectionist senator favored open trade agreements with all countries.\",\"p\":\"non-proh-TEK-shun-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.pro.tec.tion.ist\",\"ps\":\"adjective\",\"t\":[\"politics\",\"economy\",\"war\",\"sports\",\"olatin\"]},{\"w\":\"nonprotective\",\"d\":\"Not providing protection or defense; failing to guard against harm, damage, or danger.\",\"s\":\"The thin coating was nonprotective and offered no real shield against moisture.\",\"p\":\"non-proh-TEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.tec.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproteinaceous\",\"d\":\"Not composed of or relating to protein; describing a substance or molecule that does not have the nature or composition of protein.\",\"s\":\"Scientists discovered that the enzyme's active ingredient was surprisingly nonproteinaceous.\",\"p\":\"non-proh-tee-NAY-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pro.teina.ceous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonproteinic\",\"d\":\"Not of or relating to protein; describing compounds or substances that are not protein in nature or composition.\",\"s\":\"The supplement contained nonproteinic compounds that still boosted muscle recovery.\",\"p\":\"non-proh-TEE-nik\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.pro.teinic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproteinogenic\",\"d\":\"Describing an amino acid or molecule that is not used in the biological synthesis of proteins; not naturally incorporated into proteins during translation.\",\"s\":\"Some nonproteinogenic amino acids are used in medicine but not to build normal proteins.\",\"p\":\"non-proh-tee-noh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pro.teino.genic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"wordwords\",\"olatin\"]},{\"w\":\"nonproteinous\",\"d\":\"Not consisting of or resembling protein; lacking the qualities or composition characteristic of proteins.\",\"s\":\"The lab identified several nonproteinous molecules in the sample that puzzled researchers.\",\"p\":\"non-proh-TEE-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.pro.teinous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonproteinuric\",\"d\":\"Not characterized by the presence of excess protein in the urine; describing a condition or patient in whom proteinuria is absent.\",\"s\":\"The patient's test results were nonproteinuric, showing no excess protein in the urine.\",\"p\":\"non-proh-tee-NYOOR-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.pro.tein.uric\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonproteolytic\",\"d\":\"Not capable of breaking down or digesting proteins; describing an enzyme, organism, or process that does not cleave protein molecules.\",\"s\":\"The bacteria used a nonproteolytic pathway to break down nutrients without attacking proteins.\",\"p\":\"non-proh-tee-oh-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pro.te.olyt.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonproteolytically\",\"d\":\"In a manner that does not involve the breakdown or digestion of proteins; without proteolytic activity.\",\"s\":\"The enzyme functioned nonproteolytically, processing sugars rather than proteins.\",\"p\":\"non-proh-tee-oh-LIT-ih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.pro.te.olyt.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonprotest\",\"d\":\"The absence of protest or objection; a state in which no formal complaint, demonstration, or opposition is expressed.\",\"s\":\"The student chose a nonprotest response, quietly writing a letter instead of marching.\",\"p\":\"non-PROH-test\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.protest\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonprotesting\",\"d\":\"Not engaging in or expressing protest or objection; refraining from demonstrating opposition or complaint.\",\"s\":\"The nonprotesting crowd stood silently as the announcement was made.\",\"p\":\"non-proh-TEST-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.protest.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprotic\",\"d\":\"Describing a solvent or substance that cannot donate a proton (hydrogen ion); not capable of acting as a proton donor in chemical reactions.\",\"s\":\"The chemistry teacher explained that nonprotic solvents don't donate hydrogen ions the way water does.\",\"p\":\"non-PROH-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pro.t.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonprotozoan\",\"d\":\"Not belonging to or characteristic of protozoa; describing an organism or cell that is not a single-celled protozoan organism.\",\"s\":\"The scientist confirmed the organism was nonprotozoan, classifying it as a fungus instead.\",\"p\":\"non-proh-toh-ZOH-an\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pro.to.zoan\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprotruding\",\"d\":\"Not sticking out or extending beyond a surface; lying flat or flush without projecting outward.\",\"s\":\"The sleek, nonprotruding design of the phone made it fit perfectly in any pocket.\",\"p\":\"non-proh-TROOD-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pro.trud.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprovable\",\"d\":\"Not capable of being proved or demonstrated to be true; impossible to establish with evidence or logical argument.\",\"s\":\"The theory was interesting but ultimately nonprovable with current technology.\",\"p\":\"non-PROOV-ah-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.prov.able\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonproven\",\"d\":\"Not yet established or confirmed as true or effective; lacking sufficient evidence or testing to be accepted as fact.\",\"s\":\"The court dismissed the nonproven allegations for lack of evidence.\",\"p\":\"non-PROO-ven\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.proven\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonprovocative\",\"d\":\"Not intended to provoke, irritate, or stir up conflict; calm and inoffensive in nature or manner.\",\"s\":\"She chose nonprovocative language to keep the debate calm and respectful.\",\"p\":\"non-proh-VOK-ah-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.provoca.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpseudomorphic\",\"d\":\"Not having or exhibiting the characteristics of a pseudomorph; describing a mineral or structure that has not assumed a false or deceptive crystalline form.\",\"s\":\"The crystal was identified as nonpseudomorphic because it retained its original structural form.\",\"p\":\"non-soo-doh-MOR-fik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonpseu.do.mor.phic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"nonpsychiatric\",\"d\":\"Not related to or involving psychiatry or mental disorders; describing conditions, treatments, or professionals outside the field of mental health medicine.\",\"s\":\"The clinic treated nonpsychiatric conditions like diabetes and heart disease.\",\"p\":\"non-sy-kee-AT-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"nonpsy.chi.atric\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonpsychiatrist\",\"d\":\"A person who is not a psychiatrist; a medical or mental health professional who has not specialized in the diagnosis and treatment of mental disorders.\",\"s\":\"As a nonpsychiatrist, the general practitioner referred complex mental health cases to specialists.\",\"p\":\"non-sy-KY-ah-trist\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonpsy.chi.a.trist\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"character\",\"olatin\"]},{\"w\":\"nonpsychic\",\"d\":\"Not relating to or involving psychic or supernatural mental abilities; having no paranormal or extrasensory powers.\",\"s\":\"The detective solved the case through nonpsychic means, using only logic and evidence.\",\"p\":\"non-SY-kik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonpsy.chic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpsychical\",\"d\":\"Not of or relating to psychic or supernatural phenomena; lacking any connection to paranormal mental forces or abilities.\",\"s\":\"The researcher studied nonpsychical explanations for the strange events at the old house.\",\"p\":\"non-SY-kih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonpsy.chi.cal\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonpsychoactive\",\"d\":\"not affecting the mind or mental processes\",\"s\":\"A nonpsychoactive pain reliever.\",\"p\":\"non-sy-koh-AK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonpsy.choac.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpsychoanalytic\",\"d\":\"Not based on or relating to psychoanalysis; describing therapeutic or psychological approaches that do not use Freudian methods of analyzing the unconscious mind.\",\"s\":\"The therapist used a nonpsychoanalytic approach, preferring cognitive techniques over Freudian methods.\",\"p\":\"non-sy-koh-an-ah-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"nonpsy.cho.an.a.lyt.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpsychoanalytical\",\"d\":\"Not pertaining to psychoanalysis; describing theories, methods, or practitioners that do not follow the principles of psychoanalytic practice or thought.\",\"s\":\"Her nonpsychoanalytical therapy sessions focused on practical goal-setting rather than childhood memories.\",\"p\":\"non-sy-koh-an-ah-LIT-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"nonpsy.cho.an.a.lyt.i.cal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonpsychogenic\",\"d\":\"Not originating in or caused by psychological or mental factors; describing a physical symptom or disorder with a purely biological rather than emotional cause.\",\"s\":\"The doctor concluded that the patient's headaches were nonpsychogenic, meaning they had a clear physical cause rather than a mental one.\",\"p\":\"non-sy-koh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"sy\":\"nonpsy.chogenic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"emotions\",\"olatin\"]},{\"w\":\"nonpsychological\",\"d\":\"Not related to psychology or the workings of the mind; describing factors, causes, or approaches that are not based on mental or emotional processes.\",\"s\":\"The researcher argued that the child's learning difficulties had a nonpsychological basis, rooted instead in a vision problem.\",\"p\":\"non-sy-koh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonpsy.cho.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonpsychopathic\",\"d\":\"Not exhibiting the traits of a psychopath; describing a person or behavior that does not show antisocial, manipulative, or emotionally deviant characteristics.\",\"s\":\"The counselor noted that most people who lie occasionally are nonpsychopathic and simply afraid of getting in trouble.\",\"p\":\"non-sy-koh-PATH-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonpsy.cho.path.ic\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonpsychophysical\",\"d\":\"Not relating to the relationship between mental and physical processes; describing phenomena or studies that do not involve the interaction between mind and body.\",\"s\":\"The experiment focused on nonpsychophysical factors, such as room temperature, rather than the mind-body connection.\",\"p\":\"non-sy-koh-FIZ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonpsy.chophys.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpsychosexual\",\"d\":\"Not related to the psychological aspects of sexuality; describing development, behavior, or theory that does not involve the mental or emotional dimensions of sexual experience.\",\"s\":\"The therapist explained that some developmental milestones are nonpsychosexual and are purely about motor skills.\",\"p\":\"non-sy-koh-SEK-shoo-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonpsy.cho.sex.u.al\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"logic\",\"olatin\"]},{\"w\":\"nonpsychosis\",\"d\":\"A mental state or condition that is not characterized by psychosis; the absence of a break from reality such as hallucinations or delusions.\",\"s\":\"The psychiatrist's report confirmed a nonpsychosis diagnosis, ruling out any break from reality in the patient.\",\"p\":\"non-sy-KOH-sis\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonpsy.chosis\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonpsychosomatic\",\"d\":\"Not involving or caused by the interaction of psychological and physical factors; describing an illness or symptom with no mind-body component.\",\"s\":\"The rash was deemed nonpsychosomatic after tests revealed an allergic reaction to a new laundry detergent.\",\"p\":\"non-sy-koh-soh-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonpsy.cho.so.mat.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonpsychotic\",\"d\":\"Not relating to or affected by psychosis; describing a person or mental state in which there is no loss of contact with reality.\",\"s\":\"The judge ordered a mental health evaluation, and the defendant was found to be nonpsychotic and fully aware of his actions.\",\"p\":\"non-sy-KOT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonpsy.chot.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpsychotomimetic\",\"d\":\"Not producing effects that mimic psychosis or a psychotic state; describing a drug or substance that does not cause hallucinations or other psychosis-like symptoms.\",\"s\":\"Scientists were relieved to find the new compound was nonpsychotomimetic, meaning it would not mimic the effects of psychosis.\",\"p\":\"non-sy-koh-toh-mih-MET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonpsy.chotomimet.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonpubertal\",\"d\":\"Not relating to or characteristic of puberty; describing a stage of life or physical state before or outside the period of sexual maturation.\",\"s\":\"The growth chart showed that the child was still in a nonpubertal stage of development at age nine.\",\"p\":\"non-pyoo-BER-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.pu.ber.tal\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"nonpubescent\",\"d\":\"Not having reached or undergoing pubescence; describing a person or organism that has not yet begun the process of physical maturation associated with adolescence.\",\"s\":\"The study only included nonpubescent children, all under the age of ten, to examine early childhood nutrition.\",\"p\":\"non-pyoo-BES-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pubescent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpublisher\",\"d\":\"A person or organization that is not in the business of publishing; someone who does not produce or distribute books, magazines, or other printed or digital media.\",\"s\":\"As a nonpublisher, she shared her writing only with close friends rather than seeking a wider audience.\",\"p\":\"non-PUB-lish-er\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.pub.lish.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpublishing\",\"d\":\"Not engaged in or relating to the activity of publishing; describing a person, company, or endeavor that does not produce or distribute written or recorded works.\",\"s\":\"The nonpublishing author kept dozens of completed novels locked away in a drawer at home.\",\"p\":\"non-PUB-lish-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pub.lish.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpuerperal\",\"d\":\"Not related to or caused by childbirth or the period immediately following delivery; describing a condition that occurs independently of pregnancy or the postpartum state.\",\"s\":\"The infection was classified as nonpuerperal because it appeared in a patient who had not recently given birth.\",\"p\":\"non-pyoo-ER-per-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.puer.per.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpulmonary\",\"d\":\"Not relating to or involving the lungs; describing a condition, process, or cause that originates outside of the pulmonary system.\",\"s\":\"The doctor determined the patient's breathing difficulty had a nonpulmonary cause, tracing it to a heart condition instead.\",\"p\":\"non-PUL-muh-nair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.pul.monary\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonpulmonic\",\"d\":\"Not produced or originating from the lungs; used especially in linguistics to describe sounds made without airflow from the lungs.\",\"s\":\"Certain click consonants in African languages are produced with a nonpulmonic airstream, not from the lungs.\",\"p\":\"non-pul-MON-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.pul.monic\",\"ps\":\"adjective\",\"t\":[\"body\",\"wordwords\",\"olatin\"]},{\"w\":\"nonpulse\",\"d\":\"Not characterized by a regular rhythmic beat or pulse; describing a signal, waveform, or biological reading that lacks a pulsing pattern.\",\"s\":\"The engineer designed a nonpulse signal that remained steady rather than flickering on and off.\",\"p\":\"non-PULS\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.pulse\",\"ps\":\"adjective\",\"t\":[\"music\",\"character\",\"olatin\"]},{\"w\":\"nonpunctual\",\"d\":\"Not arriving or occurring at the expected or scheduled time; habitually late or lacking promptness.\",\"s\":\"Her nonpunctual habits meant she missed the first ten minutes of every class throughout the semester.\",\"p\":\"non-PUNK-choo-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.punc.tu.al\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonpunctuated\",\"d\":\"Lacking punctuation marks such as commas, periods, or colons; describing text or writing that does not use standard punctuation conventions.\",\"s\":\"The ancient manuscript was nonpunctuated, making it extremely difficult for scholars to determine where sentences ended.\",\"p\":\"non-PUNK-choo-ay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.punc.tu.at.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpunitive\",\"d\":\"Not intended to inflict punishment or penalty; describing an approach or policy that focuses on correction or support rather than discipline.\",\"s\":\"The school adopted a nonpunitive approach to discipline, focusing on understanding behavior rather than issuing detentions.\",\"p\":\"non-PYOO-nih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.puni.tive\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonpurchasable\",\"d\":\"Not able to be bought or acquired through payment; describing something that cannot be obtained commercially or through monetary exchange.\",\"s\":\"True happiness is nonpurchasable, no matter how much money you spend at the mall.\",\"p\":\"non-PUR-chus-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pur.chasable\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonpurchased\",\"d\":\"Not obtained through buying; describing goods, services, or items that were acquired by means other than a financial transaction.\",\"s\":\"The nonpurchased supplies were donated by local businesses to help the school art program.\",\"p\":\"non-PUR-chust\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.pur.chased\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpurchaser\",\"d\":\"A person who does not buy or has not bought a particular product or service; someone who refrains from making a purchase.\",\"s\":\"As a nonpurchaser, he simply browsed the store for an hour without buying anything.\",\"p\":\"non-PUR-chus-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pur.chas.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpurchasing\",\"d\":\"Not engaged in the act of buying; describing behavior, departments, or individuals that do not participate in procurement or buying activities.\",\"s\":\"The survey targeted nonpurchasing visitors to the website to find out why they didn't complete their orders.\",\"p\":\"non-PUR-chus-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.pur.chas.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonpurine\",\"d\":\"Not belonging to or derived from the purine group of chemical compounds; describing molecules or dietary substances that do not contain a purine base.\",\"s\":\"The nutritionist recommended a nonpurine diet for the patient to help reduce uric acid levels.\",\"p\":\"non-PYOOR-een\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.purine\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonpurist\",\"d\":\"A person who is not strict or rigid about following traditional rules or standards; someone who accepts variations or impurities in language, art, or practice.\",\"s\":\"As a nonpurist, she happily mixed traditional cooking techniques with modern shortcuts.\",\"p\":\"non-PYOOR-ist\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.purist\",\"ps\":\"noun\",\"t\":[\"festivals\",\"character\",\"wordwords\",\"olatin\"]},{\"w\":\"nonpurity\",\"d\":\"The state or quality of not being pure; the presence of mixed, contaminated, or impure elements in a substance or concept.\",\"s\":\"The chemist noted the nonpurity of the sample, explaining that trace metals had contaminated it.\",\"p\":\"non-PYOOR-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.pu.ri.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonpurple\",\"d\":\"Not of the color purple; describing any hue, shade, or object that does not fall within the purple range of the color spectrum.\",\"s\":\"The designer carefully separated the nonpurple fabrics into a different pile to keep the color scheme consistent.\",\"p\":\"non-PUR-pul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.pur.ple\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonpurposive\",\"d\":\"Not directed toward a specific goal or intention; describing behavior, movement, or processes that lack deliberate aim or purpose.\",\"s\":\"Some animal behaviors appear nonpurposive, seeming random rather than directed toward any goal.\",\"p\":\"non-PUR-puh-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.pur.po.sive\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonpyritic\",\"d\":\"Not containing or relating to pyrite; describing rock, ore, or mineral deposits that are free from iron sulfide compounds.\",\"s\":\"The geologist confirmed the rock sample was nonpyritic, containing no iron sulfide minerals.\",\"p\":\"non-py-RIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.pyrit.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"nonpyritized\",\"d\":\"Not converted into or replaced by pyrite through a chemical process; describing organic material or minerals that have not undergone pyritization.\",\"s\":\"The fossils were nonpyritized and had been preserved in limestone rather than converted to iron sulfide.\",\"p\":\"non-PY-rih-tyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.pyri.tized\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"minerals\",\"olatin\"]},{\"w\":\"nonpyrogenic\",\"d\":\"Not producing or causing fever; describing substances, especially medical injections or materials, that do not trigger a fever response in the body.\",\"s\":\"The label confirmed the injection was nonpyrogenic, meaning it would not cause a fever when administered.\",\"p\":\"non-py-roh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.py.ro.genic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonpyrophoric\",\"d\":\"Not capable of spontaneously igniting upon contact with air or oxygen; describing a material that does not catch fire without an external ignition source.\",\"s\":\"The storage guidelines noted that the chemical was nonpyrophoric and would not spontaneously ignite in air.\",\"p\":\"non-py-roh-FOR-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.py.rophoric\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonquadratic\",\"d\":\"Not involving or described by a quadratic equation; referring to mathematical expressions or relationships that do not contain a squared variable term.\",\"s\":\"The math teacher explained that a straight-line equation is nonquadratic because it has no squared variable.\",\"p\":\"non-kwah-DRAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.quadrat.ic\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonquadratically\",\"d\":\"In a manner that is not quadratic; describing how a mathematical function or relationship behaves without following a squared or parabolic pattern.\",\"s\":\"The data grew nonquadratically, increasing in a simple linear pattern rather than curving upward sharply.\",\"p\":\"non-kwah-DRAT-ih-kuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.quadrat.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonquadrilateral\",\"d\":\"Not having four sides; describing a geometric shape or figure that does not qualify as a quadrilateral because it has a different number of sides.\",\"s\":\"A triangle is a nonquadrilateral shape because it has only three sides, not four.\",\"p\":\"non-kwah-drih-LAT-er-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.quadri.lat.er.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonqualified\",\"d\":\"Not meeting the required standards, credentials, or criteria for a particular role, benefit, or plan; lacking the necessary qualifications.\",\"s\":\"The nonqualified applicant was politely told he lacked the required certifications for the engineering position.\",\"p\":\"nah-NKWAH-luh-feye-d\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"naa.nkwaa.lah.fay.d\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonqualifier\",\"d\":\"A person or entry that has not met the necessary standards or scores to advance in a competition, program, or selection process.\",\"s\":\"As a nonqualifier in the regional tournament, she did not advance to the state championship.\",\"p\":\"non-KWAH-lih-fy-ur\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.qual.i.fi.er\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonqualitative\",\"d\":\"Not based on or involving qualities, characteristics, or descriptive attributes; relating to data or analysis that does not use subjective or descriptive measures.\",\"s\":\"The scientist preferred nonqualitative data, relying on numbers and measurements rather than descriptive observations.\",\"p\":\"non-KWAH-lih-tay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.qual.i.ta.tive\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonquantal\",\"d\":\"Not occurring in discrete, fixed units of energy or matter; describing a process or phenomenon that does not follow the rules of quantum behavior.\",\"s\":\"The physicist explained that classical mechanics operates on a nonquantal scale, where energy flows continuously rather than in discrete packets.\",\"p\":\"non-KWAN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.quan.tal\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonquantifiable\",\"d\":\"Not able to be measured, counted, or expressed as a numerical quantity; describing qualities or phenomena that resist precise numerical measurement.\",\"s\":\"The joy a puppy brings is nonquantifiable because no number can capture that feeling.\",\"p\":\"non-KWAN-tih-fy-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.quan.tifi.able\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonquantitative\",\"d\":\"Not involving numerical measurement or the expression of data in quantities; describing an approach or method that relies on descriptions rather than numbers.\",\"s\":\"The teacher used a nonquantitative approach, focusing on feelings and opinions rather than statistics.\",\"p\":\"non-KWAN-tih-tay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.quan.ti.ta.tive\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonquantized\",\"d\":\"Not divided into or existing as discrete, fixed units; describing a physical quantity or system that varies continuously rather than in distinct steps.\",\"s\":\"Unlike energy in an atom, the water flowing in the river was nonquantized and moved in a continuous stream.\",\"p\":\"non-KWAN-tyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.quan.tized\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonquantum\",\"d\":\"Not governed by or related to the principles of quantum mechanics; describing physical systems or phenomena that follow classical rather than quantum rules.\",\"s\":\"Classical physics describes nonquantum behavior, where objects follow smooth, predictable paths.\",\"p\":\"non-KWAN-tum\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.quan.tum\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"olatin\"]},{\"w\":\"nonquarantinable\",\"d\":\"Not subject to quarantine restrictions; describing a disease, person, or condition that does not legally or medically require isolation to prevent spread.\",\"s\":\"The health officer confirmed the mild cold was nonquarantinable because it posed no serious public threat.\",\"p\":\"non-KWOR-un-tee-nuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.quar.antin.able\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"law\",\"olatin\"]},{\"w\":\"nonquarantine\",\"d\":\"Not involving or subject to a period of isolation; describing situations, individuals, or conditions that do not require separation to prevent disease transmission.\",\"s\":\"The travelers were placed in a nonquarantine zone after testing negative for the virus.\",\"p\":\"non-KWOR-un-teen\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.quar.an.tine\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonquarantined\",\"d\":\"Not placed under or subjected to a quarantine; describing a person, animal, or item that has been allowed to move freely without isolation restrictions.\",\"s\":\"The nonquarantined passengers were free to walk through the airport without restrictions.\",\"p\":\"non-KWOR-un-teend\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.quar.an.tined\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonquarterly\",\"d\":\"Not occurring or issued every quarter of a year; describing a schedule, payment, or publication that does not follow a four-times-per-year frequency.\",\"s\":\"The club held nonquarterly meetings, gathering every month instead of every three months.\",\"p\":\"non-KWOR-tur-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.quar.ter.ly\",\"ps\":\"adjective\",\"t\":[\"physics\",\"time\",\"olatin\"]},{\"w\":\"nonquestioning\",\"d\":\"Not inclined to ask questions or challenge information; accepting facts, rules, or authority without inquiry or doubt.\",\"s\":\"The nonquestioning student accepted every answer the teacher gave without wondering why.\",\"p\":\"non-KWES-chun-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.ques.tion.ing\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"character\",\"olatin\"]},{\"w\":\"nonqueued\",\"d\":\"Not arranged in or waiting in a sequential line or queue; describing a system, process, or group of people that does not follow a first-come, first-served order.\",\"s\":\"The nonqueued system allowed customers to be served immediately without waiting in any line.\",\"p\":\"non-KYOOD\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.queued\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonqueuing\",\"d\":\"Not forming or involving a waiting line; describing a system or process in which tasks, people, or data are handled without being placed in a sequential queue.\",\"s\":\"The app used a nonqueuing method that connected users to a representative instantly.\",\"p\":\"non-KYOO-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.queu.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonquiescent\",\"d\":\"Not in a state of quiet, rest, or inactivity; describing something that is active, restless, or continuously changing rather than still and dormant.\",\"s\":\"The nonquiescent volcano rumbled constantly, reminding nearby villagers it was still active.\",\"p\":\"non-kwy-ES-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.qui.es.cent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonquiet\",\"d\":\"Not quiet; characterized by noise, sound, or a lack of stillness or calm.\",\"s\":\"The library became nonquiet after the fire drill sent everyone into the hallway talking loudly.\",\"p\":\"non-KWY-et\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.qui.et\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonquitter\",\"d\":\"A person who does not give up; someone who persists and continues despite difficulty or setbacks.\",\"s\":\"She was a true nonquitter who kept practicing her violin even after failing the audition twice.\",\"p\":\"non-KWIT-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.quit.ter\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonquota\",\"d\":\"Not subject to or limited by a quota; describing goods, immigrants, or items that are not restricted by a set numerical limit.\",\"s\":\"The nonquota immigrants were admitted based on special skills rather than country limits.\",\"p\":\"non-KWOH-tuh\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.quo.ta\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrabbinic\",\"d\":\"Not relating to or derived from the teachings or authority of rabbis; outside the tradition of rabbinic scholarship.\",\"s\":\"The nonrabbinic interpretation of the text came from a secular historian rather than a religious leader.\",\"p\":\"non-ruh-BIN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonrab.binic\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"religion\",\"festivals\",\"olatin\"]},{\"w\":\"nonrabbinical\",\"d\":\"Not of or pertaining to rabbinical tradition, law, or learning; describing something that falls outside the scope of rabbinic authority.\",\"s\":\"The nonrabbinical commentary was written by a philosopher with no formal Jewish religious training.\",\"p\":\"non-ruh-BIN-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonrab.bini.cal\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"religion\",\"festivals\",\"law\",\"olatin\"]},{\"w\":\"nonrabbit\",\"d\":\"Not a rabbit; describing any animal, object, or entity that is not a rabbit.\",\"s\":\"The animal shelter carefully separated the nonrabbit pets from the bunny enclosure.\",\"p\":\"non-RAB-it\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonrab.bit\",\"ps\":\"adjective\",\"t\":[\"animals\",\"religion\",\"olatin\"]},{\"w\":\"nonracemic\",\"d\":\"Describing a chemical compound or mixture that is not racemic, meaning it does not contain equal amounts of both mirror-image (enantiomer) forms of a molecule.\",\"s\":\"The chemist produced a nonracemic compound that contained only one mirror-image form of the molecule.\",\"p\":\"non-ruh-SEE-mik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.racemic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"household\",\"olatin\"]},{\"w\":\"nonracing\",\"d\":\"Not involving or related to racing; describing activities, vehicles, or events that are not competitive speed contests.\",\"s\":\"She bought a nonracing bicycle designed for casual rides around the neighborhood.\",\"p\":\"non-RAY-sing\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.rac.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"vehicles\",\"olatin\"]},{\"w\":\"nonracism\",\"d\":\"The absence of racism; a state or philosophy characterized by the rejection of racial prejudice and discrimination.\",\"s\":\"The community center promoted nonracism by hosting cultural festivals that celebrated every background.\",\"p\":\"non-RAY-siz-um\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.racism\",\"ps\":\"noun\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonracist\",\"d\":\"unprejudiced about race\",\"s\":\"The nonracist coach treated every player equally regardless of where they came from.\",\"p\":\"non-RAY-sist\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.racist\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonradar\",\"d\":\"Not using or involving radar technology; describing navigation, detection, or systems that operate without radar.\",\"s\":\"The pilot relied on nonradar navigation tools like GPS and visual landmarks during the flight.\",\"p\":\"non-RAY-dar\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.radar\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonradial\",\"d\":\"Not directed along or relating to a radius; describing motion, structure, or patterns that do not extend outward from a central point.\",\"s\":\"The engineer designed a nonradial pattern where all the lines ran parallel instead of spreading from a center.\",\"p\":\"non-RAY-dee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ra.di.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonradiate\",\"d\":\"Not emitting or radiating energy, heat, or light; describing a substance or body that does not give off radiant energy.\",\"s\":\"Unlike a glowing star, a dark matter particle is nonradiate and emits no detectable light.\",\"p\":\"non-RAY-dee-ayt\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ra.di.ate\",\"ps\":\"adjective\",\"t\":[\"physics\",\"colors\",\"olatin\"]},{\"w\":\"nonradical\",\"d\":\"Not extreme or revolutionary in opinion or action; describing a moderate approach that does not seek drastic change.\",\"s\":\"The politician took a nonradical stance, suggesting small gradual changes rather than dramatic reforms.\",\"p\":\"non-RAD-ih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.rad.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonradio\",\"d\":\"Not involving or transmitted by radio waves; describing communication or technology that does not use radio signals.\",\"s\":\"The campers used nonradio communication, passing handwritten notes to each other across the campsite.\",\"p\":\"non-RAY-dee-oh\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.ra.dio\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"nonradioactivity\",\"d\":\"The state or property of not being radioactive; the absence of the emission of ionizing radiation from atomic nuclei.\",\"s\":\"Scientists confirmed the nonradioactivity of the mineral, making it safe to handle without protective gear.\",\"p\":\"non-ray-dee-oh-ak-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.ra.dioac.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonradiolucent\",\"d\":\"Not allowing X-rays or other radiation to pass through easily; describing a material that blocks or absorbs radiation rather than permitting it to pass.\",\"s\":\"The dense metal implant was nonradiolucent, meaning X-rays could not pass through it.\",\"p\":\"non-ray-dee-oh-LOO-sent\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ra.di.olu.cent\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonradiometric\",\"d\":\"Not based on or measured by radiometric methods; describing dating or measurement techniques that do not rely on radioactive decay.\",\"s\":\"The geologist used a nonradiometric method to date the rock layers by studying their fossil content.\",\"p\":\"non-ray-dee-oh-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ra.dio.met.ric\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonradiopaque\",\"d\":\"Not opaque to X-rays; describing a material or substance that allows X-rays to pass through it rather than blocking them.\",\"s\":\"The soft tissue was nonradiopaque, so it appeared transparent and faint on the X-ray image.\",\"p\":\"non-ray-dee-oh-PAYK\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.ra.diopaque\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonradium\",\"d\":\"Not containing or involving the element radium; describing substances or environments in which radium is absent.\",\"s\":\"The scientist tested several nonradium elements to find a safer alternative for medical treatments.\",\"p\":\"non-RAY-dee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ra.di.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ecology\",\"olatin\"]},{\"w\":\"nonradon\",\"d\":\"Not containing or involving radon gas; describing an environment or material in which the radioactive gas radon is absent or undetected.\",\"s\":\"The air quality test confirmed the basement was nonradon, so the family felt safe living there.\",\"p\":\"non-RAY-don\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.radon\",\"ps\":\"adjective\",\"t\":[\"physics\",\"ecology\",\"olatin\"]},{\"w\":\"nonrail\",\"d\":\"Not involving or related to rail transportation; describing travel, freight, or infrastructure that does not use railway tracks.\",\"s\":\"The city invested in nonrail transportation like buses and bike lanes to reduce congestion.\",\"p\":\"non-RAYL\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.rail\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonrailroad\",\"d\":\"Not pertaining to or operated by a railroad; describing transportation, companies, or land that has no connection to rail lines.\",\"s\":\"The nonrailroad shipping company used only trucks and boats to deliver its cargo across the country.\",\"p\":\"non-RAYL-rohd\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.rail.road\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonrailway\",\"d\":\"Not associated with or dependent on a railway system; describing routes, vehicles, or services that operate independently of rail tracks.\",\"s\":\"The remote village was connected to the city only by nonrailway roads winding through the mountains.\",\"p\":\"non-RAYL-way\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rail.way\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonrainforest\",\"d\":\"Not constituting or resembling a rainforest; describing a biome, ecosystem, or region that lacks the dense vegetation and heavy rainfall characteristic of a rainforest.\",\"s\":\"The researchers studied nonrainforest ecosystems like deserts and grasslands to compare biodiversity.\",\"p\":\"non-RAYN-for-est\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.rain.for.est\",\"ps\":\"adjective\",\"t\":[\"weather\",\"ecology\",\"olatin\"]},{\"w\":\"nonrainy\",\"d\":\"Not characterized by rain; describing weather, seasons, or periods that are dry and without precipitation.\",\"s\":\"On a nonrainy afternoon the children rushed outside to play soccer in the dry sunshine.\",\"p\":\"non-RAY-nee\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.rainy\",\"ps\":\"adjective\",\"t\":[\"weather\",\"character\",\"time\",\"olatin\"]},{\"w\":\"nonraised\",\"d\":\"Not elevated, embossed, or lifted above a surface; describing a flat or flush design with no raised elements.\",\"s\":\"The nonraised text on the sign was flat and smooth, unlike the bumpy Braille letters beside it.\",\"p\":\"non-RAYZD\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.raised\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonranching\",\"d\":\"Not involving or related to the raising of livestock on a ranch; describing land use, farming, or activities that do not constitute ranching.\",\"s\":\"The nonranching farmers focused entirely on growing crops rather than raising cattle.\",\"p\":\"non-RAN-ching\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.ranch.ing\",\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonrancid\",\"d\":\"Not rancid; describing food or fat that has not spoiled, turned sour, or developed an unpleasant smell due to decomposition.\",\"s\":\"The nonrancid butter had been stored properly in the refrigerator all week.\",\"p\":\"non-RAN-sid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ran.cid\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrandomization\",\"d\":\"The absence of randomization; a process or study design in which participants or elements are assigned deliberately rather than by chance.\",\"s\":\"The study used nonrandomization, selecting participants based on specific criteria rather than by chance.\",\"p\":\"non-ran-dum-ih-ZAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ran.dom.iza.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrandomized\",\"d\":\"Not assigned or arranged by a random process; describing a study, trial, or selection in which choices are made deliberately rather than by chance.\",\"s\":\"The nonrandomized trial assigned patients to groups based on their age and health history.\",\"p\":\"non-RAN-dum-yzd\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.ran.dom.ized\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonrandomizing\",\"d\":\"Not using or applying a process of random assignment; describing a method that deliberately orders or selects rather than leaving things to chance.\",\"s\":\"The researcher's nonrandomizing approach meant she carefully chose each participant for the experiment.\",\"p\":\"non-RAN-dum-y-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ran.dom.iz.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrandomness\",\"d\":\"The quality or state of not being random; the presence of pattern, order, or intentional structure in a sequence or arrangement.\",\"s\":\"The pattern in the data showed clear nonrandomness, suggesting an outside force was influencing results.\",\"p\":\"non-RAN-dum-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ran.dom.ness\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrarefied\",\"d\":\"Not rarefied; describing air, gas, or an atmosphere that is dense and at normal or high pressure rather than thin and low-pressure.\",\"s\":\"The nonrarefied air at sea level felt thick and heavy compared to mountain conditions.\",\"p\":\"non-RAIR-uh-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.rar.efied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonraster\",\"d\":\"Not using a raster format; describing digital images or graphics that are defined by mathematical paths and shapes rather than a grid of pixels.\",\"s\":\"The designer preferred nonraster graphics because they could be scaled without losing quality.\",\"p\":\"non-RAS-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.raster\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonrated\",\"d\":\"Not assigned an official rating or classification; describing a film, product, or individual that has not been evaluated or ranked by a recognized authority.\",\"s\":\"The nonrated film had no official review score, making it hard to know what to expect.\",\"p\":\"non-RAY-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.rat.ed\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonratifiable\",\"d\":\"Not capable of being ratified or officially approved; describing a treaty, agreement, or proposal that cannot be formally confirmed or validated.\",\"s\":\"The treaty was considered nonratifiable because it violated several constitutional principles.\",\"p\":\"non-RAT-ih-fy-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.rat.i.fi.able\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonratified\",\"d\":\"Describing a treaty, agreement, or document that has not been formally approved or confirmed by the required authority or governing body.\",\"s\":\"The nonratified agreement sat unsigned on the governor's desk for weeks.\",\"p\":\"non-RAT-ih-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.rat.i.fied\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"politics\",\"olatin\"]},{\"w\":\"nonratifying\",\"d\":\"Describing an entity or party that is not in the process of formally approving or confirming an agreement, treaty, or official document.\",\"s\":\"The nonratifying states refused to sign the new education policy proposed by the federal government.\",\"p\":\"non-RAT-ih-fy-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.rat.i.fy.ing\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonrating\",\"d\":\"Referring to something that does not involve or apply a rating, score, or evaluative classification to a person, product, or performance.\",\"s\":\"The nonrating system at the new school meant students received written feedback instead of grades.\",\"p\":\"non-RAY-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.rat.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonrationalistic\",\"d\":\"Not based on or characterized by the belief that reason and logic alone are the primary sources of knowledge and truth.\",\"s\":\"Her nonrationalistic beliefs were based on intuition and emotion rather than logical reasoning.\",\"p\":\"non-rash-uh-nuh-LIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ra.tional.is.tic\",\"ps\":\"adjective\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonrationalizable\",\"d\":\"Describing something that cannot be explained, justified, or made to appear reasonable through logical reasoning or rational argument.\",\"s\":\"The strange behavior was nonrationalizable — no logical explanation could account for it.\",\"p\":\"non-RASH-uh-nuh-ly-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ra.tional.iz.able\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonrationalized\",\"d\":\"Not having been explained away or made to seem logical through after-the-fact reasoning; not subjected to a process of rationalization.\",\"s\":\"The nonrationalized decision confused the team because no clear reason was ever given.\",\"p\":\"non-RASH-uh-nuh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ra.tional.ized\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonrationed\",\"d\":\"Not subject to rationing; describing goods or resources that are distributed freely without restrictions on the amount each person may receive.\",\"s\":\"During peacetime, food was nonrationed and people could buy as much as they could afford.\",\"p\":\"non-RASH-und\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.ra.tioned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonraven\",\"d\":\"Not of or relating to a raven; describing a bird or object that does not belong to the raven species or does not share raven characteristics.\",\"s\":\"The birdwatcher noted that the large black bird was actually nonraven — it was a crow.\",\"p\":\"non-RAY-vun\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.raven\",\"ps\":\"adjective\",\"t\":[\"birds\",\"olatin\"]},{\"w\":\"nonraw\",\"d\":\"Not in a raw or unprocessed state; referring to something that has been cooked, treated, or otherwise prepared from its natural form.\",\"s\":\"The chef only served nonraw fish that had been thoroughly cooked to ensure food safety.\",\"p\":\"non-RAW\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.raw\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonreaction\",\"d\":\"The absence of a response or reaction to a stimulus, event, or substance; a state in which no noticeable change or response occurs.\",\"s\":\"The scientist was puzzled by the nonreaction when the two chemicals were combined.\",\"p\":\"non-ree-AK-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.ac.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreactionary\",\"d\":\"Not characterized by opposition to progress or change; describing a person or policy that does not seek to return to a previous state of affairs.\",\"s\":\"The nonreactionary politician welcomed change rather than trying to return to old ways.\",\"p\":\"non-ree-AK-shuh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.re.ac.tionary\",\"ps\":\"adjective\",\"t\":[\"politics\",\"character\",\"olatin\"]},{\"w\":\"nonreactive\",\"d\":\"Not tending to react chemically, emotionally, or physically to a stimulus; remaining stable and unchanged when exposed to other substances or situations.\",\"s\":\"Gold is nonreactive with most chemicals, which is why it doesn't tarnish easily.\",\"p\":\"non-ree-AK-tiv\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.ac.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"character\",\"emotions\",\"olatin\"]},{\"w\":\"nonreactivity\",\"d\":\"The quality or state of being unable or unlikely to react chemically, emotionally, or physically to external stimuli or other substances.\",\"s\":\"The lab report confirmed the nonreactivity of the new compound under extreme temperatures.\",\"p\":\"non-ree-ak-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.ac.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"emotions\",\"olatin\"]},{\"w\":\"nonreactor\",\"d\":\"A substance, person, or system that does not react to a particular stimulus, test, or chemical agent, showing no measurable response.\",\"s\":\"The facility was labeled a nonreactor because it stored nuclear materials but didn't generate power.\",\"p\":\"non-ree-AK-tur\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.re.ac.tor\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonreadable\",\"d\":\"Not capable of being read or interpreted, either because the text is illegible, encoded, or in a format that cannot be processed.\",\"s\":\"The smudged ink made the old letter completely nonreadable, frustrating the historian.\",\"p\":\"non-REE-duh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.read.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreading\",\"d\":\"Not involving or related to the act of reading; describing a person who does not read regularly or an activity that does not require reading.\",\"s\":\"The nonreading child relied on pictures and oral storytelling to understand the world.\",\"p\":\"non-REE-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.read.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreal\",\"d\":\"Not existing in reality; imaginary, fictional, or existing only in theory, mathematics, or the imagination rather than the physical world.\",\"s\":\"Imaginary numbers are considered nonreal in standard mathematics, yet they are incredibly useful.\",\"p\":\"non-REE-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":20,\"sy\":\"non.re.al\",\"ps\":\"adjective\",\"t\":[\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"nonrealist\",\"d\":\"A person who does not adhere to realism in art, literature, or philosophy, favoring instead abstract, idealistic, or imaginative approaches.\",\"s\":\"As a nonrealist artist, she painted swirling dreamscapes that defied ordinary perception.\",\"p\":\"non-REE-uh-list\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.re.al.ist\",\"ps\":\"noun\",\"t\":[\"poetry\",\"logic\",\"olatin\"]},{\"w\":\"nonrealtime\",\"d\":\"Not occurring or processed at the same moment events happen; describing data, communication, or computing that is delayed rather than immediate.\",\"s\":\"The nonrealtime video feed was delayed by several seconds, which caused confusion during the broadcast.\",\"p\":\"non-REE-ul-tym\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.re.al.time\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonreasonable\",\"d\":\"Not guided by or based on sound reasoning or good judgment; failing to demonstrate logic, fairness, or rational thinking.\",\"s\":\"The judge dismissed the nonreasonable claim as having no logical or legal basis.\",\"p\":\"non-REE-zun-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.rea.son.able\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonreassuring\",\"d\":\"Failing to provide comfort, confidence, or relief from worry; describing something that does not make a person feel more secure or certain.\",\"s\":\"The doctor's nonreassuring tone made the patient even more anxious about the test results.\",\"p\":\"non-ree-uh-SHOOR-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.as.sur.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecalled\",\"d\":\"Not having been called back, withdrawn, or brought back to memory; describing a product, person, or memory that has not been recalled.\",\"s\":\"The nonrecalled products were safe and remained on store shelves without any concerns.\",\"p\":\"non-rih-KAWLD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.re.called\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreceipt\",\"d\":\"The state or fact of not having received something, such as a payment, shipment, or communication that was expected.\",\"s\":\"The customer reported nonreceipt of her package even though the tracking said it was delivered.\",\"p\":\"non-rih-SEET\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.re.ceipt\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrecent\",\"d\":\"Not belonging to or occurring in the near past; referring to something that happened a long time ago or is no longer considered new or current.\",\"s\":\"The archaeologist's discovery was labeled nonrecent, dating back over two thousand years.\",\"p\":\"non-REE-sunt\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.re.cent\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonrecently\",\"d\":\"Not in the near past; at a time that was not recent, indicating that something occurred or existed long before the present moment.\",\"s\":\"The event occurred nonrecently, so most witnesses had trouble remembering the exact details.\",\"p\":\"non-REE-sunt-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.cent.ly\",\"ps\":\"adverb\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonreceptive\",\"d\":\"Not open or willing to receive new ideas, information, or stimuli; resistant to accepting or absorbing what is offered or presented.\",\"s\":\"The nonreceptive audience sat in silence, showing no interest in the speaker's message.\",\"p\":\"non-rih-SEP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.cep.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreceptivity\",\"d\":\"The quality or state of being unwilling or unable to receive, absorb, or respond to new ideas, stimuli, or information.\",\"s\":\"Her nonreceptivity to new ideas made it hard for the team to move the project forward.\",\"p\":\"non-rih-sep-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.cep.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreceptor\",\"d\":\"A cell, molecule, or structure that does not function as a receptor and therefore does not bind to or respond to a specific chemical signal.\",\"s\":\"The scientist discovered that the nonreceptor protein could not bind to the drug molecule at all.\",\"p\":\"non-rih-SEP-tur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.cep.tor\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonrecessed\",\"d\":\"Not set back into a surface or wall; describing a fixture, panel, or architectural feature that is flush with or protruding from a surface.\",\"s\":\"The nonrecessed light fixtures stuck out from the ceiling like little boxes instead of sitting flush.\",\"p\":\"non-rih-SEST\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.re.cessed\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"olatin\"]},{\"w\":\"nonrecession\",\"d\":\"A period or condition in which an economy does not experience a recession, maintaining growth or stability rather than declining output.\",\"s\":\"During a period of nonrecession, businesses hire more workers and shoppers spend freely.\",\"p\":\"non-rih-SESH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.ces.sion\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonrecessionary\",\"d\":\"Not characteristic of or related to an economic recession; describing conditions in which the economy remains stable or continues to grow.\",\"s\":\"The economist described the stable, nonrecessionary period as one of the healthiest in decades.\",\"p\":\"non-rih-SESH-uh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.ces.sion.ary\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonrecidivist\",\"d\":\"A person who has not returned to criminal behavior or relapsed into prior bad habits after a period of reform or rehabilitation.\",\"s\":\"The judge praised the nonrecidivist for never returning to crime after his release from prison.\",\"p\":\"non-rih-SID-ih-vist\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.cidi.vist\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonrecipient\",\"d\":\"A person or entity that does not receive something, such as aid, a gift, or a benefit, that others may be receiving.\",\"s\":\"As a nonrecipient of the scholarship, she had to find another way to pay for college.\",\"p\":\"non-rih-SIP-ee-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.re.cip.i.ent\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreciprocity\",\"d\":\"The absence of mutual exchange or equal give-and-take between two parties; a one-sided relationship lacking balanced cooperation or benefit.\",\"s\":\"The trade deal collapsed because of nonreciprocity—one country gave benefits but got nothing back.\",\"p\":\"non-reh-sih-PROS-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.ciproc.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrecirculating\",\"d\":\"Not designed to cycle or flow back through a system repeatedly; describing a system in which fluid, air, or material passes through only once.\",\"s\":\"The nonrecirculating water system sent water in one direction and never reused it.\",\"p\":\"non-ree-SUR-kyuh-lay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.re.cir.cu.lat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecognition\",\"d\":\"The failure or refusal to acknowledge, identify, or formally accept someone or something, such as a government refusing to recognize another state.\",\"s\":\"The country's nonrecognition of the new government meant there would be no official diplomatic ties.\",\"p\":\"non-rek-ug-NISH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.recog.ni.tion\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonrecognizable\",\"d\":\"Unable to be identified or distinguished from before; so changed in appearance or form that it cannot be recognized by familiar observers.\",\"s\":\"After the makeover, the actress was nonrecognizable even to her closest friends.\",\"p\":\"non-REK-ug-ny-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.rec.og.niz.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecoil\",\"d\":\"Describing a firearm or mechanism designed so that it does not spring or kick backward when fired, absorbing the force of discharge internally.\",\"s\":\"The engineer designed a nonrecoil mechanism so the cannon wouldn't slide backward when fired.\",\"p\":\"non-rih-KOYL\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.coil\",\"ps\":\"adjective\",\"t\":[\"physics\",\"tools\",\"time\",\"olatin\"]},{\"w\":\"nonrecombining\",\"d\":\"Not undergoing recombination; describing genetic material or chromosomes that do not exchange segments during cell division or reproduction.\",\"s\":\"The scientists identified nonrecombining regions of DNA that stayed the same across generations.\",\"p\":\"non-ree-kum-BY-ning\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.com.bin.ing\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonreconfigurable\",\"d\":\"Not capable of being rearranged, restructured, or set up in a different way once it has been initially designed or programmed.\",\"s\":\"The old circuit board was nonreconfigurable, meaning engineers couldn't change its layout after manufacturing.\",\"p\":\"non-ree-kun-FIG-yur-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.con.fig.urable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreconstituted\",\"d\":\"Not restored or reassembled from separate parts into its original or a usable form; describing something that has never been reconstituted.\",\"s\":\"The nonreconstituted dried herbs had never been soaked in water to restore their original form.\",\"p\":\"non-ree-kon-STI-choo-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.re.con.sti.tut.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreconstructed\",\"d\":\"Not rebuilt, reorganized, or restored to a former or improved state; describing something left in its original, unaltered condition without reconstruction.\",\"s\":\"The nonreconstructed ruins were left exactly as they were found, untouched by restorers.\",\"p\":\"non-ree-kon-STRUKT-id\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.con.struct.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecordable\",\"d\":\"Not able to be recorded or captured onto a recording medium; describing a format or surface on which information cannot be saved.\",\"s\":\"The judge ruled that the private conversation was nonrecordable and couldn't be used as evidence.\",\"p\":\"non-reh-KORD-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.record.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecorded\",\"d\":\"Not captured or preserved through any recording process; describing information or events for which no recording exists.\",\"s\":\"Many important folk songs were nonrecorded, existing only in the memories of village singers.\",\"p\":\"non-reh-KORD-id\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.record.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecording\",\"d\":\"Not engaged in or capable of making a recording; describing a device or situation in which no recording is taking place.\",\"s\":\"The nonrecording session was just a casual rehearsal with no microphones or equipment running.\",\"p\":\"non-reh-KORD-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.record.ing\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonrecourse\",\"d\":\"Describing a type of loan or financial agreement in which the lender's only remedy upon default is to seize the collateral, with no further claim against the borrower personally.\",\"s\":\"With a nonrecourse loan, the bank can only take the property but cannot chase the borrower for more money.\",\"p\":\"non-REE-kors\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.re.course\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"economy\",\"olatin\"]},{\"w\":\"nonrecreational\",\"d\":\"done for work or a serious purpose rather than for fun\",\"s\":\"The professional potter insisted his craft was nonrecreational—it was his full-time livelihood, not a hobby.\",\"p\":\"non-rek-ree-AY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.recre.ation.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecruited\",\"d\":\"Not sought out or actively brought in through a recruiting process; describing someone who joined or was hired without being formally recruited.\",\"s\":\"The nonrecruited athlete walked onto the team through tryouts, impressing the coach without any prior invitation.\",\"p\":\"non-reh-KROOT-id\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.cruit.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecruiting\",\"d\":\"Not engaged in the process of actively seeking or enlisting new members, employees, or participants.\",\"s\":\"The small club was nonrecruiting that semester because they already had too many members.\",\"p\":\"non-reh-KROOT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.cruit.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrectangular\",\"d\":\"Not having the shape of a rectangle; describing a figure or object that does not have four right angles and two pairs of parallel sides.\",\"s\":\"The architect sketched a nonrectangular room with angled walls that gave the space a unique feel.\",\"p\":\"non-rek-TANG-gyoo-ler\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rect.an.gu.lar\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonrectilinear\",\"d\":\"Not following or forming straight lines; describing shapes, paths, or forms made up of curved or irregular lines rather than straight ones.\",\"s\":\"The artist preferred nonrectilinear sculptures that curved and spiraled instead of following straight lines.\",\"p\":\"non-rek-tih-LIN-ee-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rec.ti.lin.ear\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecuperative\",\"d\":\"Not having the ability to recover, regain strength, or restore energy; describing a process or system that cannot recoup lost resources.\",\"s\":\"The nonrecuperative furnace wasted heat by releasing it into the air instead of recycling it.\",\"p\":\"non-reh-KOO-per-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.re.cu.per.a.tive\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonrecurrence\",\"d\":\"The state or condition of something not happening again; the absence of a repeated occurrence of an event, symptom, or problem.\",\"s\":\"After treatment, the doctor was hopeful about the nonrecurrence of the infection.\",\"p\":\"non-reh-KUR-ents\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.cur.rence\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonrecurrent\",\"d\":\"Not happening repeatedly or at regular intervals; describing an event or expense that occurs only once and is not expected to happen again.\",\"s\":\"The flood was a nonrecurrent event that the town had never seen before and likely wouldn't see again.\",\"p\":\"non-reh-KUR-ent\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.cur.rent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrecyclable\",\"d\":\"Not capable of being processed and reused as a material; describing waste or products that cannot enter a recycling system.\",\"s\":\"She was frustrated to learn that the foam packaging was nonrecyclable and would go straight to the landfill.\",\"p\":\"non-ree-SY-kluh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.cy.clable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonred\",\"d\":\"Not red in color; describing anything that does not display or belong to the red part of the color spectrum.\",\"s\":\"The decorator chose nonred tones like blues and greens to create a calmer atmosphere in the room.\",\"p\":\"NON-red\",\"o\":\"Latin\",\"y\":8,\"bp\":16,\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonredacted\",\"d\":\"Not having had sensitive or confidential information removed or blacked out; describing a document or text presented in its complete, unaltered form.\",\"s\":\"The nonredacted report showed all the details that had been blacked out in the public version.\",\"p\":\"non-reh-DAK-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonredact.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonredeemed\",\"d\":\"Not exchanged for cash, goods, or a promised benefit; describing a coupon, bond, or pledge that has not yet been cashed in or fulfilled.\",\"s\":\"The nonredeemed gift cards piled up in the company's accounts as unclaimed money.\",\"p\":\"non-reh-DEEMD\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonre.deemed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreduced\",\"d\":\"Not decreased in amount, size, or degree; in chemistry, describing a substance that has not undergone reduction by gaining electrons.\",\"s\":\"The chemist noted that the nonreduced compound still had all its oxygen atoms fully intact.\",\"p\":\"non-reh-DOOST\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nonre.duced\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonreducible\",\"d\":\"Not capable of being simplified, broken down, or diminished; describing something that cannot be reduced to a simpler form or smaller quantity.\",\"s\":\"The complex equation was nonreducible and could not be simplified any further by the students.\",\"p\":\"non-reh-DOO-suh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonre.ducible\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreductional\",\"d\":\"Not involving a reduction in number or complexity; in biology, describing cell division in which the chromosome number is not halved.\",\"s\":\"The biologist explained that nonreductional cell division produces daughter cells with the same number of chromosomes as the parent.\",\"p\":\"non-reh-DUK-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonre.duc.tion.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonreductionist\",\"d\":\"A person who believes that complex systems or phenomena cannot be fully explained by reducing them to their simplest parts or a single underlying principle.\",\"s\":\"As a nonreductionist, the philosopher believed that the mind could not be fully explained by brain chemistry alone.\",\"p\":\"non-reh-DUK-shun-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"nonre.duc.tion.ist\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonreductionistic\",\"d\":\"Describing an approach or viewpoint that does not try to explain complex things by breaking them down to their simplest components or a single cause.\",\"s\":\"Her nonreductionistic approach to studying ecosystems considered all factors together rather than one at a time.\",\"p\":\"non-reh-duk-shun-IS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonre.duc.tion.is.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreduplicative\",\"d\":\"Not involving or characterized by the repetition or doubling of a word, syllable, or element; describing language or processes without duplication.\",\"s\":\"The linguist noted that the word formation was nonreduplicative, meaning no syllable was repeated for emphasis.\",\"p\":\"non-reh-DOO-plih-kuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonredu.plica.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"character\",\"wordwords\",\"olatin\"]},{\"w\":\"nonreefal\",\"d\":\"Not related to, formed by, or associated with a coral reef; describing a marine environment or sediment that is not of reef origin.\",\"s\":\"The marine biologist studied nonreefal ocean zones where corals were absent but other life thrived.\",\"p\":\"non-REE-ful\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.reefal\",\"ps\":\"adjective\",\"t\":[\"marine\",\"minerals\",\"ecology\",\"olatin\"]},{\"w\":\"nonrefereed\",\"d\":\"Not reviewed or evaluated by expert peers before publication or presentation; describing academic work that has not undergone a formal peer-review process.\",\"s\":\"She submitted her essay to a nonrefereed blog, where no expert reviewed it before publication.\",\"p\":\"non-ref-uh-REED\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ref.er.eed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreference\",\"d\":\"The quality or state of not referring to or denoting a specific person, object, or concept; the absence of a referential relationship in language or logic.\",\"s\":\"The word was used in a nonreference context, meaning it pointed to nothing specific in the real world.\",\"p\":\"non-REF-er-ents\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ref.er.ence\",\"ps\":\"noun\",\"t\":[\"logic\",\"wordwords\",\"olatin\"]},{\"w\":\"nonreferenced\",\"d\":\"Not cited, sourced, or linked to a specific reference or source material; describing a statement or data point that lacks supporting citations.\",\"s\":\"The teacher marked the essay down because its claims were nonreferenced and lacked any sources.\",\"p\":\"non-REF-er-enst\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ref.er.enced\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreferent\",\"d\":\"Something that does not point to or stand for a specific real-world object, person, or concept; a term or symbol lacking a concrete referent.\",\"s\":\"The philosopher argued that some symbols are nonreferent, pointing to nothing real in the world.\",\"p\":\"non-REF-er-ent\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ref.er.ent\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreferential\",\"d\":\"Not pointing to or standing for a specific real-world object or concept; describing language or symbols that do not refer to anything outside themselves.\",\"s\":\"The poem used nonreferential language, creating mood through sound rather than meaning.\",\"p\":\"non-ref-er-EN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ref.er.en.tial\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonreferentially\",\"d\":\"In a manner that does not point to or denote any specific real-world object or concept; used to describe how language or symbols function without external reference.\",\"s\":\"The artist used words nonreferentially, caring more about rhythm than what the words described.\",\"p\":\"non-ref-er-EN-shul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.ref.er.en.tial.ly\",\"ps\":\"adverb\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonreflecting\",\"d\":\"not capable of physical reflection\",\"s\":\"The scientists coated the telescope lens with a nonreflecting material to reduce glare.\",\"p\":\"non-reh-FLEK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.flect.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreflective\",\"d\":\"not capable of physical reflection\",\"s\":\"The nonreflective paint on the stage floor kept spotlights from bouncing into the audience's eyes.\",\"p\":\"non-reh-FLEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.flec.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreflex\",\"d\":\"A response or action that is deliberate and voluntary rather than automatic or instinctive; not driven by an involuntary reflex.\",\"s\":\"The doctor noted that the patient's response was a nonreflex action, meaning it was fully voluntary.\",\"p\":\"non-REE-fleks\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.re.flex\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreflexive\",\"d\":\"Not automatically referring back to the subject or itself; in grammar or logic, describing a relation or verb that does not loop back to the original element.\",\"s\":\"In grammar class, we learned that some verbs are nonreflexive because their action goes outward, not back to the subject.\",\"p\":\"non-reh-FLEK-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.flex.ive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"logic\",\"wordwords\",\"olatin\"]},{\"w\":\"nonreform\",\"d\":\"The absence of change or improvement in a system, institution, or policy; a failure or refusal to make reforms.\",\"s\":\"Critics accused the committee of nonreform, saying the new rules changed nothing meaningful.\",\"p\":\"non-reh-FORM\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.re.form\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonreformable\",\"d\":\"Not capable of being changed, improved, or restructured; describing a system, habit, or institution that resists or cannot undergo reform.\",\"s\":\"Some historians believe the ancient system was nonreformable and had to be completely replaced.\",\"p\":\"non-reh-FORM-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.re.formable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreformed\",\"d\":\"Not changed, improved, or restructured from a previous state; describing a system, practice, or institution that has not undergone reform.\",\"s\":\"The nonreformed policy remained unchanged despite years of public complaints.\",\"p\":\"non-reh-FORMD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.formed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreforming\",\"d\":\"Not making or seeking to make changes or improvements; describing an entity or process that does not engage in reforming actions.\",\"s\":\"The nonreforming government refused to update its outdated education laws.\",\"p\":\"non-reh-FORM-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.form.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrefracting\",\"d\":\"Not bending or deflecting light, sound, or other waves as they pass through a medium; describing a material or surface through which waves travel without changing direction.\",\"s\":\"The nonrefracting panel let light pass straight through without bending it at all.\",\"p\":\"non-reh-FRAKT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.fract.ing\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"nonrefractive\",\"d\":\"Not causing light or other waves to bend or change direction as they pass through a medium; lacking the property of refraction.\",\"s\":\"A nonrefractive window does not bend or distort the light coming through it.\",\"p\":\"non-rih-FRAK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.frac.tive\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"olatin\"]},{\"w\":\"nonrefractory\",\"d\":\"Not resistant to heat, chemical change, or treatment; easily melted, softened, or managed under high temperatures or difficult conditions.\",\"s\":\"The nonrefractory clay melted quickly in the kiln because it could not withstand extreme heat.\",\"p\":\"non-rih-FRAK-toh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.frac.to.ry\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonrefreshing\",\"d\":\"Failing to restore energy, alertness, or a sense of renewal; not providing the relief or invigoration one would expect.\",\"s\":\"After a nonrefreshing nap, she still felt tired and groggy.\",\"p\":\"non-rih-FRESH-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.fresh.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonrefrigerated\",\"d\":\"Not kept cool by mechanical refrigeration; stored or transported at room temperature rather than in a chilled environment.\",\"s\":\"The nonrefrigerated truck was not suitable for transporting dairy products on a hot summer day.\",\"p\":\"non-rih-FRIJ-er-ay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.re.frig.er.at.ed\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonrefugee\",\"d\":\"A person who has not been displaced from their home country by war, persecution, or disaster and therefore does not hold refugee status.\",\"s\":\"Authorities had to determine whether each person was a nonrefugee who had left by choice or someone fleeing danger.\",\"p\":\"non-REF-yoo-jee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.refugee\",\"ps\":\"noun\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonrefunded\",\"d\":\"Describing a payment or deposit that has not been returned to the original payer; money that was spent without being given back.\",\"s\":\"The nonrefunded ticket price disappointed the student when the concert was rescheduled.\",\"p\":\"non-rih-FUN-did\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.fund.ed\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonrefusal\",\"d\":\"The state or act of not refusing; an inability or unwillingness to decline a request or offer.\",\"s\":\"Her nonrefusal of every request meant she was constantly overwhelmed with extra work.\",\"p\":\"non-rih-FYOO-zul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.re.fusal\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonregardance\",\"d\":\"A complete lack of attention, consideration, or respect toward something or someone; the state of paying no regard whatsoever.\",\"s\":\"His nonregardance of traffic rules made him a danger to other drivers.\",\"p\":\"non-rih-GAR-duns\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.gar.dance\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonregenerative\",\"d\":\"Unable to regrow, renew, or restore lost or damaged tissue, cells, or components; lacking the capacity for self-repair or regeneration.\",\"s\":\"Unlike lizards, humans have nonregenerative limbs, meaning we cannot grow back lost fingers.\",\"p\":\"non-rih-JEN-er-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.re.gen.er.a.tive\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonregent\",\"d\":\"A person who does not hold the position of regent and therefore has no authority to rule or govern on behalf of a monarch.\",\"s\":\"As a nonregent member of the board, she could advise but not make final decisions.\",\"p\":\"non-REE-junt\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.re.gent\",\"ps\":\"noun\",\"t\":[\"poetry\",\"politics\",\"royalty\",\"olatin\"]},{\"w\":\"nonregimental\",\"d\":\"Not organized according to the strict, formal structure of a military regiment; free from rigid rules, ranks, or disciplined order.\",\"s\":\"The summer camp had a nonregimental schedule, letting kids choose their own activities each day.\",\"p\":\"non-rej-ih-MEN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.reg.i.men.tal\",\"ps\":\"adjective\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonregional\",\"d\":\"Not limited to or characteristic of any particular geographic region; applying broadly across many areas rather than one specific locality.\",\"s\":\"The radio host spoke in a nonregional accent so listeners from any state could easily understand her.\",\"p\":\"non-REE-jun-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.gion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonregioselective\",\"d\":\"Describing a chemical reaction that does not preferentially occur at one specific location on a molecule over another; showing no preference for a particular site.\",\"s\":\"The nonregioselective reaction produced a mixture of products instead of targeting one specific site.\",\"p\":\"non-ree-jee-oh-sih-LEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.re.gios.e.lec.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonregister\",\"d\":\"Something that falls outside the recognized ranges or categories of a formal system, especially outside the standard vocal registers used in singing or speaking.\",\"s\":\"The choir director scolded the student for singing in a nonregister that clashed with the harmony.\",\"p\":\"non-REJ-ih-ster\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.reg.is.ter\",\"ps\":\"noun\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonregisterable\",\"d\":\"Not capable of being officially recorded, enrolled, or entered into a formal registry or database under existing rules.\",\"s\":\"The unofficial club was nonregisterable under the school's new charter rules.\",\"p\":\"non-REJ-ih-ster-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.reg.is.ter.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonregistered\",\"d\":\"Not officially recorded, enrolled, or recognized by a government body, institution, or formal registry; lacking official registration status.\",\"s\":\"The nonregistered vehicle was ticketed for driving on public roads without proper paperwork.\",\"p\":\"non-REJ-ih-sterd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.reg.is.tered\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonregistrable\",\"d\":\"Incapable of being registered or formally recorded; not meeting the legal or institutional requirements needed for official enrollment.\",\"s\":\"The ancient land claim was deemed nonregistrable because it lacked the required legal documents.\",\"p\":\"non-REJ-ih-struh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.reg.is.tra.ble\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonregular\",\"d\":\"Not following a fixed, consistent, or standard pattern; occurring irregularly or outside the normal schedule or set of rules.\",\"s\":\"As a nonregular volunteer, she only helped out during the school's biggest events.\",\"p\":\"non-REG-yoo-ler\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.reg.u.lar\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonregularity\",\"d\":\"The quality or state of lacking a consistent pattern, schedule, or uniformity; the condition of being irregular or unpredictable.\",\"s\":\"The scientist noted the nonregularity of the heartbeat pattern and ordered more tests.\",\"p\":\"non-reg-yoo-LAIR-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.reg.u.lar.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonregularizable\",\"d\":\"Describing something that cannot be made regular, uniform, or consistent through any mathematical or procedural process.\",\"s\":\"The mathematician proved the function was nonregularizable under standard conditions.\",\"p\":\"non-REG-yoo-ler-eye-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.reg.u.lar.iz.able\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonregularized\",\"d\":\"Not having been made uniform, standardized, or smoothed out; still containing irregular, inconsistent, or raw elements.\",\"s\":\"The nonregularized data set caused errors in the computer model's predictions.\",\"p\":\"non-REG-yoo-ler-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.reg.u.lar.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonregulation\",\"d\":\"Not conforming to the official rules, standards, or specifications required by an authority; outside of or contrary to established regulations.\",\"s\":\"The referee flagged the player's nonregulation equipment before the game could begin.\",\"p\":\"non-reg-yoo-LAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.reg.u.la.tion\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonrehydrated\",\"d\":\"Not having had water or moisture added back after drying; remaining in a dried or dehydrated state without being reconstituted.\",\"s\":\"The nonrehydrated food powder was too stiff and crumbly to eat without adding water first.\",\"p\":\"non-ree-HY-dray-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.hy.drat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreimbursable\",\"d\":\"Describing an expense or cost that will not be paid back or repaid by another party, such as an employer or insurance provider.\",\"s\":\"The travel agent warned that the hotel deposit was nonreimbursable if we canceled last minute.\",\"p\":\"non-ree-im-BER-suh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.im.bursable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreinforced\",\"d\":\"Not strengthened, supported, or supplemented by additional material, training, or rewards; lacking any added reinforcement.\",\"s\":\"The nonreinforced concrete wall cracked under pressure because it had no steel rods inside.\",\"p\":\"non-ree-in-FORST\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.in.forced\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonreinforcement\",\"d\":\"The absence of any reward, support, or strengthening response following a behavior or action, especially in psychology or structural engineering.\",\"s\":\"In psychology class, we learned that nonreinforcement of a behavior can cause it to fade away over time.\",\"p\":\"non-ree-in-FORS-munt\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.in.force.ment\",\"ps\":\"noun\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonreinstated\",\"d\":\"Describing someone or something that has not been restored to a former position, status, or condition after being removed or suspended.\",\"s\":\"The nonreinstated employee was surprised to find her badge still deactivated after the appeal.\",\"p\":\"non-ree-in-STAY-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.in.stat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrejected\",\"d\":\"Not having been turned down, dismissed, or refused; still accepted or under consideration rather than being cast aside.\",\"s\":\"The nonrejected application moved forward to the next round of review.\",\"p\":\"non-rih-JEK-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.ject.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrejection\",\"d\":\"The absence of a refusal or dismissal; the state of accepting rather than turning something or someone away.\",\"s\":\"The committee's nonrejection of the proposal surprised everyone who expected a veto.\",\"p\":\"non-rih-JEK-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.jec.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrelatable\",\"d\":\"Impossible to connect with on a personal or emotional level; difficult to understand or identify with based on one's own experiences.\",\"s\":\"The character's alien lifestyle made her completely nonrelatable to most readers.\",\"p\":\"non-rih-LAY-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.lat.able\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonrelated\",\"d\":\"Having no connection, association, or family tie to another person or thing; completely unrelated by blood, subject matter, or cause.\",\"s\":\"The two incidents were nonrelated, so the police handled them separately.\",\"p\":\"non-rih-LAY-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.re.lat.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"kinship\",\"olatin\"]},{\"w\":\"nonrelatedness\",\"d\":\"The condition of having no connection, kinship, or shared qualities with another person, organism, or concept.\",\"s\":\"The nonrelatedness of the two species surprised the biologists studying them.\",\"p\":\"non-rih-LAY-tid-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.lat.ed.ness\",\"ps\":\"noun\",\"t\":[\"kinship\",\"olatin\"]},{\"w\":\"nonrelational\",\"d\":\"Not involving or based on relationships between entities; in computing, describing a database that does not use structured tables linked by common fields.\",\"s\":\"The nonrelational database stored data differently than traditional table-based systems.\",\"p\":\"non-rih-LAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.la.tion.al\",\"ps\":\"adjective\",\"t\":[\"household\",\"olatin\"]},{\"w\":\"nonrelationship\",\"d\":\"The absence of any meaningful personal, social, or professional bond between two or more people; a connection that is too weak or undefined to be called a relationship.\",\"s\":\"Their awkward nonrelationship made every group project uncomfortable.\",\"p\":\"non-rih-LAY-shun-ship\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.la.tion.ship\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrelativistically\",\"d\":\"In a manner that does not take into account the effects described by Einstein's theory of relativity, typically because speeds or energies involved are too low for relativistic effects to matter.\",\"s\":\"The slow-moving object behaved nonrelativistically, obeying simple Newtonian laws.\",\"p\":\"non-rel-uh-tih-VIS-tik-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.rel.a.tivis.ti.cal.ly\",\"ps\":\"adverb\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonrelaxation\",\"d\":\"The absence of a loosening, easing, or release of tension in muscles, rules, or other systems; a failure to achieve a more relaxed state.\",\"s\":\"The athlete's nonrelaxation of muscles led to soreness after the competition.\",\"p\":\"non-ree-lak-SAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.lax.ation\",\"ps\":\"noun\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonrelaxed\",\"d\":\"Not in a state of calm, ease, or reduced tension; remaining tense, stiff, or stressed rather than being at rest.\",\"s\":\"The nonrelaxed student kept tapping her pencil nervously throughout the test.\",\"p\":\"non-rih-LAKST\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.re.laxed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrelaxing\",\"d\":\"Not producing or promoting a feeling of calm or ease; tending to maintain or increase tension rather than reduce it.\",\"s\":\"The chaotic holiday gathering was completely nonrelaxing for the shy teenager.\",\"p\":\"non-rih-LAK-sing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.lax.ing\",\"ps\":\"adjective\",\"t\":[\"character\",\"emotions\",\"olatin\"]},{\"w\":\"nonreleasable\",\"d\":\"Not permitted or able to be freed, published, distributed, or made available to others due to legal, safety, or policy restrictions.\",\"s\":\"The classified documents were deemed nonreleasable to the public for security reasons.\",\"p\":\"non-rih-LEE-suh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.re.leasable\",\"ps\":\"adjective\",\"t\":[\"law\",\"politics\",\"olatin\"]},{\"w\":\"nonrelevance\",\"d\":\"The quality of having no connection to or bearing on the subject at hand; the state of being unimportant or inapplicable to the current situation.\",\"s\":\"The judge dismissed the evidence due to its nonrelevance to the case.\",\"p\":\"non-REL-ih-vuns\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.rel.e.vance\",\"ps\":\"noun\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonrelevant\",\"d\":\"Not related or connected to the subject or matter being discussed; lacking pertinence or applicability.\",\"s\":\"His comment about the weather was nonrelevant during the science debate.\",\"p\":\"non-REL-eh-vunt\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.rel.e.vant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreliability\",\"d\":\"The quality or state of being untrustworthy or unable to be depended upon consistently.\",\"s\":\"The old car's nonreliability made every long trip a gamble.\",\"p\":\"non-reh-ly-uh-BIL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.re.li.a.bil.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreliable\",\"d\":\"Not able to be trusted or counted on to perform consistently or as expected.\",\"s\":\"A nonreliable narrator makes readers question every detail of the story.\",\"p\":\"non-reh-LY-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.re.li.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreligion\",\"d\":\"The absence of religious belief, practice, or affiliation; the state of having no religious faith.\",\"s\":\"The survey asked participants to describe their nonreligion and personal belief system.\",\"p\":\"non-reh-LIJ-un\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.li.gion\",\"ps\":\"noun\",\"t\":[\"religion\",\"logic\",\"olatin\"]},{\"w\":\"nonreloadable\",\"d\":\"Not capable of being refilled or loaded again after initial use.\",\"s\":\"The single-use cartridge was nonreloadable and had to be discarded after use.\",\"p\":\"non-ree-LOH-duh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.reload.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrelocatable\",\"d\":\"Unable to be moved or transferred to a different location or position.\",\"s\":\"The massive stone monument was nonrelocatable without destroying it completely.\",\"p\":\"non-ree-LOH-kuh-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.lo.cat.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrelocated\",\"d\":\"Not having been moved or transferred to a new place or position.\",\"s\":\"The nonrelocated families stayed in the flood zone despite the government's warnings.\",\"p\":\"non-ree-LOH-kay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.re.lo.cat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrelocating\",\"d\":\"Not in the process of moving or transferring to a different location.\",\"s\":\"The nonrelocating employees worked remotely rather than move to the new city.\",\"p\":\"non-ree-LOH-kay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.lo.cat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonremarkable\",\"d\":\"Not worthy of special attention or comment; ordinary and unremarkable in every way.\",\"s\":\"The film was nonremarkable, forgettable before the credits even finished rolling.\",\"p\":\"non-reh-MAR-kuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.mark.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonremedial\",\"d\":\"Not intended or designed to correct a deficiency or provide extra help for struggling students.\",\"s\":\"The advanced class was nonremedial, designed for students already excelling in math.\",\"p\":\"non-reh-MEE-dee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.me.di.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonremethylatable\",\"d\":\"In biochemistry, describing a molecule or site that cannot have methyl chemical groups reattached to it after they have been removed.\",\"s\":\"Scientists discovered that the nonremethylatable gene region could not regain its chemical tags.\",\"p\":\"non-ree-METH-ih-lay-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.remethy.lat.able\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonremote\",\"d\":\"Not distant or far away; situated close by or easily accessible.\",\"s\":\"The cabin was in a nonremote area, just a short drive from the nearest town.\",\"p\":\"non-reh-MOHT\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.mote\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonremovable\",\"d\":\"Not capable of being taken away, detached, or eliminated from its current position.\",\"s\":\"The nonremovable stain on his shirt ruined the garment permanently.\",\"p\":\"non-reh-MOO-vuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.mov.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonremoved\",\"d\":\"Not having been taken away, eliminated, or separated from its original place.\",\"s\":\"The nonremoved debris blocked the drain and caused the yard to flood.\",\"p\":\"non-reh-MOOVD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.re.moved\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrendition\",\"d\":\"The failure or refusal to perform, deliver, or hand over something that is expected or required.\",\"s\":\"The musician's nonrendition of the final piece left the audience confused about the program.\",\"p\":\"non-ren-DIH-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ren.di.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrenewal\",\"d\":\"The act or fact of not renewing a contract, subscription, license, or agreement when it expires.\",\"s\":\"The tenant received a nonrenewal notice and had to find a new apartment.\",\"p\":\"non-reh-NOO-ul\",\"o\":\"Latin\",\"y\":7,\"bp\":30,\"sy\":\"non.re.new.al\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonrenewed\",\"d\":\"Not having been extended, refreshed, or continued beyond an original expiration date.\",\"s\":\"Her nonrenewed library card meant she couldn't check out any more books.\",\"p\":\"non-reh-NOOD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.re.newed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrenewer\",\"d\":\"A person or entity that chooses not to renew a contract, membership, or subscription.\",\"s\":\"As a nonrenewer, he let his gym membership lapse at the end of the year.\",\"p\":\"non-reh-NOO-er\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.re.new.er\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonrenewing\",\"d\":\"Not in the process of extending, refreshing, or continuing something beyond its current term.\",\"s\":\"The nonrenewing lease meant the business had to find a different location.\",\"p\":\"non-reh-NOO-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.new.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrenormalisable\",\"d\":\"In physics, describing a theory whose infinities cannot be removed through the mathematical process of renormalisation, making it theoretically incomplete.\",\"s\":\"The physicist explained that the nonrenormalisable theory produced infinite values that couldn't be corrected.\",\"p\":\"non-ree-NOR-muh-ly-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.renor.mal.is.able\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"nonrenormalizable\",\"d\":\"In physics, describing a theory in which divergent infinities cannot be systematically eliminated through the renormalization process, rendering precise calculations impossible.\",\"s\":\"Gravity's nonrenormalizable nature is one reason quantum gravity remains unsolved.\",\"p\":\"non-ree-NOR-muh-ly-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.renor.mal.iz.able\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"olatin\"]},{\"w\":\"nonrenormalized\",\"d\":\"Describing a physical theory or equation that has not undergone the mathematical process of renormalization to remove infinities.\",\"s\":\"The nonrenormalized calculation gave an absurd infinite result that physicists couldn't use.\",\"p\":\"non-ree-NOR-muh-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.renor.mal.ized\",\"ps\":\"adjective\",\"t\":[\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"nonrenovated\",\"d\":\"Not having been restored, updated, or improved from a worn or outdated condition.\",\"s\":\"The nonrenovated wing of the school still had desks from the 1970s.\",\"p\":\"non-REN-oh-vay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.ren.o.vat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrentable\",\"d\":\"Not suitable or available to be rented out in exchange for payment.\",\"s\":\"The flooded basement made the apartment nonrentable until repairs were completed.\",\"p\":\"non-RENT-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.rentable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrental\",\"d\":\"Not involving or related to the payment of rent; describing property or arrangements that are owned outright rather than leased.\",\"s\":\"The nonrental property was owned outright and never leased to tenants.\",\"p\":\"non-RENT-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.rental\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepairable\",\"d\":\"Not capable of being fixed or restored to working condition once damaged or broken.\",\"s\":\"The mechanic declared the engine nonrepairable and recommended buying a new car.\",\"p\":\"non-reh-PAIR-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.re.pairable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepaired\",\"d\":\"Not having been fixed or restored after damage or malfunction occurred.\",\"s\":\"The nonrepaired pothole caused several flat tires on the busy street.\",\"p\":\"non-reh-PAIRD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.re.paired\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepayable\",\"d\":\"Not required or able to be paid back; describing a debt, grant, or loan that does not need to be returned.\",\"s\":\"The charity provided nonrepayable grants to families who lost their homes in the flood.\",\"p\":\"non-reh-PAY-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.re.payable\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonrepeat\",\"d\":\"Something that does not occur again or is designed to happen only once without being duplicated.\",\"s\":\"The DJ promised a nonrepeat playlist so every song at the party would be fresh.\",\"p\":\"non-reh-PEET\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.re.peat\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrepeatable\",\"d\":\"Not able to be done, produced, or experienced again in exactly the same way a second time.\",\"s\":\"Scientists were frustrated that the experiment produced nonrepeatable results each time they tried it.\",\"p\":\"non-reh-PEET-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.peat.able\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonrepellent\",\"d\":\"Not having the quality of driving away or deterring insects, animals, or other unwanted things.\",\"s\":\"The new fabric softener was nonrepellent, meaning it attracted pet hair instead of pushing it away.\",\"p\":\"non-reh-PEL-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.pel.lent\",\"ps\":\"adjective\",\"t\":[\"animals\",\"insects\",\"olatin\"]},{\"w\":\"nonrepetitious\",\"d\":\"Not characterized by unnecessary or tiresome repetition; fresh and varied in content or delivery.\",\"s\":\"Her nonrepetitious speech kept the audience engaged from beginning to end.\",\"p\":\"non-rep-eh-TIH-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rep.e.ti.tious\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonrepetitive\",\"d\":\"marked by the absence of repetition\",\"p\":\"non-reh-PET-ih-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.repet.i.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepetitively\",\"d\":\"In a manner that does not involve unnecessary repetition; with variety and freshness rather than doing or saying the same thing over and over.\",\"s\":\"The author wrote nonrepetitively, ensuring each chapter introduced entirely new ideas.\",\"p\":\"non-reh-PET-ih-tiv-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.repet.i.tive.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonreplicable\",\"d\":\"Not able to be copied, reproduced, or duplicated in another setting or experiment.\",\"s\":\"The unique handmade vase was nonreplicable because the artist never recorded his technique.\",\"p\":\"non-REP-lih-kuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.repli.ca.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreplicated\",\"d\":\"Not having been copied, reproduced, or duplicated; describing an experiment or process that has occurred only once.\",\"s\":\"The nonreplicated study raised doubts among scientists who wanted stronger proof.\",\"p\":\"non-REP-lih-kay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.repli.cat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreplicating\",\"d\":\"Not in the process of making copies of itself, especially referring to a virus or cell that cannot reproduce or duplicate its genetic material.\",\"s\":\"The lab used a nonreplicating virus in the vaccine so patients wouldn't get sick.\",\"p\":\"non-REP-lih-kay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.repli.cat.ing\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonreplication\",\"d\":\"The state or process of failing or being unable to copy, reproduce, or duplicate something, such as a scientific experiment or biological material.\",\"s\":\"The nonreplication of the experiment's results made scientists question the original findings.\",\"p\":\"non-rep-lih-KAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.repli.ca.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreplicative\",\"d\":\"Not having the ability or tendency to make copies of itself; describing biological entities or processes that do not reproduce by duplication.\",\"s\":\"Doctors preferred the nonreplicative vaccine because it posed less risk to patients with weak immune systems.\",\"p\":\"non-REP-lih-kuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.replica.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreplier\",\"d\":\"A person who does not respond to a message, survey, invitation, or communication after receiving it.\",\"s\":\"The teacher marked him as a nonreplier after he ignored three emails about the missing homework.\",\"p\":\"non-reh-PLY-er\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.repli.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreply\",\"d\":\"The state or act of not replying; a failure or refusal to respond to a message or communication.\",\"s\":\"Her nonreply to the party invitation left the host unsure how many seats to prepare.\",\"p\":\"non-rih-PLY\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.re.ply\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreplying\",\"d\":\"Not replying or failing to respond to a message, question, or communication.\",\"s\":\"The nonreplying student frustrated his group partners who needed answers before the deadline.\",\"p\":\"non-rih-PLY-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.ply.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreportable\",\"d\":\"Not required or able to be reported; describing information or incidents that do not need to be formally documented or disclosed.\",\"s\":\"Minor scrapes at recess are considered nonreportable incidents at most schools.\",\"p\":\"non-rih-POR-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.re.portable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreporting\",\"d\":\"Not reporting or failing to submit required reports; describing an entity or individual that does not provide formal accounts of information.\",\"s\":\"The nonreporting employee forgot to submit his weekly update to the manager.\",\"p\":\"non-rih-POR-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.port.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepresentable\",\"d\":\"Not capable of being represented, depicted, or expressed in a symbolic or visual form.\",\"s\":\"The strange alien landscape the author described was so bizarre it was almost nonrepresentable in a painting.\",\"p\":\"non-rep-rih-ZEN-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rep.re.sentable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepresentational\",\"d\":\"of or relating to a style of art in which objects do not resemble those known in physical nature\",\"s\":\"The museum's newest wing featured nonrepresentational art made entirely of swirling colors and shapes.\",\"p\":\"non-rep-rih-zen-TAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.rep.re.sen.ta.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepresentative\",\"d\":\"not typical of the larger group it is supposed to stand for\",\"s\":\"The survey used a nonrepresentative sample, so its results couldn't apply to the whole school.\",\"p\":\"non-rep-rih-ZEN-tuh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.rep.re.sen.ta.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepresented\",\"d\":\"Not having representation; describing a group or individual whose views or interests are not presented or advocated on their behalf.\",\"s\":\"Many small community groups felt nonrepresented in the city council's final decision.\",\"p\":\"non-rep-rih-ZEN-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rep.re.sent.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrepressive\",\"d\":\"Not repressive; describing a system, policy, or authority that does not suppress or restrict the freedom of individuals.\",\"s\":\"The school adopted a nonrepressive approach that encouraged students to express their opinions freely.\",\"p\":\"non-rih-PRES-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.pres.sive\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"politics\",\"olatin\"]},{\"w\":\"nonreproduced\",\"d\":\"Not reproduced or copied; describing material that has not been duplicated or replicated from an original source.\",\"s\":\"The ancient manuscript remained nonreproduced for centuries because it was considered too fragile to copy.\",\"p\":\"non-ree-pruh-DOOST\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.pro.duced\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreproducible\",\"d\":\"Not capable of being reproduced, duplicated, or replicated; describing results or items that cannot be repeated under the same conditions.\",\"s\":\"The scientist's stunning crystal was nonreproducible because the conditions that formed it were so rare.\",\"p\":\"non-ree-pruh-DOO-suh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.pro.ducible\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreproducing\",\"d\":\"Not reproducing or generating new copies, offspring, or replications of itself.\",\"s\":\"Worker bees are nonreproducing members of the hive, leaving all egg-laying to the queen.\",\"p\":\"non-ree-pruh-DOO-sing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.pro.duc.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreproduction\",\"d\":\"The absence or failure of reproduction; the state of not producing offspring or copies.\",\"s\":\"The species' nonreproduction in captivity puzzled zoologists for many years.\",\"p\":\"non-ree-pruh-DUK-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.pro.duc.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreproductive\",\"d\":\"Not relating to or capable of reproduction; describing organisms, cells, or processes that do not produce offspring or new copies.\",\"s\":\"The plant's nonreproductive stems were used only for absorbing sunlight, not creating seeds.\",\"p\":\"non-ree-pruh-DUK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.pro.duc.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreptile\",\"d\":\"An animal that is not a reptile; any creature that does not belong to the class Reptilia.\",\"s\":\"A frog is a nonreptile amphibian, even though it's often confused with lizards.\",\"p\":\"non-REP-tyl\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rep.tile\",\"ps\":\"noun\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonreptilian\",\"d\":\"Not belonging to or characteristic of reptiles; describing animals or traits that are not associated with the class Reptilia.\",\"s\":\"The biology teacher sorted the class's toy animals into reptilian and nonreptilian groups.\",\"p\":\"non-rep-TIL-ee-un\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.rep.til.ian\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonrepublic\",\"d\":\"A nation or state that is not organized as a republic; a country whose government is not based on elected representatives of the people.\",\"s\":\"A monarchy is a nonrepublic because the head of state is a king or queen, not an elected president.\",\"p\":\"non-rih-PUB-lik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.pub.lic\",\"ps\":\"noun\",\"t\":[\"nations\",\"politics\",\"olatin\"]},{\"w\":\"nonrepulsive\",\"d\":\"Not repulsive or disgusting; describing something that does not cause feelings of strong aversion or disgust.\",\"s\":\"The new classroom décor was cheerfully nonrepulsive, making students feel welcome instead of uncomfortable.\",\"p\":\"non-rih-PUL-siv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.pul.sive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrequested\",\"d\":\"Not asked for or solicited; describing something that was provided or occurred without being specifically requested.\",\"s\":\"The teacher handed back nonrequested feedback on every student's essay.\",\"p\":\"non-rih-KWES-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.quest.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrequired\",\"d\":\"Not mandatory or obligatory; describing something that is optional and not demanded by rules or authority.\",\"s\":\"Reading the extra novel was nonrequired but highly recommended by the English teacher.\",\"p\":\"non-rih-KWYRD\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.re.quired\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonrequirement\",\"d\":\"Something that is not a requirement; a condition or item that is not obligatory or necessary.\",\"s\":\"Wearing a uniform was listed as a nonrequirement at the new arts school.\",\"p\":\"non-rih-KWYR-munt\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.re.quire.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonresealable\",\"d\":\"Not able to be sealed again after being opened; describing packaging that cannot be closed back up once it has been unsealed.\",\"s\":\"Once you tear open a nonresealable bag of chips, you need a clip to keep them fresh.\",\"p\":\"non-ree-SEE-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.seal.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresearch\",\"d\":\"Not involving or related to formal research; describing activities, roles, or tasks that do not include systematic investigation or study.\",\"s\":\"Her nonresearch job at the hospital involved patient care rather than laboratory experiments.\",\"p\":\"non-rih-SURCH\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.re.search\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonresearcher\",\"d\":\"A person who does not conduct research; someone whose professional role does not involve systematic investigation or scholarly inquiry.\",\"s\":\"As a nonresearcher, the nurse focused on treating patients rather than running experiments.\",\"p\":\"non-rih-SUR-chur\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.re.searcher\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonresectional\",\"d\":\"Not involving surgical resection; describing a medical procedure or approach that does not require the cutting out or removal of tissue or an organ.\",\"s\":\"The surgeon chose a nonresectional procedure that treated the tumor without cutting any tissue away.\",\"p\":\"non-rih-SEK-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.sec.tion.al\",\"ps\":\"adjective\",\"t\":[\"body\",\"music\",\"olatin\"]},{\"w\":\"nonresemblance\",\"d\":\"The absence of resemblance or similarity; the state of not looking like or bearing any likeness to something else.\",\"s\":\"The twins' nonresemblance was striking — one was tall with curly hair, the other short with straight hair.\",\"p\":\"non-rih-ZEM-bluns\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.re.sem.blance\",\"ps\":\"noun\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonreservation\",\"d\":\"A situation or policy in which no reservation is required; also, land that is not designated as a Native American reservation.\",\"s\":\"The restaurant had a nonreservation policy, meaning every table was first-come, first-served.\",\"p\":\"non-rez-ur-VAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.reser.va.tion\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonreserve\",\"d\":\"Not set aside or held in reserve; describing funds, resources, or land that have not been designated for a specific purpose or future use.\",\"s\":\"The nonreserve land was open to anyone who wanted to camp there.\",\"p\":\"non-rih-ZURV\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.serve\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreserved\",\"d\":\"Not reserved or set apart for a specific person or purpose; describing seats, resources, or areas that are available to anyone.\",\"s\":\"The nonreserved seats filled up quickly once the doors opened.\",\"p\":\"non-rih-ZURVD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.served\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresidence\",\"d\":\"The state of not living in a particular place; the condition of not being a resident in a specific location, country, or institution.\",\"s\":\"His nonresidence in the district made him ineligible to vote in the local election.\",\"p\":\"non-REZ-ih-dens\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.res.i.dence\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonresidency\",\"d\":\"The status of not being an official resident; the condition of living or working outside the place where one is formally registered or enrolled.\",\"s\":\"The university noted her nonresidency status and charged out-of-state tuition.\",\"p\":\"non-REZ-ih-den-see\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.res.i.den.cy\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonresilient\",\"d\":\"not resilient\",\"s\":\"The nonresilient plastic cracked under pressure instead of bouncing back.\",\"p\":\"non-rih-ZIL-yunt\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.re.silient\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresin\",\"d\":\"A substance or material that does not contain or consist of resin; anything that lacks the sticky, hardened properties characteristic of natural or synthetic resins.\",\"s\":\"The scientist labeled the substance as a nonresin because it lacked sticky, sap-like properties.\",\"p\":\"non-REZ-in\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.resin\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonresinous\",\"d\":\"not having resin\",\"s\":\"The nonresinous wood dried out quickly and didn't leave any sticky residue.\",\"p\":\"non-REZ-in-us\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.resinous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresister\",\"d\":\"A person who does not resist or oppose authority, force, or oppression; someone who practices nonresistance as a principle.\",\"s\":\"As a nonresister, she accepted the new rules without argument.\",\"p\":\"non-rih-ZIS-tur\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.sister\",\"ps\":\"noun\",\"t\":[\"physics\",\"poetry\",\"logic\",\"olatin\"]},{\"w\":\"nonresisting\",\"d\":\"Not resisting or offering opposition; accepting force, authority, or circumstances without struggle or protest.\",\"s\":\"The nonresisting crowd quietly followed the officer's instructions.\",\"p\":\"non-rih-ZIS-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.sist.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"poetry\",\"olatin\"]},{\"w\":\"nonresistor\",\"d\":\"A component or material that does not act as a resistor; something that does not impede or restrict the flow of electrical current.\",\"s\":\"In the circuit diagram, the component was labeled a nonresistor because it conducted electricity freely.\",\"p\":\"non-rih-ZIS-tur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.sis.tor\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonresizable\",\"d\":\"Not capable of being resized or adjusted in dimensions; describing an image, window, or object whose size is fixed and cannot be changed.\",\"s\":\"The nonresizable window on the app frustrated users who wanted a larger view.\",\"p\":\"non-rih-SY-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.siz.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresolved\",\"d\":\"Not resolved or settled; describing a problem, conflict, or issue that remains unanswered or without a solution.\",\"s\":\"The nonresolved conflict between the two classmates made the teacher uncomfortable.\",\"p\":\"non-rih-ZOLVD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.solved\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresonantly\",\"d\":\"In a manner that is not resonant; without producing or exhibiting a full, deep, or echoing sound or quality.\",\"s\":\"The note was played nonresonantly, producing a flat, hollow sound.\",\"p\":\"non-REZ-uh-nunt-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.res.o.nant.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonresorptive\",\"d\":\"Not relating to or causing resorption, the process by which the body absorbs or breaks down its own tissue or substances.\",\"s\":\"The nonresorptive material did not break down or absorb back into the surrounding tissue.\",\"p\":\"nahn-rih-SORP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.sorp.tive\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonrespectable\",\"d\":\"Not worthy of respect or social regard; failing to meet the standards that would make someone or something deserving of esteem.\",\"s\":\"The judge called the behavior nonrespectable and unworthy of the courtroom.\",\"p\":\"nahn-rih-SPEK-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.spectable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrespectful\",\"d\":\"Lacking respect or courtesy toward others; showing a failure to treat people or things with proper regard.\",\"s\":\"The nonrespectful tone in his email offended his entire team.\",\"p\":\"nahn-rih-SPEKT-ful\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.spect.ful\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrespiratory\",\"d\":\"Not relating to or involved in the process of breathing or the exchange of gases in living organisms.\",\"s\":\"The doctor noted that the patient's problem was nonrespiratory and unrelated to the lungs.\",\"p\":\"nahn-reh-SPY-ruh-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.res.pi.ra.to.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrespondent\",\"d\":\"A person or entity that does not respond, especially one who fails to reply to a survey, questionnaire, or legal summons.\",\"s\":\"Each nonrespondent in the survey was sent a follow-up email asking for their feedback.\",\"p\":\"nahn-rih-SPAHN-dunt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.spon.dent\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonresponse\",\"d\":\"A failure or refusal to give a reply or reaction, especially in the context of surveys or studies where a response is expected.\",\"s\":\"The survey team was concerned about the high rate of nonresponse from older participants.\",\"p\":\"nahn-rih-SPAHNS\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.sponse\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonresponsibility\",\"d\":\"The state or condition of lacking responsibility or accountability for one's actions or duties.\",\"s\":\"The company claimed nonresponsibility for any damage caused by misuse of the product.\",\"p\":\"nahn-rih-spahn-suh-BIL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.re.spon.si.bil.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonresponsible\",\"d\":\"Not accountable or answerable for one's actions; lacking the obligation or ability to be held responsible.\",\"s\":\"The contract stated that the landlord was nonresponsible for items left in the hallway.\",\"p\":\"nahn-rih-SPAHN-suh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.spon.si.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresponsive\",\"d\":\"Not reacting or replying to a stimulus, question, or request; failing to show a response when one is expected.\",\"s\":\"The patient was nonresponsive after the accident, so paramedics acted quickly.\",\"p\":\"nah-nrih-SPAH-nsih-v\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"naa.nrih.spaa.nsih.v\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrestaurant\",\"d\":\"Not functioning as or related to a restaurant; describing a setting or establishment that does not serve food to the public in the manner of a restaurant.\",\"s\":\"The food truck operated as a nonrestaurant vendor at the outdoor market.\",\"p\":\"nahn-RES-tuh-rahnt\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.restau.rant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresting\",\"d\":\"Not in a state of rest; continuously active or in motion rather than pausing or stopping.\",\"s\":\"The nonresting cell was constantly dividing and growing throughout the experiment.\",\"p\":\"nahn-REST-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.rest.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrestorable\",\"d\":\"Not capable of being brought back to its original condition or repaired; impossible to restore.\",\"s\":\"The ancient vase was deemed nonrestorable after it shattered into hundreds of tiny pieces.\",\"p\":\"nahn-rih-STOR-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"non.restorable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrestrained\",\"d\":\"Not held back, limited, or controlled by force or rules; free from restraint or constraint.\",\"s\":\"The nonrestrained puppy raced wildly around the yard, knocking over the flowerpots.\",\"p\":\"nahn-rih-STRAYND\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.re.strained\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonrestraining\",\"d\":\"Not acting to hold back, limit, or control someone or something; failing or refusing to impose restraint.\",\"s\":\"The nonrestraining approach to classroom management gave students more freedom.\",\"p\":\"nahn-rih-STRAYN-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.re.strain.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrestricted\",\"d\":\"Not subject to limitations, rules, or conditions that would limit access or use; open and unrestricted.\",\"s\":\"The nonrestricted area of the park was available to all visitors at any hour.\",\"p\":\"nah-nrih-STRIH-ktuh-d\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"naa.nrih.strih.ktah.d\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonresumptive\",\"d\":\"Not involving or characterized by resumption; not picking up again after a pause or interruption.\",\"s\":\"The nonresumptive clause in the contract meant the agreement could not restart after it ended.\",\"p\":\"nahn-rih-ZUMP-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.sump.tive\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonresurgent\",\"d\":\"Not experiencing or showing a revival, renewal, or return to strength after a period of decline.\",\"s\":\"Scientists were relieved that the virus appeared nonresurgent after the treatment.\",\"p\":\"nahn-rih-SUR-junt\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.resur.gent\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretail\",\"d\":\"Not involving the sale of goods directly to consumers; relating to wholesale, institutional, or other non-consumer channels of commerce.\",\"s\":\"The warehouse sold goods at nonretail prices directly to businesses.\",\"p\":\"nahn-REE-tayl\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.re.tail\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonretailer\",\"d\":\"A business or person that does not sell goods directly to consumers, such as a wholesaler or distributor.\",\"s\":\"As a nonretailer, the company sold its products only through distributors.\",\"p\":\"nahn-REE-tay-lur\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.re.tail.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonretailing\",\"d\":\"Not engaged in the practice of selling goods or products directly to the general public or end consumers.\",\"s\":\"The nonretailing business model focused on wholesale distribution rather than consumer sales.\",\"p\":\"nahn-REE-tay-ling\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.tail.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretaliatory\",\"d\":\"Not involving retaliation or revenge; describing actions or policies that do not seek to pay back harm with harm.\",\"s\":\"The country issued a nonretaliatory statement, promising not to respond with force.\",\"p\":\"nahn-rih-TAL-ee-uh-tor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.re.tal.ia.to.ry\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonretentive\",\"d\":\"Not capable of retaining or holding onto things, such as memories, moisture, or other substances.\",\"s\":\"The nonretentive soil let water drain through so fast that the plants couldn't absorb it.\",\"p\":\"nahn-rih-TEN-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.ten.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretinal\",\"d\":\"Not relating to or involving the retina, the light-sensitive layer of tissue at the back of the eye.\",\"s\":\"The eye doctor confirmed the problem was nonretinal and came from the optic nerve instead.\",\"p\":\"nahn-RET-ih-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.reti.nal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonretired\",\"d\":\"Not having left the workforce or ceased regular employment; still actively working rather than enjoying retirement.\",\"s\":\"The nonretired workers continued to show up every morning, eager to keep working.\",\"p\":\"nahn-rih-TYRD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.re.tired\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretirement\",\"d\":\"The state of not being retired; the condition of continuing to work or remain active rather than withdrawing from employment.\",\"s\":\"Her nonretirement was a choice — she loved her job too much to ever stop.\",\"p\":\"nahn-rih-TYR-munt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.tire.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonretouched\",\"d\":\"Not altered, edited, or adjusted after the original creation, especially referring to photographs or images left in their natural, unedited state.\",\"s\":\"The photographer proudly displayed the nonretouched photos to show natural beauty.\",\"p\":\"nahn-rih-TUCHT\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.re.touched\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretractable\",\"d\":\"not capable of being retracted\",\"s\":\"The surgeon warned that the nonretractable clamp would remain fixed in place throughout the entire procedure.\",\"p\":\"nahn-rih-TRAK-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.tractable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretractile\",\"d\":\"not capable of being retracted\",\"s\":\"Unlike a cat's claws, a dog's claws are nonretractile and always exposed.\",\"p\":\"nahn-rih-TRAK-tyl\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.trac.tile\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretracting\",\"d\":\"Not pulling back or withdrawing; remaining extended or in place rather than retracting.\",\"s\":\"The nonretracting antenna stayed fully extended even when the device was folded shut.\",\"p\":\"nahn-rih-TRAK-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.tract.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretroactive\",\"d\":\"Not applying to events, actions, or situations that occurred before the present rule or law came into effect.\",\"s\":\"The judge clarified that the new tax law was nonretroactive and would only apply to future income.\",\"p\":\"nahn-reh-troh-AK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.retroac.tive\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonretroactivity\",\"d\":\"The quality or condition of not having retroactive effect; the principle that a rule or law applies only from the present forward, not to past events.\",\"s\":\"The principle of nonretroactivity means people cannot be punished under laws that didn't exist when they acted.\",\"p\":\"nahn-reh-troh-ak-TIV-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.retroac.tiv.i.ty\",\"ps\":\"noun\",\"t\":[\"law\",\"logic\",\"olatin\"]},{\"w\":\"nonretroflex\",\"d\":\"Not pronounced with the tongue tip curled back toward the roof of the mouth; describing a sound or articulation made with the tongue in a forward position.\",\"s\":\"The linguist noted that the dialect used nonretroflex consonants, with the tongue staying flat rather than curling back.\",\"p\":\"nahn-REH-troh-fleks\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.retroflex\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonretrograde\",\"d\":\"Not moving, developing, or changing in a backward direction; continuing forward rather than declining or reversing.\",\"s\":\"The planet's nonretrograde orbit meant it steadily moved forward without appearing to reverse direction.\",\"p\":\"nahn-REH-troh-grayd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ret.ro.grade\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretroreflective\",\"d\":\"Not having the property of reflecting light directly back toward its source, as opposed to materials designed to bounce light back to the observer.\",\"s\":\"The matte black paint used on the stealth vehicle was nonretroreflective, absorbing light instead of bouncing it back.\",\"p\":\"nahn-reh-troh-rih-FLEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.retrore.flec.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonretroviral\",\"d\":\"Not relating to or caused by retroviruses, a class of viruses that use RNA to create DNA inside a host cell.\",\"s\":\"The doctor explained that the common cold is a nonretroviral infection, meaning it works differently from HIV.\",\"p\":\"nahn-reh-troh-VY-rul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.retro.vi.ral\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonreturn\",\"d\":\"A condition or policy in which something, such as a bottle or ticket, is not meant to be returned or sent back.\",\"s\":\"The nonreturn valve in the plumbing system prevented water from flowing backward into the clean supply.\",\"p\":\"nahn-rih-TURN\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.re.turn\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonreturned\",\"d\":\"Not sent back or given back to its original owner or place; describing something that has not been returned.\",\"s\":\"The library sent notices about all nonreturned books that had been overdue for more than a month.\",\"p\":\"nahn-rih-TURND\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.turned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreturner\",\"d\":\"A person who does not return something, such as a borrowed item, or someone who does not come back to a place or activity.\",\"s\":\"The store tracked every nonreturner who borrowed equipment and never brought it back.\",\"p\":\"nahn-rih-TUR-nur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.turn.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreusable\",\"d\":\"Not designed or able to be used more than once; intended for single use only and then to be discarded.\",\"s\":\"The hospital staff disposed of all nonreusable syringes immediately after each injection.\",\"p\":\"nahn-ree-YOO-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.reusable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrevenue\",\"d\":\"Not producing or generating income; describing something that does not bring in money or financial returns, such as a trip made without paying passengers.\",\"s\":\"The bus company scheduled nonrevenue trips to move empty vehicles between depots without charging fares.\",\"p\":\"non-REV-uh-nyoo\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rev.enue\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonreversed\",\"d\":\"Not turned around, flipped, or changed to an opposite direction or order; remaining in its original orientation or state.\",\"s\":\"The editor confirmed that the nonreversed image showed the text reading correctly from left to right.\",\"p\":\"non-rih-VERST\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.versed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreviewed\",\"d\":\"Not examined, assessed, or evaluated by a reviewer; describing work or material that has not undergone a formal review process.\",\"s\":\"The nonreviewed manuscript sat in the editor's pile for weeks, waiting for someone to evaluate it.\",\"p\":\"non-rih-VYOOD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.viewed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreviewer\",\"d\":\"A person who does not serve in the role of a reviewer and does not evaluate or critique submitted work, applications, or content.\",\"s\":\"As a nonreviewer on the committee, she could not officially score the submitted research proposals.\",\"p\":\"non-rih-VYOO-er\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.re.view.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonreviewing\",\"d\":\"Not engaged in or involving the process of reviewing, evaluating, or assessing something; lacking a review component.\",\"s\":\"The nonreviewing panel members attended the meeting but had no authority to evaluate the candidates.\",\"p\":\"non-rih-VYOO-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.view.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrevised\",\"d\":\"Not changed, corrected, or updated from an earlier version; remaining in its original, unedited form without any revisions.\",\"s\":\"The teacher handed back the nonrevised draft and asked students to make improvements before the final submission.\",\"p\":\"non-rih-VYZD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.re.vised\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrevisionary\",\"d\":\"Not involving or advocating a reinterpretation or revision of established ideas, historical events, or existing systems; accepting the original version as correct.\",\"s\":\"The historian took a nonrevisionary approach, sticking closely to the original accepted account of events.\",\"p\":\"non-rih-VIZH-uh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.vi.sion.ary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrevisionist\",\"d\":\"A person who does not reinterpret or revise accepted historical, political, or ideological accounts, instead accepting the traditional or established version of events.\",\"s\":\"As a nonrevisionist scholar, she accepted the traditional interpretation of the war without challenging it.\",\"p\":\"non-rih-VIZH-uh-nist\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.re.vi.sion.ist\",\"ps\":\"noun\",\"t\":[\"festivals\",\"politics\",\"olatin\"]},{\"w\":\"nonrevivable\",\"d\":\"Not capable of being brought back to life, use, or activity; impossible to revive or restore to a former state.\",\"s\":\"Once the ancient dialect was lost with its last speaker, experts considered it nonrevivable.\",\"p\":\"non-rih-VY-vuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.re.viv.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrevocable\",\"d\":\"Not able to be taken back, canceled, or annulled; permanent and impossible to revoke once issued or declared.\",\"s\":\"Once signed, the nonrevocable agreement meant neither party could back out under any circumstances.\",\"p\":\"non-REV-uh-kuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.re.vo.ca.ble\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrevolution\",\"d\":\"The absence of a fundamental, sweeping change or overthrow of an existing system; a situation in which major social or political transformation does not occur.\",\"s\":\"Historians debated whether the gradual social changes of that era constituted a nonrevolution — slow reform rather than dramatic upheaval.\",\"p\":\"non-rev-uh-LOO-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.rev.o.lu.tion\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonrevolutionary\",\"d\":\"Not characteristic of or relating to a revolution; describing ideas, actions, or people that do not seek to overthrow or radically transform existing systems.\",\"s\":\"The new policy was considered nonrevolutionary because it made only minor adjustments to the existing system.\",\"p\":\"non-rev-uh-LOO-shuh-nair-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.rev.o.lu.tion.ary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrevolving\",\"d\":\"Not rotating, spinning, or turning in a circular motion; describing something that remains stationary rather than revolving around a point.\",\"s\":\"The nonrevolving display case held the artifacts perfectly still so visitors could photograph them clearly.\",\"p\":\"non-rih-VOLV-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.re.volv.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreworkable\",\"d\":\"Not capable of being altered, adjusted, or redone after its initial creation; impossible to revise or work on again.\",\"s\":\"Once the concrete set overnight, the foundation was nonreworkable and any mistakes became permanent.\",\"p\":\"non-ree-WUR-kuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.re.work.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonreworked\",\"d\":\"Not subjected to revision, modification, or additional processing after its original creation; remaining untouched in its first form.\",\"s\":\"The original nonreworked recording was preferred by fans over the over-produced studio version.\",\"p\":\"non-ree-WURKT\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.re.worked\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonrhetorical\",\"d\":\"Not intended merely for stylistic effect or persuasion; describing a question or statement that is genuine and expects a real, direct answer.\",\"s\":\"Her nonrhetorical question genuinely surprised the class because she actually wanted an answer.\",\"p\":\"non-rih-TOR-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.rhetor.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrheumatic\",\"d\":\"Not caused by, relating to, or affected by rheumatic disease; describing a condition or person in which rheumatic inflammation of the joints is absent.\",\"s\":\"The doctor confirmed that the joint pain was nonrheumatic and likely caused by overuse during sports.\",\"p\":\"non-roo-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.rheumat.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonrhizomatous\",\"d\":\"Not producing or having rhizomes, which are underground horizontal stems; describing a plant that spreads or grows without this type of root structure.\",\"s\":\"Unlike bamboo, the nonrhizomatous plant spread only through seeds rather than underground stems.\",\"p\":\"non-ry-ZOM-uh-tus\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.rhi.zoma.tous\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonrhizomelic\",\"d\":\"Not characterized by shortening of the limbs closest to the body, such as the upper arms or thighs; describing a condition where these limbs grow to a normal length.\",\"s\":\"The physical therapist noted that the patient's limb proportions were nonrhizomelic, meaning the upper segments were normal in length.\",\"p\":\"non-ry-zoh-MEL-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.rhi.zomel.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"character\",\"olatin\"]},{\"w\":\"nonrhoticity\",\"d\":\"The linguistic property of a dialect or accent in which the letter 'r' is not pronounced after a vowel unless followed by another vowel, as heard in many British and some American accents.\",\"s\":\"The nonrhoticity of the Boston accent is what causes speakers to drop the 'r' in words like 'car' and 'park.'.\",\"p\":\"non-roh-TIS-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.rhotic.i.ty\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonrhyming\",\"d\":\"Not using rhyme; describing poetry, lyrics, or verse in which the ending sounds of lines do not correspond or match each other.\",\"s\":\"The poet deliberately chose a nonrhyming style to make the verse feel more like natural conversation.\",\"p\":\"non-RY-ming\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.rhyming\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"sports\",\"olatin\"]},{\"w\":\"nonrhythmic\",\"d\":\"deliberately not rhythmic\",\"s\":\"The composer used nonrhythmic percussion to create a sense of chaos and unpredictability in the piece.\",\"p\":\"non-RITH-mik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.rhyth.mic\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonrhythmically\",\"d\":\"In a manner that is not rhythmic; without a regular beat, pattern, or measured flow of sound or movement.\",\"s\":\"The dancer moved nonrhythmically, deliberately ignoring the beat to express inner emotional turmoil.\",\"p\":\"non-RITH-mih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.rhyth.mi.cal.ly\",\"ps\":\"adverb\",\"t\":[\"music\",\"numbers\",\"olatin\"]},{\"w\":\"nonribbed\",\"d\":\"Lacking raised ridges, ribs, or textured lines on its surface; smooth and without the parallel ridged pattern associated with ribbed materials.\",\"s\":\"The smooth, nonribbed pipe allowed water to flow through it with minimal resistance.\",\"p\":\"non-RIBD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.ribbed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrice\",\"d\":\"Not consisting of or derived from rice; describing a food, dish, or agricultural product that does not contain or involve rice.\",\"s\":\"The restaurant offered several nonrice dishes for guests who preferred noodles or bread instead.\",\"p\":\"non-RYS\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.rice\",\"ps\":\"adjective\",\"t\":[\"farming\",\"olatin\"]},{\"w\":\"nonrich\",\"d\":\"Not wealthy or affluent; lacking great financial resources or material abundance.\",\"s\":\"The survey found that nonrich households spent a greater portion of their income on basic necessities.\",\"p\":\"non-RICH\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.rich\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonrider\",\"d\":\"A person who does not ride a horse, bicycle, motorcycle, or other vehicle; someone who chooses not to participate in riding activities.\",\"s\":\"As a nonrider, she waited at the trailhead while her friends took the horses through the forest.\",\"p\":\"non-RY-der\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.rid.er\",\"ps\":\"noun\",\"t\":[\"animals\",\"vehicles\",\"olatin\"]},{\"w\":\"nonriding\",\"d\":\"Not involving or related to the act of riding a horse, bicycle, or other vehicle; describing activities or people that do not include riding.\",\"s\":\"The nonriding passengers waited at the stable while their friends trotted around the track.\",\"p\":\"non-RY-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.rid.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"vehicles\",\"olatin\"]},{\"w\":\"nonRiemannian\",\"d\":\"Not conforming to or based on Riemannian geometry, the mathematical system developed by Bernhard Riemann that describes curved surfaces; relating to geometries that use different rules for curved space.\",\"s\":\"The physicist studied nonRiemannian geometry to explore curved spaces that even Einstein's framework couldn't describe.\",\"p\":\"non-ree-MAH-nee-un\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.rie.man.ni.an\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonright\",\"d\":\"Not constituting a legal, moral, or political right; describing something to which a person or group is not entitled or does not have a claim.\",\"s\":\"The judge declared the claim a nonright, meaning it had no legal standing in court.\",\"p\":\"non-RYT\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.right\",\"ps\":\"adjective\",\"t\":[\"law\",\"politics\",\"logic\",\"olatin\"]},{\"w\":\"nonrights\",\"d\":\"Things or entitlements that are not recognized as legal or moral rights; the plural form referring to multiple instances of something that does not qualify as a right.\",\"s\":\"The lawyer argued that the protesters were asserting nonrights that had never been recognized by law.\",\"p\":\"non-RYTS\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.rights\",\"ps\":\"noun\",\"t\":[\"law\",\"logic\",\"olatin\"]},{\"w\":\"nonrigidity\",\"d\":\"The quality or state of not being stiff or rigid; the property of being flexible, pliable, or easily bent without breaking.\",\"s\":\"The engineer praised the nonrigidity of the new polymer because it could bend without breaking.\",\"p\":\"non-rih-JID-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.rigid.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrigorous\",\"d\":\"Not thorough, strict, or precise; describing an approach, method, or standard that lacks careful attention to detail and exactness.\",\"s\":\"The teacher warned that a nonrigorous study method would leave gaps in their understanding of math.\",\"p\":\"non-RIG-er-us\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.rig.or.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrioter\",\"d\":\"A person who does not participate in a riot or civil disturbance; someone who remains calm and peaceful during unrest.\",\"s\":\"Police carefully identified each nonrioter in the crowd so they could leave safely before arrests began.\",\"p\":\"non-RY-uh-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ri.ot.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonrioting\",\"d\":\"Not engaging in or involving riotous, disorderly, or violent public behavior; describing a peaceful, controlled group or situation.\",\"s\":\"The nonrioting section of the crowd held signs and chanted peacefully throughout the afternoon.\",\"p\":\"non-RY-uh-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.ri.ot.ing\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonriparian\",\"d\":\"Not located on, relating to, or having rights associated with the bank of a river or other body of water; describing land or property owners without riverbank access.\",\"s\":\"The nonriparian landowners had no legal claim to the river's water because their property didn't touch its banks.\",\"p\":\"non-rih-PAIR-ee-un\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.ri.par.i.an\",\"ps\":\"adjective\",\"t\":[\"waterways\",\"economy\",\"olatin\"]},{\"w\":\"nonripe\",\"d\":\"Not fully matured or developed; describing fruit, vegetables, or other produce that has not yet reached the stage of ripeness needed for eating.\",\"s\":\"She bit into the nonripe mango and immediately winced at the sour, starchy taste.\",\"p\":\"non-RYP\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.ripe\",\"ps\":\"adjective\",\"t\":[\"spices\",\"stage\",\"olatin\"]},{\"w\":\"nonrisk\",\"d\":\"Involving no danger, hazard, or chance of loss; describing an investment, activity, or situation that carries zero or negligible risk.\",\"s\":\"The financial advisor recommended the nonrisk savings account for clients who couldn't afford to lose money.\",\"p\":\"non-RISK\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.risk\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonrisky\",\"d\":\"Not dangerous, hazardous, or likely to result in loss or harm; describing a safe and secure activity, choice, or investment.\",\"s\":\"Choosing the nonrisky path through the forest meant taking the wider, well-lit trail.\",\"p\":\"non-RIS-kee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.risky\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonritualistic\",\"d\":\"Not involving or following established rituals, ceremonies, or prescribed symbolic actions; describing behavior or practices that are informal and free of traditional rites.\",\"s\":\"The ceremony was refreshingly nonritualistic, with no set prayers or prescribed movements.\",\"p\":\"non-rich-oo-uh-LIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ritu.al.is.tic\",\"ps\":\"adjective\",\"t\":[\"religion\",\"festivals\",\"olatin\"]},{\"w\":\"nonrivalrous\",\"d\":\"Describing a good or resource that can be used or enjoyed by many people at the same time without being used up or diminished for others.\",\"s\":\"Shared knowledge is nonrivalrous because one person learning a fact doesn't prevent another from learning it too.\",\"p\":\"non-RIV-ul-rus\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ri.val.rous\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonriverine\",\"d\":\"Not relating to, located near, or characteristic of a river or riverbank environment.\",\"s\":\"The biologist shifted her research to nonriverine wetlands, studying swamps far from any flowing water.\",\"p\":\"non-RIV-er-een\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.river.ine\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"waterways\",\"olatin\"]},{\"w\":\"nonroad\",\"d\":\"Not intended or designed for use on public roads; typically describing vehicles or equipment meant for off-road use.\",\"s\":\"The farmer's nonroad vehicle was designed specifically to plow fields, not cruise highways.\",\"p\":\"non-ROHD\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.road\",\"ps\":\"adjective\",\"t\":[\"vehicles\",\"olatin\"]},{\"w\":\"nonroaming\",\"d\":\"Not wandering or moving over a wide area; staying within a fixed or limited territory.\",\"s\":\"The nonroaming animal stayed within a tiny territory and never ventured far from its burrow.\",\"p\":\"non-ROH-ming\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.roam.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonroasted\",\"d\":\"Not having been subjected to roasting or dry heat; remaining in a raw or uncooked state.\",\"s\":\"The recipe called for nonroasted almonds so their mild flavor wouldn't overpower the delicate sauce.\",\"p\":\"non-ROH-sted\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.roast.ed\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonrobbery\",\"d\":\"The absence of robbery; a situation or incident in which no theft or forcible taking of property occurred.\",\"s\":\"The detective categorized the break-in as a nonrobbery since nothing was actually taken from the house.\",\"p\":\"non-ROB-er-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rob.bery\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonrobotic\",\"d\":\"Not robotic; characterized by natural, fluid, or human-like movement and behavior rather than mechanical or programmed actions.\",\"s\":\"The theater director wanted a nonrobotic performance, urging actors to move with natural, human emotion.\",\"p\":\"non-roh-BOT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.robot.ic\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonrobust\",\"d\":\"Lacking strength, durability, or resilience; fragile or weak in structure or function.\",\"s\":\"The nonrobust bridge shook dangerously in the wind and was quickly closed to traffic.\",\"p\":\"non-roh-BUST\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ro.bust\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrocky\",\"d\":\"Not rocky; describing terrain or a surface that is smooth, soft, or free of rocks and stones.\",\"s\":\"The trail through the nonrocky meadow was easy on their ankles after days of rugged mountain hiking.\",\"p\":\"non-ROK-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.rocky\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"landforms\",\"olatin\"]},{\"w\":\"nonrodent\",\"d\":\"Not belonging to the order Rodentia; describing any animal that is not a rodent, such as a rabbit or a dog.\",\"s\":\"The veterinarian's expertise covered nonrodent small animals like rabbits, hedgehogs, and ferrets.\",\"p\":\"non-ROH-dent\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.ro.dent\",\"ps\":\"adjective\",\"t\":[\"animals\",\"religion\",\"olatin\"]},{\"w\":\"nonromance\",\"d\":\"A story, relationship, or situation that lacks romantic elements; the absence of a love story or romantic involvement.\",\"s\":\"The novelist described her latest book as a nonromance, focusing on friendship and adventure instead of love.\",\"p\":\"non-roh-MANS\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ro.mance\",\"ps\":\"noun\",\"t\":[\"poetry\",\"ancient\",\"olatin\"]},{\"w\":\"nonromantic\",\"d\":\"Not romantic; lacking sentimental, idealistic, or loving qualities; practical or unaffectionate in nature.\",\"s\":\"He gave a very nonromantic birthday speech that listed his friend's faults before praising his cooking.\",\"p\":\"non-roh-MAN-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ro.man.tic\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"olatin\"]},{\"w\":\"nonroof\",\"d\":\"The absence of a roof; describing a structure or area that has no overhead covering.\",\"s\":\"The architect designed a bold nonroof structure, leaving the courtyard open to the sky.\",\"p\":\"non-ROOF\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.roof\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonroofed\",\"d\":\"Not covered by a roof; open to the sky or lacking an overhead structure.\",\"s\":\"The nonroofed patio collected puddles every time it rained, making afternoon gatherings tricky.\",\"p\":\"non-ROOFT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.roofed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrooted\",\"d\":\"Not having established roots; describing a plant, idea, or system that lacks a firm foundation or stable base.\",\"s\":\"The nonrooted cutting failed to grow because it had never developed the underground anchors it needed.\",\"p\":\"non-ROO-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.root.ed\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonroster\",\"d\":\"Not officially listed on a team's roster; describing a player or individual who participates in practice or tryouts without guaranteed membership.\",\"s\":\"The coach invited three nonroster players to training camp to see if any deserved a spot on the team.\",\"p\":\"non-ROS-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.roster\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonrotatable\",\"d\":\"Unable to be rotated or turned around an axis; fixed permanently in one position.\",\"s\":\"The nonrotatable lens mount was fixed in place and couldn't be adjusted once the camera was assembled.\",\"p\":\"non-ROH-tay-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.ro.tat.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrotated\",\"d\":\"Not having been rotated or moved around an axis; remaining in its original orientation or position.\",\"s\":\"The nonrotated crops in the same field year after year slowly exhausted the soil's nutrients.\",\"p\":\"non-ROH-tay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.ro.tat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrotating\",\"d\":\"Not spinning or turning around an axis; remaining stationary while other objects or systems may be in motion.\",\"s\":\"Scientists confirmed that the nonrotating black hole model simplified their calculations significantly.\",\"p\":\"non-ROH-tay-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.ro.tat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrotational\",\"d\":\"Not involving or relating to rotation; describing motion or forces that do not cause spinning or turning.\",\"s\":\"The nonrotational force pushed the object straight forward without causing any spin.\",\"p\":\"non-roh-TAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.ro.ta.tion.al\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonrotavirus\",\"d\":\"Not caused by or related to the rotavirus; describing a gastrointestinal illness or condition resulting from a different pathogen.\",\"s\":\"The lab results confirmed a nonrotavirus infection, so doctors adjusted the treatment plan accordingly.\",\"p\":\"non-ROH-tuh-vy-rus\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.ro.tavirus\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonrotting\",\"d\":\"Not subject to decay or decomposition; resistant to the natural process of rotting.\",\"s\":\"The nonrotting synthetic lumber on the deck looked like wood but would last decades without decaying.\",\"p\":\"non-ROT-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rot.ting\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonroughened\",\"d\":\"Not made rough or textured; remaining smooth and unaltered on the surface.\",\"s\":\"The nonroughened surface of the lens was perfectly smooth, allowing light to pass through without scattering.\",\"p\":\"non-RUF-end\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.rough.ened\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrounded\",\"d\":\"Not rounded; having sharp, angular, or flat edges rather than curved or smooth contours.\",\"s\":\"The sharp, nonrounded corners of the modern table gave the room a sleek, angular look.\",\"p\":\"non-ROWN-ded\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.round.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrouted\",\"d\":\"Not assigned or directed along a specific path or channel; lacking a designated route for travel or data flow.\",\"s\":\"The nonrouted data packets were lost in the network because no path had been set for them.\",\"p\":\"non-ROW-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.rout.ed\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonroutine\",\"d\":\"Not part of a regular or predictable schedule; unusual, irregular, or out of the ordinary.\",\"s\":\"The fire drill was a nonroutine event that caught most students off guard during their math test.\",\"p\":\"non-roo-TEEN\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rou.tine\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonroyal\",\"d\":\"Not belonging to or associated with a royal family; relating to a commoner or someone without noble or monarchical status.\",\"s\":\"The nonroyal guests at the palace banquet marveled at the golden chandeliers and marble floors.\",\"p\":\"non-ROY-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.roy.al\",\"ps\":\"adjective\",\"t\":[\"politics\",\"kinship\",\"royalty\",\"olatin\"]},{\"w\":\"nonroyalty\",\"d\":\"People who are not members of a royal family; also, referring to agreements or works that do not involve the payment of royalties.\",\"s\":\"The nonroyalty members of the crowd cheered just as loudly as the princes and princesses at the parade.\",\"p\":\"non-ROY-ul-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.roy.al.ty\",\"ps\":\"noun\",\"t\":[\"kinship\",\"royalty\",\"olatin\"]},{\"w\":\"nonrubber\",\"d\":\"Not made of or containing rubber; describing a material or product composed of substances other than natural or synthetic rubber.\",\"s\":\"The engineer chose a nonrubber material for the gasket because it needed to withstand extreme heat.\",\"p\":\"non-RUB-er\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.rub.ber\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrubberized\",\"d\":\"Not coated, treated, or infused with rubber; lacking the waterproof or grippy properties that rubberizing provides.\",\"s\":\"The nonrubberized gloves slipped easily off the workers' hands in the wet conditions.\",\"p\":\"non-RUB-er-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.rub.ber.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrubella\",\"d\":\"Not caused by or related to rubella, the viral disease also known as German measles; describing a rash or illness with a different origin.\",\"s\":\"The doctor confirmed the rash was nonrubella and likely caused by a mild allergic reaction.\",\"p\":\"non-roo-BEL-uh\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.rubel.la\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonruby\",\"d\":\"Not ruby-colored or not made of ruby; lacking the deep red color or the gemstone quality associated with rubies.\",\"s\":\"The jeweler sorted the red gems into ruby and nonruby categories before pricing them.\",\"p\":\"non-ROO-bee\",\"o\":\"Latin\",\"y\":8,\"bp\":20,\"sy\":\"non.ru.by\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"colors\",\"olatin\"]},{\"w\":\"nonrugby\",\"d\":\"Not relating to or involving the sport of rugby; describing athletic activities, players, or organizations outside of rugby.\",\"s\":\"The nonrugby athletes at the school still used the field for soccer and track practice.\",\"p\":\"non-RUG-bee\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.rug.by\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonrugged\",\"d\":\"Not rugged; lacking toughness, durability, or the ability to withstand harsh conditions.\",\"s\":\"The nonrugged phone case cracked the first time he dropped his device on the sidewalk.\",\"p\":\"non-RUG-ed\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.rugged\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonruggedized\",\"d\":\"Not engineered or reinforced to withstand harsh environmental conditions such as extreme temperatures, shock, or moisture.\",\"s\":\"The nonruggedized tablet was not designed to survive drops or extreme outdoor conditions.\",\"p\":\"non-RUG-uh-dyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.ruggedi.zed\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"tools\",\"olatin\"]},{\"w\":\"nonruling\",\"d\":\"Not holding power or authority; describing a group, class, or individual that does not govern or make binding decisions.\",\"s\":\"The nonruling parties still had a strong voice in debating the new laws.\",\"p\":\"nah-NROO-lih-ng\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"naa.nruw.lih.ng\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonruminant\",\"d\":\"not ruminant\",\"s\":\"Dogs and cats are nonruminant animals, so they digest food very differently from cows.\",\"p\":\"non-ROO-mih-nunt\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.rumi.nant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonruminating\",\"d\":\"Not engaging in the process of chewing cud; also, not deeply thinking over or dwelling on a subject or problem.\",\"s\":\"Unlike sheep, pigs are nonruminating creatures that do not chew their cud.\",\"p\":\"non-ROO-mih-nay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.rumi.nat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrunic\",\"d\":\"Not written in or relating to runes; describing a script, inscription, or language that does not use the runic alphabet.\",\"s\":\"The archaeologist noted that the carvings were nonrunic and came from a completely different ancient culture.\",\"p\":\"non-ROO-nik\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.runic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonrunning\",\"d\":\"Not currently operating, moving, or in motion; describing a machine, engine, or process that is stopped or inactive.\",\"s\":\"The nonrunning appliances in the garage needed repairs before the family could use them again.\",\"p\":\"non-RUN-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.run.ning\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonrural\",\"d\":\"Not relating to or characteristic of the countryside or rural areas; typically describing urban or suburban settings.\",\"s\":\"The study compared health services available in rural areas versus nonrural urban neighborhoods.\",\"p\":\"non-ROOR-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.rural\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrusted\",\"d\":\"Not affected by rust or oxidation; describing a metal or surface that remains free from corrosion.\",\"s\":\"The nonrusted bolts on the old bridge surprised the engineers during the inspection.\",\"p\":\"non-RUS-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.rust.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonrustic\",\"d\":\"Not having the simple, rough, or old-fashioned qualities associated with country life; modern or refined in character.\",\"s\":\"The interior designer gave the cabin a nonrustic, modern look with sleek furniture and glass walls.\",\"p\":\"non-RUS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.rus.tic\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonrusting\",\"d\":\"Not prone to rusting or forming surface corrosion; describing materials that resist oxidation over time.\",\"s\":\"The chef preferred nonrusting stainless-steel knives that stayed sharp and clean for years.\",\"p\":\"non-RUS-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.rust.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonrusty\",\"d\":\"Free from rust or corrosion; describing a surface or object that remains clean, smooth, and unaffected by oxidation.\",\"s\":\"The nonrusty hinges swung open easily, unlike the old corroded ones on the barn door.\",\"p\":\"non-RUS-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.rusty\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsaccharine\",\"d\":\"Not excessively sweet, sentimental, or artificially pleasant in tone or flavor; genuine and straightforward rather than cloying.\",\"s\":\"The critic praised the film for its nonsaccharine ending, which felt honest rather than overly sweet.\",\"p\":\"non-SAK-uh-rin\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sac.cha.rine\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsacerdotal\",\"d\":\"Not relating to or characteristic of priests or the priestly office; lacking a clerical or priestly nature or function.\",\"s\":\"The nonsacerdotal ceremony was led by a community elder rather than a priest.\",\"p\":\"non-sas-er-DOH-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sac.er.do.tal\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonsacred\",\"d\":\"Not regarded as holy, divine, or deserving of religious reverence; secular or ordinary in nature.\",\"s\":\"The artist displayed her work in a nonsacred building, turning an old factory into a gallery.\",\"p\":\"non-SAY-krid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sa.cred\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonsadistic\",\"d\":\"not cruel; not the kind of person who enjoys being harsh to others\",\"s\":\"The trainer took a nonsadistic approach, encouraging athletes with praise rather than harsh criticism.\",\"p\":\"non-say-DIS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sadis.tic\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonsafe\",\"d\":\"Not safe; presenting a risk or danger to people or property under normal conditions of use.\",\"s\":\"The inspector labeled the playground equipment nonsafe and ordered it removed immediately.\",\"p\":\"non-SAYF\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.safe\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsailing\",\"d\":\"Not involving or related to the sport or activity of sailing; describing activities or vessels not connected to sail-powered travel.\",\"s\":\"The nonsailing passengers enjoyed the cruise while the crew managed the sails and rigging.\",\"p\":\"non-SAYL-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sail.ing\",\"ps\":\"adjective\",\"t\":[\"seafaring\",\"sports\",\"olatin\"]},{\"w\":\"nonsailor\",\"d\":\"A person who is not a sailor and does not work on or navigate a sailing vessel; a landlubber.\",\"s\":\"As a nonsailor, Maria felt nervous stepping onto the small boat for the first time.\",\"p\":\"non-SAY-lur\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sailor\",\"ps\":\"noun\",\"t\":[\"maps\",\"character\",\"seafaring\",\"olatin\"]},{\"w\":\"nonsalable\",\"d\":\"Not able to be sold; lacking the qualities or conditions necessary to be offered or accepted in a marketplace.\",\"s\":\"The cracked pottery was deemed nonsalable and set aside for the studio's decoration.\",\"p\":\"non-SAY-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sal.able\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonsalary\",\"d\":\"Not relating to or constituting a fixed regular payment for employment; describing compensation that is not in the form of a salary.\",\"s\":\"The freelancer negotiated nonsalary benefits like flexible hours and project bonuses.\",\"p\":\"non-SAL-uh-ree\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.salary\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonsale\",\"d\":\"Not constituting or resulting in an actual commercial transaction; describing an exchange or event that does not involve a sale.\",\"s\":\"The item was marked as a nonsale product, meaning its price never changed no matter what.\",\"p\":\"non-SAYL\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.sale\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonsaleable\",\"d\":\"Not fit or available to be sold; lacking the necessary conditions or qualities to be purchased or traded on the market.\",\"s\":\"The expired food was nonsaleable and had to be donated to a composting program.\",\"p\":\"non-SAYL-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.saleable\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonsales\",\"d\":\"Not relating to the activity or process of selling goods or services; describing departments or roles outside of a sales function.\",\"s\":\"The nonsales staff at the company included engineers, designers, and customer support teams.\",\"p\":\"non-SAYLZ\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.sales\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsalesman\",\"d\":\"A person whose role or profession does not involve selling goods or services to customers; someone outside the sales field.\",\"s\":\"Despite working at the store, he was a nonsalesman who only handled inventory and stocking.\",\"p\":\"non-SAYLZ-man\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sales.man\",\"ps\":\"noun\",\"t\":[\"jobs\",\"olatin\"]},{\"w\":\"nonsalient\",\"d\":\"Not standing out as important, noticeable, or particularly relevant; lacking the quality of being especially prominent or significant.\",\"s\":\"The teacher asked students to cut out nonsalient details that cluttered their essays.\",\"p\":\"non-SAY-lee-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.salient\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsaline\",\"d\":\"Not containing or relating to salt; describing a substance, environment, or solution that is free from significant salt content.\",\"s\":\"The scientist tested the river water and confirmed it was nonsaline, making it safe for drinking.\",\"p\":\"non-SAY-lyn\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.saline\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonsalivary\",\"d\":\"Not relating to or produced by the salivary glands; describing secretions or tissues that are unconnected to saliva production.\",\"s\":\"The biologist studied nonsalivary digestive enzymes that work further along in the digestive tract.\",\"p\":\"non-SAL-ih-vair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sali.vary\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonsalmon\",\"d\":\"Not of, relating to, or consisting of salmon; describing a fish, food, or color that is distinct from salmon.\",\"s\":\"The sushi chef prepared a nonsalmon platter for guests who preferred tuna and shrimp.\",\"p\":\"non-SAM-un\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.salmon\",\"ps\":\"adjective\",\"t\":[\"marine\",\"colors\",\"olatin\"]},{\"w\":\"nonsalt\",\"d\":\"Not containing or consisting of salt; describing a substance or preparation that is entirely free from salt.\",\"s\":\"The nutritionist recommended a nonsalt seasoning blend for patients with high blood pressure.\",\"p\":\"non-SAWLT\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.salt\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsalted\",\"d\":\"Not treated, preserved, or seasoned with salt; describing food or other substances that have had no salt added.\",\"s\":\"She preferred nonsalted butter when baking so she could control the saltiness herself.\",\"p\":\"non-SAWL-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.salt.ed\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"time\",\"olatin\"]},{\"w\":\"nonsalty\",\"d\":\"Lacking a salty taste or high salt content; describing food or substances that are not seasoned or naturally rich in salt.\",\"s\":\"The nonsalty crackers were perfect for the toddler who wasn't used to strong flavors yet.\",\"p\":\"non-SAWL-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.salty\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"time\",\"olatin\"]},{\"w\":\"nonsalutary\",\"d\":\"Not producing a beneficial, healthy, or wholesome effect; describing influences or conditions that fail to promote well-being.\",\"s\":\"The doctor warned that skipping sleep was nonsalutary and would harm the patient's recovery.\",\"p\":\"non-SAL-yuh-tair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.salu.tary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsampled\",\"d\":\"Not selected or included as part of a statistical or research sample; describing data or populations that were not tested or surveyed.\",\"s\":\"The nonsampled regions of the forest were left out of the wildlife study entirely.\",\"p\":\"non-SAM-puld\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sam.pled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsanctified\",\"d\":\"Not made holy or consecrated through a religious rite or blessing; remaining in a secular or unconsecrated state.\",\"s\":\"The old chapel stood nonsanctified for years before a priest finally blessed it.\",\"p\":\"non-SANK-tih-fyd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sanc.ti.fied\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonsanctimonious\",\"d\":\"Not displaying an exaggerated or self-righteous attitude of moral superiority; genuine, humble, and free from hypocritical piety.\",\"s\":\"Everyone appreciated her nonsanctimonious attitude — she gave advice without acting morally superior.\",\"p\":\"non-sank-tih-MOH-nee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.sanc.ti.mo.nious\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonsanctioned\",\"d\":\"Not officially approved, authorized, or permitted by a recognized authority; lacking formal endorsement or legal backing.\",\"s\":\"The nonsanctioned tournament was fun, but the results wouldn't count toward the official rankings.\",\"p\":\"non-SANK-shund\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.sanc.tioned\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"law\",\"olatin\"]},{\"w\":\"nonsandstone\",\"d\":\"Not composed of or relating to sandstone; describing a rock, material, or geological formation made of a different substance.\",\"s\":\"The geologist confirmed that the cliff face was nonsandstone, composed instead of limestone and granite.\",\"p\":\"non-SAND-stohn\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.sand.stone\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonsane\",\"d\":\"Not mentally sound or rational; lacking clarity of mind or the ability to reason and make balanced judgments.\",\"s\":\"The character's nonsane decisions in the story led to a series of bizarre and chaotic events.\",\"p\":\"non-SAYN\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.sane\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonsapient\",\"d\":\"Not possessing wisdom, higher reasoning, or conscious intelligence; describing creatures or entities that lack the capacity for rational thought.\",\"s\":\"The robot in the story was nonsapient, following only programmed commands without any true understanding.\",\"p\":\"non-SAY-pee-unt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sapi.ent\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonsaponaceous\",\"d\":\"Not having the soapy, lathering, or cleansing properties associated with soap; describing a substance that cannot form a lather.\",\"s\":\"The chemist noted the oil was nonsaponaceous and could not be converted into soap through the usual process.\",\"p\":\"non-sap-uh-NAY-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sapona.ceous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsaponified\",\"d\":\"Not converted into soap through the chemical process of saponification; describing fats or oils that remain in their original unsoaped form.\",\"s\":\"The nonsaponified portion of the mixture remained oily because it hadn't reacted with the lye.\",\"p\":\"non-suh-PON-ih-fyd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.saponi.fied\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsarcastic\",\"d\":\"Not using or characterized by sarcasm; expressing ideas in a sincere, straightforward manner without irony or mockery.\",\"s\":\"Her nonsarcastic praise surprised the class because they expected her usual dry humor.\",\"p\":\"non-sar-KAS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.sar.cas.tic\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonsatanic\",\"d\":\"Not relating to, involving, or associated with Satan, devil worship, or anything considered diabolically evil in nature.\",\"s\":\"The gothic decorations were purely artistic and nonsatanic, despite what some neighbors assumed.\",\"p\":\"non-suh-TAN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.sa.tan.ic\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonsatirical\",\"d\":\"Not employing satire, irony, or exaggerated mockery to criticize or comment on society; expressing ideas in a direct and sincere way.\",\"s\":\"Unlike his usual comedy, his nonsatirical speech at the ceremony was sincere and heartfelt.\",\"p\":\"non-suh-TEER-ih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.satir.i.cal\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonsatisfied\",\"d\":\"Not satisfied or fulfilled; describing a state in which needs, desires, or expectations have not been adequately met.\",\"s\":\"The nonsatisfied customer returned the product and demanded a full refund.\",\"p\":\"non-SAT-is-fyd\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.sat.is.fied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsatisfying\",\"d\":\"Not providing satisfaction or fulfillment; failing to meet the expectations or needs of a person or situation.\",\"s\":\"The nonsatisfying ending of the movie left audiences puzzled and disappointed.\",\"p\":\"non-SAT-is-fy-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sat.is.fy.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsaturable\",\"d\":\"Not capable of being saturated or completely filled; describing a system or substance that cannot reach a point of maximum capacity.\",\"s\":\"The nonsaturable receptor kept binding molecules endlessly, unlike typical receptors that reach a limit.\",\"p\":\"non-SACH-er-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.sat.urable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsaturated\",\"d\":\"Not saturated; describing a substance or solution that has not absorbed or dissolved the maximum possible amount of another substance.\",\"s\":\"The nonsaturated soil quickly absorbed the rainwater without flooding the garden.\",\"p\":\"non-SACH-uh-ray-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.sat.u.rat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsaturating\",\"d\":\"Not causing or reaching saturation; describing a process or condition that does not bring a substance to its maximum capacity.\",\"s\":\"Scientists used a nonsaturating dose of the chemical to keep the reaction steady and controllable.\",\"p\":\"non-SACH-uh-ray-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sat.u.rat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsave\",\"d\":\"Describing a state or operation in which data or progress is not stored or preserved for future use.\",\"s\":\"In the video game, the nonsave zone meant any progress made there would be lost if you quit.\",\"p\":\"non-SAYV\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.save\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsaved\",\"d\":\"Not saved or stored; referring to data, files, or information that has not been preserved and may be lost.\",\"s\":\"The nonsaved document disappeared when the computer crashed, and she had to start her essay over.\",\"p\":\"non-SAYVD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.saved\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsavvy\",\"d\":\"Lacking practical knowledge, skill, or shrewd understanding in a particular area or subject.\",\"s\":\"The nonsavvy shopper paid full price, unaware of the discount codes available online.\",\"p\":\"non-SAV-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.savvy\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonscalable\",\"d\":\"Not capable of being scaled up or expanded in size, capacity, or complexity without significant problems or limitations.\",\"s\":\"The nonscalable software worked fine for ten users but crashed completely when a thousand tried to log in.\",\"p\":\"non-SKAY-luh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.scal.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscalar\",\"d\":\"Not scalar; referring to a quantity or value that cannot be expressed as a single number and requires multiple components, such as a vector or matrix.\",\"s\":\"The math teacher explained that velocity is nonscalar because it has both magnitude and direction.\",\"p\":\"non-SKAY-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.scalar\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonscalding\",\"d\":\"Not hot enough to burn or scald; describing a liquid or surface that is at a safe, tolerable temperature.\",\"s\":\"The barista made sure the hot chocolate was nonscalding before handing it to the young child.\",\"p\":\"non-SKAWL-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.scald.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscaled\",\"d\":\"Not drawn or represented according to a proportional scale; describing a map, diagram, or model that does not use consistent measurements.\",\"s\":\"The nonscaled drawing looked odd because the tiny car was drawn the same size as the skyscraper.\",\"p\":\"non-SKAYLD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.scaled\",\"ps\":\"adjective\",\"t\":[\"maps\",\"numbers\",\"olatin\"]},{\"w\":\"nonscaling\",\"d\":\"Not increasing or adjusting proportionally in size, scope, or complexity; describing a system or design that does not scale with changing demands.\",\"s\":\"The nonscaling font stayed the same tiny size no matter how large the window became.\",\"p\":\"non-SKAY-ling\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.scal.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscaly\",\"d\":\"Not having or covered with scales; describing a smooth-skinned animal or surface that lacks the overlapping plate-like structures typical of fish or reptiles.\",\"s\":\"Unlike most reptiles, this salamander's skin was smooth and nonscaly to the touch.\",\"p\":\"non-SKAY-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.scaly\",\"ps\":\"adjective\",\"t\":[\"animals\",\"marine\",\"olatin\"]},{\"w\":\"nonscandal\",\"d\":\"A situation or event that is expected to cause public outrage or controversy but does not actually do so; the absence of scandal.\",\"s\":\"The politician's boring budget speech was pure nonscandal — not a single headline-worthy moment.\",\"p\":\"non-SKAN-dul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.scan.dal\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonscandalous\",\"d\":\"Not shocking, controversial, or morally offensive; describing behavior or events that are perfectly ordinary and do not cause public outrage.\",\"s\":\"Despite the rumors, the celebrity's actions turned out to be completely nonscandalous and unremarkable.\",\"p\":\"non-SKAN-duh-lus\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.scan.dalous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscannable\",\"d\":\"Not able to be read or processed by a scanner; describing a barcode, document, or object that cannot be successfully scanned by electronic equipment.\",\"s\":\"The barcode was so smudged it was nonscannable, and the cashier had to type in the price manually.\",\"p\":\"non-SKAN-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.scannable\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonscanned\",\"d\":\"Not yet scanned or converted to a digital format; describing physical documents or images that remain in their original, non-digital form.\",\"s\":\"The nonscanned documents sat in boxes, unavailable to anyone searching the digital archive.\",\"p\":\"non-SKAND\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.scanned\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscarce\",\"d\":\"Not scarce or in short supply; describing a resource, item, or commodity that is plentiful and readily available.\",\"s\":\"Water was nonscarce in the rainforest, flowing freely in streams throughout the dense jungle.\",\"p\":\"non-SKAIRS\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.scarce\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscary\",\"d\":\"Not frightening or alarming; describing something that fails to cause fear or anxiety despite perhaps being expected to do so.\",\"s\":\"The haunted house was supposed to be terrifying, but my little sister found it completely nonscary.\",\"p\":\"non-SKAIR-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.scary\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonscattered\",\"d\":\"Not spread out or dispersed; describing particles, light, or objects that remain concentrated or travel together without being deflected in multiple directions.\",\"s\":\"The nonscattered light beam stayed focused and bright as it traveled through the clean glass lens.\",\"p\":\"non-SKAT-erd\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.scat.tered\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonsceptic\",\"d\":\"A person who is not skeptical and tends to accept ideas, claims, or information without strong doubt or questioning.\",\"s\":\"As a nonsceptic, she believed the scientist's findings without demanding extra proof.\",\"p\":\"non-SKEP-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.scep.tic\",\"ps\":\"noun\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonsceptical\",\"d\":\"Not inclined to question or doubt; describing a person or attitude that accepts information or claims readily without critical scrutiny.\",\"s\":\"The nonsceptical audience cheered enthusiastically, never questioning the magician's impossible tricks.\",\"p\":\"non-SKEP-tih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.scep.ti.cal\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonscheduled\",\"d\":\"Not planned or arranged in advance according to a timetable; describing an event, flight, or activity that occurs without prior scheduling.\",\"s\":\"The nonscheduled power outage interrupted classes and caught everyone completely off guard.\",\"p\":\"non-SKEJ-oold\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.sched.uled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonschizoid\",\"d\":\"Not having or relating to schizoid personality traits; describing a person who does not exhibit the emotional detachment or social withdrawal associated with schizoid personality.\",\"s\":\"The psychologist noted that the patient's personality was nonschizoid, showing warm social connections.\",\"p\":\"non-SKIT-soyd\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.schizoid\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonschizophrenic\",\"d\":\"Not affected by or related to schizophrenia; describing a person or condition that does not involve the disrupted thinking, perceptions, or behaviors characteristic of schizophrenia.\",\"s\":\"The evaluation confirmed the patient was nonschizophrenic, and her confusion had a different medical cause.\",\"p\":\"non-skit-suh-FREN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.schizophrenic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonschizotypal\",\"d\":\"Not exhibiting the unusual patterns of thinking, perception, or behavior associated with schizotypal personality; describing a person who shows no signs of this personality type.\",\"s\":\"The therapist determined that the teen's quirky habits were nonschizotypal and simply part of her personality.\",\"p\":\"non-skit-soh-TY-pul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.schizo.ty.pal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscholar\",\"d\":\"A person who is not a scholar; someone who does not engage in academic study, research, or intellectual pursuits at a formal or professional level.\",\"s\":\"The nonscholar in the group admitted he had never read a single academic paper.\",\"p\":\"non-SKOL-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.schol.ar\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonscholarly\",\"d\":\"Not characteristic of or suited to scholarly work; describing writing, research, or behavior that does not meet the rigorous standards of academic study.\",\"s\":\"The blog post was written in a nonscholarly style, full of jokes and casual language.\",\"p\":\"non-SKOL-er-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.schol.ar.ly\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscholarship\",\"d\":\"Not involving or awarded through a scholarship; describing financial aid, enrollment, or participation that is not based on academic merit or a formal scholarship award.\",\"s\":\"He was a nonscholarship athlete who paid his own tuition while playing on the team.\",\"p\":\"non-SKOL-er-ship\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.schol.ar.ship\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscholastic\",\"d\":\"Not related to schools, formal education, or academic learning; describing activities, knowledge, or skills that exist outside the traditional educational system.\",\"s\":\"Her nonscholastic hobbies, like painting and hiking, kept her balanced outside of school.\",\"p\":\"non-skuh-LAS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.scholas.tic\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"logic\",\"olatin\"]},{\"w\":\"nonschool\",\"d\":\"Not related to or taking place within a school setting; describing time, activities, or environments outside of formal educational institutions.\",\"s\":\"The kids spent their nonschool hours playing basketball at the park.\",\"p\":\"non-SKOOL\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.school\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"time\",\"olatin\"]},{\"w\":\"nonscience\",\"d\":\"A field of study or body of knowledge that does not use the systematic methods of scientific inquiry; any discipline or subject that falls outside the natural or physical sciences.\",\"s\":\"History and literature are considered nonscience subjects in most college catalogs.\",\"p\":\"non-SY-ens\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.science\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonscissile\",\"d\":\"Not capable of being easily cut or split; describing a material or substance that resists being divided by cutting or cleaving.\",\"s\":\"The tough material was nonscissile, meaning it could not be cleanly cut along a flat plane.\",\"p\":\"non-SIS-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.scis.sile\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonscoliotic\",\"d\":\"Not affected by or relating to scoliosis; describing a spine or individual that does not have the abnormal lateral curvature associated with scoliosis.\",\"s\":\"The school nurse confirmed that the student's spine was nonscoliotic after the screening.\",\"p\":\"non-skoh-lee-OT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":41,\"sy\":\"non.sco.l.i.ot.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonscourable\",\"d\":\"Not capable of being cleaned by vigorous scrubbing; describing a surface or material that cannot withstand or respond to scouring without damage.\",\"s\":\"The delicate fabric was nonscourable, so it had to be gently hand-washed instead of scrubbed.\",\"p\":\"non-SKOW-ruh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.scour.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscratchable\",\"d\":\"Not able to be scratched or marked by abrasion; describing a surface that is resistant to being damaged by sharp or rough objects.\",\"s\":\"The phone screen was advertised as nonscratchable, making it perfect for clumsy users.\",\"p\":\"non-SKRACH-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.scratch.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscreaming\",\"d\":\"Not producing or characterized by screaming or loud, shrill cries; describing a person, situation, or environment that is calm and free from screaming.\",\"s\":\"The librarian appreciated the nonscreaming policy that kept the children's section peaceful.\",\"p\":\"non-SKREE-ming\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.scream.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"character\",\"olatin\"]},{\"w\":\"nonscreened\",\"d\":\"Not filtered, tested, or examined through a screening process; describing applicants, substances, or content that have not undergone evaluation or review.\",\"s\":\"The nonscreened windows let in a cool breeze but also every bug in the neighborhood.\",\"p\":\"non-SKREEND\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.screened\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscriptable\",\"d\":\"Not capable of being automated or controlled through a script or programming commands; referring to a process or interface that cannot be scripted.\",\"s\":\"The old software was nonscriptable, so every action had to be done manually by the user.\",\"p\":\"non-SCRIP-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.script.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscripted\",\"d\":\"Not following a prepared script; occurring spontaneously or without planned written dialogue.\",\"s\":\"The funniest moments of the show were completely nonscripted and totally unexpected.\",\"p\":\"non-SCRIP-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.script.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonscriptural\",\"d\":\"Not based on, derived from, or related to religious scripture or sacred texts.\",\"s\":\"The pastor noted that some popular holiday traditions are nonscriptural, not found in the Bible.\",\"p\":\"non-SCRIP-chur-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.scrip.tural\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonscripturally\",\"d\":\"In a manner that does not reference or rely on religious scripture or sacred writings.\",\"s\":\"He argued nonscripturally, drawing on philosophy rather than religious texts.\",\"p\":\"non-SCRIP-chur-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.scrip.tural.ly\",\"ps\":\"adverb\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonscrolling\",\"d\":\"Not moving or able to scroll; describing a display or interface element that remains fixed and does not move up, down, or sideways.\",\"s\":\"The designer chose a nonscrolling layout so all information fit on one fixed screen.\",\"p\":\"non-SKROH-ling\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.scrolling\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonscuff\",\"d\":\"Designed or treated to resist or prevent scuffing and surface scratches; not causing or leaving scuff marks.\",\"s\":\"The gym floor was coated with a nonscuff finish to prevent marks from sneakers.\",\"p\":\"non-SKUF\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.scuff\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsea\",\"d\":\"Not related to, located in, or characteristic of the sea or ocean; pertaining to land or non-marine environments.\",\"s\":\"Freshwater fish are nonsea creatures that cannot survive in the salty ocean.\",\"p\":\"non-SEE\",\"o\":\"Latin\",\"y\":9,\"bp\":18,\"sy\":\"non.sea\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"waterways\",\"olatin\"]},{\"w\":\"nonseafood\",\"d\":\"Not consisting of or derived from seafood such as fish, shellfish, or other marine creatures; describing food that comes entirely from non-ocean sources.\",\"s\":\"She ordered the nonseafood option since she was allergic to shellfish.\",\"p\":\"non-SEE-food\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.seafood\",\"ps\":\"adjective\",\"t\":[\"marine\",\"waterways\",\"olatin\"]},{\"w\":\"nonsealed\",\"d\":\"Not closed, fastened, or made airtight with a seal; describing a container or surface that remains open or improperly closed.\",\"s\":\"The nonsealed container let moisture in, ruining the crackers inside.\",\"p\":\"non-SEELD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.sealed\",\"ps\":\"adjective\",\"t\":[\"marine\",\"olatin\"]},{\"w\":\"nonsearchable\",\"d\":\"Not able to be searched or indexed; describing digital content or databases that cannot be queried using a search function.\",\"s\":\"The scanned document was nonsearchable because it was saved as an image, not text.\",\"p\":\"non-SUR-chuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.search.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsebaceous\",\"d\":\"Not relating to or involving sebaceous glands; describing tissue or structures that do not produce or secrete sebum or oily substances.\",\"s\":\"The dermatologist noted that the cyst was nonsebaceous and unrelated to the oil glands.\",\"p\":\"non-sih-BAY-shus\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.se.ba.ceous\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonsecondary\",\"d\":\"Not at the secondary level of education or classification; referring to something that does not belong to the second tier or stage.\",\"s\":\"The college only accepted students from nonsecondary programs if they had equivalent experience.\",\"p\":\"non-SEK-un-dair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.sec.ondary\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"nonsecrecy\",\"d\":\"The absence of secrecy; a state in which information is openly shared and nothing is kept hidden or confidential.\",\"s\":\"The government promoted nonsecrecy in its operations to build public trust.\",\"p\":\"non-SEE-kruh-see\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.se.cre.cy\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsecret\",\"d\":\"Not hidden or kept confidential; openly known or available to anyone without restriction.\",\"s\":\"The meeting was entirely nonsecret and open to any community member who wanted to attend.\",\"p\":\"non-SEE-krit\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.se.cret\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsecretarial\",\"d\":\"Not related to or involving the duties of a secretary, such as typing, filing, or managing correspondence.\",\"s\":\"Her job duties were largely nonsecretarial, focusing on research rather than administrative tasks.\",\"p\":\"non-sek-ruh-TAIR-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.sec.re.tar.i.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsecretary\",\"d\":\"Not functioning as or relating to a secretary; describing a person or role that does not involve administrative or clerical duties.\",\"s\":\"The committee was looking for a nonsecretary role that didn't involve keeping meeting minutes.\",\"p\":\"non-SEK-ruh-tair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.sec.re.tary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsecretor\",\"d\":\"A person or organism that does not secrete certain substances, such as blood group antigens, into body fluids like saliva or sweat.\",\"s\":\"A nonsecretor does not release blood type antigens into body fluids like saliva.\",\"p\":\"non-sih-KREE-tur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.se.cre.tor\",\"ps\":\"noun\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonsecretory\",\"d\":\"Not involved in or capable of secretion; describing cells, glands, or tissues that do not produce or release substances into the body.\",\"s\":\"The lab determined that the cells were nonsecretory and produced no hormones.\",\"p\":\"non-sih-KREE-tuh-ree\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.se.cre.to.ry\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonsectional\",\"d\":\"Not divided into or organized by sections or regions; applying uniformly across all parts without division into separate groups.\",\"s\":\"The band's nonsectional rehearsal brought all the instruments together for the first time.\",\"p\":\"non-SEK-shun-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.sec.tion.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsectioned\",\"d\":\"Not divided or separated into distinct sections; remaining whole and undivided.\",\"s\":\"The long pipe was nonsectioned, meaning it was delivered as one continuous piece.\",\"p\":\"non-SEK-shund\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.sec.tioned\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsecular\",\"d\":\"Not secular; relating to or associated with religion, spirituality, or sacred matters rather than worldly or civil concerns.\",\"s\":\"The school had a nonsecular mission and began every day with a prayer.\",\"p\":\"non-SEK-yuh-lur\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.sec.u.lar\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonsecure\",\"d\":\"Not safe, protected, or free from risk; lacking the safeguards or protections needed to prevent unauthorized access or danger.\",\"s\":\"The expert warned that using public Wi-Fi is nonsecure and risky for personal data.\",\"p\":\"non-sih-KYOOR\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.se.cure\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsecured\",\"d\":\"Not backed by collateral or a guarantee; describing a loan or financial agreement that has no asset pledged as security.\",\"s\":\"The nonsecured loan required no collateral but came with a much higher interest rate.\",\"p\":\"non-sih-KYOORD\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.se.cured\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonsecurity\",\"d\":\"The condition of lacking security or protection; an absence of safety measures, guarantees, or safeguards.\",\"s\":\"The analyst warned that the nonsecurity of the old database posed a serious threat.\",\"p\":\"non-sih-KYOOR-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.se.cu.ri.ty\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsedated\",\"d\":\"Not having been given a sedative or calming medication; fully alert and awake without the influence of sedating drugs.\",\"s\":\"The nonsedated patient was wide awake and anxious during the minor procedure.\",\"p\":\"non-SED-ay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"nonse.dat.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonsedating\",\"d\":\"Not causing drowsiness or sedation; describing a medication or substance that does not make the user sleepy or less alert.\",\"s\":\"The doctor prescribed a nonsedating allergy medication so she could drive safely.\",\"p\":\"non-SED-ay-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonse.dat.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonsedative\",\"d\":\"Not having a sedating or calming effect on the nervous system; describing a drug or treatment that does not induce drowsiness.\",\"s\":\"The doctor prescribed a nonsedative painkiller so the patient could stay alert during the day.\",\"p\":\"non-SED-uh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"nonseda.tive\",\"ps\":\"adjective\",\"t\":[\"pharmacy\",\"olatin\"]},{\"w\":\"nonsedimentable\",\"d\":\"Not capable of settling or being deposited as sediment; describing particles or substances that remain suspended rather than sinking to the bottom.\",\"s\":\"The scientist noted that the tiny particles were nonsedimentable and stayed suspended in the liquid for days.\",\"p\":\"non-sed-ih-MEN-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonsed.i.mentable\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"physics\",\"olatin\"]},{\"w\":\"nonsedimentary\",\"d\":\"Not formed by the accumulation and layering of sediment; describing rocks or geological formations that did not originate from settled particles.\",\"s\":\"The geologist classified the volcanic rock as nonsedimentary because it formed from cooled lava, not deposited particles.\",\"p\":\"non-sed-ih-MEN-tuh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonsed.i.men.ta.ry\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"physics\",\"olatin\"]},{\"w\":\"nonseductive\",\"d\":\"Not appealing, tempting, or designed to attract or lure; lacking the quality of being seductive or enticing.\",\"s\":\"The advertisement used a straightforward, nonseductive approach to explain the product's benefits honestly.\",\"p\":\"non-sih-DUK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"nonse.duc.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonseeing\",\"d\":\"Unable to see; lacking the sense of sight or not exercising the ability to perceive visually.\",\"s\":\"The nonseeing creature navigated the dark cave entirely by touch and smell.\",\"p\":\"non-SEE-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.see.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsegmental\",\"d\":\"Having a body or structure that is not divided into repeated segments or sections.\",\"s\":\"The biology teacher explained that earthworms are segmental creatures, while a flatworm is nonsegmental, meaning its body does not show clearly divided, repeating sections.\",\"p\":\"non-seg-MEN-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.seg.men.tal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsegmented\",\"d\":\"Not divided into distinct, separate segments; describing an organism, structure, or object that lacks segmentation or divided parts.\",\"s\":\"Unlike insects, some simple worms have a nonsegmented body that looks like a smooth tube.\",\"p\":\"non-SEG-men-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.seg.ment.ed\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsegregating\",\"d\":\"Not separating or dividing people or things into distinct groups based on race, category, or other characteristics; promoting integration.\",\"s\":\"The nonsegregating school policy ensured that students of all backgrounds learned together in every classroom.\",\"p\":\"non-SEG-rih-gay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.seg.re.gat.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonsegregation\",\"d\":\"The absence of segregation; the condition in which people of different groups are not separated from one another in schools, housing, or public spaces.\",\"s\":\"Civil rights activists fought hard for nonsegregation in public spaces across the country.\",\"p\":\"non-seg-rih-GAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.seg.re.ga.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsegregational\",\"d\":\"Not relating to or characterized by the practice of segregation; supporting or reflecting the integration of different groups.\",\"s\":\"The nonsegregational housing policy allowed families of every background to live in any neighborhood.\",\"p\":\"non-seg-rih-GAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.seg.re.ga.tion.al\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonsegregative\",\"d\":\"Not tending to separate or segregate; describing a system, policy, or organism that does not divide things or people into isolated groups.\",\"s\":\"The teacher used a nonsegregative seating plan, mixing students randomly rather than by ability group.\",\"p\":\"non-SEG-rih-gay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.seg.rega.tive\",\"ps\":\"adjective\",\"t\":[\"politics\",\"character\",\"numbers\",\"olatin\"]},{\"w\":\"nonseismic\",\"d\":\"Not related to, caused by, or involving earthquakes or seismic activity; describing regions or events free from earthquake disturbance.\",\"s\":\"Engineers were relieved to build in a nonseismic region where earthquakes were extremely rare.\",\"p\":\"non-SYZ-mik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.seis.mic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonseizure\",\"d\":\"Not involving or related to a seizure; describing a neurological event, medication, or condition that does not cause or result in seizure activity.\",\"s\":\"The neurologist confirmed a nonseizure episode, meaning the trembling had a different cause than epilepsy.\",\"p\":\"non-SEE-zhur\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.seizure\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonselectable\",\"d\":\"Not able to be chosen or selected; describing an option, item, or candidate that cannot be picked or designated for a particular purpose.\",\"s\":\"The grayed-out menu option was nonselectable until the user completed the first step.\",\"p\":\"non-sih-LEK-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.s.e.lectable\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonselected\",\"d\":\"Not having been chosen or picked; referring to something or someone that was passed over during a selection process.\",\"s\":\"The nonselected applicants were encouraged to reapply for the program next year.\",\"p\":\"non-sih-LEK-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.s.e.lect.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonselecting\",\"d\":\"Not engaged in the process of choosing or picking; describing a system, method, or agent that makes no distinctions in selection.\",\"s\":\"A nonselecting admissions process would accept every student who applied, regardless of grades.\",\"p\":\"non-sih-LEK-ting\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.s.e.lect.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonselenium\",\"d\":\"Not containing or relating to the chemical element selenium; describing a compound or material that lacks selenium in its composition.\",\"s\":\"The chemist confirmed the compound was nonselenium based and contained no trace of the element.\",\"p\":\"non-sih-LEE-nee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.se.le.ni.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonselfadjoint\",\"d\":\"In mathematics, describing a linear operator or matrix that is not equal to its own adjoint (conjugate transpose), meaning it does not satisfy the condition of self-adjointness.\",\"s\":\"The math professor warned that nonselfadjoint matrices require extra care when computing their eigenvalues.\",\"p\":\"non-self-AD-joint\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.selfad.joint\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonseminal\",\"d\":\"Not serving as an original, influential, or foundational source of ideas; lacking the quality of being highly important or generative in a field.\",\"s\":\"The critic called the film entertaining but nonseminal, since it introduced no new ideas to cinema.\",\"p\":\"non-SEM-ih-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.sem.i.nal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsemiotic\",\"d\":\"Not relating to or based on the study of signs and symbols; describing an approach or system that does not employ semiotic analysis or sign-based meaning.\",\"s\":\"The researcher argued that pure mathematics is nonsemiotic because numbers carry meaning without symbols.\",\"p\":\"non-see-mee-AH-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.semi.otic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsemisimple\",\"d\":\"In algebra, describing a ring or module that does not satisfy the conditions of being semisimple, meaning it cannot be decomposed into a direct sum of simple components.\",\"s\":\"The algebra student struggled with nonsemisimple rings because they have a more complex structure than simple ones.\",\"p\":\"non-sem-ee-SIM-pul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.semisim.ple\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonSemitic\",\"d\":\"Not belonging to, derived from, or characteristic of the Semitic group of languages or the peoples who historically spoke them, such as Arabic or Hebrew speakers.\",\"s\":\"The linguist studied both Semitic and nonSemitic languages spoken in the same region.\",\"p\":\"non-suh-MIT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.semitic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsenate\",\"d\":\"Not belonging to or associated with a senate or senatorial body; referring to a group, committee, or individual outside the jurisdiction of a senate.\",\"s\":\"The nonsenate committee was formed to handle issues that fell outside the senate's usual jurisdiction.\",\"p\":\"non-SEN-it\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.se.n.ate\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonsenator\",\"d\":\"A person who is not a senator; someone who does not hold the office or position of senator in a legislative body.\",\"s\":\"As a nonsenator, she could still attend the hearing but was not allowed to vote on the bill.\",\"p\":\"non-SEN-uh-ter\",\"o\":\"Latin\",\"y\":8,\"bp\":32,\"sy\":\"non.se.n.a.tor\",\"ps\":\"noun\",\"t\":[\"politics\",\"character\",\"olatin\"]},{\"w\":\"nonsenatorial\",\"d\":\"Not relating to, characteristic of, or appropriate for a senator or a senate; describing roles, duties, or qualities outside the scope of senatorial office.\",\"s\":\"He held a nonsenatorial government position, advising leaders without ever running for the senate.\",\"p\":\"non-sen-uh-TOR-ee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.se.n.a.to.ri.al\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonsenile\",\"d\":\"Not affected by or showing the mental or physical decline associated with old age; describing a person whose cognitive and physical faculties remain intact regardless of age.\",\"s\":\"At ninety years old, the professor remained sharp, active, and clearly nonsenile.\",\"p\":\"non-SEE-nyl\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.se.nile\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsenior\",\"d\":\"Not holding the rank, status, or classification of a senior; referring to a person or position that has not yet reached the highest or most experienced level.\",\"s\":\"The scholarship was open only to nonsenior students who still had at least two years remaining in school.\",\"p\":\"non-SEEN-yer\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.se.nior\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsensational\",\"d\":\"Not intended to shock, thrill, or provoke strong reactions; describing reporting, writing, or presentation that is calm, measured, and free from exaggeration.\",\"s\":\"The reporter's nonsensational writing focused on facts rather than exaggerated drama.\",\"p\":\"non-sen-SAY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sen.sa.tion.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsensationalist\",\"d\":\"A person who avoids exaggerating or dramatizing events for emotional effect; someone who presents information in a factual and restrained manner without seeking to provoke excitement.\",\"s\":\"The nonsensationalist journalist was respected for reporting difficult stories calmly and accurately.\",\"p\":\"non-sen-SAY-shun-ul-ist\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.sen.sa.tion.al.ist\",\"ps\":\"noun\",\"t\":[\"stage\",\"emotions\",\"olatin\"]},{\"w\":\"nonsensationalistic\",\"d\":\"Not characterized by the tendency to present information in a shocking or exaggerated way; describing a style or approach that relies on facts rather than dramatic effect.\",\"s\":\"The documentary took a nonsensationalistic approach, presenting scientific findings without hype or alarm.\",\"p\":\"non-sen-say-shun-ul-IS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.sen.sa.tion.al.is.tic\",\"ps\":\"adjective\",\"t\":[\"stage\",\"character\",\"olatin\"]},{\"w\":\"nonsensicalness\",\"d\":\"The quality or state of being completely absurd, illogical, or lacking any reasonable meaning; the condition of making no sense whatsoever.\",\"s\":\"The students laughed at the nonsensicalness of the villain's overly complicated plan in the story.\",\"p\":\"non-SEN-sih-kul-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.sen.si.cal.ness\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsensory\",\"d\":\"Not involving or relating to the five physical senses; describing perception, experience, or information that is processed without the use of sensory organs.\",\"s\":\"Memory and imagination are considered nonsensory mental activities because they don't rely directly on sight or touch.\",\"p\":\"non-SEN-suh-ree\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.sen.so.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsensual\",\"d\":\"Not relating to or derived from physical sensation or the gratification of the senses; describing something that is intellectual, spiritual, or abstract in nature.\",\"s\":\"The poet described the relationship in purely emotional and nonsensual terms, focusing on the mind rather than the body.\",\"p\":\"non-SEN-shoo-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.sen.su.al\",\"ps\":\"adjective\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonsensuality\",\"d\":\"The absence of sensuality; the state or quality of being free from physical or sensory pleasure, often describing a purely intellectual or spiritual orientation.\",\"s\":\"Critics praised the film's nonsensuality, noting that its romance was driven by conversation rather than physical attraction.\",\"p\":\"non-sen-shoo-AL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sen.su.al.i.ty\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonsensuous\",\"d\":\"Not appealing to or involving the senses; describing something that lacks a rich, pleasurable quality associated with sensory experience and remains purely conceptual or abstract.\",\"s\":\"The philosopher argued that true understanding is nonsensuous, arising from reason alone rather than physical experience.\",\"p\":\"non-SEN-shoo-us\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.sen.su.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsentence\",\"d\":\"A group of words that does not constitute a grammatically complete sentence because it lacks a required element such as a subject or a main verb.\",\"s\":\"The grammar teacher circled the fragment on the paper and wrote 'nonsentence' because it lacked a verb.\",\"p\":\"non-SEN-tens\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.sen.tence\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"wordwords\",\"olatin\"]},{\"w\":\"nonsentient\",\"d\":\"Lacking the capacity to perceive, feel, or experience sensations; describing beings or objects, such as rocks or simple machines, that have no conscious awareness.\",\"s\":\"Rocks and rivers are nonsentient objects that cannot feel pain or awareness.\",\"p\":\"non-SEN-shent\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sen.tient\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"tools\",\"olatin\"]},{\"w\":\"nonsentimental\",\"d\":\"Not influenced by or expressing tender emotions or nostalgic feelings; describing a practical, detached, or objective attitude that avoids emotional attachment.\",\"s\":\"The coach gave a nonsentimental speech focused entirely on strategy rather than feelings.\",\"p\":\"non-sen-tih-MEN-tul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sen.ti.men.tal\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonseparable\",\"d\":\"Not capable of being divided, detached, or set apart; in mathematics, describing a topological space that does not have a countable dense subset.\",\"s\":\"The two chemicals were nonseparable once combined, forming a permanent new compound.\",\"p\":\"non-SEP-ur-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.sep.a.ra.ble\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonseptal\",\"d\":\"Not relating to or involving a septum, which is a dividing wall or partition in anatomy; describing a structure or condition that lacks such a partition.\",\"s\":\"The biologist noted that the simple fungal strand was nonseptal, meaning it lacked the walls that divide cells.\",\"p\":\"non-SEP-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sep.tal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonseptate\",\"d\":\"In biology, describing a cell, filament, or fungal hypha that lacks cross-walls or septa, forming a continuous, undivided tube or structure.\",\"s\":\"The scientist noted that the nonseptate fungal hyphae lacked internal dividing walls.\",\"p\":\"non-SEP-tayt\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sep.tate\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonseptic\",\"d\":\"Not caused by, relating to, or involving harmful bacteria or infection; describing a wound, condition, or environment that is free from pathogenic contamination.\",\"s\":\"The doctor confirmed the wound was nonseptic and showed no signs of bacterial infection.\",\"p\":\"non-SEP-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sep.tic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"ecology\",\"olatin\"]},{\"w\":\"nonsepticemic\",\"d\":\"Not related to or caused by septicemia, which is a serious bloodstream infection; describing a condition or patient in whom bacteria have not spread through the blood.\",\"s\":\"The lab results showed the patient's condition was nonsepticemic, meaning bacteria had not entered the bloodstream.\",\"p\":\"non-sep-tih-SEE-mik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.sep.ticemic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonsequel\",\"d\":\"A work, such as a film or book, that does not serve as a continuation of a previous story; something that stands entirely on its own without following from an earlier installment.\",\"s\":\"The director insisted the new film was a nonsequel, standing completely on its own without referencing the original story.\",\"p\":\"non-SEE-kwul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.se.quel\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonsequence\",\"d\":\"A lack of logical or ordered progression; a situation in which events, steps, or elements do not follow one another in a meaningful or expected order.\",\"s\":\"The random events in the dream formed a nonsequence that made no logical order.\",\"p\":\"non-SEE-kwens\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.se.quence\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonsequenced\",\"d\":\"Not arranged or organized in a particular order or sequence; describing data, instructions, or events that have not been placed in a structured series.\",\"s\":\"The nonsequenced data made it difficult for scientists to analyze the genetic information properly.\",\"p\":\"non-SEE-kwenst\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.se.quenced\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsequestered\",\"d\":\"Not isolated, set apart, or separated from the general population or environment; describing a person, group, or substance that remains in open contact with others.\",\"s\":\"The nonsequestered jury members were allowed to return home each evening during the trial.\",\"p\":\"non-sih-KWES-terd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.se.questered\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonsequitur\",\"d\":\"A statement or conclusion that does not logically follow from the preceding argument or evidence; a remark that is completely unrelated to what was just said.\",\"s\":\"When asked about homework, Jake's reply about dinosaurs was a total nonsequitur that left everyone confused.\",\"p\":\"non-SEK-wih-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.se.quitur\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonserf\",\"d\":\"A person who is not a serf; someone who is free from the feudal obligations of serfdom and is not bound to work the land of a lord.\",\"s\":\"As a nonserf, the medieval craftsman was free to move between towns and choose his own work.\",\"p\":\"non-SURF\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.serf\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonserial\",\"d\":\"Not published, broadcast, or presented in a series of successive installments; describing a work that is complete and self-contained rather than divided into sequential parts.\",\"s\":\"The nonserial novel told one complete story rather than continuing across multiple installments.\",\"p\":\"non-SEER-ee-ul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.se.ri.al\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonserialized\",\"d\":\"Not converted into or published as a series of separate installments; describing content that is released or presented as a whole unit rather than in sequential episodes.\",\"s\":\"The nonserialized podcast episodes could be listened to in any order without missing context.\",\"p\":\"non-SEER-ee-ul-yzd\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.se.ri.al.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonserially\",\"d\":\"Not in a serial or sequential manner; describing something that occurs or is presented all at once rather than in a succession of ordered parts or installments.\",\"s\":\"The chapters were published nonserially, all appearing together in one printed volume.\",\"p\":\"non-SEER-ee-ul-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.se.ri.al.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonserious\",\"d\":\"Not grave, earnest, or requiring significant concern; describing a situation, person, or matter that is lighthearted, trivial, or lacking in great importance.\",\"s\":\"The comedian kept the mood nonserious by cracking jokes throughout the entire presentation.\",\"p\":\"non-SEER-ee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.se.ri.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonserological\",\"d\":\"Not involving or relating to serology, the study of blood serum and its reactions; describing tests or methods that do not use blood serum analysis.\",\"s\":\"The nonserological test diagnosed the disease without examining any blood serum samples.\",\"p\":\"non-seer-oh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sero.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonserotonin\",\"d\":\"Not involving or related to serotonin, the chemical messenger in the brain and body; describing pathways or mechanisms that operate independently of serotonin.\",\"s\":\"The researcher studied nonserotonin pathways to understand mood changes that couldn't be explained by serotonin alone.\",\"p\":\"non-sair-oh-TOH-nin\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.sero.tonin\",\"ps\":\"adjective\",\"t\":[\"body\",\"chemistry\",\"tools\",\"olatin\"]},{\"w\":\"nonserrated\",\"d\":\"Not having a jagged, saw-like edge; describing a surface or blade that is smooth and unnotched rather than toothed.\",\"s\":\"The chef preferred a nonserrated blade for slicing soft tomatoes cleanly.\",\"p\":\"non-SAIR-ay-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.ser.rat.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"tools\",\"olatin\"]},{\"w\":\"nonserum\",\"d\":\"Not consisting of or derived from blood serum; describing a substance or preparation that contains no serum component.\",\"s\":\"The nonserum treatment used plant extracts instead of blood-derived components.\",\"p\":\"non-SEER-um\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.serum\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonservant\",\"d\":\"A person who is not employed or acting in the capacity of a servant; someone who does not hold a subordinate service role.\",\"s\":\"As a nonservant employee, she managed her own schedule without answering to a household employer.\",\"p\":\"non-SUR-vunt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.ser.vant\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonserver\",\"d\":\"A person or entity that does not serve in a particular capacity, such as one who does not initiate play in a sport or does not provide a specific service.\",\"s\":\"In the game, the nonserver had to wait patiently while the other player started each round.\",\"p\":\"non-SUR-ver\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.serv.er\",\"ps\":\"noun\",\"t\":[\"stage\",\"sports\",\"olatin\"]},{\"w\":\"nonserving\",\"d\":\"Not currently engaged in serving or providing a service; describing someone or something that plays no active serving role.\",\"s\":\"The nonserving members of the committee advised on policy without taking active roles in operations.\",\"p\":\"non-SUR-ving\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.serv.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsessile\",\"d\":\"Not permanently attached to a surface; describing an organism or structure that is free-moving rather than fixed in one place.\",\"s\":\"Unlike barnacles, the nonsessile organisms could move freely along the ocean floor.\",\"p\":\"non-SES-ile\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nons.es.sile\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsettleable\",\"d\":\"Not capable of being settled, resolved, or deposited; describing particles that remain suspended or disputes that cannot be brought to a conclusion.\",\"s\":\"The lawsuit involved nonsettleable claims that had to be decided by a judge, not negotiated privately.\",\"p\":\"non-SET-ul-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.set.tleable\",\"ps\":\"adjective\",\"t\":[\"physics\",\"logic\",\"olatin\"]},{\"w\":\"nonsettled\",\"d\":\"Not established, resolved, or stabilized; describing a situation, community, or question that remains unsettled and in flux.\",\"s\":\"The nonsettled dispute between the two neighbors dragged on for years without resolution.\",\"p\":\"non-SET-uld\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.set.tled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsevere\",\"d\":\"Not intense, harsh, or serious in degree; describing a condition, symptom, or situation that is mild rather than extreme.\",\"s\":\"The doctor was relieved to classify the patient's injury as nonsevere and easily treatable.\",\"p\":\"non-suh-VEER\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.se.vere\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonsexism\",\"d\":\"The absence of discrimination or prejudice based on a person's sex; an attitude or policy that treats all genders with equal fairness.\",\"s\":\"The school promoted nonsexism by ensuring both boys and girls had equal opportunities in all activities.\",\"p\":\"non-SEK-siz-um\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sex.ism\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonshadowed\",\"d\":\"Not darkened or obscured by a shadow; describing an area or image that receives full, unobstructed light with no dark regions.\",\"s\":\"The photographer wanted a nonshadowed portrait, so she set up lights on all sides of the subject.\",\"p\":\"non-SHAD-ohd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.shad.owed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshaking\",\"d\":\"Not trembling, vibrating, or quivering; describing something that remains completely steady and free from any shaking motion.\",\"s\":\"The surgeon's nonshaking hands allowed her to perform the delicate procedure with perfect precision.\",\"p\":\"non-SHAYK-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.shak.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshallow\",\"d\":\"Not lacking depth; describing water, thought, or analysis that has significant depth rather than being superficial or shallow.\",\"s\":\"The philosopher's nonshallow arguments forced students to think deeply about complex moral questions.\",\"p\":\"non-SHAL-oh\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.shal.low\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshaman\",\"d\":\"A person who is not a shaman and does not practice shamanism; someone lacking the spiritual or ritualistic role of a traditional healer.\",\"s\":\"As a nonshaman, the village elder led ceremonies based on written tradition rather than spiritual healing practices.\",\"p\":\"non-SHAH-mun\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.shaman\",\"ps\":\"noun\",\"t\":[\"religion\",\"festivals\",\"character\",\"olatin\"]},{\"w\":\"nonshamanic\",\"d\":\"Not relating to or characteristic of shamanism; describing practices, beliefs, or rituals that have no connection to shamanic traditions.\",\"s\":\"The nonshamanic ceremony was led by a priest who followed written religious texts rather than spiritual trance.\",\"p\":\"non-shuh-MAN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.shaman.ic\",\"ps\":\"adjective\",\"t\":[\"religion\",\"festivals\",\"logic\",\"olatin\"]},{\"w\":\"nonshamanistic\",\"d\":\"Not based on or associated with shamanistic beliefs or practices; describing a worldview or ceremony that falls entirely outside shamanism.\",\"s\":\"The anthropologist compared nonshamanistic rituals to traditional healing ceremonies in her research.\",\"p\":\"non-shuh-muh-NIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.shaman.is.tic\",\"ps\":\"adjective\",\"t\":[\"religion\",\"logic\",\"olatin\"]},{\"w\":\"nonshameful\",\"d\":\"Not causing or deserving shame; describing an action or quality that carries no stigma or embarrassment whatsoever.\",\"s\":\"She gave a nonshameful account of her past mistakes, speaking openly and without embarrassment.\",\"p\":\"non-SHAYM-ful\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.shame.ful\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshaped\",\"d\":\"Not formed into a definite or intentional shape; describing material that is formless, unstructured, or not yet molded.\",\"s\":\"The nonshaped clay blob sat on the table, waiting for the artist to mold it into something meaningful.\",\"p\":\"non-SHAYPT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.shaped\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshared\",\"d\":\"Not held in common with others; describing resources, information, or experiences that belong exclusively to one individual or group.\",\"s\":\"The twins had very different personalities because of their nonshared environments growing up.\",\"p\":\"non-SHAIRD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.shared\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshareholder\",\"d\":\"A person or entity that does not own shares in a company; someone who has no equity stake or ownership interest in a corporation.\",\"s\":\"As a nonshareholder employee, she had no voting rights at the company's annual stockholder meeting.\",\"p\":\"non-SHAIR-hohl-der\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.share.hold.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonshareholding\",\"d\":\"Not owning or possessing shares in a company; describing a status or arrangement in which no stock or equity is held.\",\"s\":\"The nonshareholding manager still played an important role in running the company's daily operations.\",\"p\":\"non-SHAIR-hohl-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.share.hold.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshearable\",\"d\":\"Not capable of being cut, sheared, or divided by a shearing force; describing a material that resists being sliced or clipped.\",\"s\":\"The engineer noted that the nonshearable material could not be cut by the machine's blades.\",\"p\":\"non-SHEER-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.s.hear.able\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonshearing\",\"d\":\"Not involving the process of cutting or shearing; describing a force, action, or material that produces no shearing effect.\",\"s\":\"The nonshearing fabric stayed perfectly intact even under heavy pressure.\",\"p\":\"non-SHEER-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.s.hear.ing\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonshedding\",\"d\":\"Not releasing or losing fur, skin, leaves, or other material; describing an animal or plant that does not shed its outer covering.\",\"s\":\"My family chose a nonshedding dog breed so the furniture would stay fur-free.\",\"p\":\"non-SHED-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.shed.ding\",\"ps\":\"adjective\",\"t\":[\"body\",\"animals\",\"botany\",\"olatin\"]},{\"w\":\"nonsheep\",\"d\":\"Any animal or entity that is not a sheep; used to distinguish non-ovine animals or, figuratively, someone who does not blindly follow others.\",\"s\":\"The farmer separated the nonsheep animals into a different pasture from the flock.\",\"p\":\"non-SHEEP\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.sheep\",\"ps\":\"noun\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonshell\",\"d\":\"Not having or relating to a shell; describing an organism, structure, or material that lacks an outer protective shell casing.\",\"s\":\"The biologist studied nonshell mollusks that had lost their protective outer coverings over time.\",\"p\":\"non-SHEL\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.shell\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshelled\",\"d\":\"Not enclosed in or protected by a shell; describing an organism or object from which the shell has been removed or that never had one.\",\"s\":\"The recipe called for nonshelled peas, meaning they were already removed from their pods.\",\"p\":\"non-SHELD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.shelled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshielded\",\"d\":\"Not protected by a shield or shielding material; describing something that is exposed and lacks a protective barrier against harm or interference.\",\"s\":\"The nonshielded wires were exposed to interference from nearby electronics.\",\"p\":\"non-SHEELD-id\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.shield.ed\",\"ps\":\"adjective\",\"t\":[\"war\",\"olatin\"]},{\"w\":\"nonshifted\",\"d\":\"Not moved, displaced, or changed in position; describing something that has remained in its original place without any shift or adjustment.\",\"s\":\"The nonshifted data remained in its original position after the computer ran the program.\",\"p\":\"non-SHIF-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.shift.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshiny\",\"d\":\"Lacking luster or gloss; describing a surface that does not reflect light brightly and appears dull or matte instead of shiny.\",\"s\":\"She chose a nonshiny finish for her phone case so it wouldn't show fingerprints.\",\"p\":\"non-SHIY-nee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.shiny\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshipment\",\"d\":\"The failure or absence of a shipment; a situation in which goods that were expected to be sent were not dispatched or delivered.\",\"s\":\"The store issued a refund due to the nonshipment of the ordered items after two weeks.\",\"p\":\"non-SHIP-munt\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.ship.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonshipper\",\"d\":\"A person or company that does not ship goods; someone who is not involved in the transportation or dispatching of products.\",\"s\":\"As a nonshipper, the local artist sold all her work directly from her studio.\",\"p\":\"non-SHIP-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ship.per\",\"ps\":\"noun\",\"t\":[\"character\",\"seafaring\",\"olatin\"]},{\"w\":\"nonshipping\",\"d\":\"Not involving the transport or delivery of goods; describing a business, policy, or item that does not include or require shipping.\",\"s\":\"The nonshipping vendor required all customers to pick up their orders in person.\",\"p\":\"non-SHIP-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.ship.ping\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonshivering\",\"d\":\"Not involving or producing shivering; describing a process, such as certain types of heat generation in the body, that keeps an organism warm without muscle trembling.\",\"s\":\"Scientists studied nonshivering heat production in newborns who generate warmth through brown fat.\",\"p\":\"non-SHIV-er-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.shiv.er.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonshoe\",\"d\":\"Something that is worn on the foot but does not qualify as a true shoe, such as a sandal, slipper, or other open footwear; any foot covering that falls outside the strict definition of a shoe.\",\"s\":\"The yoga instructor preferred nonshoe footwear like toe socks during her classes.\",\"p\":\"NON-shoo\",\"o\":\"Latin\",\"y\":9,\"bp\":19,\"sy\":\"non.shoe\",\"ps\":\"noun\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonshooting\",\"d\":\"Not involving or characterized by shooting; describing a player, situation, or event in which no shots are fired or attempted.\",\"s\":\"The nonshooting players on the team focused on defense and passing during the game.\",\"p\":\"non-SHOOT-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.shoot.ing\",\"ps\":\"adjective\",\"t\":[\"character\",\"sports\",\"olatin\"]},{\"w\":\"nonshopper\",\"d\":\"A person who does not engage in shopping, either by choice or circumstance, often preferring to avoid stores and commercial purchases altogether.\",\"s\":\"My dad is a confirmed nonshopper who avoids malls at all costs.\",\"p\":\"non-SHOP-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.shop.per\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonshopping\",\"d\":\"The state or practice of refraining from shopping; not involving or related to any purchasing activity in stores or online.\",\"s\":\"She spent a nonshopping Saturday hiking in the mountains instead of hitting the stores.\",\"p\":\"non-SHOP-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.shop.ping\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshower\",\"d\":\"not involving a fall of rain; also, a person who does not wash under falling water\",\"s\":\"The forecast promised a nonshower afternoon, so the class left their umbrellas in the cupboard.\",\"p\":\"non-SHOW-er\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.show.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonshowy\",\"d\":\"Not flashy, gaudy, or attention-seeking; describing something or someone that is modest, understated, and does not draw unnecessary attention to itself.\",\"s\":\"The garden featured nonshowy plants with subtle colors that blended into the landscape.\",\"p\":\"non-SHOH-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.showy\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshreddable\",\"d\":\"Not capable of being torn, cut, or shredded into small pieces; describing a material that resists the action of shredding by being too tough or specially constructed.\",\"s\":\"The bank stored documents in a nonshreddable format to ensure they could never be destroyed.\",\"p\":\"non-SHRED-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.shred.dable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshredded\",\"d\":\"Not torn apart, cut up, or broken into shreds; remaining whole and intact rather than having been put through a shredding process.\",\"s\":\"The chef topped the pizza with nonshredded cheese, slicing it into thick rounds instead.\",\"p\":\"non-SHRED-id\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.shred.ded\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshrink\",\"d\":\"Designed or treated so as not to shrink when washed, heated, or subjected to moisture; describing a fabric or material that retains its original size and shape under normal conditions.\",\"s\":\"The label promised the nonshrink sweater would fit perfectly even after many washes.\",\"p\":\"non-SHRINK\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.shrink\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonshrinkable\",\"d\":\"Not capable of shrinking; describing a material or fabric that has been specially treated or constructed so that it will not reduce in size when exposed to heat or water.\",\"s\":\"The designer used a nonshrinkable wool blend to ensure the coat kept its shape.\",\"p\":\"non-SHRINK-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.shrink.able\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonshrinking\",\"d\":\"Not shrinking or reducing in size; describing a material that maintains its original dimensions even when washed, dried, or exposed to heat and moisture.\",\"s\":\"The nonshrinking material made it easy to wash the uniforms without worrying about size.\",\"p\":\"non-SHRINK-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.shrink.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonshunted\",\"d\":\"Not redirected or diverted to a side path; in electrical or medical contexts, describing a circuit or system in which current or fluid has not been diverted through an alternate route.\",\"s\":\"The nonshunted electrical circuit allowed full current to flow through the main path.\",\"p\":\"non-SHUN-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.shunt.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"physics\",\"maps\",\"olatin\"]},{\"w\":\"nonshy\",\"d\":\"Not timid, bashful, or reserved; describing a person or animal that is bold, outgoing, and comfortable interacting with others in social situations.\",\"s\":\"The nonshy student volunteered immediately when the teacher asked for a class presenter.\",\"p\":\"non-SHY\",\"o\":\"Latin\",\"y\":8,\"bp\":18,\"sy\":\"non.shy\",\"ps\":\"adjective\",\"t\":[\"animals\",\"character\",\"olatin\"]},{\"w\":\"nonsigmoidal\",\"d\":\"Not having the characteristic S-shaped curve known as a sigmoid shape; describing a graph, relationship, or biological response that follows a different mathematical pattern than the classic S-curve.\",\"s\":\"The nonsigmoidal curve on the graph showed a simple straight-line relationship between the two variables.\",\"p\":\"non-sig-MOY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.sigmoidal\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsignalling\",\"d\":\"Not producing, sending, or involving a signal; describing a molecule, cell, or process that does not participate in transmitting information or chemical messages.\",\"s\":\"The nonsignalling molecule did not trigger any response in the cells it contacted.\",\"p\":\"non-SIG-nul-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":22,\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsignatory\",\"d\":\"A person, organization, or nation that has not signed a particular treaty, agreement, or document and is therefore not bound by its terms.\",\"s\":\"Several nonsignatory countries refused to be bound by the terms of the international treaty.\",\"p\":\"non-SIG-nuh-tор-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonsigna.to.ry\",\"ps\":\"noun\",\"t\":[\"nations\",\"politics\",\"olatin\"]},{\"w\":\"nonsigned\",\"d\":\"Not bearing a signature; describing a document, contract, or artwork that has not been officially signed or authenticated by the relevant party.\",\"s\":\"The nonsigned contract had no legal force because neither party had written their name.\",\"p\":\"non-SYND\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.signed\",\"ps\":\"adjective\",\"t\":[\"maps\",\"painting\",\"law\",\"olatin\"]},{\"w\":\"nonsigner\",\"d\":\"A person who refuses or has chosen not to sign a particular document, petition, contract, or agreement.\",\"s\":\"The nonsigner of the petition disagreed with its goals and refused to add her name.\",\"p\":\"non-SY-ner\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sign.er\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonsignificance\",\"d\":\"The quality or state of lacking statistical or practical significance; the condition in which a result or difference is too small or uncertain to be considered meaningful or reliable.\",\"s\":\"The researcher acknowledged the nonsignificance of her findings, noting they could be due to chance.\",\"p\":\"non-sig-NIF-ih-kunts\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.signif.i.cance\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsignificant\",\"d\":\"attributable to chance\",\"s\":\"The difference between the two groups was nonsignificant, meaning it could have happened by chance.\",\"p\":\"non-sig-NIF-ih-kunt\",\"o\":\"Latin\",\"y\":7,\"bp\":27,\"sy\":\"non.signif.i.cant\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsignificantly\",\"d\":\"In a manner that is not statistically or practically significant; used to describe a result or difference so small that it cannot be reliably distinguished from chance or random variation.\",\"s\":\"The two test scores differed nonsignificantly, so the teacher concluded both methods worked equally well.\",\"p\":\"non-sig-NIF-ih-kunt-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.signif.i.cant.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonsigning\",\"d\":\"The act or practice of not signing a document, contract, or agreement; describing a situation or person characterized by a refusal or failure to sign.\",\"s\":\"The nonsigning athlete was free to join any team since she had no official contract.\",\"p\":\"non-SY-ning\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sign.ing\",\"ps\":\"adjective\",\"t\":[\"law\",\"character\",\"olatin\"]},{\"w\":\"nonsilence\",\"d\":\"The presence of sound, noise, or vocal activity; the condition of not being silent, often referring to ongoing background noise or deliberate speech that persists in an environment.\",\"s\":\"The constant nonsilence of the city streets made it hard for her to concentrate.\",\"p\":\"non-SY-lunts\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.si.lence\",\"ps\":\"noun\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonsilenced\",\"d\":\"Not having been quieted, suppressed, or muted; describing a gene, voice, or mechanism that continues to function and express itself without being shut down.\",\"s\":\"The nonsilenced gene continued to produce its protein even after the experiment attempted to shut it down.\",\"p\":\"non-SY-lunst\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.si.lenced\",\"ps\":\"adjective\",\"t\":[\"tools\",\"olatin\"]},{\"w\":\"nonsilicon\",\"d\":\"Not made from or based on silicon; describing a semiconductor, electronic component, or material that uses an alternative substance instead of silicon as its primary element.\",\"s\":\"Scientists are developing nonsilicon computer chips made from carbon-based materials.\",\"p\":\"non-SIL-ih-kon\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.sil.i.con\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonsilicone\",\"d\":\"Not containing or made from silicone; describing a product, coating, or material that is manufactured without the use of silicone polymers.\",\"s\":\"The chef used a nonsilicone spatula because it was safer for cooking at high temperatures.\",\"p\":\"non-SIL-ih-kohn\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.sil.i.cone\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsiliconized\",\"d\":\"Not treated or coated with silicone; describing a surface, paper, or material that has not undergone silicone application and therefore does not have silicone's characteristic slippery or non-stick properties.\",\"s\":\"The nonsiliconized paper was used in the printer because it absorbed ink more effectively.\",\"p\":\"non-SIL-ih-kuh-nyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sil.i.conized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsilicotic\",\"d\":\"Not relating to, caused by, or characteristic of silicosis, the lung disease caused by inhaling silica dust; describing a condition, patient, or lung tissue that is free from silicosis.\",\"s\":\"The doctor confirmed the miner's lung condition was nonsilicotic, meaning it was not caused by silica dust.\",\"p\":\"non-sil-ih-KOT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.sil.i.cot.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonsilk\",\"d\":\"Not made of or containing silk; describing a fabric, thread, or textile product that is manufactured from materials other than natural silk fibers.\",\"s\":\"The budget dress was made of nonsilk fabric that still had a smooth, shiny appearance.\",\"p\":\"non-SILK\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.silk\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonsilly\",\"d\":\"Not foolish, absurd, or lacking seriousness; describing behavior, speech, or a person that is sensible, rational, and appropriately serious for the given situation.\",\"s\":\"The teacher appreciated the nonsilly questions students asked during the science experiment.\",\"p\":\"non-SIL-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sil.ly\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonsilver\",\"d\":\"Not made of, containing, or coated with silver; describing an object, compound, or material that uses a substance other than silver as its primary component.\",\"s\":\"The jeweler used nonsilver metals like copper and brass to create affordable decorative pieces.\",\"p\":\"non-SIL-ver\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sil.ver\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"colors\",\"olatin\"]},{\"w\":\"nonsilvered\",\"d\":\"Not coated, plated, or treated with a layer of silver; describing a mirror, surface, or object that lacks the reflective silver backing or silver coating typically applied in manufacturing.\",\"s\":\"The nonsilvered mirror coating made it less reflective but more durable for outdoor use.\",\"p\":\"non-SIL-verd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sil.vered\",\"ps\":\"adjective\",\"t\":[\"household\",\"colors\",\"olatin\"]},{\"w\":\"nonsimilar\",\"d\":\"Not alike or resembling one another; describing things or people that are clearly different from each other in appearance, nature, or qualities.\",\"s\":\"The two rock samples were nonsimilar in texture, color, and mineral composition.\",\"p\":\"non-SIM-ih-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.sim.i.lar\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsimilarity\",\"d\":\"The quality or state of being unlike or different; the absence of resemblance or shared characteristics between two or more things being compared.\",\"s\":\"Scientists noted the nonsimilarity between the two species despite their shared habitat.\",\"p\":\"non-sim-ih-LAIR-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sim.i.lar.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsimilarly\",\"d\":\"In a manner that is not alike or comparable; used to describe how two things differ in the way they behave, appear, or relate to something else.\",\"s\":\"The twins behaved nonsimilarly when faced with the same challenge, surprising their parents.\",\"p\":\"non-SIM-ih-ler-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.sim.i.lar.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonsimple\",\"d\":\"Not simple or straightforward; involving complexity, multiple parts, or complications that make something difficult to understand, classify, or resolve with a basic approach.\",\"s\":\"The math problem appeared nonsimple at first glance but became clear after careful reading.\",\"p\":\"non-SIM-pul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sim.ple\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsimplex\",\"d\":\"In mathematics, describing a geometric shape, space, or structure that does not qualify as a simplex, the most basic type of polytope in its dimension, such as a triangle or tetrahedron.\",\"s\":\"The geometry professor explained that nonsimplex shapes require more complex mathematical descriptions.\",\"p\":\"non-SIM-pleks\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sim.plex\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsimplicial\",\"d\":\"In mathematics, not having the properties of or relating to a simplicial complex; describing a topological space or geometric structure that cannot be broken down into simple triangular components called simplices.\",\"s\":\"The advanced topology homework focused on nonsimplicial complexes that couldn't be broken into triangles.\",\"p\":\"non-sim-PLISH-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sim.pli.cial\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsimply\",\"d\":\"In a way that is not simple or uncomplicated; used in mathematics or logic to describe a space or structure that does not satisfy the condition of being simply connected or straightforwardly organized.\",\"s\":\"The instructions were written nonsimply, making it hard for beginners to follow along.\",\"p\":\"non-SIM-plee\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sim.ply\",\"ps\":\"adverb\",\"t\":[\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"nonsimulated\",\"d\":\"Not artificially created, imitated, or reproduced by a computer or other simulation method; describing something that is genuine, real, and occurring in actual conditions rather than in a modeled or virtual environment.\",\"s\":\"The training exercise used nonsimulated equipment to prepare soldiers for real conditions.\",\"p\":\"non-SIM-yoo-lay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.sim.u.lat.ed\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonsimulation\",\"d\":\"The absence or lack of simulation; a state or condition in which something is real or actual rather than being imitated or artificially reproduced.\",\"s\":\"The researchers valued the nonsimulation approach, testing their ideas in real-world conditions.\",\"p\":\"non-sim-yuh-LAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sim.u.la.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsimultaneous\",\"d\":\"Not occurring at the same time; happening at different or separate moments rather than together.\",\"s\":\"The two earthquakes were nonsimultaneous, occurring hours apart despite being in the same region.\",\"p\":\"non-sy-mul-TAY-nee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.si.mul.ta.ne.ous\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonsinger\",\"d\":\"A person who does not sing or who is not considered a singer by training or profession.\",\"s\":\"Jake described himself as a nonsinger but still enjoyed humming along to his favorite songs.\",\"p\":\"non-SING-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.singer\",\"ps\":\"noun\",\"t\":[\"music\",\"jobs\",\"olatin\"]},{\"w\":\"nonsinging\",\"d\":\"Not involving or relating to the act of singing; describing a role, activity, or function that does not include vocal performance.\",\"s\":\"The nonsinging role in the musical still required strong acting and dancing skills.\",\"p\":\"non-SING-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sing.ing\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonsingle\",\"d\":\"Not released or marketed as a single; referring to a song or recording that was not chosen as a standalone commercial release.\",\"s\":\"The album's nonsingle tracks were often fans' favorites because they felt more personal and raw.\",\"p\":\"non-SING-gul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.s.in.gle\",\"ps\":\"adjective\",\"t\":[\"music\",\"economy\",\"olatin\"]},{\"w\":\"nonsinglet\",\"d\":\"In physics or chemistry, describing a quantum state that is not a singlet, meaning it has more than one possible spin or energy configuration.\",\"s\":\"The physics student learned that a nonsinglet particle state has multiple components rather than just one.\",\"p\":\"non-SING-glit\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.s.in.glet\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"olatin\"]},{\"w\":\"nonsingular\",\"d\":\"In mathematics, describing a matrix or transformation that has an inverse and a nonzero determinant, meaning it does not collapse dimensions.\",\"s\":\"The nonsingular matrix could be inverted, which was essential for solving the equation system.\",\"p\":\"non-SING-gyuh-lur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.sin.gu.lar\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsinkable\",\"d\":\"Not capable of sinking; designed or constructed in a way that prevents it from going below the surface of water.\",\"s\":\"Engineers designed the vessel to be as nonsinkable as possible, adding multiple watertight compartments.\",\"p\":\"non-SINK-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.sink.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsinusoidal\",\"d\":\"Not shaped like or following the pattern of a sine wave; describing a waveform or signal whose shape is irregular or non-periodic.\",\"s\":\"The engineer noted that the electrical signal was nonsinusoidal, with sharp peaks instead of smooth waves.\",\"p\":\"non-sy-nuh-SOY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.si.nu.soidal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsiphonate\",\"d\":\"In biology, describing a mollusk or organism that does not possess a siphon, the tube-like structure used for drawing in or expelling water.\",\"s\":\"The biologist classified the mollusk as nonsiphonate because it lacked a siphon structure.\",\"p\":\"non-SY-fuh-nayt\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.siphonate\",\"ps\":\"adjective\",\"t\":[\"marine\",\"painting\",\"olatin\"]},{\"w\":\"nonsituational\",\"d\":\"Not dependent on or determined by a particular situation or set of circumstances; applying generally rather than to a specific context.\",\"s\":\"The psychologist argued that the behavior was nonsituational, meaning it stayed consistent regardless of environment.\",\"p\":\"non-sich-oo-AY-shun-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.si.t.u.a.tion.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonskater\",\"d\":\"A person who does not skate or who lacks the skill or habit of skating on ice or wheels.\",\"s\":\"As a nonskater, Maya cheered from the sidelines while her friends raced around the ice rink.\",\"p\":\"non-SKAYT-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.skater\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonsked\",\"d\":\"Not operating on a fixed or regular schedule; referring especially to an airline or flight service that does not follow a published timetable.\",\"s\":\"The small nonsked airline offered flexible charter flights without a fixed timetable.\",\"p\":\"non-SKED\",\"o\":\"Latin\",\"y\":8,\"bp\":17,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonskeletal\",\"d\":\"Not relating to or forming part of the skeleton; describing tissues, cells, or structures that are not bone or cartilage.\",\"s\":\"The doctor studied the patient's nonskeletal tissues, including the muscles and organs, for signs of disease.\",\"p\":\"non-SKEL-ih-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"nonskele.tal\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonskeletonized\",\"d\":\"Not reduced to or resembling a skeleton; describing a leaf, structure, or object that still retains its full flesh or material rather than having it removed.\",\"s\":\"The leaf was nonskeletonized, still retaining its full green surface without any damage from insects.\",\"p\":\"non-SKEL-ih-tuh-nyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"nonskele.tonized\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonskeptic\",\"d\":\"A person who is not a skeptic; someone who tends to accept claims or beliefs without demanding strong proof or evidence.\",\"s\":\"As a nonskeptic, she accepted the new scientific findings without demanding extra proof.\",\"p\":\"non-SKEP-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"nonskep.tic\",\"ps\":\"noun\",\"t\":[\"character\",\"logic\",\"olatin\"]},{\"w\":\"nonskeptical\",\"d\":\"Not characterized by doubt or questioning; tending to accept ideas or information without critical examination or suspicion.\",\"s\":\"The nonskeptical audience believed every claim the presenter made without asking questions.\",\"p\":\"non-SKEP-tih-kul\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonskep.ti.cal\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonskewed\",\"d\":\"Not twisted, distorted, or asymmetrically distributed; describing data, shapes, or distributions that are balanced and symmetrical.\",\"s\":\"The nonskewed data set made the statistical analysis much more straightforward and reliable.\",\"p\":\"non-SKYOOD\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonskier\",\"d\":\"A person who does not ski or who does not participate in the sport of skiing.\",\"s\":\"As a nonskier, Daniel spent the mountain vacation reading by the fireplace while others hit the slopes.\",\"p\":\"non-SKEE-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.ski.er\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonslack\",\"d\":\"Not loose, limp, or lacking tension; describing a rope, cable, or system that is taut and firm rather than sagging.\",\"s\":\"The nonslack rope held the tent firmly in place even during the windstorm.\",\"p\":\"non-SLAK\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.slack\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonslave\",\"d\":\"A person who is not a slave; an individual who is free and not held in bondage or forced servitude.\",\"s\":\"In the historical debate, the nonslave population still faced many economic and social challenges.\",\"p\":\"non-SLAYV\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.slave\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonslaveholder\",\"d\":\"A person who does not own slaves; especially used historically to describe someone in a slaveholding society who did not participate in the ownership of enslaved people.\",\"s\":\"Many nonslaveholder farmers in the South before the Civil War owned small plots of land they worked themselves.\",\"p\":\"non-SLAYV-hohl-dur\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.slave.hold.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonslaveholding\",\"d\":\"Not owning or involving the ownership of slaves; describing a person, region, or society that does not practice or support slaveholding.\",\"s\":\"The historian focused her research on nonslaveholding communities in the antebellum South.\",\"p\":\"non-SLAYV-hohl-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.slave.hold.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonSlavic\",\"d\":\"Not belonging to or characteristic of the Slavic peoples, languages, or cultures of Eastern Europe and Central Asia.\",\"s\":\"The linguist compared nonSlavic European languages with Polish and Russian to find common roots.\",\"p\":\"non-SLAV-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.slav.ic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsleep\",\"d\":\"A state or period in which sleep does not occur; the condition of being awake or of not experiencing normal sleep.\",\"s\":\"Doctors warned that prolonged nonsleep states can seriously damage memory and immune function.\",\"p\":\"non-SLEEP\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.sleep\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsliced\",\"d\":\"Not cut into slices; remaining whole or uncut, as in a loaf of bread or other food item that has not been divided into portions.\",\"s\":\"The bakery offered the bread as nonsliced so customers could cut it to their preferred thickness.\",\"p\":\"non-SLYST\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.sliced\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"numbers\",\"olatin\"]},{\"w\":\"nonsliding\",\"d\":\"Not moving or designed to move by sliding; describing a door, panel, or component that does not operate by gliding along a track.\",\"s\":\"The nonsliding door was fixed in place and could only swing open on its hinges.\",\"p\":\"non-SLY-ding\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.s.lid.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonslippage\",\"d\":\"The absence of slipping or sliding movement; a condition in which no unwanted displacement or loss of grip occurs between surfaces or parts.\",\"s\":\"The engineer praised the nonslippage of the new conveyor belt design.\",\"p\":\"non-SLIP-ij\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.slip.page\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonslippery\",\"d\":\"Not slippery; not likely to slip or skid; providing a firm, stable surface that allows secure footing or grip.\",\"s\":\"The gym installed nonslippery flooring so students wouldn't fall during dodgeball.\",\"p\":\"non-SLIP-ur-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.slip.pery\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsloping\",\"d\":\"Not having a slope or incline; describing a surface, path, or terrain that is flat and level rather than tilted.\",\"s\":\"The architect designed a nonsloping ramp that turned out to be just a flat platform.\",\"p\":\"non-SLOH-ping\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.slop.ing\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"olatin\"]},{\"w\":\"nonsmart\",\"d\":\"Not smart or intelligent; lacking cleverness, advanced technology, or the ability to make sophisticated decisions.\",\"s\":\"He made a nonsmart decision by forgetting his homework three days in a row.\",\"p\":\"non-SMART\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.s.mart\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsmoked\",\"d\":\"Not treated, preserved, or flavored by exposure to smoke; describing food or other products that have not undergone the smoking process.\",\"s\":\"The chef offered a nonsmoked salmon option for guests who preferred a milder flavor.\",\"p\":\"non-SMOKT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.smoked\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsmoothly\",\"d\":\"Not in a smooth or even manner; in a way that is rough, uneven, or marked by friction and irregularity.\",\"s\":\"The old car engine ran nonsmoothly, sputtering at every stoplight.\",\"p\":\"non-SMOOTH-lee\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.s.mooth.ly\",\"ps\":\"adverb\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonsnack\",\"d\":\"A food item or product that is not classified as a snack; something not intended to be eaten as a light, between-meal bite.\",\"s\":\"The dietitian classified the celery sticks as a nonsnack because they were part of the main meal.\",\"p\":\"non-SNAK\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.snack\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsnow\",\"d\":\"Precipitation or a substance that resembles snow but is not actually snow; any wintry material that falls from the sky but differs in composition from true snow.\",\"s\":\"The weather report described the white flakes as nonsnow precipitation, actually frozen sleet.\",\"p\":\"non-SNOH\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.snow\",\"ps\":\"noun\",\"t\":[\"weather\",\"olatin\"]},{\"w\":\"nonsoap\",\"d\":\"A cleansing product that does not contain true soap; a synthetic detergent or cleanser formulated without traditional soap ingredients.\",\"s\":\"The dermatologist recommended a nonsoap cleanser for her sensitive skin.\",\"p\":\"non-SOHP\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.soap\",\"ps\":\"noun\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"nonsoapy\",\"d\":\"Not having the qualities of soap; lacking a soapy texture, lather, or residue.\",\"s\":\"The nonsoapy texture of the lotion surprised him since it still cleaned his hands well.\",\"p\":\"non-SOH-pee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.soapy\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsoccer\",\"d\":\"Not related to or involving the sport of soccer; describing an activity, event, or context that has nothing to do with soccer.\",\"s\":\"During the nonsoccer season, the field was used for community concerts.\",\"p\":\"non-SOK-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"nonsoc.cer\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonsociable\",\"d\":\"Not sociable; not inclined to seek out or enjoy the company of others; preferring to avoid social interaction.\",\"s\":\"The nonsociable cat hid under the bed whenever guests arrived.\",\"p\":\"non-SOH-shuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"nonso.cia.ble\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonsocialist\",\"d\":\"Not adhering to or associated with socialist principles or policies; describing a person, government, or system that does not support collective or state ownership of production.\",\"s\":\"The nonsocialist party proposed cutting government programs during the debate.\",\"p\":\"non-SOH-shuh-list\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"nonso.cial.ist\",\"ps\":\"adjective\",\"t\":[\"politics\",\"logic\",\"olatin\"]},{\"w\":\"nonsocializing\",\"d\":\"Not engaging in social interaction or friendly communication with others; avoiding or refraining from mixing with people in a group setting.\",\"s\":\"The nonsocializing student spent every lunch break reading alone in the library.\",\"p\":\"non-SOH-shuh-ly-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonso.cial.iz.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsocioeconomic\",\"d\":\"Not related to or involving the combination of social and economic factors, such as income, education level, or class status.\",\"s\":\"The study looked at nonsocioeconomic factors like personality when explaining student success.\",\"p\":\"non-SOH-see-oh-ek-uh-NOM-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonso.cioe.co.nom.ic\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonsociolinguistic\",\"d\":\"Not pertaining to the study of how language is shaped by or interacts with social factors such as culture, class, or community.\",\"s\":\"The researcher focused on nonsociolinguistic aspects of language, such as brain activity patterns.\",\"p\":\"non-SOH-see-oh-ling-GWIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"nonso.ci.olin.guis.tic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsociological\",\"d\":\"Not relating to or based on the scientific study of human society, social behavior, or group dynamics.\",\"s\":\"The psychologist offered a nonsociological explanation for why people fear spiders.\",\"p\":\"non-SOH-see-uh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"nonso.ci.o.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsociologist\",\"d\":\"A person who is not a trained or professional sociologist; someone who studies or comments on society without formal sociological credentials.\",\"s\":\"As a nonsociologist, she still had strong opinions about how communities function.\",\"p\":\"non-SOH-see-OL-uh-jist\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"nonso.ci.ol.o.gist\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonsociology\",\"d\":\"Any field of study or approach to understanding human behavior that does not use the methods or frameworks of sociology.\",\"s\":\"The curriculum focused on nonsociology subjects like math and chemistry.\",\"p\":\"non-SOH-see-OL-uh-jee\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"nonso.ci.ol.o.gy\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsociopath\",\"d\":\"A person who does not exhibit sociopathic traits; someone who maintains normal empathy, conscience, and regard for social rules.\",\"s\":\"The psychologist confirmed that the suspect was a nonsociopath with normal empathy levels.\",\"p\":\"non-SOH-see-uh-path\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"nonso.ciopath\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsociopathic\",\"d\":\"Not displaying the antisocial, manipulative, or empathy-lacking traits associated with sociopathy; relating to normal emotional and social functioning.\",\"s\":\"His nonsociopathic behavior showed clearly when he cried during the sad movie.\",\"p\":\"non-SOH-see-uh-PATH-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonso.cio.path.ic\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonsodic\",\"d\":\"Not containing or characterized by an excess of sodium ions; used especially to describe soils or solutions with low sodium content.\",\"s\":\"The geologist noted that the nonsodic soil lacked the salt content found in coastal regions.\",\"p\":\"non-SOD-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.sod.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"character\",\"olatin\"]},{\"w\":\"nonsodium\",\"d\":\"Containing no sodium or formulated to exclude sodium, often used to describe foods, compounds, or chemical solutions free of the element Na.\",\"s\":\"The nutritionist recommended nonsodium seasonings to lower the patient's blood pressure.\",\"p\":\"non-SOH-dee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sodi.um\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsoftware\",\"d\":\"Referring to components of a computer system or technology product that are not software, such as physical hardware, printed manuals, or electronic circuits.\",\"s\":\"The nonsoftware components of the computer, like the keyboard, needed replacing first.\",\"p\":\"non-SAWFT-wair\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.soft.ware\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonsoil\",\"d\":\"Any material or substance that is not true soil, such as gravel, rock, sand, or synthetic growing media used in place of natural earth.\",\"s\":\"Sand and gravel are considered nonsoil materials in many agricultural classifications.\",\"p\":\"non-SOIL\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.soil\",\"ps\":\"noun\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"nonsoiled\",\"d\":\"Not soiled, stained, or dirtied; remaining clean and free of contamination or marks.\",\"s\":\"The chef insisted on using only nonsoiled linens for the fancy dinner table.\",\"p\":\"non-SOILD\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.soiled\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsoiling\",\"d\":\"Not causing or producing stains or soiling; describing materials or surfaces that resist picking up or leaving behind dirt and marks.\",\"s\":\"The manufacturer advertised the fabric as nonsoiling, perfect for kids' school uniforms.\",\"p\":\"non-SOIL-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.soil.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsolar\",\"d\":\"Not derived from, powered by, or related to the sun or solar energy; describing energy sources or systems that operate independently of sunlight.\",\"s\":\"The cabin used nonsolar energy sources like wind and hydroelectric power.\",\"p\":\"non-SOH-ler\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.so.lar\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"physics\",\"olatin\"]},{\"w\":\"nonsolenoidal\",\"d\":\"In physics and mathematics, describing a vector field that is not divergence-free; a field that does not satisfy the conditions of a solenoidal, or curl-based, field.\",\"s\":\"The physicist explained that nonsolenoidal fields can have sources and sinks unlike pure magnetic fields.\",\"p\":\"non-SOH-luh-NOI-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"non.solenoidal\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonsolicit\",\"d\":\"Not involving or engaging in solicitation; describing an agreement, policy, or behavior that prohibits seeking out clients, employees, or donations.\",\"s\":\"The sign on the door read 'nonsolicit zone,' warning salespeople to stay away.\",\"p\":\"non-suh-LIS-it\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"non.so.lic.it\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonsolicitation\",\"d\":\"A formal agreement or policy in which a person or organization agrees not to seek out or recruit clients, customers, or employees from a competing party.\",\"s\":\"The employees signed a nonsolicitation agreement promising not to recruit colleagues to rival firms.\",\"p\":\"non-suh-lis-ih-TAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.so.lic.i.ta.tion\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonsolicited\",\"d\":\"Not asked for, requested, or invited; arriving or occurring without being sought out by the recipient.\",\"s\":\"She was annoyed by the nonsolicited advice her neighbor kept giving about her garden.\",\"p\":\"non-suh-LIS-ih-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.so.licit.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsoliciting\",\"d\":\"Not actively seeking clients, customers, business, or recruits; refraining from making requests or pitches to others.\",\"s\":\"The school maintained a strict nonsoliciting policy, banning all fundraising calls to parents.\",\"p\":\"non-suh-LIS-ih-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.so.lic.it.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsolid\",\"d\":\"Not in a solid physical state; referring to matter that is liquid, gas, or plasma, or to a material that lacks firm, rigid structure.\",\"s\":\"Water and air are both nonsolid substances that take the shape of their container.\",\"p\":\"non-SOL-id\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.sol.id\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsolitary\",\"d\":\"Not living or occurring alone; describing organisms, behaviors, or lifestyles that involve groups, communities, or social interaction rather than isolation.\",\"s\":\"Wolves are nonsolitary animals that live and hunt in tight family packs.\",\"p\":\"non-SOL-ih-tair-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.soli.tary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsoluble\",\"d\":\"Not capable of being dissolved in a liquid, especially water; remaining intact and separate when placed in a solvent.\",\"s\":\"Sand is nonsoluble in water, which is why beaches don't disappear when it rains.\",\"p\":\"non-SOL-yuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.sol.u.ble\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsolution\",\"d\":\"Something that fails to resolve a problem or address its root cause; an approach or answer that does not actually solve the issue at hand.\",\"s\":\"The teacher told Marcus that giving up was a nonsolution to his math problem.\",\"p\":\"non-suh-LOO-shun\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.so.lu.tion\",\"ps\":\"noun\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonsolvable\",\"d\":\"Not capable of being solved, resolved, or worked out; describing a problem or equation for which no solution exists or can be found.\",\"s\":\"Some ancient mathematical puzzles were once thought to be nonsolvable until modern computers cracked them.\",\"p\":\"non-SOL-vuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.solv.able\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsolvency\",\"d\":\"The condition of not being solvent; the state in which a person or organization lacks sufficient funds or assets to pay its debts and obligations.\",\"s\":\"The bank warned that nonsolvency would result if the company didn't repay its debts quickly.\",\"p\":\"non-SOL-ven-see\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.sol.ven.cy\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"economy\",\"olatin\"]},{\"w\":\"nonsonant\",\"d\":\"In phonetics, describing a speech sound that lacks the resonant, vowel-like qualities of a sonant; a consonant that is not voiced or resonant in the manner of a sonant.\",\"s\":\"The linguist classified certain consonants as nonsonant because they lacked the resonance of vowels.\",\"p\":\"non-SOH-nunt\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.so.nant\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsongbird\",\"d\":\"Any bird that does not belong to the group of songbirds, or oscines, which are known for their complex, melodious vocalizations produced by a specialized vocal organ.\",\"s\":\"The pelican is a nonsongbird that communicates through bill clapping rather than melodious calls.\",\"p\":\"non-SONG-berd\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.song.bird\",\"ps\":\"noun\",\"t\":[\"birds\",\"music\",\"olatin\"]},{\"w\":\"nonsonicated\",\"d\":\"Not treated or processed using sonication, a technique that applies high-frequency sound waves to agitate or break apart particles in a liquid sample.\",\"s\":\"The nonsonicated sample was tested alongside the treated one to compare cell disruption rates.\",\"p\":\"non-SON-ih-kay-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.son.i.cat.ed\",\"ps\":\"adjective\",\"t\":[\"physics\",\"waterways\",\"olatin\"]},{\"w\":\"nonsonorous\",\"d\":\"Not producing a full, deep, or richly resonant sound; lacking the loud, impressive, or pleasant tonal quality associated with sonorous voices or instruments.\",\"s\":\"The speaker's nonsonorous whisper barely carried across the small classroom.\",\"p\":\"non-SON-er-us\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.sonorous\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonsoporific\",\"d\":\"Not causing or tending to cause sleepiness or drowsiness; describing a substance, activity, or experience that does not induce sleep.\",\"s\":\"The lively documentary was refreshingly nonsoporific, keeping every student wide awake.\",\"p\":\"non-SOH-puh-RIF-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.so.porif.ic\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonsortal\",\"d\":\"In logic and philosophy, describing a concept or term that does not function as a sortal, meaning it does not provide clear criteria for counting or identifying individual members of a category.\",\"s\":\"The philosopher argued that some concepts are nonsortal because they don't divide objects into distinct kinds.\",\"p\":\"non-SOR-tul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sor.tal\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonsorted\",\"d\":\"Not arranged, organized, or classified into groups or categories; remaining in a mixed, random, or unordered state.\",\"s\":\"The geologist examined the nonsorted glacial debris scattered randomly across the valley floor.\",\"p\":\"non-SOR-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sort.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsoundtrack\",\"d\":\"Audio content that is not part of an official film, game, or media soundtrack; describing music or sound not composed or licensed specifically for a production.\",\"s\":\"The director chose to use nonsoundtrack ambient noise to give the film a raw, realistic feel.\",\"p\":\"non-SOUND-trak\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.sound.track\",\"ps\":\"adjective\",\"t\":[\"music\",\"sports\",\"olatin\"]},{\"w\":\"nonsoup\",\"d\":\"Any liquid food or dish served in a bowl that does not meet the definition of soup, lacking the broth-based or slow-simmered qualities that characterize true soups.\",\"s\":\"The chef labeled the broth a nonsoup because its thick texture made it more of a stew.\",\"p\":\"non-SOOP\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.soup\",\"ps\":\"noun\",\"t\":[\"culinary\",\"dishes\",\"olatin\"]},{\"w\":\"nonsouthern\",\"d\":\"Not from, characteristic of, or relating to the southern region of a country, especially the southern United States; belonging to or associated with other geographic regions.\",\"s\":\"The nonsouthern dialect of the new student sounded refreshingly different to her classmates in Georgia.\",\"p\":\"non-SUTH-ern\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.south.ern\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsovereign\",\"d\":\"(of peoples and political bodies) controlled by outside forces\",\"s\":\"The nonsovereign territory had to seek approval from a larger nation before signing any trade agreements.\",\"p\":\"non-SOV-rin\",\"o\":\"Latin\",\"y\":8,\"bp\":33,\"ps\":\"adjective\",\"t\":[\"physics\",\"politics\",\"olatin\"]},{\"w\":\"nonsovereignty\",\"d\":\"The condition or status of lacking full independent governing authority; the absence of supreme political power or self-rule in a nation, region, or people.\",\"s\":\"The island's nonsovereignty meant that its residents could not vote in international treaties.\",\"p\":\"non-SOV-rin-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"sy\":\"nonsovereign.ty\",\"ps\":\"noun\",\"t\":[\"nations\",\"poetry\",\"politics\",\"olatin\"]},{\"w\":\"nonsoviet\",\"d\":\"Not related to, characteristic of, or aligned with the former Soviet Union or its political, economic, and cultural systems.\",\"s\":\"Many nonsoviet nations watched the space race with great interest during the Cold War.\",\"p\":\"non-SOH-vee-et\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"nonso.vi.et\",\"ps\":\"adjective\",\"t\":[\"politics\",\"economy\",\"olatin\"]},{\"w\":\"nonspace\",\"d\":\"An area, zone, or region that lacks the defining qualities of usable or meaningful space; in architecture or philosophy, a place that feels empty, transitional, or devoid of purpose.\",\"s\":\"The artist filled the canvas with painted nonspace to represent the void between galaxies.\",\"p\":\"non-SPAYS\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.space\",\"ps\":\"noun\",\"t\":[\"buildings\",\"logic\",\"olatin\"]},{\"w\":\"nonspacelike\",\"d\":\"In physics, describing an interval or path in spacetime that is not spacelike—meaning it does not connect two events that could theoretically occur at the same time in some reference frame, behaving instead as timelike or lightlike.\",\"s\":\"In physics class, the professor explained that a nonspacelike interval connects events that can influence each other.\",\"p\":\"non-SPAYS-lyk\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.space.like\",\"ps\":\"adjective\",\"t\":[\"physics\",\"time\",\"olatin\"]},{\"w\":\"nonspalling\",\"d\":\"Not prone to spalling, meaning a material does not chip, flake, or break apart in fragments when subjected to pressure, heat, or impact.\",\"s\":\"Engineers chose a nonspalling concrete mix to prevent chunks from breaking off the bridge's surface.\",\"p\":\"non-SPAWL-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.spalling\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspam\",\"d\":\"Referring to email or digital messages that are legitimate and wanted, as opposed to unsolicited bulk messages sent for advertising or malicious purposes.\",\"s\":\"The email filter carefully sorted nonspam messages into the inbox while trapping junk in the other folder.\",\"p\":\"non-SPAM\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.spam\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspare\",\"d\":\"Describing a part or component that is not extra or supplementary but is essential and required for normal operation.\",\"s\":\"Every nonspare part in the engine was essential and could not be removed without causing failure.\",\"p\":\"non-SPAIR\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.s.pare\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsparing\",\"d\":\"Not lenient, restrained, or merciful; giving fully without holding back, often used to describe harsh criticism or relentless effort.\",\"s\":\"The nonsparing critic gave every film a brutally honest review without softening her words.\",\"p\":\"non-SPAIR-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.spar.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsparking\",\"d\":\"Describing tools, materials, or equipment that are designed or constructed so they do not produce sparks when struck, making them safe for use in flammable or explosive environments.\",\"s\":\"Workers in the chemical plant used nonsparking tools to prevent accidental fires near flammable gases.\",\"p\":\"non-SPARK-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.spark.ing\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"tools\",\"olatin\"]},{\"w\":\"nonsparkling\",\"d\":\"Not producing bubbles or a fizzy effervescence; still and flat, as in a beverage that contains no carbonation.\",\"s\":\"She ordered nonsparkling water because carbonated drinks always made her stomach uncomfortable.\",\"p\":\"non-SPARK-ling\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sparkling\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"nonspastic\",\"d\":\"Not characterized by spasticity or involuntary muscle stiffness; describing movement or muscle tone that is free from the rigid contractions associated with certain neurological conditions.\",\"s\":\"The neurologist confirmed that the patient's muscle movements were nonspastic and completely normal.\",\"p\":\"non-SPAS-tik\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.spas.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"law\",\"character\",\"olatin\"]},{\"w\":\"nonspatial\",\"d\":\"Not related to, existing in, or determined by physical space or spatial dimensions; having no connection to location, distance, or arrangement in space.\",\"p\":\"non-SPAY-shul\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.spa.tial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspatiality\",\"d\":\"The quality or condition of having no spatial dimension or spatial properties; the state of being entirely independent of physical space.\",\"s\":\"The philosopher wrote a paper exploring the nonspatiality of emotions and abstract thought.\",\"p\":\"non-spay-shee-AL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.spa.tial.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonspatialized\",\"d\":\"Not arranged, organized, or represented in terms of spatial dimensions or physical location; existing or expressed without being mapped onto a spatial framework.\",\"s\":\"The sound in the recording was nonspatialized, meaning it had no directional or three-dimensional quality.\",\"p\":\"non-SPAY-shuh-lysd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.spa.tial.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspatially\",\"d\":\"In a manner that does not involve or depend on spatial relationships, dimensions, or physical location.\",\"s\":\"The mathematician argued that numbers exist nonspatially, with no location in the physical world.\",\"p\":\"non-SPAY-shuh-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.spa.tial.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonspatiotemporal\",\"d\":\"Not belonging to or governed by the combined framework of space and time; existing or conceived outside the usual dimensions of space and time.\",\"s\":\"Some philosophers claim that numbers are nonspatiotemporal, existing outside of space and time entirely.\",\"p\":\"non-spay-shee-oh-TEM-puh-rul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.spa.tiotem.po.ral\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonspeaker\",\"d\":\"A person who does not speak or is not proficient in a particular language; someone who communicates through means other than spoken language.\",\"s\":\"As a nonspeaker of Japanese, Marcus relied on a translation app during his trip to Tokyo.\",\"p\":\"non-SPEE-kur\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.speak.er\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonspecialist\",\"d\":\"A person who does not have specialized training or expertise in a particular field and instead has broad, general knowledge across many subjects.\",\"s\":\"The science book was written for the nonspecialist reader who had no background in chemistry.\",\"p\":\"non-SPESH-uh-list\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.spe.cial.ist\",\"ps\":\"noun\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonspecializing\",\"d\":\"Not concentrating on or developing expertise in a single specific field or area; remaining generalized rather than focused on one discipline.\",\"s\":\"The nonspecializing doctor treated patients with a wide range of conditions rather than focusing on one area.\",\"p\":\"non-SPESH-uh-ly-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.spe.cial.iz.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspecialty\",\"d\":\"Something that is not the particular area of skill, focus, or expertise of a person or establishment; a general or ordinary offering rather than a signature one.\",\"s\":\"The restaurant's nonspecialty dishes were decent, but their famous pasta was truly extraordinary.\",\"p\":\"non-SPESH-ul-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.spe.cial.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonspecification\",\"d\":\"The absence of clear, detailed requirements or descriptions; a situation in which no formal specifications have been stated or provided.\",\"s\":\"The vague contract was criticized for its nonspecification of deadlines and deliverables.\",\"p\":\"non-spes-ih-fih-KAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.spec.i.fi.ca.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonspecificity\",\"d\":\"The quality of lacking precision or definiteness; the condition of being vague or general rather than targeted toward a particular thing or purpose.\",\"s\":\"The test's nonspecificity was a problem because it reacted to several different viruses, not just the target one.\",\"p\":\"non-spes-ih-FIS-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.speci.fici.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonspeckled\",\"d\":\"Not marked with small spots or flecks of color; having a smooth, uniform surface or appearance without any speckles.\",\"s\":\"The nonspeckled eggs were a solid pale blue, making them easy to distinguish from the spotted ones.\",\"p\":\"non-SPEK-uld\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.speck.led\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonspectacular\",\"d\":\"Not impressive, dramatic, or visually striking; ordinary and unremarkable in appearance or effect.\",\"s\":\"The game ended in a nonspectacular tie that disappointed the fans hoping for an exciting finish.\",\"p\":\"non-spek-TAK-yuh-lur\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.spec.tac.u.lar\",\"ps\":\"adjective\",\"t\":[\"stage\",\"olatin\"]},{\"w\":\"nonspectral\",\"d\":\"Not relating to or forming part of the visible spectrum of light; not associated with the wavelengths of electromagnetic radiation that produce color.\",\"s\":\"White and black are considered nonspectral colors because they don't appear in the rainbow's spectrum.\",\"p\":\"non-SPEK-trul\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.spec.tral\",\"ps\":\"adjective\",\"t\":[\"physics\",\"colors\",\"olatin\"]},{\"w\":\"nonspecular\",\"d\":\"Not reflecting light in the manner of a mirror or smooth surface; producing scattered, diffuse reflection rather than a sharp, direct image.\",\"s\":\"The matte paint on the wall was nonspecular, scattering light evenly rather than creating a mirror-like shine.\",\"p\":\"non-SPEK-yuh-lur\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.spec.u.lar\",\"ps\":\"adjective\",\"t\":[\"household\",\"olatin\"]},{\"w\":\"nonspeculative\",\"d\":\"Not based on guesswork, theory, or uncertain assumptions; grounded in established facts, evidence, or proven methods rather than speculation.\",\"s\":\"The scientist stuck to nonspeculative conclusions, reporting only what the data clearly showed.\",\"p\":\"non-SPEK-yuh-lay-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.spec.u.la.tive\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonspeech\",\"d\":\"Referring to communication or sounds that do not involve spoken language, such as gestures, facial expressions, sign language, or written symbols.\",\"s\":\"Nodding, pointing, and facial expressions are all examples of nonspeech communication.\",\"p\":\"non-SPEECH\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.speech\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonspender\",\"d\":\"A person who does not spend money freely or readily; someone known for saving rather than purchasing goods or services.\",\"s\":\"As a careful nonspender, she saved most of her allowance instead of buying things impulsively.\",\"p\":\"non-SPEN-dur\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.spender\",\"ps\":\"noun\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonspending\",\"d\":\"Not involving the expenditure of money; describing a period, policy, or behavior characterized by the absence of financial spending.\",\"s\":\"The family adopted a nonspending weekend challenge where they enjoyed free activities at the park.\",\"p\":\"non-SPEND-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.spend.ing\",\"ps\":\"adjective\",\"t\":[\"politics\",\"economy\",\"character\",\"olatin\"]},{\"w\":\"nonsphere\",\"d\":\"An object or shape that is not a sphere; any three-dimensional form that lacks the perfectly round, symmetrical geometry of a sphere.\",\"s\":\"The scientist noted that the asteroid was a nonsphere, resembling a lumpy potato more than a perfect ball.\",\"p\":\"non-SFEER\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sphere\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsphericity\",\"d\":\"The quality or degree to which something deviates from being a perfect sphere; the measure of how non-round or irregularly shaped an object is.\",\"s\":\"The nonsphericity of the planet's shape caused it to bulge slightly at the equator.\",\"p\":\"non-sfeh-RIS-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.spheric.i.ty\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonspherocytic\",\"d\":\"In medicine, describing a type of hemolytic anemia in which the red blood cells are not abnormally sphere-shaped, distinguishing it from spherocytic forms of the condition.\",\"s\":\"The lab report described the patient's red blood cells as nonspherocytic, meaning they kept their normal disc shape.\",\"p\":\"non-sfeh-roh-SIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sphe.ro.cyt.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonspheroidal\",\"d\":\"Not having the shape of a spheroid; describing an object or form that deviates from the slightly flattened or elongated sphere shape of a spheroid.\",\"s\":\"The crystal grew in a nonspheroidal pattern, forming sharp, angular edges instead of a rounded form.\",\"p\":\"non-sfeh-ROY-dul\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"non.spheroidal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspiced\",\"d\":\"Not flavored or seasoned with spices; describing food or drink that has been prepared without the addition of any aromatic or pungent spice ingredients.\",\"s\":\"The chef prepared a nonspiced broth for the patient who couldn't tolerate strong flavors.\",\"p\":\"non-SPYST\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.spiced\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"spices\",\"numbers\",\"time\",\"olatin\"]},{\"w\":\"nonspicy\",\"d\":\"Not having a hot, pungent, or strongly flavored quality; mild and free from the burning sensation associated with spicy ingredients like chili peppers.\",\"s\":\"She ordered the nonspicy version of the curry because she didn't like the burning sensation.\",\"p\":\"non-SPY-see\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.spicy\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspiked\",\"d\":\"having no sharp points sticking up from a surface\",\"s\":\"The nonspiked collar felt smooth and gentle around the puppy's neck.\",\"p\":\"non-SPYKT\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.spiked\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"olatin\"]},{\"w\":\"nonspinal\",\"d\":\"Not relating to or involving the spine or spinal cord; describing structures, conditions, or treatments that have no connection to the vertebral column.\",\"s\":\"The doctor determined that the patient's pain was nonspinal, originating from a muscle rather than the backbone.\",\"p\":\"non-SPY-nul\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.spinal\",\"ps\":\"adjective\",\"t\":[\"body\",\"buildings\",\"olatin\"]},{\"w\":\"nonspinning\",\"d\":\"Not rotating or turning around an axis; describing an object, particle, or system that has no spin or rotational motion.\",\"s\":\"The nonspinning top sat motionless on the table until the child gave it a twirl.\",\"p\":\"non-SPIN-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.spin.ning\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonspiral\",\"d\":\"Not having the form of a spiral; describing a shape, galaxy, or structure that does not curve or wind progressively outward from a central point.\",\"s\":\"Unlike a galaxy with curving arms, this star cluster had a nonspiral, globular shape.\",\"p\":\"non-SPY-rul\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.spir.al\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"weather\",\"olatin\"]},{\"w\":\"nonspirit\",\"d\":\"Something that is not a spirit, ghost, or immaterial being; a material or physical entity lacking supernatural or spiritual qualities.\",\"s\":\"The philosopher argued that rocks and machines are nonspirit entities, lacking any inner life.\",\"p\":\"non-SPIR-it\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.spir.it\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"nonspirituality\",\"d\":\"The absence of spiritual quality, belief, or orientation; the state of being entirely concerned with material, physical, or secular matters rather than spiritual ones.\",\"s\":\"His nonspirituality was evident when he dismissed meditation as simply a breathing exercise.\",\"p\":\"non-spir-ih-choo-AL-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.spir.i.tu.al.i.ty\",\"ps\":\"noun\",\"t\":[\"religion\",\"logic\",\"olatin\"]},{\"w\":\"nonspirituous\",\"d\":\"Not containing alcohol or distilled spirits; describing a beverage or substance that is free from alcoholic content.\",\"s\":\"The banquet offered only nonspirituous beverages like juice and sparkling water.\",\"p\":\"non-SPIR-ih-choo-us\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.spir.i.tu.ous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"dishes\",\"olatin\"]},{\"w\":\"nonspliced\",\"d\":\"Not joined or connected by splicing; describing material, film, or genetic sequences that have not been cut and rejoined at any point.\",\"s\":\"The editor used the original, nonspliced footage for the documentary to keep it authentic.\",\"p\":\"non-SPLYST\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.spliced\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsplinterable\",\"d\":\"Not capable of breaking or fragmenting into sharp, jagged pieces; describing materials that remain intact without producing splinters.\",\"s\":\"The safety glass was nonsplinterable, so it crumbled into harmless pebbles instead of sharp shards.\",\"p\":\"non-SPLIN-ter-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.splin.ter.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsplintering\",\"d\":\"Not breaking apart into sharp fragments or splinters; describing a material that stays smooth and whole under pressure or impact.\",\"s\":\"The contractor chose nonsplintering wood for the playground equipment to protect the children's hands.\",\"p\":\"non-SPLIN-ter-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.splin.ter.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonspoilage\",\"d\":\"The absence of decay, decomposition, or deterioration in food or organic material; a condition in which spoiling does not occur.\",\"s\":\"The vacuum-sealed packaging guaranteed nonspoilage of the food for up to two years.\",\"p\":\"non-SPOY-lij\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.spoilage\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonspoken\",\"d\":\"Not expressed or communicated through spoken words; conveyed through writing, gesture, or other nonverbal means rather than speech.\",\"s\":\"Their friendship was built on nonspoken understanding — a glance was enough to communicate.\",\"p\":\"non-SPOH-kun\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.spo.ken\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonspongy\",\"d\":\"Not soft, porous, or absorbent like a sponge; describing a material that is firm, dense, and does not soak up liquids.\",\"s\":\"The scientist needed a nonspongy material for the mold so it wouldn't absorb the liquid.\",\"p\":\"non-SPUN-jee\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.spongy\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsponsor\",\"d\":\"A person, organization, or entity that does not provide financial backing, support, or endorsement for an event, program, or individual.\",\"s\":\"The charity listed the company as a nonsponsor since it declined to contribute funds to the event.\",\"p\":\"non-SPON-ser\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.spon.sor\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsponsored\",\"d\":\"Not financially supported, endorsed, or backed by a sponsor; describing an activity, event, or person that operates without outside funding.\",\"s\":\"The nonsponsored athlete paid for all her own training equipment and travel expenses.\",\"p\":\"non-SPON-serd\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.spon.sored\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsponsoring\",\"d\":\"Not providing financial support, endorsement, or backing for a cause, event, or person; describing an entity that declines to act as a sponsor.\",\"s\":\"The nonsponsoring companies were still invited to attend the conference as observers.\",\"p\":\"non-SPON-ser-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.spon.sor.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsporadic\",\"d\":\"Not occurring at irregular or scattered intervals; happening in a consistent, regular, or continuous pattern rather than sporadically.\",\"s\":\"The nonsporadic rainfall during monsoon season fell in a steady, predictable pattern every afternoon.\",\"p\":\"non-spuh-RAD-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.spo.radic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsporogenic\",\"d\":\"Not capable of producing or generating spores; describing an organism or substance that does not form reproductive or resting spores.\",\"s\":\"The lab identified the bacteria as nonsporogenic, meaning it could not form protective spores to survive harsh conditions.\",\"p\":\"non-spor-uh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.sporo.genic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsport\",\"d\":\"An activity, hobby, or pursuit that does not qualify as or relate to organized athletic competition; something outside the category of sports.\",\"s\":\"Chess and debate are sometimes called nonsport activities, even though they require intense mental competition.\",\"p\":\"non-SPORT\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.sport\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonsports\",\"d\":\"Not related to or involving athletic competition or sporting events; describing content, activities, or categories outside the world of sports.\",\"s\":\"The school newsletter covered nonsports achievements like art awards and science fair winners.\",\"p\":\"non-SPORTS\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.sports\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonspotted\",\"d\":\"Having no spots, marks, or patches of color on its surface; describing an animal, object, or material that is uniform and unmarked.\",\"s\":\"Unlike a leopard, the lion has a nonspotted coat that is a uniform sandy color.\",\"p\":\"non-SPOT-id\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"nonspot.ted\",\"ps\":\"adjective\",\"t\":[\"animals\",\"colors\",\"olatin\"]},{\"w\":\"nonspreadable\",\"d\":\"Not able to be spread, extended, or distributed across a surface; describing a substance too thick, stiff, or solid to be spread easily.\",\"s\":\"The frozen butter was nonspreadable and tore the toast every time he tried to use it.\",\"p\":\"non-SPRED-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.spread.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsquamous\",\"d\":\"Not composed of or relating to flat, scale-like cells; used especially in medicine to describe cell types that are not squamous in structure.\",\"s\":\"The pathologist noted that the lung tumor was nonsquamous, requiring a different type of treatment.\",\"p\":\"non-SKWAY-mus\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.squa.mous\",\"ps\":\"adjective\",\"t\":[\"body\",\"pharmacy\",\"olatin\"]},{\"w\":\"nonsquare\",\"d\":\"Not having the shape, properties, or dimensions of a perfect square; describing a figure, number, or form that does not meet the definition of a square.\",\"s\":\"The architect designed a nonsquare room with angled walls to give the space a dynamic feel.\",\"p\":\"non-SKWAIR\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.square\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonstability\",\"d\":\"The quality or condition of lacking stability, firmness, or consistent balance; a tendency toward instability or unpredictable change.\",\"s\":\"The engineer warned that nonstability in the bridge's design could be dangerous during strong winds.\",\"p\":\"non-stuh-BIL-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":39,\"sy\":\"non.sta.bil.i.ty\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonstackable\",\"d\":\"Not designed or able to be stacked or piled on top of one another; describing objects whose shape or structure prevents safe stacking.\",\"s\":\"The curved bowls were nonstackable and had to be stored side by side on the shelf.\",\"p\":\"non-STAK-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.stack.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstacked\",\"d\":\"Not arranged or placed in a pile or stack; describing items that are stored or displayed individually rather than layered on top of each other.\",\"s\":\"The nonstacked chairs were scattered around the room after the event ended.\",\"p\":\"non-STAKT\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.stacked\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstaff\",\"d\":\"Not belonging to or employed as part of the regular staff of an organization; describing a person or role outside the official workforce.\",\"s\":\"Volunteers and nonstaff helpers set up the chairs and tables before the ceremony began.\",\"p\":\"non-STAF\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.staff\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstained\",\"d\":\"Not treated with a stain, dye, or coloring agent; describing wood, fabric, or other material that retains its natural, uncolored appearance.\",\"s\":\"The nonstained wood floor showed its natural pale color before the varnish was applied.\",\"p\":\"non-STAYND\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.stained\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"colors\",\"olatin\"]},{\"w\":\"nonstaining\",\"d\":\"Not leaving or producing a stain or discoloration on surfaces it contacts; describing a substance that can be used without causing permanent marks.\",\"s\":\"The art teacher recommended nonstaining markers so kids wouldn't ruin their clothes.\",\"p\":\"non-STAYN-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.stain.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstale\",\"d\":\"Not old, dry, or past its peak freshness; describing food or ideas that remain fresh, current, and appealing.\",\"s\":\"The bakery guaranteed nonstale bread by baking fresh loaves every single morning.\",\"p\":\"non-STAYL\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.stale\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstamped\",\"d\":\"Not bearing an official stamp, postmark, or impressed mark; describing a document, envelope, or object that lacks any stamped impression.\",\"s\":\"The nonstamped envelope was returned by the post office because it had no postage.\",\"p\":\"non-STAMPT\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.stamped\",\"ps\":\"adjective\",\"t\":[\"maps\",\"olatin\"]},{\"w\":\"nonstandardized\",\"d\":\"Not brought into conformity with an established standard or uniform system; describing methods, tests, or products that vary without a fixed rule.\",\"s\":\"The nonstandardized test allowed each student to respond creatively rather than following a fixed format.\",\"p\":\"non-STAN-der-dyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.stan.dard.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstandardly\",\"d\":\"In a way that does not conform to accepted or established standards; behaving or functioning outside of the usual or expected norms.\",\"s\":\"She solved the math problem nonstandardly, using a creative shortcut her teacher had never seen before.\",\"p\":\"non-STAN-derd-lee\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.stan.dard.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonstandardness\",\"d\":\"The quality or state of not conforming to accepted standards or norms; the degree to which something departs from what is considered regular or typical.\",\"s\":\"The teacher noted the nonstandardness of the student's unusual but creative approach to solving the math problem.\",\"p\":\"non-STAN-derd-nes\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.stan.dard.ness\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonstaphylococcal\",\"d\":\"Not caused by, related to, or involving the Staphylococcus genus of bacteria; describing infections, conditions, or organisms not associated with staph bacteria.\",\"s\":\"The lab report confirmed that the infection was nonstaphylococcal, so the doctor prescribed a different antibiotic.\",\"p\":\"non-staf-ih-loh-KOK-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.staphy.lo.coc.cal\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonstaple\",\"d\":\"Not considered a basic, essential, or regularly used food or commodity; describing items that are supplementary or occasional rather than fundamental.\",\"s\":\"Quinoa was once considered a nonstaple grain in many Western countries, though it has become very popular today.\",\"p\":\"non-STAY-pul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sta.ple\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstar\",\"d\":\"A person, object, or celestial body that does not have star status or the qualities associated with a star; not a featured or celebrated performer.\",\"s\":\"The director chose a nonstar actor for the lead role, believing fresh faces would make the film feel more realistic.\",\"p\":\"non-STAR\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.star\",\"ps\":\"noun\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"nonstarch\",\"d\":\"Not containing or consisting of starch; describing foods or substances that are free from starchy carbohydrates such as those found in potatoes or bread.\",\"s\":\"The nutritionist recommended eating more nonstarch vegetables like broccoli and spinach to lower blood sugar.\",\"p\":\"non-STARCH\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.starch\",\"ps\":\"adjective\",\"t\":[\"dishes\",\"spices\",\"olatin\"]},{\"w\":\"nonstarched\",\"d\":\"Not treated or stiffened with starch; describing fabric or clothing that has not had starch applied and therefore feels soft and flexible.\",\"s\":\"She preferred a nonstarched collar on her shirt because it felt softer and more comfortable throughout the day.\",\"p\":\"non-STARCHT\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.starched\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonstarred\",\"d\":\"Not marked with a star or asterisk; not given a star rating or featured as a starred performer or item in a list or review.\",\"s\":\"The nonstarred restaurants in the guide were often hidden gems that locals loved but critics had overlooked.\",\"p\":\"non-STARD\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.starred\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"nonstarting\",\"d\":\"Not in the lineup to begin a game or competition from the opening; describing a player or participant who begins on the bench rather than in the starting position.\",\"s\":\"The coach benched the nonstarting players during the first half but brought them in when the game was close.\",\"p\":\"non-START-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.start.ing\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonstarving\",\"d\":\"Not experiencing starvation or extreme hunger; describing a person, animal, or population that has sufficient food to meet basic nutritional needs.\",\"s\":\"The nonstarving students were able to concentrate better during the afternoon exam than those who had skipped lunch.\",\"p\":\"non-STAR-ving\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.starv.ing\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonstate\",\"d\":\"Not belonging to, controlled by, or representative of an official government or state authority; describing independent actors or organizations outside state structures.\",\"s\":\"Many nonstate organizations, like charities and international relief groups, provide aid in war zones without government backing.\",\"p\":\"non-STAYT\",\"o\":\"Latin\",\"y\":7,\"bp\":25,\"sy\":\"non.state\",\"ps\":\"adjective\",\"t\":[\"stage\",\"poetry\",\"politics\",\"olatin\"]},{\"w\":\"nonstated\",\"d\":\"Not explicitly expressed, declared, or written out; describing a rule, assumption, or fact that is implied or understood rather than formally stated.\",\"s\":\"There were several nonstated reasons why she decided to leave the team, and her teammates could only guess.\",\"p\":\"non-STAY-tid\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.stat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstateful\",\"d\":\"Not retaining information about previous interactions or states between sessions; used especially in computing to describe systems with no persistent memory of past data.\",\"s\":\"A nonstateful server doesn't remember previous requests, treating each one as completely new and independent.\",\"p\":\"non-STAYT-ful\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.state.ful\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstatement\",\"d\":\"Something that appears to be a statement but conveys no meaningful, clear, or verifiable information; an utterance or declaration that is essentially empty of content.\",\"s\":\"His vague answer was really a nonstatement that told reporters absolutely nothing about his plans.\",\"p\":\"non-STAYT-munt\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.state.ment\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonstationarity\",\"d\":\"The property of a data set or process whose statistical characteristics, such as mean or variance, change over time rather than remaining constant.\",\"s\":\"Scientists study the nonstationarity of climate patterns to understand why historical weather data may not predict future trends.\",\"p\":\"non-stay-shuh-NAIR-ih-tee\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"sy\":\"non.sta.tion.ar.i.ty\",\"ps\":\"noun\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonstatistical\",\"d\":\"Not based on or involving the use of statistics or numerical data analysis; relying on qualitative rather than quantitative methods.\",\"s\":\"The researcher took a nonstatistical approach to her study, relying on personal interviews rather than number crunching.\",\"p\":\"non-stuh-TIS-tih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sta.tis.ti.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstatistically\",\"d\":\"In a manner that does not rely on statistical methods or numerical analysis; without using data-based calculations.\",\"s\":\"The results were described nonstatistically in plain language so parents could easily understand the findings.\",\"p\":\"non-stuh-TIS-tih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.sta.tis.ti.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonstative\",\"d\":\"Describing a verb or expression that conveys action, change, or process rather than a fixed state, such as 'run' or 'build.'\",\"s\":\"Verbs like 'run' and 'eat' are nonstative because they describe actions rather than ongoing states of being.\",\"p\":\"non-STAY-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sta.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonstatutory\",\"d\":\"Not established or required by a formal written law or statute; based on custom, agreement, or common law instead.\",\"s\":\"The school's dress code was a nonstatutory rule, meaning it was a school policy but not required by law.\",\"p\":\"non-STACH-oo-tor-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.statu.to.ry\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonsteady\",\"d\":\"Not constant or uniform over time; characterized by fluctuation or irregular change in flow, pressure, or another measurable property.\",\"s\":\"The nonsteady flow of the river made it dangerous for kayakers during the spring flood season.\",\"p\":\"non-STED-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.steady\",\"ps\":\"adjective\",\"t\":[\"character\",\"time\",\"olatin\"]},{\"w\":\"nonsteak\",\"d\":\"Not consisting of or relating to steak; describing a food item or diet that contains no beef steak.\",\"s\":\"The restaurant created a creative nonsteak entrée using mushrooms that satisfied even the most dedicated meat lovers.\",\"p\":\"non-STAYK\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.steak\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstealing\",\"d\":\"The practice or principle of refraining from taking what does not belong to oneself; an ethical commitment to honesty regarding others' property.\",\"s\":\"The program taught nonstealing principles to help young children understand honesty and respect for others' belongings.\",\"p\":\"non-STEEL-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.steal.ing\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonstealth\",\"d\":\"Not designed to avoid detection; openly visible or audible rather than hidden or covert.\",\"s\":\"The military parade was a nonstealth display of power, meant to be seen and heard by everyone watching.\",\"p\":\"non-STELTH\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.stealth\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsteam\",\"d\":\"Not powered by or making use of steam; describing engines, systems, or processes that operate without steam energy.\",\"s\":\"The engineer switched to a nonsteam heating system that used hot water instead of pressurized vapor.\",\"p\":\"non-STEEM\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.steam\",\"ps\":\"adjective\",\"t\":[\"physics\",\"tools\",\"olatin\"]},{\"w\":\"nonsteamed\",\"d\":\"Not cooked or treated by exposure to steam; prepared using a dry or non-steam-based method.\",\"s\":\"The nonsteamed vegetables were roasted in the oven, giving them a crispy texture instead of a soft one.\",\"p\":\"non-STEEMD\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.steamed\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonsteel\",\"d\":\"Not made of or containing steel; constructed from alternative materials such as wood, aluminum, or composite substances.\",\"s\":\"The architect designed the bridge using nonsteel materials, including carbon fiber and reinforced concrete.\",\"p\":\"non-STEEL\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.steel\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstellar\",\"d\":\"Not relating to or originating from stars; describing objects, phenomena, or energy sources in space that are not stars.\",\"s\":\"Astronomers discovered that the mysterious object emitting the signal was nonstellar and might be a rogue planet.\",\"p\":\"non-STEL-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.stel.lar\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"physics\",\"olatin\"]},{\"w\":\"nonstem\",\"d\":\"Not having or relating to a stem; describing a plant part, cell type, or object that lacks the characteristic elongated supporting structure.\",\"s\":\"The florist used nonstem flowers arranged in a low bowl rather than tall vase arrangements for the centerpiece.\",\"p\":\"non-STEM\",\"o\":\"Latin\",\"y\":8,\"bp\":19,\"sy\":\"non.stem\",\"ps\":\"adjective\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"nonstereogenic\",\"d\":\"Describing a molecule or atom that does not create a new stereoisomer when its groups are interchanged; lacking a chiral center.\",\"s\":\"The chemist confirmed that the carbon atom in the molecule was nonstereogenic and would not affect the compound's mirror image.\",\"p\":\"non-stair-ee-oh-JEN-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.stere.ogenic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonstereoscopic\",\"d\":\"Not producing or involving a three-dimensional visual effect; appearing flat rather than having depth perceived through binocular vision.\",\"s\":\"The old camera produced nonstereoscopic images that appeared flat rather than giving a sense of depth.\",\"p\":\"non-stair-ee-oh-SKOP-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.stereo.scop.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstereoselective\",\"d\":\"Describing a chemical reaction that does not preferentially produce one stereoisomer over another, yielding a mixture of spatial arrangements.\",\"s\":\"The reaction was nonstereoselective, producing an equal mix of both mirror-image forms of the molecule.\",\"p\":\"non-stair-ee-oh-sih-LEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.stere.os.e.lec.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonstereospecific\",\"d\":\"Describing a reaction or enzyme that does not require or produce a specific three-dimensional molecular arrangement; lacking spatial selectivity.\",\"s\":\"Because the enzyme was nonstereospecific, it could act on both versions of the molecule without discrimination.\",\"p\":\"non-stair-ee-oh-speh-SIF-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.stere.ospe.cif.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstereospecifically\",\"d\":\"In a manner that does not involve or require a specific three-dimensional molecular orientation; without spatial selectivity in a reaction.\",\"s\":\"The catalyst worked nonstereospecifically, attaching to molecules regardless of their three-dimensional orientation.\",\"p\":\"non-stair-ee-oh-speh-SIF-ih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.stere.ospecif.i.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonstereotypical\",\"d\":\"Not conforming to a fixed, oversimplified image or idea about a group or thing; defying conventional or expected patterns.\",\"s\":\"The movie featured nonstereotypical characters who broke expected roles and surprised audiences with their complexity.\",\"p\":\"non-stair-ee-oh-TIP-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.stereo.typ.i.cal\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsterilizable\",\"d\":\"Not capable of being made free from germs or microorganisms through sterilization processes; unable to be rendered completely sterile.\",\"s\":\"The delicate electronic sensor was nonsterilizable, so doctors had to use a sterile protective cover over it instead.\",\"p\":\"non-STAIR-ih-lyz-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.ster.il.iz.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsterilized\",\"d\":\"Not having been subjected to a sterilization process; still potentially containing living microorganisms or contaminants.\",\"s\":\"Using nonsterilized equipment in a medical setting can lead to dangerous infections and serious health risks.\",\"p\":\"non-STAIR-ih-lyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.ster.il.ized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsterilizing\",\"d\":\"Not having the effect of killing or removing all microorganisms; cleaning or treating without achieving complete sterility.\",\"s\":\"The cleaning solution was nonsterilizing and could remove dirt but could not kill harmful bacteria on its own.\",\"p\":\"non-STAIR-ih-ly-zing\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.ster.il.iz.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsteroid\",\"d\":\"An organic compound that does not contain a steroid structure; a substance lacking the characteristic four-ring carbon framework of steroids.\",\"s\":\"The doctor prescribed a nonsteroid anti-inflammatory drug to reduce the athlete's knee swelling without hormonal side effects.\",\"p\":\"non-STAIR-oyd\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.s.teroid\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsticky\",\"d\":\"Not adhesive or prone to clinging; having a smooth surface from which other materials slide off easily without adhering.\",\"s\":\"The nonsticky surface of the pan made it easy to flip the pancakes without them tearing apart.\",\"p\":\"non-STIK-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.sticky\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstiff\",\"d\":\"Not rigid or firm; flexible and easy to bend without resistance or stiffness.\",\"s\":\"The yoga instructor recommended nonstiff fabrics for workout clothes so students could move freely through every pose.\",\"p\":\"non-STIF\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.s.tiff\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstiffened\",\"d\":\"Not having been treated, reinforced, or altered to increase rigidity; remaining soft or flexible without added stiffening material.\",\"s\":\"The nonstiffened fabric draped elegantly over the mannequin, flowing softly rather than holding a rigid shape.\",\"p\":\"non-STIF-end\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.s.tiff.ened\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstiffening\",\"d\":\"Not causing or undergoing an increase in rigidity or stiffness; remaining pliable under changing conditions.\",\"s\":\"The engineer chose a nonstiffening material for the flexible joint so it could bend freely in cold weather.\",\"p\":\"non-STIF-en-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.s.tiff.en.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstigmatic\",\"d\":\"Not relating to or causing a stigma; free from the distortion of a lens defect or the social mark of shame or disgrace.\",\"s\":\"The new lens was nonstigmatic, meaning it focused light evenly without the distortion that plagued older designs.\",\"p\":\"non-stig-MAT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.stig.mat.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonstigmatized\",\"d\":\"Not having been labeled with a negative social mark or subjected to shame and discrimination based on a perceived characteristic.\",\"s\":\"In that progressive community, people with mental health challenges felt nonstigmatized and openly sought help.\",\"p\":\"non-STIG-muh-tyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.stig.ma.tized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstimulated\",\"d\":\"Not having been activated, excited, or provoked by an external stimulus; remaining in an inert or baseline state.\",\"s\":\"The control group remained nonstimulated throughout the experiment so scientists could compare results fairly.\",\"p\":\"non-STIM-yoo-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.stim.u.lat.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstimulating\",\"d\":\"Not causing excitement, heightened activity, or a response in cells, nerves, or senses; dull or inert in effect.\",\"s\":\"The doctor recommended a nonstimulating bedtime routine, avoiding screens and caffeine before sleep.\",\"p\":\"non-STIM-yoo-lay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.stim.u.lat.ing\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonstimulation\",\"d\":\"The absence of any stimulus or activating agent; a condition in which no external force provokes a response in an organism or system.\",\"s\":\"The study examined whether nonstimulation of certain brain regions led to slower recovery after injury.\",\"p\":\"non-stim-yoo-LAY-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.stim.u.la.tion\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonstipendiary\",\"d\":\"Not receiving a stipend or regular salary; performing duties or holding a position without financial compensation.\",\"s\":\"She accepted the nonstipendiary volunteer position at the museum because she loved history and didn't need the pay.\",\"p\":\"non-sty-PEN-dee-air-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.stipen.di.ary\",\"ps\":\"adjective\",\"t\":[\"economy\",\"olatin\"]},{\"w\":\"nonstipulated\",\"d\":\"Not specified or agreed upon in advance through a formal condition or requirement; left unstated in a contract or agreement.\",\"s\":\"The nonstipulated terms of the casual agreement left both parties free to adjust their plans at any time.\",\"p\":\"non-STIP-yoo-lay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.stip.u.lat.ed\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonstochastic\",\"d\":\"Not involving or governed by random probability; describing a process or outcome that is entirely determined by fixed, predictable rules.\",\"s\":\"The physicist explained that a nonstochastic process follows predictable rules rather than random chance.\",\"p\":\"non-stoh-KAS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.stochas.tic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstochastically\",\"d\":\"In a manner that is fully determined and not subject to random chance; operating according to fixed and predictable patterns.\",\"s\":\"The simulation ran nonstochastically, producing the exact same output every single time it was executed.\",\"p\":\"non-stoh-KAS-tih-klee\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.stochas.ti.cal.ly\",\"ps\":\"adverb\",\"t\":[\"olatin\"]},{\"w\":\"nonstockholder\",\"d\":\"A person who does not own shares of stock in a company; an individual with no equity stake in a corporation.\",\"s\":\"As a nonstockholder, she had no voting rights at the company's annual shareholder meeting.\",\"p\":\"non-STOK-hohl-der\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.stock.hold.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonstockholding\",\"d\":\"Not owning or holding any shares of stock in a company; relating to a status in which no corporate equity is possessed.\",\"s\":\"The nonstockholding employees were still given bonuses based on the company's record profits that year.\",\"p\":\"non-STOK-hohl-ding\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.stock.hold.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstoichiometric\",\"d\":\"Describing a chemical compound whose elements are not present in exact whole-number ratios, deviating from the proportions predicted by standard chemical formulas.\",\"s\":\"The chemist discovered that the nonstoichiometric compound had more iron atoms than the standard formula predicted.\",\"p\":\"non-stoy-kee-oh-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.sto.i.chio.met.ric\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"numbers\",\"olatin\"]},{\"w\":\"nonstoichiometry\",\"d\":\"A condition in solid compounds, especially minerals and semiconductors, where the ratio of atoms of different elements does not match simple whole-number ratios as expected by chemical formulas.\",\"s\":\"Nonstoichiometry in metal oxides can create unique electrical properties useful in semiconductors.\",\"p\":\"non-stoy-kee-OM-ih-tree\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.sto.i.chiom.e.try\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"minerals\",\"sports\",\"numbers\",\"olatin\"]},{\"w\":\"nonstolen\",\"d\":\"Describing something that has not been taken illegally or without permission; legitimately obtained or possessed.\",\"s\":\"The antique dealer provided certificates proving the paintings were nonstolen and legally obtained.\",\"p\":\"non-STOH-len\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.stolen\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstopped\",\"d\":\"Describing something that was not brought to a halt or interrupted at any point during its course.\",\"s\":\"The nonstopped flow of water from the broken pipe caused flooding throughout the basement.\",\"p\":\"non-STOPT\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.stopped\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstopping\",\"d\":\"Continuing without pausing or coming to a halt; never ceasing movement or action.\",\"s\":\"The nonstopping rain during the festival ruined the outdoor stages and forced everyone inside.\",\"p\":\"non-STOP-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.stop.ping\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstorable\",\"d\":\"Describing a substance or item that cannot be kept or preserved for later use without deteriorating or losing its usefulness.\",\"s\":\"Fresh strawberries are essentially nonstorable for more than a few days without refrigeration.\",\"p\":\"non-STOR-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.storable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstorage\",\"d\":\"The absence of any system or facility for keeping goods, data, or energy for future use; relating to something that cannot be stored.\",\"s\":\"The new app used a nonstorage model, processing data instantly without saving any personal information.\",\"p\":\"non-STOR-ij\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.stor.age\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonstore\",\"d\":\"Relating to retail or commerce that does not take place in a physical brick-and-mortar location, such as online or catalog shopping.\",\"s\":\"Nonstore retailers like online shops have changed how millions of people buy clothes and electronics.\",\"p\":\"non-STOR\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.store\",\"ps\":\"adjective\",\"t\":[\"buildings\",\"economy\",\"olatin\"]},{\"w\":\"nonstored\",\"d\":\"Describing energy, data, or material that has been used immediately rather than saved or kept in reserve.\",\"s\":\"The nonstored energy from the solar panels was fed directly into the power grid each sunny afternoon.\",\"p\":\"non-STORD\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.stored\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonstory\",\"d\":\"A news report or media item that lacks genuine newsworthiness or narrative interest; something presented as a story but containing little or no real significance.\",\"s\":\"The editor called the rumor a nonstory and refused to publish it because there was no evidence.\",\"p\":\"non-STOR-ee\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.sto.ry\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonstraight\",\"d\":\"Not forming a straight line; curved, bent, or deviating from a direct path.\",\"s\":\"The architect chose nonstraight lines for the building's facade to give it a more dynamic, flowing appearance.\",\"p\":\"non-STRAYT\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.straight\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstraightenable\",\"d\":\"Impossible to make straight or to correct into a linear form, no matter how much effort is applied.\",\"s\":\"The twisted metal beam was nonstraightenable after the fire, so the crew had to replace it entirely.\",\"p\":\"non-STRAYT-en-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.straight.en.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstraightened\",\"d\":\"Not having been made straight or corrected into a direct, even form; remaining bent or crooked.\",\"s\":\"Her nonstraightened curls bounced freely as she walked into the classroom on the first day of school.\",\"p\":\"non-STRAYT-end\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.straight.ened\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstrange\",\"d\":\"Completely ordinary, familiar, or expected; lacking any unusual, odd, or surprising qualities.\",\"s\":\"In physics, a nonstrange particle contains no strange quarks, making it simpler to analyze than exotic matter.\",\"p\":\"non-STRAYNJ\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.strange\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstranger\",\"d\":\"A person who is known to someone rather than being unfamiliar; an acquaintance, friend, or family member rather than a stranger.\",\"s\":\"Because they had met at summer camp the year before, Jake was a nonstranger to everyone in the cabin.\",\"p\":\"non-STRAYN-jer\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.stranger\",\"ps\":\"noun\",\"t\":[\"character\",\"kinship\",\"olatin\"]},{\"w\":\"nonstratiform\",\"d\":\"Describing clouds or precipitation that do not form in flat, horizontal layers but instead develop in a more vertical or irregular pattern.\",\"s\":\"The nonstratiform clouds gathered in puffy towers rather than lying in flat, layered sheets across the sky.\",\"p\":\"non-STRAT-ih-form\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.strat.i.form\",\"ps\":\"adjective\",\"t\":[\"weather\",\"olatin\"]},{\"w\":\"nonstratospheric\",\"d\":\"Not relating to or reaching the stratosphere; describing conditions, prices, or levels that remain relatively low or moderate rather than extremely high.\",\"s\":\"The balloon floated at a nonstratospheric altitude, staying well within the lower atmosphere during its journey.\",\"p\":\"non-strat-oh-SFEER-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.strato.spher.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstray\",\"d\":\"Describing an animal that has a permanent home and owner and does not wander without belonging to anyone.\",\"s\":\"The shelter confirmed the dog was nonstray and had a registered owner who was searching frantically.\",\"p\":\"non-STRAY\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.stray\",\"ps\":\"adjective\",\"t\":[\"animals\",\"olatin\"]},{\"w\":\"nonstreamed\",\"d\":\"Not divided into separate academic tracks or ability groups; describing an educational system where students of all abilities are taught together.\",\"s\":\"The nonstreamed classroom mixed students of all abilities together rather than separating them by skill level.\",\"p\":\"non-STREEMD\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"sy\":\"non.streamed\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonstreaming\",\"d\":\"Relating to an educational approach that does not separate students into different groups based on academic ability or performance.\",\"s\":\"The rural school used a nonstreaming approach, believing every student benefited from learning alongside diverse peers.\",\"p\":\"non-STREE-ming\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.stream.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstreamlined\",\"d\":\"Not shaped or designed to reduce air or water resistance; lacking the smooth, tapered form intended to allow efficient movement through a fluid.\",\"s\":\"The old delivery truck had a boxy, nonstreamlined shape that made it less fuel-efficient on the highway.\",\"p\":\"non-STREEM-lynd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.stream.lined\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstrengthened\",\"d\":\"Not having been reinforced or made more powerful, durable, or resistant; lacking additional structural or physical support.\",\"s\":\"The nonstrengthened glass shattered easily when struck, unlike the tempered version used in car windows.\",\"p\":\"non-STRENGTH-end\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.strength.ened\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonstreptococcal\",\"d\":\"Not caused by or related to streptococcus bacteria; describing an infection or condition whose origin lies with a different type of microorganism.\",\"s\":\"The doctor confirmed the throat infection was nonstreptococcal, so antibiotics were not necessary for treatment.\",\"p\":\"non-strep-toh-KOK-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.strep.to.coc.cal\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonstressed\",\"d\":\"Describing a syllable, word, or element that does not receive emphasis or extra force when spoken; unstressed in pronunciation or usage.\",\"s\":\"In poetry, nonstressed syllables are spoken more softly and quickly than the accented beats around them.\",\"p\":\"non-STREST\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.stressed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"physics\",\"wordwords\",\"olatin\"]},{\"w\":\"nonstretch\",\"d\":\"Describing fabric or material that does not expand or elongate when pulled; lacking elasticity.\",\"s\":\"The tailor recommended nonstretch denim for the structured trousers so they would hold their sharp shape all day.\",\"p\":\"non-STRECH\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.stretch\",\"ps\":\"adjective\",\"t\":[\"fabrics\",\"olatin\"]},{\"w\":\"nonstretched\",\"d\":\"Not having been pulled, extended, or elongated from its original form or size.\",\"s\":\"The nonstretched canvas was rolled tightly in the tube, waiting to be mounted on a frame for painting.\",\"p\":\"non-STRECHT\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.stretched\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstretchy\",\"d\":\"Lacking the ability to stretch or expand; rigid and inelastic in material or composition.\",\"s\":\"She bought nonstretchy ribbon for the gift bow, knowing it would hold its crisp shape without drooping.\",\"p\":\"non-STRECH-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"sy\":\"non.stretchy\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstriated\",\"d\":\"Lacking visible parallel lines or bands of color; describing smooth muscle tissue that does not show the stripe-like pattern seen in skeletal muscle.\",\"s\":\"Smooth muscle is nonstriated, meaning it lacks the striped appearance you see in voluntary skeletal muscles.\",\"p\":\"non-STRY-ay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.s.tri.at.ed\",\"ps\":\"adjective\",\"t\":[\"body\",\"colors\",\"olatin\"]},{\"w\":\"nonstrike\",\"d\":\"Relating to a period, agreement, or action in which workers do not engage in a work stoppage or labor strike.\",\"s\":\"The factory operated under a nonstrike agreement that kept production running smoothly for years.\",\"p\":\"non-STRYK\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.strike\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstriker\",\"d\":\"A worker who continues to work and does not participate in a strike; also, in cricket, the batsman at the non-bowling end who is not currently facing the ball.\",\"s\":\"The nonstriker chose to keep working while his colleagues picketed outside the building.\",\"p\":\"non-STRY-ker\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.strik.er\",\"ps\":\"noun\",\"t\":[\"insects\",\"olatin\"]},{\"w\":\"nonstriped\",\"d\":\"Having no stripes, bands, or lines of contrasting color; uniformly plain in appearance.\",\"s\":\"The nonstriped fabric was a solid navy blue, making it easy to match with any outfit.\",\"p\":\"non-STRYPT\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.striped\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"colors\",\"olatin\"]},{\"w\":\"nonstructure\",\"d\":\"Something that lacks a definite, organized physical or conceptual framework; an entity without a coherent or stable form or arrangement.\",\"s\":\"The artist's installation was intentionally a nonstructure, with no walls, roof, or frame.\",\"p\":\"non-STRUK-cher\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.struc.ture\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonstudied\",\"d\":\"Not learned through deliberate study or research; natural, spontaneous, or unplanned in manner or origin.\",\"s\":\"Her nonstudied charm made her seem naturally friendly rather than rehearsed or fake.\",\"p\":\"non-STUD-eed\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.stud.ied\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstudio\",\"d\":\"Not produced or recorded in a professional studio setting; describing music, film, or art created outside of a formal production environment.\",\"s\":\"The band recorded their hit album in a nonstudio setting, using a converted barn.\",\"p\":\"non-STOO-dee-oh\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.stu.dio\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"music\",\"olatin\"]},{\"w\":\"nonstudious\",\"d\":\"Not inclined to study or engage seriously with academic work; showing little interest in reading, learning, or scholarly pursuits.\",\"s\":\"The nonstudious student preferred skateboarding to reading textbooks after school.\",\"p\":\"non-STOO-dee-us\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.stu.dious\",\"ps\":\"adjective\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonstudying\",\"d\":\"Not engaged in the act of reviewing or learning academic material; spending time on activities other than study.\",\"s\":\"During his nonstudying hours, Marcus liked to cook elaborate meals for his family.\",\"p\":\"non-STUD-ee-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.study.ing\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonstupid\",\"d\":\"Not lacking intelligence or good judgment; showing reasonable sense, awareness, or cleverness in thought or action.\",\"s\":\"The teacher praised the nonstupid approach the students took to solving the tricky math problem.\",\"p\":\"non-STOO-pid\",\"o\":\"Latin\",\"y\":8,\"bp\":26,\"sy\":\"non.stupid\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonstyle\",\"d\":\"The absence of any recognizable or distinctive aesthetic approach; a manner of presentation that lacks a coherent or intentional design identity.\",\"s\":\"His deliberately mismatched outfit was considered a nonstyle by fashion critics.\",\"p\":\"non-STYL\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.style\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonstylistic\",\"d\":\"Not related to or concerned with style, artistic form, or aesthetic choices; focusing purely on content, function, or factual accuracy.\",\"s\":\"The editor made only nonstylistic corrections, fixing grammar without changing the author's voice.\",\"p\":\"non-sty-LIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.stylis.tic\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonsubcultural\",\"d\":\"Not belonging to or associated with any particular subculture or specialized social group; representing mainstream or broadly shared cultural values.\",\"s\":\"The mall's music was deliberately nonsubcultural, designed to appeal to absolutely everyone.\",\"p\":\"non-sub-KUL-cher-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sub.cul.tur.al\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubject\",\"d\":\"A person or entity not under the authority or rule of a particular state or sovereign; also, something that falls outside the topic or scope under discussion.\",\"s\":\"The moderator declared taxes a nonsubject for the debate, keeping discussion focused.\",\"p\":\"non-SUB-jekt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sub.ject\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonsubjective\",\"d\":\"undistorted by emotion or personal bias; based on observable phenomena\",\"p\":\"non-sub-JEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sub.jec.tive\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonsubmarine\",\"d\":\"Not relating to or involving submarines; describing vessels, operations, or environments that remain above water rather than underwater.\",\"s\":\"The naval exercise was entirely nonsubmarine, with every ship and patrol craft staying on the surface of the ocean throughout the week-long drill.\",\"p\":\"non-sub-muh-REEN\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.sub.ma.rine\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"seafaring\",\"olatin\"]},{\"w\":\"nonsubmission\",\"d\":\"The act or condition of refusing to submit, yield, or surrender to authority, rules, or demands.\",\"s\":\"The protester's nonsubmission to the unfair regulations inspired dozens of other citizens to stand up and speak out against the unjust policy at the town hall.\",\"p\":\"non-sub-MISH-un\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sub.mis.sion\",\"ps\":\"noun\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonsubmissive\",\"d\":\"Not inclined to yield, comply, or give in to authority or pressure; resistant and independent in behavior or attitude.\",\"s\":\"The nonsubmissive student respectfully but firmly challenged the teacher's reasoning, presenting carefully researched evidence that contradicted the textbook's outdated explanation.\",\"p\":\"non-sub-MIS-iv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sub.mis.sive\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"character\",\"olatin\"]},{\"w\":\"nonsubordinate\",\"d\":\"Not placed in a lower rank or lesser position; describing someone or something that is not under the authority or control of another.\",\"s\":\"The team was structured as entirely nonsubordinate, meaning every member had an equal voice in decisions and no single person could override the group's collective judgment.\",\"p\":\"non-sub-OR-dih-nut\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sub.or.di.nate\",\"ps\":\"adjective\",\"t\":[\"poetry\",\"olatin\"]},{\"w\":\"nonsubordinating\",\"d\":\"Not acting to place persons or things in a lower rank; describing a structure or approach that does not establish hierarchical control over others.\",\"s\":\"The cooperative used a nonsubordinating management style, ensuring that every worker from the newest hire to the most experienced veteran participated equally in setting company policy.\",\"p\":\"non-sub-OR-dih-nay-ting\",\"o\":\"Latin\",\"y\":9,\"bp\":32,\"sy\":\"non.sub.or.di.nat.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubscriber\",\"d\":\"A person who has not signed up for or paid for a subscription to a service, publication, or membership program.\",\"s\":\"As a nonsubscriber, Marcus could only read the first three articles on the news website before a pop-up blocked the rest of the content behind a paywall.\",\"p\":\"non-sub-SKRY-ber\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.sub.scriber\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsubscribing\",\"d\":\"Not signing up for, enrolling in, or agreeing to a subscription, membership, or formal arrangement.\",\"s\":\"The nonsubscribing visitors to the museum website could browse event listings but were unable to access exclusive member content, virtual tours, or archived lecture recordings.\",\"p\":\"non-sub-SKRY-bing\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sub.scrib.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubscripted\",\"d\":\"Not written or formatted with a subscript; describing text or characters that appear on the normal baseline rather than slightly below it.\",\"s\":\"In the simplified chemistry worksheet designed for younger students, all chemical formulas were presented in nonsubscripted text so the numbers sat on the same line as the letters.\",\"p\":\"non-sub-SKRIP-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sub.script.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubscription\",\"d\":\"A model, arrangement, or service that does not require a recurring fee or formal sign-up commitment from users.\",\"s\":\"The library's digital archive operated on a nonsubscription basis, allowing anyone with a library card to access thousands of historical documents completely free of charge at any time.\",\"p\":\"non-sub-SKRIP-shun\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sub.scrip.tion\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsubsidised\",\"d\":\"Not financially supported or funded by a government, organization, or outside source; operating without external financial assistance. (British spelling)\",\"s\":\"The small, nonsubsidised theatre company had to charge higher ticket prices than its government-funded rivals just to cover the basic costs of renting a performance space each month.\",\"p\":\"non-SUB-sih-dyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.sub.sidised\",\"ps\":\"adjective\",\"t\":[\"politics\",\"wordwords\",\"olatin\"]},{\"w\":\"nonsubsidized\",\"d\":\"Not receiving financial support or grants from a government body or other funding organization; self-supporting without outside monetary aid.\",\"s\":\"Running a nonsubsidized community garden was challenging because every seed, tool, and bag of soil had to be paid for entirely through donations and volunteer fundraising efforts.\",\"p\":\"non-SUB-sih-dyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sub.si.dized\",\"ps\":\"adjective\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonsubstantial\",\"d\":\"Lacking material substance, importance, or significant weight; not considerable in size, amount, or significance.\",\"s\":\"The critic dismissed the essay as nonsubstantial, pointing out that its sweeping claims about history were supported by only two vague references and no concrete evidence whatsoever.\",\"p\":\"non-sub-STAN-shul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sub.stan.tial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubstantive\",\"d\":\"Lacking real content, importance, or practical effect; describing something that is superficial or without meaningful substance.\",\"s\":\"The candidate's speech was largely nonsubstantive, filled with inspiring-sounding phrases but offering no specific plans or policies that voters could actually evaluate or hold her accountable to.\",\"p\":\"non-sub-STAN-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sub.stan.tive\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubstitutable\",\"d\":\"Impossible to replace with an alternative; so unique or essential that no substitute can adequately take its place.\",\"s\":\"Clean drinking water is nonsubstitutable for human survival, no matter how advanced technology becomes, because no artificial beverage can permanently replace what pure water does for the body.\",\"p\":\"non-sub-STICH-oo-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sub.sti.tutable\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubstituted\",\"d\":\"Not having one atom or group replaced by another; describing a chemical compound in which the original atoms remain unchanged and unswapped.\",\"s\":\"The chemistry students compared the properties of the nonsubstituted benzene ring with several versions that had hydrogen atoms replaced by other chemical groups to observe the differences in reactivity.\",\"p\":\"non-sub-STICH-oo-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sub.sti.tut.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsubstrate\",\"d\":\"A molecule or substance that does not act as a substrate; something that an enzyme or catalyst will not bind to or act upon.\",\"s\":\"During the biology experiment, the students added a nonsubstrate molecule to the enzyme solution and observed that no reaction occurred because the enzyme simply could not recognize or bind to it.\",\"p\":\"non-SUB-strayt\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.sub.strate\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsubtle\",\"d\":\"Completely obvious, blunt, or lacking in delicacy; not indirect or understated in expression or approach.\",\"s\":\"His nonsubtle hint that he wanted a new video game for his birthday involved pointing directly at the store display and saying, 'I want that one, please, for my birthday next week.'.\",\"p\":\"non-SUT-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sub.tle\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsubtractive\",\"d\":\"Not involving the removal or reduction of elements; relating to a process in which colors or components are added together rather than filtered out.\",\"s\":\"Digital screens use a nonsubtractive color system, mixing red, green, and blue light to create every shade you see, which is the opposite of how paint pigments combine on paper.\",\"p\":\"non-sub-TRAK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sub.trac.tive\",\"ps\":\"adjective\",\"t\":[\"colors\",\"olatin\"]},{\"w\":\"nonsuburban\",\"d\":\"Not characteristic of or located in a suburb; relating to areas that are urban, rural, or otherwise outside typical suburban neighborhoods.\",\"s\":\"Growing up in a nonsuburban environment, Priya spent her childhood surrounded by sprawling cornfields and unpaved roads rather than cul-de-sacs, strip malls, and manicured front lawns.\",\"p\":\"non-sub-UR-bun\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.sub.ur.ban\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsuccess\",\"d\":\"The state or condition of failing to achieve a desired goal or outcome; a lack of success.\",\"s\":\"The scientist recorded the experiment's nonsuccess in careful detail, knowing that understanding exactly why the result failed was just as valuable as achieving a breakthrough would have been.\",\"p\":\"non-suk-SES\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.suc.cess\",\"ps\":\"noun\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonsuccessful\",\"d\":\"Not achieving the intended goal or desired result; failing to succeed in an endeavor or attempt.\",\"s\":\"Although the first three attempts to launch the model rocket were nonsuccessful, the engineering club learned something important from each failure and finally achieved a perfect launch on the fourth try.\",\"p\":\"non-suk-SES-ful\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.suc.cess.ful\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonsucrose\",\"d\":\"Describing a substance, food, or solution that contains no sucrose, the common table sugar found naturally in many plants.\",\"s\":\"The nutritionist recommended a nonsucrose diet for her patient, replacing table sugar entirely with small amounts of fruit and naturally occurring sweeteners that the body processes differently than refined sugar.\",\"p\":\"non-SOO-krohs\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sucrose\",\"ps\":\"adjective\",\"t\":[\"botany\",\"household\",\"olatin\"]},{\"w\":\"nonsufficient\",\"d\":\"Not adequate or enough to meet a requirement, standard, or need; falling short of what is necessary.\",\"s\":\"The judges ruled that the evidence presented was nonsufficient to reach a verdict, and they asked both legal teams to return with stronger documentation before the case could proceed further.\",\"p\":\"non-suh-FISH-unt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.suf.fi.cient\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsuffixed\",\"d\":\"Not having a suffix added to the end; describing a word or linguistic form that consists only of its root without any attached ending.\",\"s\":\"In her linguistics homework, Yara had to identify which words in the list were nonsuffixed roots and which had been modified by adding common endings like '-tion,' '-ly,' or '-ness.'.\",\"p\":\"non-SUF-ikst\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.suf.fixed\",\"ps\":\"adjective\",\"t\":[\"botany\",\"wordwords\",\"olatin\"]},{\"w\":\"nonsugar\",\"d\":\"A substance that is not a sugar; any carbohydrate or compound that does not belong to the sugar category, or a sweetener that contains no actual sugar.\",\"s\":\"Food scientists developed a nonsugar sweetener that could satisfy a sweet tooth without affecting blood glucose levels, making it a promising option for people managing diabetes or reducing calorie intake.\",\"p\":\"non-SHOOG-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.sug.ar\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsugared\",\"d\":\"Not sweetened with or coated in sugar; containing no added sugar in its preparation or ingredients.\",\"s\":\"The nutritionist handed out nonsugared granola bars at the health fair, explaining that even small reductions in daily added sugar can make a significant difference in long-term heart health.\",\"p\":\"non-SHOOG-urd\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sug.ared\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsugary\",\"d\":\"Not containing sugar or having a sweet, sugary quality; describing food, drink, or substances that are free from sweetness associated with sugar.\",\"s\":\"For her afternoon snack, Leila chose a nonsugary option of sliced cucumbers and hummus instead of the cookies, hoping to avoid the energy crash that sweets always seemed to cause her.\",\"p\":\"non-SHOOG-uh-ree\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sug.ary\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsuing\",\"d\":\"Not pursuing or engaged in legal action; describing a party that chooses not to file a lawsuit or initiate litigation.\",\"s\":\"Both companies reached an agreement outside of court by signing a nonsuing contract, promising that neither side would take legal action over the disputed patent for the next five years.\",\"p\":\"non-SOO-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.suing\",\"ps\":\"adjective\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonsuitable\",\"d\":\"Not appropriate, fitting, or well-matched for a particular purpose, role, or situation; unsuitable.\",\"s\":\"The casting director politely told the applicant that his performance style, while energetic, was nonsuitable for the quiet, understated dramatic role the director had specifically envisioned for this particular production.\",\"p\":\"non-SOO-tuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.suit.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsulfated\",\"d\":\"Not treated with or containing a sulfate group; describing a chemical compound from which sulfate has been excluded or removed.\",\"s\":\"The biochemist chose a nonsulfated version of the compound for the experiment because the presence of sulfate groups in earlier trials had interfered unexpectedly with the enzyme's normal binding behavior.\",\"p\":\"non-SUL-fay-ted\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"sy\":\"non.sul.fat.ed\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsulfhydryl\",\"d\":\"Not containing or involving a sulfhydryl group, which is a chemical group made up of a sulfur atom bonded to a hydrogen atom.\",\"s\":\"The research team specifically selected a nonsulfhydryl reagent for the reaction because sulfhydryl groups in previous compounds had caused unwanted cross-linking that disrupted the protein structure they were carefully trying to preserve.\",\"p\":\"non-sulf-HY-drul\",\"o\":\"Latin\",\"y\":9,\"bp\":23,\"sy\":\"non.sulfhydryl\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsulfur\",\"d\":\"Not containing or involving elemental sulfur; describing a substance, compound, or process that is free from sulfur.\",\"s\":\"Environmentalists praised the factory's switch to a nonsulfur fuel source, noting that the change dramatically reduced the acid rain-causing emissions that had been damaging nearby forests and lakes for decades.\",\"p\":\"non-SUL-fur\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sul.fur\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsulfurous\",\"d\":\"Not containing or producing sulfur or sulfur compounds; free from the properties or effects associated with sulfur.\",\"s\":\"The geologist identified the spring water as nonsulfurous after testing it thoroughly, which explained why it smelled fresh and clean rather than carrying the rotten-egg odor typical of sulfur-rich springs.\",\"p\":\"non-SUL-fyur-us\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.sul.furous\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"nonsummer\",\"d\":\"Not belonging to or characteristic of the summer season; relating to or occurring during times of year other than summer.\",\"s\":\"The ski resort thrived during nonsummer months when snow blanketed the mountain, but the owners struggled every year to attract enough visitors once the warm weather melted the slopes bare.\",\"p\":\"non-SUM-ur\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sum.mer\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonsuperconductor\",\"d\":\"A material that does not exhibit superconductivity; a substance through which electrical resistance remains present and does not drop to zero, even at very low temperatures.\",\"s\":\"Copper is a nonsuperconductor because it always retains some electrical resistance no matter how cold it gets, unlike true superconducting materials that lose all resistance below a critical temperature.\",\"p\":\"non-soo-pur-kon-DUK-tur\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.super.con.duc.tor\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonsuperficial\",\"d\":\"Not shallow, surface-level, or lacking depth; involving genuine depth of analysis, feeling, or understanding beyond mere appearances.\",\"s\":\"The book review praised the author's nonsuperficial treatment of the subject, noting that every chapter dug beneath obvious observations to explore the complex social forces shaping her characters' difficult decisions.\",\"p\":\"non-soo-pur-FISH-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.super.fi.cial\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsuperfluid\",\"d\":\"A substance or material that does not exhibit superfluidity, meaning it retains normal viscosity and flow resistance rather than flowing without any friction.\",\"s\":\"Unlike helium-4 cooled to near absolute zero, the liquid in the experiment behaved as a nonsuperfluid, showing measurable resistance to flow and behaving according to ordinary laws of fluid dynamics.\",\"p\":\"non-soo-pur-FLOO-id\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.super.flu.id\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonsuperfluous\",\"d\":\"Not excessive or unnecessary; containing only what is needed and nothing more, without any wasteful or redundant elements.\",\"s\":\"Every word in her speech was nonsuperfluous, chosen with careful purpose.\",\"p\":\"non-soo-PER-floo-us\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.super.flu.ous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsuperheated\",\"d\":\"Not heated beyond the normal boiling point or standard temperature; describing steam or a substance that has not undergone superheating.\",\"s\":\"The engineer tested the pipe using nonsuperheated steam to avoid damaging the seals.\",\"p\":\"non-SOO-per-hee-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.super.heat.ed\",\"ps\":\"adjective\",\"t\":[\"culinary\",\"olatin\"]},{\"w\":\"nonsupermarket\",\"d\":\"A retail store or food shop that does not qualify as a full-scale supermarket, typically smaller in size or more limited in the variety of goods it offers.\",\"s\":\"She preferred shopping at nonsupermarket stores where she could find unique local products.\",\"p\":\"non-SOO-per-mar-kit\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.super.mar.ket\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsupernatural\",\"d\":\"Not involving or relating to forces or events beyond the laws of nature; entirely explainable by natural or scientific means.\",\"s\":\"The scientist insisted there was a nonsupernatural explanation for the strange lights in the sky.\",\"p\":\"non-soo-per-NACH-er-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.super.nat.u.ral\",\"ps\":\"adjective\",\"t\":[\"physics\",\"law\",\"olatin\"]},{\"w\":\"nonsuperpower\",\"d\":\"A country or entity that does not possess the extraordinary military, economic, or political strength required to be considered a superpower on the world stage.\",\"s\":\"Many nonsuperpower nations still play important roles in international diplomacy.\",\"p\":\"non-SOO-per-pow-er\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.super.pow.er\",\"ps\":\"noun\",\"t\":[\"stage\",\"politics\",\"economy\",\"war\",\"olatin\"]},{\"w\":\"nonsuperstar\",\"d\":\"A person who is not a superstar; someone who has not achieved exceptional fame, celebrity status, or outstanding recognition in their field.\",\"s\":\"The coach reminded the team that a nonsuperstar player can still win the championship with teamwork.\",\"p\":\"non-SOO-per-star\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"sy\":\"non.super.star\",\"ps\":\"noun\",\"t\":[\"character\",\"olatin\"]},{\"w\":\"nonsuperstitious\",\"d\":\"Not believing in or influenced by superstitions; approaching events and outcomes with a rational rather than superstitious mindset.\",\"s\":\"Her nonsuperstitious attitude meant she walked under ladders without a second thought.\",\"p\":\"non-soo-per-STISH-us\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.super.sti.tious\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"logic\",\"olatin\"]},{\"w\":\"nonsupersymmetric\",\"d\":\"Not exhibiting or relating to supersymmetry, a theoretical framework in physics that proposes a symmetry between particles of different types.\",\"s\":\"The physicist showed that the particles behaved in a nonsupersymmetric pattern under the new conditions.\",\"p\":\"non-soo-per-si-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.super.sym.met.ric\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"nonsupervised\",\"d\":\"Not under the oversight or direction of a supervisor; carried out without someone watching over or monitoring the activity.\",\"s\":\"The students completed the nonsupervised project entirely on their own schedule.\",\"p\":\"non-SOO-per-vyzd\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.super.vised\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsupervisory\",\"d\":\"Not relating to or involving the duties of a supervisor; describing a role or position that does not include overseeing or managing other workers.\",\"s\":\"He applied for a nonsupervisory position because he preferred working independently.\",\"p\":\"non-soo-per-VY-zor-ee\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.super.vi.so.ry\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsupplementary\",\"d\":\"Not serving as a supplement or addition; not providing extra material, support, or information beyond what is already present.\",\"s\":\"The judge ruled the evidence was nonsupplementary and could not be added to the original case.\",\"p\":\"non-sup-luh-MEN-teh-ree\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.sup.ple.men.tary\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsuppletive\",\"d\":\"In linguistics, not involving suppletion, meaning a grammatical form is derived in the regular way rather than replaced by an entirely different word form.\",\"s\":\"The linguist explained that the verb form was nonsuppletive, built regularly from the root.\",\"p\":\"non-SUP-luh-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sup.ple.tive\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsupplier\",\"d\":\"A person, company, or entity that does not supply or provide goods, materials, or services to another party.\",\"s\":\"The company was listed as a nonsupplier after failing to deliver materials on time.\",\"p\":\"non-suh-PLY-er\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.sup.pli.er\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsupported\",\"d\":\"Not given backing, assistance, or reinforcement; describing something that lacks structural, financial, or other forms of support.\",\"s\":\"The nonsupported structure collapsed under the weight of the heavy snow.\",\"p\":\"non-suh-POR-tid\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.sup.port.ed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsupporter\",\"d\":\"A person who does not support, endorse, or back a particular cause, candidate, policy, or individual.\",\"s\":\"Even a nonsupporter of the team admitted the final game was thrilling to watch.\",\"p\":\"non-suh-POR-ter\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.sup.port.er\",\"ps\":\"noun\",\"t\":[\"politics\",\"olatin\"]},{\"w\":\"nonsupportive\",\"d\":\"Not providing encouragement, assistance, or emotional backing; failing to offer the help or approval that someone or something needs.\",\"s\":\"A nonsupportive environment at home can make it harder for students to succeed in school.\",\"p\":\"non-suh-POR-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sup.port.ive\",\"ps\":\"adjective\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"nonsuppressed\",\"d\":\"Not held back, restrained, or prevented from being expressed; allowed to surface or function freely without being suppressed.\",\"s\":\"The nonsuppressed immune response helped the patient fight off the infection quickly.\",\"p\":\"non-suh-PREST\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.sup.pressed\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsuppressible\",\"d\":\"Not capable of being suppressed, held back, or restrained; too strong or prominent to be stopped or hidden.\",\"s\":\"The scientist discovered that the gene was nonsuppressible under standard laboratory conditions.\",\"p\":\"non-suh-PRES-ih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sup.press.ible\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsuppurative\",\"d\":\"Not involving or producing pus; describing an infection or inflammatory condition that does not result in the formation of pus.\",\"s\":\"The doctor noted that the wound was nonsuppurative, showing no signs of pus formation.\",\"p\":\"non-SUP-yuh-ray-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sup.pu.ra.tive\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonsurety\",\"d\":\"Not serving as a guarantee, security, or formal assurance; lacking the status or function of a surety in a legal or financial context.\",\"s\":\"Without a nonsurety clause, the borrower needed a guarantor before the loan was approved.\",\"p\":\"non-SHOOR-ih-tee\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sure.ty\",\"ps\":\"noun\",\"t\":[\"law\",\"olatin\"]},{\"w\":\"nonsurfactant\",\"d\":\"A substance that does not act as a surfactant, meaning it does not reduce the surface tension of liquids or help blend oil and water.\",\"s\":\"The chemist tested a nonsurfactant additive to see how it affected the solution's surface tension.\",\"p\":\"non-ser-FAK-tunt\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sur.fac.tant\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsurjective\",\"d\":\"In mathematics, describing a function that is not surjective, meaning not every element in the target set is mapped to by at least one element in the source set.\",\"s\":\"The math teacher explained that a nonsurjective function doesn't map onto every element of the output set.\",\"p\":\"non-ser-JEK-tiv\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sur.jec.tive\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"numbers\",\"olatin\"]},{\"w\":\"nonsurplus\",\"d\":\"Not constituting a surplus; describing a quantity, amount, or supply that is not in excess of what is needed or expected.\",\"s\":\"The budget was tight, leaving the department in a nonsurplus position at year's end.\",\"p\":\"non-SER-plus\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sur.plus\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsurrealist\",\"d\":\"Not belonging to or characteristic of the surrealist art movement; describing artwork, writing, or ideas that do not employ dreamlike, irrational, or fantastical imagery.\",\"s\":\"The gallery exhibit featured both surrealist and nonsurrealist paintings displayed side by side.\",\"p\":\"non-suh-REE-uh-list\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sur.re.al.ist\",\"ps\":\"adjective\",\"t\":[\"painting\",\"olatin\"]},{\"w\":\"nonsurvey\",\"d\":\"Something that is not a formal survey, such as an area of land that has not been officially measured or mapped, or data collected through methods other than a survey.\",\"s\":\"The planning department used nonsurvey data collected from satellite images instead.\",\"p\":\"non-SER-vay\",\"o\":\"Latin\",\"y\":8,\"bp\":28,\"sy\":\"non.sur.vey\",\"ps\":\"noun\",\"t\":[\"numbers\",\"olatin\"]},{\"w\":\"nonsurveyed\",\"d\":\"Not having been examined, measured, or mapped through an official survey; describing land or data that has not undergone a formal surveying process.\",\"s\":\"Large portions of the remote jungle remained nonsurveyed by modern cartographers.\",\"p\":\"non-ser-VAYD\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sur.veyed\",\"ps\":\"adjective\",\"t\":[\"maps\",\"numbers\",\"olatin\"]},{\"w\":\"nonsurvival\",\"d\":\"The failure to continue living or existing; the state or condition of not surviving a dangerous event, illness, or threatening situation.\",\"s\":\"Scientists studied the conditions that led to the nonsurvival of the ancient colony.\",\"p\":\"non-ser-VY-vul\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sur.vival\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonsurvivor\",\"d\":\"A person who does not survive a life-threatening event, disaster, or serious illness; one who perishes rather than endures.\",\"s\":\"The memorial listed every nonsurvivor from the shipwreck, honoring those who lost their lives.\",\"p\":\"non-ser-VY-ver\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.sur.vivor\",\"ps\":\"noun\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonsusceptible\",\"d\":\"Not easily affected, influenced, or harmed by something; resistant to a particular disease, condition, or outside force.\",\"s\":\"Scientists hoped to breed a nonsusceptible strain of wheat that would resist the deadly fungus.\",\"p\":\"non-suh-SEP-tih-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sus.cep.ti.ble\",\"ps\":\"adjective\",\"t\":[\"disease\",\"physics\",\"olatin\"]},{\"w\":\"nonsushi\",\"d\":\"Food or a menu item that does not consist of sushi; referring to dishes or options that are not the Japanese preparation of seasoned rice with fish or other toppings.\",\"s\":\"The restaurant offered a nonsushi menu for guests who preferred cooked Japanese dishes.\",\"p\":\"non-SOO-shee\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.sushi\",\"ps\":\"adjective\",\"t\":[\"marine\",\"culinary\",\"dishes\",\"time\",\"olatin\"]},{\"w\":\"nonsuspect\",\"d\":\"A person who is not under suspicion of having committed a crime or wrongdoing; someone cleared of or not considered for suspicion by investigators.\",\"s\":\"The police quickly cleared the nonsuspect witnesses so they could focus on the real culprit.\",\"p\":\"non-SUS-pekt\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"non.sus.pect\",\"ps\":\"noun\",\"t\":[\"law\",\"economy\",\"character\",\"olatin\"]},{\"w\":\"nonsuspended\",\"d\":\"Not having been suspended, stopped, or temporarily removed from a position, activity, or state; continuing without interruption or penalty.\",\"s\":\"The nonsuspended students attended class as usual while their classmates served their punishment.\",\"p\":\"non-suh-SPEND-id\",\"o\":\"Latin\",\"y\":8,\"bp\":38,\"sy\":\"non.sus.pend.ed\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonsustainable\",\"d\":\"Not capable of being maintained at the current rate or level over time; describing a practice, resource use, or system that cannot continue without causing harm or depletion.\",\"s\":\"The committee warned that the nonsustainable fishing practices would empty the ocean within decades.\",\"p\":\"non-suh-STAY-nuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.sus.tain.able\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonswearing\",\"d\":\"Not involving the use of profane, vulgar, or offensive language; describing speech, content, or conduct that is free from swear words or oaths.\",\"s\":\"The drama club adopted a nonswearing policy, keeping all rehearsals clean and professional.\",\"p\":\"non-SWAIR-ing\",\"o\":\"Latin\",\"y\":8,\"bp\":35,\"sy\":\"non.swear.ing\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsweet\",\"d\":\"Not containing sugar or having a sweet flavor; describing a food, drink, or substance that lacks sweetness.\",\"s\":\"She preferred nonsweet crackers with her soup rather than the sugary dessert options.\",\"p\":\"non-SWEET\",\"o\":\"Latin\",\"y\":8,\"bp\":25,\"sy\":\"non.sweet\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonswimmer\",\"d\":\"A person who is unable to swim or who has not learned to swim; someone who does not participate in swimming as an activity.\",\"s\":\"The lifeguard kept a close eye on the nonswimmer who waded nervously at the pool's edge.\",\"p\":\"non-SWIM-er\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.swim.mer\",\"ps\":\"noun\",\"t\":[\"character\",\"sports\",\"olatin\"]},{\"w\":\"nonswimming\",\"d\":\"Not involving or relating to swimming; describing an activity, area, or individual that does not include swimming.\",\"s\":\"The nonswimming campers enjoyed kayaking with life jackets while others practiced laps.\",\"p\":\"non-SWIM-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.swim.ming\",\"ps\":\"adjective\",\"t\":[\"sports\",\"olatin\"]},{\"w\":\"nonswinger\",\"d\":\"A person or thing that does not swing; someone who remains steady or unchanged rather than shifting or oscillating between positions or states.\",\"s\":\"At the jazz festival, even the nonswinger crowd found themselves tapping their feet to the beat.\",\"p\":\"non-SWING-er\",\"o\":\"Latin\",\"y\":8,\"bp\":27,\"sy\":\"non.swinger\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonswitchable\",\"d\":\"Not capable of being switched, toggled, or changed from one state or setting to another; fixed in its current configuration.\",\"s\":\"The nonswitchable circuit was permanently set, so technicians could not redirect the signal.\",\"p\":\"non-SWICH-uh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":25,\"sy\":\"non.switch.able\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonswitching\",\"d\":\"Not involving the act of switching or changing between states, connections, or modes; remaining constant without any switching action.\",\"s\":\"The nonswitching network route sent all data straight through without any redirection.\",\"p\":\"non-SWICH-ing\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.switch.ing\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonswollen\",\"d\":\"Not swollen or enlarged; describing a body part or tissue that has not undergone abnormal puffiness or inflammation.\",\"s\":\"After icing his ankle, the doctor confirmed it was nonswollen and only mildly bruised.\",\"p\":\"non-SWOH-len\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"nonsyllabic\",\"d\":\"not forming a syllable of its own; said of a sound that leans on a nearby vowel\",\"s\":\"When 'botany' is said quickly as 'bot-ny', the n sound is nonsyllabic.\",\"p\":\"non-sih-LAB-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.syl.lab.ic\",\"ps\":\"adjective\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"nonsyllogistic\",\"d\":\"Not based on or using a syllogism; describing reasoning or argument that does not follow the formal logical structure of a syllogism.\",\"s\":\"The philosopher pointed out that the student's argument was nonsyllogistic and lacked logical structure.\",\"p\":\"non-sil-oh-JIS-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.syl.lo.gis.tic\",\"ps\":\"adjective\",\"t\":[\"logic\",\"olatin\"]},{\"w\":\"nonsymbiotic\",\"d\":\"not living in a close partnership with another kind of living thing\",\"s\":\"Unlike clownfish and anemones, the two nonsymbiotic species lived near each other without depending on one another.\",\"p\":\"non-sim-by-OT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"non.sym.bi.ot.ic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsymmetric\",\"d\":\"Not having symmetry; lacking the property of being identical or balanced on both sides of a dividing line or plane.\",\"s\":\"The artist deliberately created a nonsymmetric sculpture that looked different from every angle.\",\"p\":\"non-sih-MET-rik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.sym.met.ric\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsymmetrical\",\"d\":\"Not symmetrical; having sides, parts, or elements that are unequal, unbalanced, or not mirror images of each other.\",\"s\":\"The nonsymmetrical leaf pattern made the plant stand out from all the others in the garden.\",\"p\":\"non-sih-MET-rih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sym.met.ri.cal\",\"ps\":\"adjective\",\"t\":[\"household\",\"olatin\"]},{\"w\":\"nonsymmetrized\",\"d\":\"Not having been made symmetrical; describing something that has not undergone a process to equalize or balance its parts.\",\"s\":\"The raw data remained nonsymmetrized until the scientist applied the balancing formula.\",\"p\":\"non-SIM-ih-tryzd\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sym.metrized\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsympathetic\",\"d\":\"Lacking sympathy or compassion; not showing understanding or concern for another person's feelings or situation.\",\"s\":\"The nonsympathetic judge refused to consider the defendant's personal hardships when sentencing.\",\"p\":\"non-sim-puh-THET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"non.sym.pa.thet.ic\",\"ps\":\"adjective\",\"t\":[\"maps\",\"emotions\",\"olatin\"]},{\"w\":\"nonsympatric\",\"d\":\"Not occupying the same geographic region or habitat; describing species or populations that live in separate, non-overlapping areas.\",\"s\":\"The two bird species were nonsympatric, living on completely separate continents and never interacting.\",\"p\":\"non-sim-PAY-trik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.sym.patric\",\"ps\":\"adjective\",\"t\":[\"ecology\",\"olatin\"]},{\"w\":\"nonsymphonic\",\"d\":\"Not of, relating to, or written for a full symphony orchestra; describing music that lacks the grand, complex structure of a symphony.\",\"s\":\"The nonsymphonic performance featured a small jazz quartet rather than a full orchestra.\",\"p\":\"non-sim-FON-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.sym.phon.ic\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonsymplectic\",\"d\":\"Not symplectic; describing a mathematical structure or space that does not satisfy the conditions of symplectic geometry, which studies certain geometric forms used in physics.\",\"s\":\"The mathematician showed that the transformation was nonsymplectic and broke the geometric structure.\",\"p\":\"non-sim-PLEK-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.sym.plec.tic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"nonsymptomatic\",\"d\":\"Not showing or producing symptoms; describing a condition or person in which no outward signs of illness or disease are present.\",\"s\":\"Many nonsymptomatic carriers of the virus unknowingly spread it to others without ever feeling sick.\",\"p\":\"non-simp-toh-MAT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.symp.tomat.ic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonsymptomatological\",\"d\":\"Not related to the study or classification of symptoms; describing an approach or finding that does not involve analyzing the signs and symptoms of a disease.\",\"s\":\"The research took a nonsymptomatological approach, focusing on genetics rather than visible symptoms.\",\"p\":\"non-simp-toh-mat-oh-LOJ-ih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"non.symp.toma.to.log.i.cal\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"nonsynaptic\",\"d\":\"Not involving or occurring at a synapse; describing neural communication or signaling that does not require a direct synaptic connection between nerve cells.\",\"s\":\"The researchers discovered a nonsynaptic signaling pathway that allowed brain cells to communicate differently.\",\"p\":\"non-sih-NAP-tik\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"non.sy.nap.tic\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonsynchronizable\",\"d\":\"Not capable of being synchronized; describing systems or processes that cannot be made to operate at the same time or in coordination with each other.\",\"s\":\"The outdated clocks were nonsynchronizable because their mechanisms were too different to coordinate.\",\"p\":\"non-SING-kroh-ny-zuh-bul\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"non.syn.chro.niz.able\",\"ps\":\"adjective\",\"t\":[\"time\",\"olatin\"]},{\"w\":\"nonsynchronous\",\"d\":\"not occurring together\",\"s\":\"The nonsynchronous signals caused the machines to clash because they operated on different time cycles.\",\"p\":\"non-SING-kroh-nus\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"non.syn.chronous\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsyncopated\",\"d\":\"Not syncopated; describing music or rhythm that places accents only on the expected, regular beats without any off-beat or irregular stressing.\",\"s\":\"The nonsyncopated march kept a perfectly steady beat without any surprising rhythmic shifts.\",\"p\":\"non-SING-koh-pay-ted\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.syn.co.pat.ed\",\"ps\":\"adjective\",\"t\":[\"music\",\"olatin\"]},{\"w\":\"nonsyncretic\",\"d\":\"Not syncretic; describing a belief system, culture, or practice that does not blend or merge elements from different traditions, religions, or philosophies.\",\"s\":\"The nonsyncretic religion maintained strict traditions and refused to blend with outside beliefs.\",\"p\":\"non-sin-KRET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.syn.cret.ic\",\"ps\":\"adjective\",\"t\":[\"religion\",\"festivals\",\"logic\",\"olatin\"]},{\"w\":\"nonsyndromic\",\"d\":\"Not associated with or part of a recognized syndrome; describing a condition, especially a genetic one, that occurs without the cluster of additional symptoms that define a syndrome.\",\"s\":\"The child's hearing loss was identified as nonsyndromic, meaning it was not part of a larger genetic condition.\",\"p\":\"non-sin-DROH-mik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"non.syn.dromic\",\"ps\":\"adjective\",\"t\":[\"disease\",\"numbers\",\"olatin\"]},{\"w\":\"nonsynesthetic\",\"d\":\"Not involving synesthesia; describing perception or experience in which the senses remain separate and do not trigger automatic crossover sensations, such as seeing colors when hearing music.\",\"s\":\"For the nonsynesthetic student, the music was simply sound and did not trigger any color visions.\",\"p\":\"non-sin-es-THET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":27,\"sy\":\"non.synes.thet.ic\",\"ps\":\"adjective\",\"t\":[\"music\",\"colors\",\"olatin\"]},{\"w\":\"nonsynovial\",\"d\":\"Not relating to or producing synovial fluid; describing a joint or tissue that lacks the lubricating fluid normally found in freely movable joints.\",\"s\":\"The nonsynovial joint in the skull allows almost no movement compared to the fluid-filled knee joint.\",\"p\":\"non-sih-NOH-vee-ul\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.syn.ovial\",\"ps\":\"adjective\",\"t\":[\"body\",\"olatin\"]},{\"w\":\"nonsynthetic\",\"d\":\"not made artificially; coming from natural sources rather than a factory or laboratory\",\"p\":\"non-sin-THET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":38,\"sy\":\"non.syn.thet.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"],\"s\":\"The shirt was woven from nonsynthetic fibres such as cotton and wool.\"},{\"w\":\"nonsystem\",\"d\":\"Something that lacks the organized structure, order, or coordination of a true system; a disorganized or incoherent arrangement that fails to function as a unified whole.\",\"s\":\"Critics called the city's transportation plan a complete nonsystem because buses and trains never connected.\",\"p\":\"non-SIS-tem\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"non.sys.tem\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"nonsystemic\",\"d\":\"Not systemic; describing a substance or condition that affects only a local area and does not spread through or involve the entire body or system.\",\"s\":\"The nonsystemic pesticide affected only the surface of the leaf and did not travel through the plant.\",\"p\":\"non-sis-TEM-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.sys.temic\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"nonsystolic\",\"d\":\"Not relating to or occurring during systole; describing a heart sound, measurement, or event that does not correspond to the contracting phase of the heartbeat.\",\"s\":\"During the nonsystolic phase of the heartbeat, the ventricles are relaxed and filling with blood.\",\"p\":\"non-sis-TOL-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":35,\"sy\":\"non.sys.tolic\",\"ps\":\"adjective\",\"t\":[\"body\",\"law\",\"numbers\",\"olatin\"]}]",h:"[]"};
